window.BANQUE_INFINI = {"module":"annee-1/theorique/semestre-2/physio-patho","titre":"Physiopathologie I","sources":[{"t":"Lésion Médullaire","q":"qcm/neuro/lesion-medullaire.html","f":"fiches/neuro/lesion-medullaire.html"},{"t":"Lésions Périphériques","q":"qcm/neuro/lesions-peripheriques.html","f":"fiches/neuro/lesions-peripheriques.html"},{"t":"Lésions SNC + Encéphale","q":"qcm/neuro/lesions-snc-encephale.html","f":"fiches/neuro/lesions-snc-encephale.html"},{"t":"Système Nerveux","q":"qcm/neuro/systeme-nerveux.html","f":"fiches/neuro/systeme-nerveux.html"},{"t":"Support Neurophysio 1","q":"qcm/neuroanat/suporte-1.html","f":"fiches/neuroanat/suporte-1.html"},{"t":"Support Neurophysio 2a","q":"qcm/neuroanat/suporte-2a.html","f":"fiches/neuroanat/suporte-2a.html"},{"t":"Support Neurophysio 2b","q":"qcm/neuroanat/suporte-2b.html","f":"fiches/neuroanat/suporte-2b.html"},{"t":"TP 1 — Introduction Physiopathologie","q":"qcm/tp/tp-01.html","f":"fiches/tp/tp-01.html"},{"t":"TP 2 — Lésions Cellulaires","q":"qcm/tp/tp-02.html","f":"fiches/tp/tp-02.html"},{"t":"TP 3 — Maladies Infectieuses","q":"qcm/tp/tp-03.html","f":"fiches/tp/tp-03.html"},{"t":"TP 4 — Inflammation & Réparation","q":"qcm/tp/tp-04.html","f":"fiches/tp/tp-04.html"},{"t":"TP 5 — Squelette & Tissu Osseux","q":"qcm/tp/tp-05.html","f":"fiches/tp/tp-05.html"},{"t":"TP 6-7 — Troubles musculo-squelettiques","q":"qcm/tp/tp-06-07.html","f":"fiches/tp/tp-06-07.html"},{"t":"TP 6 — Ostéoporose & Fractures","q":"qcm/tp/tp-06.html","f":"fiches/tp/tp-06.html"},{"t":"TP 7 — Posture & Scoliose","q":"qcm/tp/tp-07.html","f":"fiches/tp/tp-07.html"},{"t":"TP 8 — Arthrose","q":"qcm/tp/tp-08.html","f":"fiches/tp/tp-08.html"},{"t":"TP 9 — Réparation Tissulaire","q":"qcm/tp/tp-09.html","f":"fiches/tp/tp-09.html"},{"t":"TP 10 — Sepsie & Choc Septique","q":"qcm/tp/tp-10.html","f":"fiches/tp/tp-10.html"},{"t":"TP 11 — Voies Respiratoires Supérieures","q":"qcm/tp/tp-11.html","f":"fiches/tp/tp-11.html"},{"t":"TP 12 — Voies Respiratoires Inférieures","q":"qcm/tp/tp-12.html","f":"fiches/tp/tp-12.html"},{"t":"TP 13 — Maladies Obstructives","q":"qcm/tp/tp-13.html","f":"fiches/tp/tp-13.html"},{"t":"TP 14 — Maladies Restrictives & Plèvre","q":"qcm/tp/tp-14.html","f":"fiches/tp/tp-14.html"},{"t":"TP 15 — Néoplasies (Cancer)","q":"qcm/tp/tp-15.html","f":"fiches/tp/tp-15.html"}],"questions":[{"q":"Jusqu'à quel niveau vertébral s'étend la moelle épinière chez l'adulte ?","o":["L4-L5","L1-L2","T12-L1","S1"],"r":1,"e":"Chez l'adulte, la moelle épinière s'étend de l'orifice occipital jusqu'à L1-L2. En dessous se trouve la queue de cheval.","s":0},{"q":"Comment s'appelle l'ensemble des racines nerveuses libres situées en dessous du cône médullaire ?","o":["Filum terminale","Queue de cheval","Plexus sacré","Cône terminal"],"r":1,"e":"La queue de cheval = ensemble des racines L2-S5 qui parcourent le canal rachidien sous le cône médullaire (fin de la moelle).","s":0},{"q":"Concernant la substance grise de la moelle, quelles affirmations sont vraies ?","o":["Les cornes antérieures sont MOTRICES","Les cornes postérieures sont SENSITIVES","Les cornes latérales contiennent les neurones du SNA","Les cornes antérieures sont sensitives","La substance grise contient principalement des axones myélinisés"],"r":[0,1,2],"e":"Antérieur = moteur, postérieur = sensitif, latéral = SNA. La substance grise contient les corps cellulaires (les axones myélinisés sont dans la substance blanche).","s":0},{"q":"La règle mnémotechnique pour la moelle est :","o":["Antérieur = sensitif, postérieur = moteur","Antérieur = moteur, postérieur = sensitif","Latéral = moteur, médian = sensitif","Toutes les directions ont des fonctions mixtes"],"r":1,"e":"Antérieur = moteur, postérieur = sensitif (valable pour les cornes ET les cordons).","s":0},{"q":"Quelles voies sensitives passent par la colonne POSTÉRIEURE de la moelle ?","o":["Proprioception consciente","Vibration","Toucher fin (épicritique)","Douleur","Température"],"r":[0,1,2],"e":"Colonne postérieure (gracile + cunéiforme) = proprioception, vibration, toucher fin. Douleur et température passent par la voie spinothalamique latérale.","s":0},{"q":"La voie spinothalamique latérale véhicule :","o":["Le toucher fin et la proprioception","La douleur et la température","La motricité volontaire","Les réflexes ostéo-tendineux"],"r":1,"e":"La voie spinothalamique latérale = douleur + température (voie protopathique). Elle CROISE rapidement (1-2 segments au-dessus de l'entrée).","s":0},{"q":"Une lésion AU-DESSUS de D1 (T1) entraîne :","o":["Une paraplégie","Une tétraplégie","Une hémiplégie","Aucun déficit"],"r":1,"e":"Au-dessus de T1 = atteinte des 4 membres = tétraplégie/tétraparésie. En dessous de T1 = paraplégie.","s":0},{"q":"Concernant le syndrome de BROWN-SÉQUARD (hémisection médullaire), quelles affirmations sont vraies ?","o":["Perte motrice IPSILATÉRALE","Perte de la proprioception IPSILATÉRALE","Perte de la douleur et température CONTROLATÉRALE","Perte motrice controlatérale","Aucun déficit moteur"],"r":[0,1,2],"e":"Brown-Séquard : motricité + proprioception ipsilatérales (corticospinale et colonne postérieure homolatérales) ; douleur/T° controlatérales (spinothalamique croisée).","s":0},{"q":"Le syndrome ANTÉRIEUR de la moelle (atteinte de l'artère spinale antérieure) se caractérise par :","o":["Perte motrice + douleur/T°, avec PROPRIOCEPTION PRÉSERVÉE","Perte de la proprioception uniquement","Hémisection avec déficit croisé","Atteinte sphinctérienne isolée"],"r":0,"e":"Le syndrome antérieur (artère spinale antérieure) atteint les 2/3 antérieurs de la moelle : déficit moteur + perte douleur/T° BILATÉRALES, mais la colonne POSTÉRIEURE est intacte (proprioception et toucher fin préservés).","s":0},{"q":"Concernant le syndrome CENTROMÉDULLAIRE, quelles propositions sont vraies ?","o":["Membres supérieurs plus touchés que les membres inférieurs","Mécanisme typique : hyperextension cervicale","Atteinte centrale (canal central et fibres médianes)","Membres inférieurs systématiquement plus touchés","Pas d'atteinte sphinctérienne"],"r":[0,1,2],"e":"Syndrome centromédullaire : MS > MI (les fibres des MS sont plus centrales dans le tractus corticospinal latéral). Mécanisme classique : hyperextension cervicale. Rétention urinaire fréquente.","s":0},{"q":"Quel niveau médullaire contient le centre de la miction ?","o":["L1-L2","S2-S4","T10-T12","C5-C6"],"r":1,"e":"Le centre médullaire de la miction se situe en S2-S4 (parasympathique sacré). Une lésion à ce niveau entraîne une vessie flasque/autonome.","s":0},{"q":"Concernant le CHOC MÉDULLAIRE (phase initiale), quelles affirmations sont correctes ?","o":["Paralysie flasque","Aréflexie","Anesthésie","Hyperréflexie immédiate","Spasticité immédiate"],"r":[0,1,2],"e":"Phase de choc spinal : paralysie FLASQUE, aréflexie, anesthésie, atonie vésicale et intestinale. La spasticité et l'hyperréflexie n'apparaissent qu'APRÈS le retour de l'activité réflexe.","s":0},{"q":"Après la phase de choc médullaire, une lésion du 1er neurone (motoneurone supérieur) se traduit par :","o":["Paralysie flasque + aréflexie + atrophie","Paralysie spastique + hyperréflexie","Aucun déficit","Atrophie isolée sans paralysie"],"r":1,"e":"Lésion 1er neurone (SNC) après le choc : paralysie spastique, hyperréflexie, signe de Babinski, spasmes. La paralysie flasque + aréflexie + atrophie = lésion du 2e neurone (SNP).","s":0},{"q":"Dans la classification ASIA, le grade A correspond à :","o":["Lésion incomplète motrice","Lésion complète","Fonctions normales","Lésion incomplète sensitive"],"r":1,"e":"ASIA A = lésion complète : aucune fonction motrice ni sensorielle préservée dans les segments S4-S5. ASIA E = normal.","s":0},{"q":"Concernant la classification ASIA, quelles correspondances sont correctes ?","o":["A = complète","B = incomplète sensitive","C = incomplète motrice avec majorité des muscles < 3/5","D = incomplète motrice avec majorité des muscles ≥ 3/5","E = atteinte sphinctérienne isolée"],"r":[0,1,2,3],"e":"ASIA : A complète, B incomplète sensitive (motricité absente sous le niveau), C incomplète motrice <3/5, D incomplète motrice ≥3/5, E normale. Les sphincters ne sont pas un grade ASIA.","s":0},{"q":"Combien de dermatomes sont testés dans l'examen ASIA ?","o":["10","15","23","31"],"r":2,"e":"L'examen ASIA teste 23 dermatomes (sensibilité tactile et douloureuse) et 10 myotomes clés (5 par côté pour le bilan moteur).","s":0},{"q":"Le myotome C5 correspond principalement à :","o":["L'extension du coude","L'abduction du bras / flexion du coude","La flexion plantaire","L'extension du poignet"],"r":1,"e":"C5 = abduction de l'épaule et flexion du coude (deltoïde, biceps). C6 = extension du poignet, C7 = extension du coude/triceps.","s":0},{"q":"Le myotome S1 correspond à :","o":["La flexion de hanche","L'extension du genou","La dorsiflexion","La flexion plantaire"],"r":3,"e":"S1 = flexion plantaire (triceps sural). L4 = dorsiflexion ; L3 = extension genou ; L2 = flexion de hanche.","s":0},{"q":"Quels niveaux médullaires assurent l'innervation diaphragmatique (centre phrénique) ?","o":["C2","C3","C4","C5","T1"],"r":[1,2,3],"e":"Le diaphragme est innervé par le nerf phrénique issu de C3-C4-C5. Une lésion AU-DESSUS de C3 menace la respiration et nécessite une ventilation.","s":0},{"q":"Parmi les complications classiques d'un blessé médullaire, on retrouve :","o":["Escarres / ulcères de pression","Thrombose veineuse profonde","Hypotension orthostatique","Ostéoporose","Hyperhidrose excessive sans risque"],"r":[0,1,2,3],"e":"Complications classiques : escarres (téguments), TVP (vasculaire), hypotension orthostatique, ostéoporose, vessie neurogène, calcifications hétérotopiques. L'hyperhidrose peut survenir lors d'une hyperréflexie autonome (urgence).","s":0},{"q":"L'anesthésie en SELLE (périnée + face interne des cuisses) évoque :","o":["Un syndrome de Brown-Séquard","Un syndrome centromédullaire","Un syndrome du cône médullaire / queue de cheval","Une section totale haute"],"r":2,"e":"L'anesthésie en selle (S3-S5) est typique du syndrome du cône médullaire / queue de cheval, avec troubles sphinctériens et sexuels.","s":0},{"q":"Une lésion COMPLÈTE selon ASIA correspond à :","o":["Aucun mouvement volontaire mais sensibilité préservée","Aucune fonction motrice ou sensorielle préservée en S4-S5","Force musculaire ≤ 3/5","Présence d'un réflexe sphinctérien isolé"],"r":1,"e":"Une lésion ASIA A (complète) = aucune fonction motrice NI sensorielle dans les segments sacrés S4-S5 (test du toucher anal et de la contraction volontaire).","s":0},{"q":"Concernant la PHASE 2 (lésion secondaire) de la lésion médullaire, quelles affirmations sont correctes ?","o":["Réduction du flux sanguin et ischémie étendue","Œdème médullaire","Excitotoxicité par libération de glutamate","Démyélinisation axonale graduelle","Rupture immédiate physique des axones"],"r":[0,1,2,3],"e":"Phase secondaire : ischémie, œdème, inflammation, excitotoxicité (glutamate, K+), apoptose, démyélinisation graduelle. La rupture physique des axones est généralement progressive (sauf blessures par balle), pas immédiate.","s":0},{"q":"Une lésion intra-durale extra-médullaire correspond à :","o":["Une lésion à l'intérieur même de la moelle (ex : syringomyélie)","Une lésion sous la dure-mère mais hors de la moelle (ex : méningiome)","Une lésion en dehors de la dure-mère (ex : hernie discale)","Une lésion vasculaire pure"],"r":1,"e":"Intra-durale extra-médullaire : sous la dure-mère MAIS en dehors de la moelle. Exemples : méningiome, schwannome. Intra-médullaire = dans la moelle ; extra-durale = hernie discale, métastase.","s":0},{"q":"Concernant la cotation motrice ASIA (0-5), quelles correspondances sont vraies ?","o":["0 = paralysie totale","2 = mouvement actif sans la pesanteur","3 = mouvement actif contre la pesanteur","4 = contre résistance partielle","5 = mouvement seulement visible"],"r":[0,1,2,3],"e":"Cotation : 0 paralysie / 1 contraction visible/palpable / 2 sans pesanteur / 3 contre pesanteur / 4 contre résistance partielle / 5 force normale.","s":0},{"q":"Selon les statistiques épidémiologiques, quelle est la cause la plus fréquente de lésion médullaire ?","o":["Les chutes","La violence","Les accidents de la route","Le sport"],"r":2,"e":"Les accidents de la route représentent ~48% des lésions médullaires, devant les chutes (~23%), la violence (~14%) et le sport (~9%). 80% des victimes sont des hommes, âge moyen ~37 ans.","s":0},{"q":"Une dyssynergie vésico-sphinctérienne correspond à :","o":["Une vessie flasque sans contraction","Un manque de coordination entre la vessie qui se contracte et le sphincter qui ne se relâche pas","Une infection urinaire","Une fistule"],"r":1,"e":"La dyssynergie vésico-sphinctérienne = contraction simultanée du détrusor (vessie) et du sphincter externe → mauvaise vidange, hyperpression, risque d'hydronéphrose. Complication classique des lésions du 1er neurone.","s":0},{"q":"Quels sites anatomiques sont à risque d'escarre chez le blessé médullaire ?","o":["Sacrum","Talons","Ischions","Occiput","Face palmaire des mains"],"r":[0,1,2,3],"e":"Les zones à risque d'escarre = points d'appui : sacrum, ischions, talons, occiput, omoplates, malléoles, coudes. La face palmaire des mains n'est pas une zone classique d'escarre.","s":0},{"q":"Une lésion médullaire haute (cervicale C1-C4) entraîne typiquement :","o":["Tétraplégie + atteinte respiratoire (diaphragme)","Paraplégie isolée","Aucune atteinte","Déficit sensitif facial"],"r":0,"e":"Lésion C1-C4 : tétraplégie + paralysie diaphragmatique (nerf phrénique C3-C5) → ventilation mécanique nécessaire.","s":0},{"q":"Une lésion thoracique provoque :","o":["Tétraplégie","Paraplégie + perte sensitive sous la lésion","Hémiplégie","Aucun déficit"],"r":1,"e":"Lésion thoracique → paraplégie (membres inférieurs) + perte sensitive sous le niveau lésionnel.","s":0},{"q":"Le choc spinal correspond à :","o":["Récupération immédiate","Aréflexie initiale temporaire (heures-semaines) sous la lésion","Spasticité immédiate","Hyperréflexie"],"r":1,"e":"Choc spinal = phase initiale de l'atteinte médullaire : aréflexie, hypotonie, perte transitoire des fonctions, dure heures à semaines.","s":0},{"q":"Après le choc spinal, on observe typiquement :","o":["Une flaccidité permanente","L'apparition d'une spasticité (lésion 1er motoneurone)","Un retour à la normale","Une atrophie totale"],"r":1,"e":"Après le choc spinal : spasticité, hyperréflexie, signe de Babinski (atteinte du 1er motoneurone).","s":0},{"q":"Le syndrome de Brown-Séquard correspond à :","o":["Atteinte symétrique","Hémisection médullaire : déficit moteur ipsi + sensibilité thermoalgique controlatéralement","Compression complète","Lésion antérieure"],"r":1,"e":"Brown-Séquard (hémisection) : moteur + tact épicritique ipsi (cordon dorsal et latéral) ; thermoalgique controlatéral (faisceau spinothalamique croisé).","s":0},{"q":"La dysréflexie autonome est :","o":["Bénigne","Une urgence chez le tétraplégique : ↑ massive de TA déclenchée par stimulus sous-lésionnel","Sans rapport","Toujours hypotensive"],"r":1,"e":"Dysréflexie autonome (lésion ≥T6) : poussée hypertensive sévère + bradycardie + sueurs sus-lésionnelles. Stimulus = vessie pleine, fécalome. Urgence.","s":0},{"q":"L'échelle ASIA évalue :","o":["L'âge","Le niveau et la complétude d'une lésion médullaire","La douleur","La vigilance"],"r":1,"e":"ASIA Impairment Scale : grade A (complète) à E (normal). Définit niveau moteur, sensitif et complétude de la lésion.","s":0},{"q":"Les complications fréquentes du blessé médullaire incluent :","o":["Escarres","Infection urinaire","Thrombose veineuse profonde","Spasticité","Ostéoporose","Hyperthyroïdie"],"r":[0,1,2,3,4],"e":"Complications : escarres, IU, TVP/EP, spasticité, ostéoporose, douleurs neuropathiques, dysréflexie autonome.","s":0},{"q":"Le réflexe rotulien (L3-L4) est :","o":["Aboli en lésion centrale","Vif (spasticité) en lésion centrale chronique","Toujours absent","Ipsi à toute lésion"],"r":1,"e":"Lésion centrale chronique → ROT vifs (hyperréflexie, spasticité). Lésion périphérique L3-L4 → ROT abolis.","s":0},{"q":"La rééducation du blessé médullaire vise à :","o":["Récupérer la marche systématiquement","Maximiser autonomie selon niveau lésionnel + prévenir complications","Aucun objectif","Soulager uniquement"],"r":1,"e":"Rééducation : autonomie selon niveau (transferts, fauteuil, AVC, marche si paraplégie incomplète), prévention complications.","s":0},{"q":"Quels espaces et membranes traverse-t-on de l'extérieur vers la moelle ?","o":["Espace épidural, dure-mère, espace sous-dural, arachnoïde, espace sous-arachnoïdien, pie-mère","Dure-mère, pie-mère, arachnoïde, LCR","Pie-mère, arachnoïde, dure-mère, espace épidural","Arachnoïde, dure-mère, pie-mère, espace épidural"],"r":0,"e":"La fiche décrit cette succession ; le LCR occupe l'espace sous-arachnoïdien, juste au-dessus de la pie-mère.","s":0},{"q":"Que contient l'espace épidural ?","o":["De la graisse et des veines","Du LCR","Des racines nerveuses libres uniquement","De la substance blanche"],"r":0,"e":"L'espace épidural est graisseux et veineux ; le LCR est sous-arachnoïdien.","s":0},{"q":"Quel type de neurones les interneurones propriospinaux relient-ils ?","o":["Ils assurent des connexions intra- et intersegmentaires dans la moelle","Ils relient directement le cortex au muscle","Ils relient le cervelet au thalamus","Ils innervent les glandes"],"r":0,"e":"Le système propriospinal, ascendant et descendant, connecte les segments médullaires entre eux.","s":0},{"q":"Que véhicule le faisceau spinothalamique antérieur ?","o":["Le toucher et la pression","La douleur et la température","La proprioception consciente","La sensibilité profonde inconsciente"],"r":0,"e":"Le spinothalamique latéral porte douleur et température, l'antérieur le toucher et la pression.","s":0},{"q":"Que véhiculent les voies spinocérébelleuses ?","o":["La sensibilité profonde inconsciente","La douleur et la température","Le toucher fin épicritique","Les commandes motrices volontaires"],"r":0,"e":"Ces voies portent la proprioception inconsciente vers le cervelet.","s":0},{"q":"À quel âge le contrôle de la miction devient-il supra-médullaire ?","o":["Vers 2 ans","Vers 6 mois","Vers 5 ans","Vers 10 ans"],"r":0,"e":"Le centre S2-S4 fonctionne sur un mode réflexe jusqu'à environ 2 ans, puis le contrôle devient supra-médullaire.","s":0},{"q":"Que désignent les CPG (générateurs centraux de schémas) médullaires ?","o":["Des réseaux assurant la coordination locomotrice automatique","Le centre de la miction","Les voies pyramidales","Les ganglions spinaux"],"r":0,"e":"Les CPG médullaires produisent les schémas rythmiques de la locomotion sans commande corticale permanente.","s":0},{"q":"À quel myotome correspond l'extension du gros orteil ?","o":["L5","L4","S1","L3"],"r":0,"e":"L4 = dorsiflexion, L5 = extension de l'hallux, S1 = flexion plantaire.","s":0},{"q":"À quel myotome correspond l'extension du genou ?","o":["L3","L2","L4","L5"],"r":0,"e":"L2 fléchit la hanche, L3 étend le genou, L4 assure la dorsiflexion.","s":0},{"q":"Quelle durée minimale la définition d'une lésion médullaire retient-elle ?","o":["Plus de 24 heures à 4 semaines","Moins de 24 heures","Plus de 6 mois","Plus de 72 heures seulement"],"r":0,"e":"La fiche définit la lésion médullaire par une atteinte durable, au-delà de 24 heures à 4 semaines.","s":0},{"q":"Quel exemple de lésion intramédullaire la fiche donne-t-elle ?","o":["Les tumeurs gliales et la syringomyélie","Le méningiome et le schwannome","La hernie discale","La métastase vertébrale"],"r":0,"e":"Gliomes et syringomyélie sont intramédullaires ; méningiome et schwannome sont intra-duraux extramédullaires.","s":0},{"q":"Quel exemple de lésion extradurale la fiche donne-t-elle ?","o":["La hernie discale et la métastase","Le schwannome","La syringomyélie","Le méningiome"],"r":0,"e":"Les lésions extradurales siègent hors de la dure-mère : hernie discale, métastase.","s":0},{"q":"Quelles cellules assurent la myélinisation des nerfs dans le SNP ?","o":["Oligodendrocytes","Cellules de Schwann","Astrocytes","Cellules microgliales"],"r":1,"e":"Dans le SNP, ce sont les cellules de Schwann qui myélinisent les axones. Les oligodendrocytes assurent cette fonction dans le SNC.","s":1},{"q":"Comment s'appelle la gaine conjonctive qui entoure CHAQUE fibre nerveuse ?","o":["Endonèvre","Périnèvre","Épinèvre","Mésonèvre"],"r":0,"e":"Endonèvre = chaque fibre. Périnèvre = un faisceau. Épinèvre = le nerf entier.","s":1},{"q":"Quelles affirmations concernant la conduction nerveuse sont VRAIES ?","o":["Avec myéline intacte, la conduction est saltatoire","La vitesse normale est d'environ 400 km/h","La perte de myéline réduit la vitesse à environ 4 km/h","Les nœuds de Ranvier ralentissent la conduction","La conduction est toujours uniforme le long de l'axone"],"r":[0,1,2],"e":"La myéline permet la conduction saltatoire (~400 km/h, de nœud de Ranvier en nœud). Sans myéline, la conduction est ~4 km/h. Les nœuds ne ralentissent pas, ils accélèrent.","s":1},{"q":"Le neurotransmetteur de la jonction neuromusculaire (système somatique) est :","o":["Noradrénaline","Acétylcholine","Dopamine","GABA"],"r":1,"e":"Le système somatique utilise l'acétylcholine (ACh) à la jonction neuromusculaire pour activer le muscle squelettique.","s":1},{"q":"Une compression neurale aiguë avec récupération en environ 10 minutes correspond à :","o":["Neurotmèse","Axonotmèse","Neuropraxie","Ischémie transitoire"],"r":3,"e":"L'ischémie transitoire (stade 0) = anoxie endonévrale aiguë avec paresthésies/déficits réversibles en ~10 min. La neuropraxie est plus longue (jours-semaines).","s":1},{"q":"Concernant la NEUROPRAXIE (Seddon I), quelles affirmations sont correctes ?","o":["Tous les éléments anatomiques sont préservés","Il y a une perte transitoire de conductivité","La sensibilité est généralement plus atteinte que la motricité","La récupération prend des jours à des semaines","Une dégénérescence wallérienne se produit"],"r":[0,1,3],"e":"Neuropraxie : préservation anatomique complète, perte transitoire de conduction, motricité plus touchée que sensibilité, récupération en jours/semaines, PAS de dégénérescence wallérienne.","s":1},{"q":"Quelle est la vitesse moyenne de régénération axonale après une axonotmèse ?","o":["0,1 mm/jour","1–2 mm/jour","1 cm/jour","10 cm/jour"],"r":1,"e":"L'axone régénère à environ 1–2 mm/jour, vitesse qui ralentit avec la distance au corps cellulaire.","s":1},{"q":"La dégénérescence de Waller correspond à :","o":["La régénération axonale après lésion","La dégénérescence de la partie distale d'un axone sectionné","La démyélinisation auto-immune","La formation d'un névrome"],"r":1,"e":"La dégénérescence de Waller est la dégénérescence de la portion distale d'un axone après section ou interruption. Elle prépare la repousse mais plus elle dure, plus la récupération est difficile.","s":1},{"q":"Concernant la NEUROTMÈSE (Seddon III / Sunderland V), quelles propositions sont vraies ?","o":["Division complète du nerf","Tubes neuraux détruits","Récupération généralement totale","Possibilité de formation d'un névrome lors de la régénération","Intervention chirurgicale souvent nécessaire"],"r":[0,1,3,4],"e":"Neurotmèse = section complète, tubes neuraux détruits, formation possible d'un névrome, fonction parfois adéquate mais JAMAIS normale, chirurgie souvent indispensable.","s":1},{"q":"Une mononeuropathie correspond à :","o":["Atteinte symétrique distale et bilatérale","Atteinte d'un seul nerf isolé","Atteinte d'un plexus complet","Atteinte des racines spinales uniquement"],"r":1,"e":"Mononeuropathie = atteinte d'un nerf isolé (ex : canal carpien, paralysie faciale). La polyneuropathie = atteinte symétrique distale bilatérale.","s":1},{"q":"Parmi les pathologies suivantes, lesquelles sont des MONONEUROPATHIES ?","o":["Syndrome du canal carpien","Paralysie faciale (Bell)","Syndrome de Guillain-Barré","Polyneuropathie diabétique","Névralgie du trijumeau"],"r":[0,1,4],"e":"Mononeuropathies = canal carpien, paralysie faciale, névralgie du trijumeau. Guillain-Barré et la polyneuropathie diabétique sont des polyneuropathies.","s":1},{"q":"Une paralysie faciale PÉRIPHÉRIQUE atteint :","o":["Uniquement la moitié inférieure du visage","La totalité d'un hémiface (incluant le front)","Les deux hémifaces","Aucune zone du visage"],"r":1,"e":"La paralysie périphérique (lésion du VII) touche TOUT l'hémiface du même côté (front + bouche). La paralysie centrale épargne le front (innervation bilatérale du frontal).","s":1},{"q":"Une lagophtalmie est :","o":["Une perte du goût","Une incapacité à fermer l'œil","Une larmoiement excessif","Une vision floue"],"r":1,"e":"La lagophtalmie = incapacité à fermer la paupière, signe classique de paralysie faciale périphérique. Elle expose la cornée et nécessite une protection oculaire.","s":1},{"q":"Concernant la paralysie faciale CENTRALE, quelles affirmations sont vraies ?","o":["Lésion au-dessus du noyau du VII","Atteinte préférentielle de la partie inférieure du visage","Front épargné","Souvent associée à un AVC","Perte du goût sur les 2/3 antérieurs de la langue"],"r":[0,1,2,3],"e":"Paralysie centrale : lésion supranucléaire (faisceau pyramidal), atteinte du visage inférieur, front épargné (innervation bilatérale), fréquente après AVC. La perte du goût est un signe périphérique.","s":1},{"q":"Le nerf facial (VII) assure la sensibilité gustative de :","o":["La totalité de la langue","Les 2/3 antérieurs de la langue","Le 1/3 postérieur de la langue","La pointe de la langue uniquement"],"r":1,"e":"Le VII (via la corde du tympan) innerve les 2/3 antérieurs de la langue pour le goût. Le 1/3 postérieur est innervé par le IX (glossopharyngien).","s":1},{"q":"Quelles sont des fonctions du nerf facial (VII) ?","o":["Motricité des muscles de la mimique","Innervation parasympathique des glandes lacrymales","Innervation parasympathique des glandes sublinguales","Innervation des muscles masticateurs","Innervation du muscle stapédien"],"r":[0,1,2,4],"e":"VII = mimique faciale + stapédien (motrice), goût (2/3 ant. langue) et parasympathique pour glandes lacrymales/salivaires sous-maxillaires/sublinguales. Les muscles masticateurs sont innervés par le V.","s":1},{"q":"Le syndrome de Guillain-Barré est une maladie :","o":["Vasculaire","Auto-immune","Tumorale","Génétique"],"r":1,"e":"Guillain-Barré = polyneuropathie auto-immune avec attaque des cellules de Schwann (démyélinisation), souvent post-infectieuse.","s":1},{"q":"Concernant le syndrome de Guillain-Barré, quelles affirmations sont vraies ?","o":["Atteinte ascendante des membres inférieurs vers le haut","Évolution rapide","Risque d'atteinte des muscles respiratoires","Hyperréflexie typique","Traitement par immunoglobulines IV ou plasmaphérèse"],"r":[0,1,2,4],"e":"GBS : faiblesse musculaire ascendante rapide, paresthésies, AREFLEXIE (pas hyperréflexie), risque d'insuffisance respiratoire, traitement = Ig IV, plasmaphérèse, corticoïdes, soins intensifs.","s":1},{"q":"La polyneuropathie diabétique est typiquement :","o":["Asymétrique et proximale","Sensitivo-motrice symétrique distale","Purement motrice","Affectant uniquement les nerfs crâniens"],"r":1,"e":"La polyneuropathie diabétique est sensitivo-motrice, symétrique et distale (mains/pieds en gants/chaussettes). Le pied diabétique en est la complication la plus grave.","s":1},{"q":"Quels sont les mécanismes physiopathologiques de la polyneuropathie diabétique ?","o":["Microangiopathie distale","Ischémie","Glycation des protéines nerveuses","Excès de radicaux libres","Démyélinisation auto-immune"],"r":[0,1,2,3],"e":"PND : microangiopathie → ischémie → glycation des protéines + stress oxydatif (radicaux libres) → dégénérescence axonale et démyélinisation secondaire. L'auto-immunité concerne le GBS, pas le diabète.","s":1},{"q":"De quelles racines naît le plexus brachial ?","o":["C1 à C4","C5 à T1","T2 à T6","L1 à L4"],"r":1,"e":"Le plexus brachial naît des branches antérieures de C5, C6, C7, C8 et T1.","s":1},{"q":"La paralysie d'Erb-Duchenne correspond à une atteinte du :","o":["Tronc supérieur (C5-C6)","Tronc moyen (C7)","Tronc inférieur (C8-T1)","Plexus entier"],"r":0,"e":"Erb-Duchenne = atteinte du tronc supérieur C5-C6, déficit en abduction d'épaule, flexion du coude et rotation externe (paralysie obstétricale classique).","s":1},{"q":"La paralysie de Klumpke correspond à une atteinte du :","o":["Tronc supérieur (C5-C6)","Tronc moyen (C7)","Tronc inférieur (C8-T1)","Nerf radial isolé"],"r":2,"e":"Klumpke = atteinte du tronc inférieur C8-T1, déficit des muscles intrinsèques de la main et flexion des doigts (main en griffe).","s":1},{"q":"Quelles sont des étapes de la régénération axonale ?","o":["Réponse du corps cellulaire (germination)","Allongement guidé par les cellules de Schwann","Cessation et synaptogenèse","Remyélinisation progressive","Apoptose massive obligatoire"],"r":[0,1,2,3],"e":"Régénération axonale en 3 étapes : germination, allongement (guidé par Schwann + facteurs chimiques), cessation/synaptogenèse + remyélinisation. L'apoptose massive n'est pas une étape de la régénération.","s":1},{"q":"Une synkinésie correspond à :","o":["Une paralysie totale d'un muscle","Un mouvement involontaire associé à un mouvement volontaire","Une douleur lors du mouvement","Une atrophie progressive"],"r":1,"e":"Synkinésie = mouvement involontaire qui accompagne un mouvement volontaire (ex : fermer la paupière en souriant). Elle signe une régénération anormale et un mauvais pronostic.","s":1},{"q":"Concernant le tableau récapitulatif des lésions, l'AXONOTMÈSE (Sunderland II) se caractérise par :","o":["Axone interrompu","Endonèvre intact","Périnèvre détruit","Dégénérescence wallérienne","Pronostic excellent en quelques minutes"],"r":[0,1,3],"e":"Axonotmèse Sunderland II : axone interrompu, endonèvre/périnèvre/épinèvre intacts, dégénérescence wallérienne présente, récupération en mois (pas minutes).","s":1},{"q":"Concernant la régénération nerveuse, quelle affirmation est vraie ?","o":["Le SNC régénère mieux que le SNP","Le SNP a une capacité de régénération que le SNC n'a pas","Aucun nerf ne peut régénérer","Seul le SNC peut régénérer"],"r":1,"e":"Le SNP peut régénérer (cellules de Schwann, tubes neuraux préservés guidant la repousse). Le SNC ne régénère pratiquement pas (cicatrice gliale, pas de tubes guides).","s":1},{"q":"Parmi les étiologies de la paralysie faciale, on retrouve :","o":["Idiopathique (Bell)","Virale (zona, herpès)","Bactérienne (Lyme)","Traumatique","Cardiovasculaire ischémique"],"r":[0,1,2,3],"e":"Étiologies de la paralysie faciale : idiopathique (Bell, la plus fréquente), virale, bactérienne (Lyme), traumatique, congénitale, métabolique. La cause cardiovasculaire concerne plutôt la paralysie centrale (AVC).","s":1},{"q":"Une lésion du nerf médian au poignet provoque :","o":["Main en griffe (médian intact)","Atrophie de l'éminence thénar + hypoesthésie 1-2-3-moitié 4","Main de prédicateur","Aucune atteinte"],"r":1,"e":"Lésion médian au poignet (canal carpien évolué) : atrophie thénarienne, déficit sensitif des 3 premiers doigts + moitié 4.","s":1},{"q":"Une lésion du nerf cubital (ulnaire) provoque :","o":["Main en griffe cubitale (4-5 doigts en flexion)","Main de prédicateur","Pied tombant","Aucune atteinte"],"r":0,"e":"Lésion ulnaire : main en griffe cubitale (4e et 5e doigts), atrophie hypothénar et interosseux, déficit sensitif 5e doigt + moitié 4.","s":1},{"q":"Une paralysie du nerf radial provoque :","o":["Main tombante (incapacité d'extension poignet/doigts)","Main en griffe","Pied tombant","Hémiplégie"],"r":0,"e":"Paralysie radiale : « main tombante » par paralysie des extenseurs du poignet et des doigts.","s":1},{"q":"Une paralysie du nerf SPE (sciatique poplité externe) provoque :","o":["Main tombante","Pied tombant (steppage)","Atrophie main","Aucune atteinte"],"r":1,"e":"Paralysie du SPE (péronier commun) : pied tombant → steppage à la marche, déficit éversion + dorsiflexion.","s":1},{"q":"Le syndrome de Guillain-Barré est :","o":["Une lésion centrale","Une polyradiculonévrite aiguë inflammatoire (auto-immune, démyélinisante)","Une myopathie","Une fracture"],"r":1,"e":"GBS = polyradiculonévrite aiguë démyélinisante, post-infectieuse, paralysie ascendante symétrique, aréflexie.","s":1},{"q":"L'évolution typique du Guillain-Barré est :","o":["Permanente","Phase d'extension (3-4 sem) → plateau → récupération en mois","Aiguë mortelle d'emblée","Aucune récupération"],"r":1,"e":"GBS : 3 phases : extension (≤4 sem) → plateau → récupération (mois). Surveillance respi en USI (atteinte phrénique).","s":1},{"q":"La paralysie faciale périphérique se distingue de la centrale par :","o":["Asymétrie inférieure","Atteinte de TOUT l'hémiface (frontale + buccale)","Pas d'atteinte du front","Aucune asymétrie"],"r":1,"e":"Périphérique : atteinte hémiface complète (front + bouche). Centrale : front respecté car innervation bilatérale.","s":1},{"q":"Le syndrome du canal carpien correspond à :","o":["Compression du nerf médian au poignet","Atteinte centrale","Lésion radiale","Atteinte sciatique"],"r":0,"e":"Canal carpien : compression du nerf médian au poignet → paresthésies/hypoesthésie nocturnes pouce-index-majeur, ± atrophie thénar tardive.","s":1},{"q":"L'EMG (électromyographie) permet de :","o":["Mesurer la TA","Évaluer la conduction nerveuse + activité musculaire (lésion neurogène vs myogène)","Mesurer la glycémie","Imager le cerveau"],"r":1,"e":"EMG/ENMG : étude conduction nerveuse + tracé musculaire → atteinte neurogène (axonale, démyélinisante) vs myogène.","s":1},{"q":"La régénération nerveuse périphérique se fait à :","o":["10 mm/jour","1-3 mm/jour (axonale, dégénérescence wallérienne)","100 mm/jour","Pas de régénération"],"r":1,"e":"Régénération axonale ~1-3 mm/jour après dégénérescence wallérienne distale. Centrale = pas de régénération.","s":1},{"q":"À quelle vitesse l'influx circule-t-il sur une fibre à myéline intacte ?","o":["Environ 400 km/h","Environ 4 km/h","Environ 40 km/h","Environ 4 000 km/h"],"r":0,"e":"La fiche oppose 400 km/h avec myéline intacte à 4 km/h après destruction de la myéline.","s":1},{"q":"Quelle caractéristique a l'axone préganglionnaire sympathique ?","o":["Il est peu myélinisé et libère de la noradrénaline en postganglionnaire","Il est très myélinisé et cholinergique","Il n'est pas myélinisé","Il n'existe qu'un seul neurone dans cette voie"],"r":0,"e":"Le sympathique comporte deux neurones, avec un axone préganglionnaire peu myélinisé et de la noradrénaline en aval.","s":1},{"q":"Quels mécanismes lésionnels du nerf périphérique la fiche énumère-t-elle ?","o":["Ischémie, traction, compression, lacération, brûlure","Infection, inflammation, tumeur, toxique, génétique","Étirement, luxation, fracture, œdème, hématome","Dénutrition, déshydratation, hypoxie, acidose, fièvre"],"r":0,"e":"Ces cinq mécanismes sont ceux listés dans la fiche pour les neuropathies traumatiques.","s":1},{"q":"Quelle est l'atteinte anatomique dans l'ischémie transitoire (stade 0) ?","o":["Aucune structure n'est lésée, il s'agit d'une anoxie endonévrale aiguë","L'axone est interrompu","L'endonèvre est détruit","Le nerf est complètement sectionné"],"r":0,"e":"Au stade 0, toutes les structures restent intactes, sans dégénérescence wallérienne, avec récupération en 10 minutes.","s":1},{"q":"Quel type de compression est à l'origine de la neuropraxie ?","o":["Une compression neurale chronique","Une compression aiguë de quelques minutes","Une section franche","Une brûlure profonde"],"r":0,"e":"La neuropraxie résulte d'une compression chronique, alors que le stade 0 correspond à une compression aiguë brève.","s":1},{"q":"Quel est l'état de la sensibilité dans une neuropraxie ?","o":["Généralement préservée, avec parfois des dysesthésies","Toujours abolie","Abolie en gant ou en chaussette","Remplacée par une hyperesthésie constante"],"r":0,"e":"La neuropraxie donne surtout une perte motrice temporaire ; la sensibilité est habituellement conservée.","s":1},{"q":"À quels stades de Sunderland l'axonotmèse correspond-elle ?","o":["Sunderland II à IV","Sunderland I","Sunderland V","Sunderland I et II"],"r":0,"e":"Seddon II = Sunderland II-IV ; Sunderland I est la neuropraxie et V la neurotmèse.","s":1},{"q":"Quelles structures sont détruites dans une axonotmèse de stade IV ?","o":["L'endonèvre et le périnèvre, l'épinèvre restant intact","L'endonèvre seul","Toutes les enveloppes","Aucune enveloppe"],"r":0,"e":"Le stade IV détruit endonèvre et périnèvre mais respecte l'épinèvre, d'où un mauvais pronostic sans section complète.","s":1},{"q":"Quelle différence sépare l'axonotmèse de stade II de celle de stade III ?","o":["Au stade III l'endonèvre est détruit, alors qu'il reste intact au stade II","Au stade III l'axone est intact","Au stade II il n'y a pas de dégénérescence wallérienne","Au stade III l'épinèvre est détruit"],"r":0,"e":"La destruction de l'endonèvre au stade III compromet le guidage de la repousse, d'où une récupération partielle.","s":1},{"q":"De quoi est constitué un névrome après neurotmèse ?","o":["De fibres régénératives, de cellules de Schwann et de fibroblastes","Uniquement de tissu cicatriciel avasculaire","De cellules gliales du SNC","De dépôts amyloïdes"],"r":0,"e":"La repousse désorganisée dans un nerf sectionné forme ce bourgeon fibro-nerveux.","s":1},{"q":"Qu'est-ce qui guide le cône de croissance lors de la régénération axonale ?","o":["Les cellules de Schwann et des facteurs chimiques (angioneurines)","Les oligodendrocytes","Les fibroblastes de l'épinèvre","La myéline résiduelle du segment distal"],"r":0,"e":"Les cellules de Schwann prolifèrent et balisent le trajet, aidées par des facteurs chimiotactiques.","s":1},{"q":"Quelle est la troisième étape de la régénération axonale ?","o":["La cessation de l'allongement et la synaptogenèse avec remyélinisation","La germination à partir du corps cellulaire","L'allongement guidé par le cône de croissance","La dégénérescence wallérienne"],"r":0,"e":"Après la réponse du corps cellulaire et l'allongement, la repousse s'arrête et de nouvelles synapses se forment.","s":1},{"q":"Le thalamus joue principalement le rôle de :","o":["Centre moteur principal","Grand relais sensoriel (sauf olfaction)","Centre du langage","Régulateur hormonal"],"r":1,"e":"Le thalamus est le grand relais sensoriel : TOUTES les afférences sensorielles (sauf olfactives) y font relais avant d'atteindre le cortex.","s":2},{"q":"Quelles structures composent les ganglions de la base ?","o":["Noyau caudé","Putamen","Globus pallidus","Noyau subthalamique","Thalamus"],"r":[0,1,2,3],"e":"Ganglions de la base : noyau caudé + putamen (= striatum), globus pallidus, noyau subthalamique. Le thalamus est une structure distincte mais très liée fonctionnellement.","s":2},{"q":"L'aire de Broca, située dans le lobe frontal, est responsable de :","o":["La compréhension du langage","La production du langage (motrice)","La vision","L'audition"],"r":1,"e":"L'aire de Broca (frontal gauche) = production motrice du langage. L'aire de Wernicke (temporal) = compréhension du langage.","s":2},{"q":"Concernant les lobes cérébraux, quelles correspondances sont correctes ?","o":["Lobe frontal → aire motrice + Broca","Lobe pariétal → somatosensoriel + schéma corporel","Lobe temporal → audition + Wernicke + mémoire","Lobe occipital → vision","Lobe occipital → langage"],"r":[0,1,2,3],"e":"Frontal = motricité + Broca + jugement ; Pariétal = somatosensoriel + schéma corporel ; Temporal = audition + Wernicke + mémoire ; Occipital = vision.","s":2},{"q":"Le système carotidien irrigue principalement :","o":["Les 2/3 antérieurs du cerveau","Le tronc cérébral et le cervelet","Les lobes occipitaux","La moelle épinière"],"r":0,"e":"Système carotidien (circulation antérieure) = 2/3 antérieurs du cerveau. Le système vertébro-basilaire (postérieur) irrigue tronc, cervelet, lobes occipitaux.","s":2},{"q":"Quelles artères naissent directement de l'artère carotide interne ?","o":["Artère cérébrale antérieure (ACA)","Artère cérébrale moyenne (ACM)","Artère ophtalmique","Artère cérébrale postérieure (ACP)","Artère choroïdienne antérieure"],"r":[0,1,2,4],"e":"De l'ACI naissent : ACA, ACM (sa branche principale), ophtalmique, choroïdienne antérieure et communicante postérieure. L'ACP naît du tronc basilaire (vertébro-basilaire).","s":2},{"q":"Le polygone de Willis est :","o":["Un faisceau de fibres motrices","Un réseau anastomotique entre circulations antérieure et postérieure","Une zone du cortex visuel","Une voie sensitive descendante"],"r":1,"e":"Le polygone de Willis est un réseau anastomotique à la base du cerveau qui relie les circulations carotidienne et vertébro-basilaire. Il permet la redistribution du flux en cas d'occlusion.","s":2},{"q":"Un AVC ischémique représente environ quelle proportion de tous les AVC ?","o":["50%","65%","85%","98%"],"r":2,"e":"L'AVC ischémique représente ~85% des AVC. L'AVC hémorragique représente les 15% restants mais a une mortalité plus élevée.","s":2},{"q":"Concernant l'AIT (Accident Ischémique Transitoire), quelles affirmations sont vraies ?","o":["Déficit neurologique focal","Durée < 24h","Lésion visible à l'imagerie","Signe d'alerte d'AVC à venir","Pas besoin de prise en charge"],"r":[0,1,3],"e":"AIT : déficit focal de < 24h SANS lésion à l'imagerie. C'est un signe d'alerte majeur pour un AVC futur — prise en charge urgente nécessaire.","s":2},{"q":"Le traitement de référence d'un AVC ischémique en phase aiguë est :","o":["Anti-hypertenseurs","Thrombolytiques (rTPA) et/ou thrombectomie","Anti-épileptiques","Corticoïdes"],"r":1,"e":"Le traitement aigu de l'AVC ischémique = rTPA (thrombolyse intraveineuse) si <4,5h, et/ou thrombectomie mécanique. Le délai est crucial : 'time is brain'.","s":2},{"q":"Concernant l'évolution clinique après AVC, dans quel ordre apparaissent les phases ?","o":["1. Hypotonie/aréflexie initiale","2. Hypertonie et co-contraction (spasticité)","3. Modèles synergiques de mouvement","4. Spasticité immédiate dès le début","5. Hypotonie permanente sans récupération"],"r":[0,1,2],"e":"Évolution AVC : phase 1 = hypotonie/aréflexie (choc) → phase 2 = hypertonie/spasticité → phase 3 = mouvements synergiques puis sélectifs. Pas de spasticité immédiate.","s":2},{"q":"Un hématome épidural se développe typiquement en :","o":["Quelques minutes","Quelques heures","Plusieurs jours","Plusieurs mois"],"r":1,"e":"Hématome épidural : développement en quelques HEURES (souvent par rupture de l'artère méningée moyenne). Sous-dural subaigu = jours, sous-dural chronique = mois.","s":2},{"q":"Concernant la maladie de Parkinson, quelles affirmations sont vraies ?","o":["Dégénérescence de la substance noire","Perte des récepteurs dopaminergiques","Hyperréflexie typique","Tremblement au REPOS","Bradykinésie"],"r":[0,1,3,4],"e":"Parkinson : dégénérescence dopaminergique de la substance noire → bradykinésie, tremblement de REPOS, rigidité, instabilité posturale. Les réflexes ne sont PAS hyperactifs.","s":2},{"q":"La rigidité 'en roue dentée' est typique de quelle maladie ?","o":["Sclérose en plaques","Maladie de Parkinson","Syndrome de Guillain-Barré","Maladie d'Alzheimer"],"r":1,"e":"La rigidité en roue dentée (résistance saccadée à la mobilisation passive) est un signe cardinal de la maladie de Parkinson, avec la bradykinésie et le tremblement de repos.","s":2},{"q":"Parmi les signes moteurs de Parkinson, on retrouve :","o":["Bradykinésie","Micrographie","Amimie (visage figé)","Marche à grands pas avec ballant","Freezing"],"r":[0,1,2,4],"e":"Signes moteurs Parkinson : bradykinésie, micrographie, amimie, hypophonie, marche à PETITS pas (festination, perte du ballant), freezing, tremblement de repos.","s":2},{"q":"Le traitement médicamenteux principal de la maladie de Parkinson est :","o":["Lévodopa","Corticoïdes","Antiépileptiques","Interférons"],"r":0,"e":"La lévodopa (souvent associée à la carbidopa) est le traitement de référence : précurseur de la dopamine qui passe la barrière hémato-encéphalique.","s":2},{"q":"Les '5 A' de la démence comprennent :","o":["Amnésie","Anomie","Apraxie","Agnosie","Aphasie","Ataxie"],"r":[0,1,2,3,4],"e":"Les 5 A de la démence : Amnésie (mémoire), Anomie (oubli des mots), Apraxie (gestes), Agnosie (reconnaissance), Aphasie (langage). L'ataxie est un trouble de la coordination d'origine cérébelleuse ou proprioceptive, hors du champ des « 5 A » cognitifs.","s":2},{"q":"Concernant la physiopathologie de la maladie d'Alzheimer, quelles affirmations sont correctes ?","o":["Formation de plaques amyloïdes (Aβ)","Tresses neurofibrillaires (protéine tau)","Démyélinisation auto-immune","Dégénérescence dopaminergique","Réponse des astrocytes et de la microglie"],"r":[0,1,4],"e":"Alzheimer : plaques amyloïdes (Aβ) extracellulaires + tresses neurofibrillaires (tau) intracellulaires + neuroinflammation. La démyélinisation = SEP, la dégénérescence dopaminergique = Parkinson.","s":2},{"q":"La sclérose en plaques (SEP) est :","o":["Une maladie auto-immune attaquant les oligodendrocytes","Une maladie vasculaire","Une maladie tumorale","Une maladie génétique transmise au mode dominant"],"r":0,"e":"SEP = maladie auto-immune attaquant les oligodendrocytes (cellules myélinisantes du SNC) → démyélinisation de la substance blanche par plaques disséminées dans le temps et l'espace.","s":2},{"q":"Quels facteurs peuvent aggraver ou déclencher une poussée de SEP ?","o":["Chaleur","Stress","Effort physique","Infections","Repos prolongé"],"r":[0,1,2,3],"e":"Facteurs aggravants/déclenchants de SEP : chaleur (signe d'Uhthoff), stress, effort physique, infections. Le repos n'est pas un déclencheur.","s":2},{"q":"La SLA (sclérose latérale amyotrophique) atteint :","o":["Le motoneurone uniquement","Les motoneurones 1er ET 2e","La sensibilité uniquement","La cognition uniquement"],"r":1,"e":"La SLA atteint à la fois le motoneurone supérieur (1er, central) ET le motoneurone inférieur (2e, périphérique). La sensibilité et la cognition restent INTACTES — paralysie progressive sans déficit sensitif.","s":2},{"q":"La myasthénie grave est due à :","o":["Une attaque auto-immune des récepteurs à l'acétylcholine","Une dégénérescence de la substance noire","Une démyélinisation du SNC","Une atteinte vasculaire"],"r":0,"e":"La myasthénie grave est une maladie auto-immune ciblant les récepteurs nicotiniques à l'acétylcholine de la jonction neuromusculaire. D'où la fatigabilité musculaire fluctuante.","s":2},{"q":"Quels sont les signes du SYNDROME CÉRÉBELLEUX ?","o":["Ataxie","Hypotonie","Dysmétrie","Dysarthrie","Hypertonie spastique"],"r":[0,1,2,3],"e":"Syndrome cérébelleux : ataxie, dysmétrie, dysdiadococinésie, dysarthrie, tremblement intentionnel, hypotonie. L'hypertonie spastique signe une atteinte pyramidale, PAS cérébelleuse.","s":2},{"q":"Quel examen offre la meilleure résolution SPATIALE pour visualiser les structures molles du cerveau ?","o":["EEG","EMG","TDM (scanner)","IRM"],"r":3,"e":"L'IRM offre la meilleure résolution spatiale pour les tissus mous (matière blanche/grise, lésions). L'EEG a la meilleure résolution TEMPORELLE.","s":2},{"q":"En urgence pour un AVC suspecté, quel examen est réalisé en premier ?","o":["EEG","EMG","TDM cérébrale (scanner)","IRMf"],"r":2,"e":"En urgence AVC : TDM cérébrale d'abord (rapide, accessible, élimine l'hémorragie). L'IRM peut être réalisée ensuite pour mieux visualiser l'ischémie aiguë.","s":2},{"q":"Parmi les principes de la NEUROPLASTICITÉ, on retrouve :","o":["Use it or lose it (utiliser ou perdre)","Specificity (spécificité de l'entraînement)","Repetition (milliers de répétitions nécessaires)","Salience (émotion et motivation)","Le repos absolu favorise la récupération"],"r":[0,1,2,3],"e":"Neuroplasticité (10 principes) : use it or lose it, use it & improve it, specificity, repetition, intensity, time, salience, age, transference, interference. Le repos absolu n'en fait PAS partie.","s":2},{"q":"Une crise d'épilepsie 'petit mal' (absence) se caractérise par :","o":["Convulsions tonico-cloniques généralisées","Regard perdu de 10-30 secondes sans chute","Paralysie d'un hémicorps","Perte définitive de conscience"],"r":1,"e":"L'absence (petit mal) = brève suspension de conscience (10-30 sec) avec regard fixe, sans convulsions ni chute. Surtout chez l'enfant.","s":2},{"q":"Quelles affirmations sur la VASCULARISATION cérébrale sont vraies ?","o":["L'ACM est la branche principale de l'ACI","Le système vertébro-basilaire irrigue le tronc et le cervelet","La PICA est la plus grande branche de l'artère vertébrale","L'ACP naît directement de la carotide interne","Le polygone de Willis relie les deux systèmes"],"r":[0,1,2,4],"e":"ACM = branche principale de l'ACI ; système vertébro-basilaire = tronc/cervelet/occipital ; PICA = grande branche de l'artère vertébrale ; polygone de Willis relie carotidien et vertébro-basilaire. L'ACP naît du tronc basilaire, PAS de l'ACI.","s":2},{"q":"L'AVC ischémique représente :","o":["10% des AVC","30% des AVC","~80% des AVC","100%"],"r":2,"e":"AVC : 80% ischémiques (occlusion artérielle), 20% hémorragiques (rupture vasculaire).","s":2},{"q":"La fenêtre thérapeutique pour la thrombolyse IV (rt-PA) dans l'AVC ischémique est de :","o":["1 heure","4h30","12 heures","24 heures"],"r":1,"e":"Thrombolyse IV (rt-PA) : ≤ 4h30 après début des symptômes. Thrombectomie possible jusqu'à 6-24h selon imagerie.","s":2},{"q":"Une hémiplégie droite + aphasie de Broca évoque une lésion :","o":["Cervelet droit","Hémisphère gauche (faisceau pyramidal + Broca)","Tronc cérébral","Médullaire"],"r":1,"e":"Hémisphère gauche dominant : moteur droit (pyramidal croisé) + langage (Broca). AVC sylvien gauche.","s":2},{"q":"Le signe de Babinski (extension du gros orteil) traduit :","o":["Réflexe normal","Atteinte du faisceau pyramidal (1er motoneurone)","Atteinte cérébelleuse","Lésion sensitive"],"r":1,"e":"Babinski + = atteinte du faisceau pyramidal (cortico-spinal), signe d'atteinte 1er motoneurone.","s":2},{"q":"L'hémorragie sous-arachnoïdienne (HSA) est typiquement due à :","o":["Hypertension","Rupture d'anévrisme cérébral","AVC ischémique","Tumeur"],"r":1,"e":"HSA : 80% par rupture d'anévrisme. Céphalée brutale en coup de tonnerre + raideur méningée.","s":2},{"q":"Un hématome extra-dural est typiquement causé par :","o":["Rupture d'anévrisme","Rupture de l'artère méningée moyenne après TC","AVC","Tumeur"],"r":1,"e":"Hématome EDL : entre l'os et la dure-mère, rupture art. méningée moyenne, intervalle libre puis aggravation.","s":2},{"q":"L'intervalle libre est caractéristique :","o":["De l'AVC ischémique","De l'hématome extra-dural traumatique","De la tumeur","De la méningite"],"r":1,"e":"Intervalle libre (lucidité initiale puis aggravation) = signe classique de l'hématome EDL après TC.","s":2},{"q":"L'œdème cérébral entraîne :","o":["↓ pression intracrânienne","↑ pression intracrânienne (PIC) → engagement","Aucun effet","Hyperventilation"],"r":1,"e":"Œdème → ↑ PIC → triade de Cushing (HTA, bradycardie, irrégularité respi), risque d'engagement et mort cérébrale.","s":2},{"q":"Les facteurs de risque modifiables d'AVC incluent :","o":["HTA","Diabète","Dyslipidémie","Tabac","FA / cardiopathie","Âge","Sexe masculin"],"r":[0,1,2,3,4],"e":"Modifiables : HTA (#1), diabète, dyslipidémie, tabac, FA, obésité, sédentarité. Non modifiables : âge, sexe, génétique.","s":2},{"q":"L'hémianopsie latérale homonyme correspond à :","o":["Perte de la vision d'un œil","Perte du même hémichamp visuel des deux yeux","Vision floue","Strabisme"],"r":1,"e":"Hémianopsie latérale homonyme = perte du même hémichamp des deux yeux, lésion rétro-chiasmatique (radiations optiques, V1).","s":2},{"q":"Quelles structures composent le système limbique selon la fiche ?","o":["Amygdale, hippocampe, fornix et hypothalamus","Thalamus, épithalamus et subthalamus","Noyau caudé, putamen et globus pallidus","Mésencéphale, pont et bulbe"],"r":0,"e":"Le système limbique associe ces quatre structures et gère comportements, mémoire émotionnelle et motivation.","s":2},{"q":"Quelle particularité de latéralité caractérise le cervelet ?","o":["Ses fibres sont ipsilatérales","Ses fibres sont toutes croisées","Il n'a aucune connexion latéralisée","Il ne reçoit que des fibres controlatérales"],"r":0,"e":"Le cervelet agit sur l'hémicorps du même côté, contrairement au cortex moteur.","s":2},{"q":"Quel rôle la fiche attribue-t-elle aux ganglions de la base ?","o":["L'idéalisation du mouvement","L'exécution directe du mouvement","Le relais de toutes les informations sensorielles","La production du LCR"],"r":0,"e":"Les noyaux gris centraux préparent et modulent le mouvement via les voies directe et indirecte ; le relais sensoriel est thalamique.","s":2},{"q":"Quel élément des ganglions de la base la fiche décrit-elle comme inhibiteur ?","o":["Le globus pallidus","Le noyau caudé","Le putamen","Le noyau subthalamique"],"r":0,"e":"Le globe pâle est le versant inhibiteur du dispositif ; caudé et putamen forment le striatum d'entrée.","s":2},{"q":"Quelles fonctions le lobe pariétal assure-t-il ?","o":["Somesthésie, schéma corporel et intelligence spatiale","Audition et compréhension du langage","Traitement visuel et reconnaissance d'objets","Pensée, jugement et production du langage"],"r":0,"e":"Le pariétal est somatosensoriel et spatial ; Wernicke est temporale et Broca frontale.","s":2},{"q":"Quelles fibres de substance blanche relient les deux hémisphères ?","o":["Les fibres commissurales","Les fibres d'association","Les fibres de projection","Les fibres perforantes"],"r":0,"e":"Les commissurales traversent la ligne médiane, les fibres d'association restent dans un hémisphère.","s":2},{"q":"Quelle proportion du cerveau le système carotidien irrigue-t-il ?","o":["Les deux tiers antérieurs","Le tiers postérieur","La totalité","Le cervelet et le tronc"],"r":0,"e":"La circulation antérieure carotidienne couvre les deux tiers antérieurs ; le système vertébro-basilaire irrigue tronc, cervelet et lobes occipitaux.","s":2},{"q":"Quelle est la branche principale de l'artère carotide interne ?","o":["L'artère cérébrale moyenne (ACM), qui suit le sillon silvien","L'artère cérébrale postérieure","L'artère basilaire","La PICA"],"r":0,"e":"L'ACM est la branche terminale principale de l'ACI et chemine dans la vallée sylvienne.","s":2},{"q":"Quelle est la plus grande branche de l'artère vertébrale ?","o":["La PICA","L'AICA","L'ACS","L'artère spinale antérieure"],"r":0,"e":"La PICA (cérébelleuse postéro-inférieure) est la plus grande branche de la vertébrale.","s":2},{"q":"Quel est l'intérêt fonctionnel du polygone de Willis ?","o":["Permettre la redistribution du flux sanguin en cas d'occlusion","Filtrer le LCR","Réguler la pression intracrânienne","Assurer le drainage veineux"],"r":0,"e":"Ce réseau anastomotique relie circulations antérieure et postérieure et supplée une occlusion.","s":2},{"q":"Quelles artères relie l'artère communicante postérieure ?","o":["La carotide interne et l'artère cérébrale postérieure","Les deux artères cérébrales antérieures","Les deux artères vertébrales","L'artère basilaire et l'ACM"],"r":0,"e":"L'AComP referme le polygone en arrière ; l'AComA relie les deux cérébrales antérieures.","s":2},{"q":"Quelles altérations primaires la fiche décrit-elle après lésion cérébrale ?","o":["Baisse du nombre d'unités motrices et de la fréquence de décharge, baisse de force, timing d'activation modifié","Rétractions musculaires et désalignement des fibres","Modifications de la coaptation articulaire","Complications respiratoires"],"r":0,"e":"Les altérations citées en premier sont primaires ; rétractions, atteintes articulaires et complications respiratoires sont secondaires.","s":2},{"q":"Quelles structures composent le Système Nerveux Central (SNC) ?","o":["Nerfs et ganglions","Encéphale et moelle épinière","Encéphale, moelle et nerfs crâniens","Cerveau seul"],"r":1,"e":"Le SNC = encéphale (cerveau, cervelet, tronc cérébral) + moelle épinière. Les nerfs et ganglions appartiennent au SNP.","s":3},{"q":"Combien de paires de nerfs crâniens et de nerfs rachidiens compte-t-on respectivement ?","o":["10 paires crâniennes et 30 paires rachidiennes","12 paires crâniennes et 31 paires rachidiennes","12 paires crâniennes et 33 paires rachidiennes","8 paires crâniennes et 31 paires rachidiennes"],"r":1,"e":"12 paires de nerfs crâniens (voie corticobulbaire) et 31 paires de nerfs rachidiens (voie cortico-spinale).","s":3},{"q":"Parmi les structures suivantes, lesquelles font partie de l'encéphale ?","o":["Cerveau","Cervelet","Tronc cérébral","Moelle épinière","Ganglions"],"r":[0,1,2],"e":"L'encéphale comprend cerveau + cervelet + tronc cérébral. La moelle épinière fait partie du SNC mais pas de l'encéphale. Les ganglions sont dans le SNP.","s":3},{"q":"Concernant le système nerveux autonome (viscéral), quelles affirmations sont vraies ?","o":["Il innerve les muscles squelettiques","Il innerve les muscles lisses, le cœur et les glandes","Il comprend le système sympathique et parasympathique","Il est volontaire","Il a une composante afférente (viscérocepteurs)"],"r":[1,2,4],"e":"Le SN autonome est involontaire. Il innerve muscles lisses/cœur/glandes. Il comprend sympathique (combat/fuite) et parasympathique (repos/digestion). Les muscles squelettiques relèvent du SN somatique.","s":3},{"q":"Quelle est la fonction principale du cervelet ?","o":["Fonctions cognitives supérieures","Coordination et équilibre","Fonctions vitales (respiration, rythme cardiaque)","Relais sensitif et moteur"],"r":1,"e":"Le cervelet est responsable de la coordination motrice et de l'équilibre. Les fonctions cognitives = cerveau ; les fonctions vitales = tronc cérébral.","s":3},{"q":"Le système sympathique est associé à :","o":["La digestion et le repos","Le combat ou la fuite","La sécrétion lacrymale","Le ralentissement cardiaque"],"r":1,"e":"Le sympathique correspond à la réaction « combat ou fuite » : dilatation pupillaire, accélération cardiaque, dilatation bronchique, sécrétion d'adrénaline.","s":3},{"q":"Parmi les nerfs crâniens suivants, lesquels sont purement SENSITIFS ?","o":["I — Olfactif","II — Optique","V — Trijumeau","VIII — Vestibulocochléaire","XII — Hypoglosse"],"r":[0,1,3],"e":"Les nerfs sensitifs purs sont I (olfactif), II (optique) et VIII (vestibulocochléaire). Le V (trijumeau) est mixte. Le XII (hypoglosse) est moteur.","s":3},{"q":"Quel nerf crânien innerve les muscles de la langue ?","o":["IX — Glossopharyngien","X — Vague","XI — Accessoire","XII — Hypoglosse"],"r":3,"e":"Le XII (hypoglosse) est moteur pour les muscles de la langue. Une déviation de la langue à la protraction = lésion du XII homolatéral.","s":3},{"q":"Quel nerf crânien évalue-t-on en demandant au patient de sourire, fermer les yeux fortement et froncer les sourcils ?","o":["V — Trijumeau","VII — Facial","IX — Glossopharyngien","XI — Spinal"],"r":1,"e":"Le VII (facial) innerve les muscles de la mimique. Tester : sourire, fermer paupières, froncer sourcils, gonfler les joues.","s":3},{"q":"Quelles sont les fonctions du nerf vague (X) ?","o":["Innervation cardiaque","Innervation des bronches","Innervation du tube digestif","Mouvement des yeux","Audition"],"r":[0,1,2],"e":"Le X (vague/pneumogastrique) innerve cœur, bronches et tube digestif (parasympathique). Le mouvement des yeux relève des III, IV, VI ; l'audition du VIII.","s":3},{"q":"Sur l'échelle de Glasgow, quel est le score minimum possible ?","o":["0","1","3","5"],"r":2,"e":"Le score de Glasgow va de 3 (minimum) à 15 (maximum). Le minimum de 3 correspond à 1 (oculaire) + 1 (verbal) + 1 (moteur).","s":3},{"q":"Un score de Glasgow ≤ 8 correspond à :","o":["Un traumatisme léger","Un traumatisme modéré","Un traumatisme sévère / coma","Une conscience normale"],"r":2,"e":"Glasgow 13-15 = traumatisme léger ; 9-12 = modéré ; ≤ 8 = sévère, coma.","s":3},{"q":"Concernant la cotation 0-5 de la force musculaire, quelles propositions sont exactes ?","o":["0 = aucune contraction","2 = mouvement contre gravité","3 = mouvement contre gravité (sans résistance)","4 = mouvement contre résistance","5 = aucune force"],"r":[0,2,3],"e":"0 = aucune contraction ; 1 = contraction visible ; 2 = mouvement SANS gravité ; 3 = mouvement CONTRE gravité ; 4 = contre résistance ; 5 = force normale.","s":3},{"q":"Une spasticité (hypertonie) signe une atteinte de :","o":["La corne antérieure de la moelle","La voie pyramidale","Le nerf périphérique","La jonction neuromusculaire"],"r":1,"e":"Spasticité = hypertonie élastique signant une atteinte de la voie pyramidale (motoneurone supérieur). La corne antérieure / SNP donnent une hypotonie.","s":3},{"q":"Une hypotonie + aréflexie + atrophie musculaire évoque :","o":["Une lésion du SNP","Une lésion de la voie pyramidale","Une lésion du cervelet","Une lésion thalamique"],"r":0,"e":"Le syndrome neurogène périphérique = hypotonie + aréflexie + atrophie + fasciculations. Atteinte du motoneurone inférieur ou du nerf périphérique.","s":3},{"q":"Parmi les éléments suivants, lesquels font partie de l'évaluation de la sensibilité de BASE ?","o":["Sensibilité douloureuse (piqûre)","Sensibilité vibratoire (diapason)","Stéréognosie","Proprioception","Graphesthésie"],"r":[0,1,3],"e":"Sensibilité de base : douloureuse, vibratoire, proprioceptive, tactile. Stéréognosie et graphesthésie relèvent de la sensibilité DISCRIMINATIVE.","s":3},{"q":"Le réflexe rotulien explore principalement la racine :","o":["L2","L4","S1","C7"],"r":1,"e":"Réflexe rotulien = L4. Achilléen = S1. Bicipital = C5-C6. Tricipital = C7.","s":3},{"q":"Le test de Romberg permet d'évaluer :","o":["La force musculaire","La coordination cérébelleuse pure","L'équilibre proprioceptif","Les réflexes ostéo-tendineux"],"r":2,"e":"Le test de Romberg (debout pieds joints, yeux fermés) évalue l'équilibre proprioceptif. Une chute aux yeux fermés = ataxie sensitive (proprioceptive).","s":3},{"q":"Quels sont les tests cérébelleux classiques ?","o":["Épreuve doigt-nez","Épreuve talon-genou","Mouvements alternés rapides (diadococinésie)","Test de Romberg yeux fermés","Réflexe cutané plantaire"],"r":[0,1,2],"e":"Tests cérébelleux : doigt-nez, talon-genou, mouvements alternés rapides (dysdiadococinésie). Le Romberg explore la proprioception, pas le cervelet pur. Le réflexe cutané plantaire explore la voie pyramidale.","s":3},{"q":"Quels sont les signes d'irritation méningée ?","o":["Raideur de nuque","Signe de Brudzinski","Signe de Kernig","Signe de Babinski","Signe de Lasègue"],"r":[0,1,2],"e":"Signes méningés : raideur de nuque, Brudzinski (flexion des hanches lors de la flexion du cou), Kernig. Babinski = atteinte pyramidale ; Lasègue = sciatalgie.","s":3},{"q":"Une marche en circumduction du membre inférieur, avec bras fléchi en écharpe, évoque :","o":["Une marche parkinsonienne","Une marche hémiplégique","Une ataxie cérébelleuse","Un steppage"],"r":1,"e":"Cette description = marche hémiplégique (lésion vasculaire du SNC controlatéral). Parkinson = petits pas/festination ; cérébelleuse = ébrieuse ; steppage = relevé du pied.","s":3},{"q":"Le steppage (footdrop) est dû à :","o":["Une atteinte du cervelet","Une paralysie des releveurs du pied","Une lésion parkinsonienne","Une lésion du nerf vague"],"r":1,"e":"Le steppage = paralysie des releveurs du pied (souvent atteinte du nerf fibulaire/sciatique poplité externe). Le patient soulève exagérément le genou pour ne pas accrocher l'orteil.","s":3},{"q":"Le topodiagnostic correspond à :","o":["Le diagnostic du mécanisme physiopathologique","Le diagnostic de la localisation anatomique de la lésion","Le diagnostic étiologique","Le diagnostic de gravité"],"r":1,"e":"Topodiagnostic = diagnostic de la LOCALISATION anatomique d'une lésion à partir des signes/symptômes.","s":3},{"q":"Associez correctement type de lésion et exemple :","o":["Focale → AVC ischémique","Multifocale → SEP (sclérose en plaques)","Diffuse → Encéphalite","Systématisée → SLA","Focale → Méningite"],"r":[0,1,2,3],"e":"Focale = 1 zone (AVC) ; Multifocale = plusieurs zones distinctes (SEP) ; Diffuse = ensemble du cerveau (encéphalite) ; Systématisée = système fonctionnel (SLA = motoneurone). La méningite est diffuse, pas focale.","s":3},{"q":"Un déficit sensitif en « gant » ou « chaussette » est typique de :","o":["Une lésion médullaire","Une lésion cérébrale corticale","Une atteinte des nerfs périphériques (polyneuropathie)","Une atteinte cérébelleuse"],"r":2,"e":"La distribution en gant et chaussette est caractéristique des polyneuropathies (atteinte distale et symétrique des nerfs périphériques, ex : neuropathie diabétique).","s":3},{"q":"Une lésion cérébrale focale peut être d'origine :","o":["Vasculaire (AVC)","Tumorale","Traumatique","Inflammatoire (méningite)","Démyélinisante","Carence en vitamine B12"],"r":[0,1,2,3,4],"e":"Les pathologies cérébrales focales possibles sont : vasculaires, tumorales, traumatiques, inflammatoires, démyélinisantes, toxiques/métaboliques. Toutes ces propositions sont correctes. La carence en B12 provoque une atteinte diffuse (sclérose combinée de la moelle, neuropathie), pas une lésion focale.","s":3},{"q":"Le MMSE (Mini-Mental State Examination) est utilisé pour :","o":["Évaluer la force musculaire","Dépister les démences (score /30)","Mesurer la spasticité","Évaluer la coordination"],"r":1,"e":"Le MMSE est un outil de dépistage des troubles cognitifs / démences, scoré sur 30. Le MoCA est plus sensible aux atteintes cognitives légères.","s":3},{"q":"Combien de paires de nerfs crâniens existe-t-il ?","o":["8","10","12","14"],"r":2,"e":"12 paires crâniennes (numérotées I à XII).","s":3},{"q":"Combien de paires de nerfs rachidiens existe-t-il ?","o":["12","24","31","42"],"r":2,"e":"31 paires rachidiennes : 8 cervicales, 12 thoraciques, 5 lombaires, 5 sacrées, 1 coccygienne.","s":3},{"q":"Le tronc cérébral comprend :","o":["Mésencéphale","Pont (protubérance)","Bulbe (moelle allongée)","Cervelet","Hypothalamus"],"r":[0,1,2],"e":"Tronc cérébral = mésencéphale + pont + bulbe. Cervelet est postérieur, hypothalamus dans le diencéphale.","s":3},{"q":"Le système nerveux sympathique est responsable de :","o":["Repos / digestion","Combat ou fuite (mobilisation des ressources)","Régulation thyroïdienne","Sécrétion biliaire"],"r":1,"e":"Sympathique = « combat ou fuite » : ↑ FC, dilatation pupille, dilatation bronches, ↑ sécrétion adrénaline.","s":3},{"q":"Le nerf X (vague) innerve :","o":["Les muscles oculaires","Le cœur, les bronches, le tube digestif","Les muscles faciaux uniquement","Les muscles de la langue"],"r":1,"e":"X (vague) : innervation parasympathique cœur, bronches, tube digestif. Atteinte → dysphonie, dysphagie.","s":3},{"q":"Le nerf trijumeau (V) est :","o":["Sensitif pur","Moteur pur","Mixte (sensibilité face + mastication)","Olfactif"],"r":2,"e":"V trijumeau = mixte : sensibilité de la face + muscles de la mastication.","s":3},{"q":"L'aphasie de Broca affecte :","o":["La compréhension","L'expression du langage (langage non fluent)","La motricité","La vision"],"r":1,"e":"Broca (aire frontale gauche) = aphasie d'expression : discours laborieux, télégraphique. Compréhension préservée.","s":3},{"q":"L'aphasie de Wernicke affecte :","o":["La compréhension du langage (discours fluent mais incohérent)","L'expression motrice","La motricité","La marche"],"r":0,"e":"Wernicke (aire temporale gauche) = aphasie de compréhension : parole fluente mais paragraphies, anosognosie.","s":3},{"q":"L'échelle de Glasgow va de :","o":["0 à 10","3 à 15","1 à 20","0 à 100"],"r":1,"e":"Glasgow : 3 (coma profond) à 15 (conscience normale) : oculaire (1-4) + verbale (1-5) + motrice (1-6).","s":3},{"q":"Un score de Glasgow ≤ 8 définit :","o":["Une conscience normale","Un coma","Une confusion légère","Une mort cérébrale"],"r":1,"e":"GCS ≤ 8 = coma (intubation à envisager pour protection des voies aériennes).","s":3},{"q":"Quelle voie est associée aux 12 paires crâniennes ?","o":["La voie corticobulbaire","La voie cortico-spinale","La voie spino-thalamique","La voie lemniscale"],"r":0,"e":"La fiche associe les paires crâniennes à la voie corticobulbaire et les 31 paires rachidiennes à la voie cortico-spinale.","s":3},{"q":"Quels récepteurs sont concernés par la branche afférente du SN somatique ?","o":["Les extérocepteurs (peau, organes des sens)","Les viscérocepteurs","Les barorécepteurs artériels","Les chémorécepteurs centraux"],"r":0,"e":"Le somatique afférent part des extérocepteurs ; le viscéral afférent part des viscérocepteurs.","s":3},{"q":"Quel effet le parasympathique exerce-t-il sur le flux salivaire et lacrymal ?","o":["Il le stimule","Il l'inhibe","Il n'a aucun effet","Il le stimule puis l'inhibe"],"r":0,"e":"Le parasympathique stimule les sécrétions salivaire et lacrymale ; le sympathique inhibe le flux salivaire.","s":3},{"q":"Comment teste-t-on cliniquement le nerf olfactif (I) ?","o":["En faisant identifier des odeurs les yeux fermés","Par le fond d'œil","Par le réflexe pupillaire","Par le réflexe nauséeux"],"r":0,"e":"Le test du I repose sur l'identification d'odeurs ; le fond d'œil explore le II et le réflexe nauséeux le IX.","s":3},{"q":"Quel mouvement oculaire le nerf trochléaire (IV) commande-t-il ?","o":["Le mouvement vers le bas et vers l'intérieur","L'abduction du globe","L'élévation de la paupière","La convergence pure"],"r":0,"e":"Le IV dirige l'œil en bas et en dedans ; l'abduction relève du VI.","s":3},{"q":"Quels tests explorent le nerf vestibulocochléaire (VIII) ?","o":["Weber, Rinne et Romberg","Doigt-nez et talon-genou","Kernig et Brudzinski","Le réflexe nauséeux"],"r":0,"e":"Weber et Rinne testent l'audition, Romberg l'équilibre proprioceptif et vestibulaire.","s":3},{"q":"Quel signe clinique traduit une lésion du nerf hypoglosse (XII) ?","o":["Une déviation de la langue à la protraction","Une dysphonie","Une lagophtalmie","Une chute de l'épaule"],"r":0,"e":"La langue dévie du côté lésé ; la dysphonie évoque le X et la chute d'épaule le XI.","s":3},{"q":"Comment la fiche définit-elle la léthargie ?","o":["Une somnolence marquée","Une confusion avec agitation motrice","Un réveil bref aux stimuli","Une impossibilité de réveiller le patient"],"r":0,"e":"La léthargie est une somnolence marquée ; la stupeur permet un réveil bref et le coma aucun.","s":3},{"q":"Quel niveau de conscience associe confusion et agitation motrice ?","o":["Le délire","La léthargie","La stupeur","Le coma"],"r":0,"e":"Le délire combine confusion et agitation ; la confusion simple se limite à des réponses inappropriées.","s":3},{"q":"Que teste la gnosie ?","o":["La reconnaissance d'objets","La capacité motrice","La mémoire de travail","L'orientation temporelle"],"r":0,"e":"La gnosie est la reconnaissance ; la praxie désigne la capacité motrice.","s":3},{"q":"Sur quel total le MMSE est-il coté ?","o":["30","15","20","100"],"r":0,"e":"Le Mini-Mental State Examination est coté sur 30 points ; l'échelle de Glasgow va de 3 à 15.","s":3},{"q":"À quel score de Glasgow correspond la réponse motrice « localise la douleur » ?","o":["5","6","4","3"],"r":0,"e":"Obéir aux ordres vaut 6, localiser la douleur 5, le retrait 4 et la décortication 3.","s":3},{"q":"Que vaut en réponse motrice une extension (décérébration) sur l'échelle de Glasgow ?","o":["2","3","1","4"],"r":0,"e":"L'extension en décérébration vaut 2, la flexion en décortication 3, l'absence de réponse 1.","s":3},{"q":"Concernant l'unité fonctionnelle du SN (le neurone), quelle proposition est exacte ?","o":["Il a plusieurs axones et une seule dendrite","Il a une seule dendrite et un seul axone","Il a plusieurs dendrites et un seul axone","Il n'a ni dendrite ni axone"],"r":2,"e":"Un neurone possède PLUSIEURS dendrites (qui amènent l'influx au corps cellulaire) mais UN SEUL axone (qui conduit l'influx loin du corps cellulaire).","s":4},{"q":"Combien de paires de nerfs spinaux compose le SNP ?","o":["12","24","31","33"],"r":2,"e":"31 paires : 8 cervicales (C1-C8), 12 thoraciques (T1-T12), 5 lombaires (L1-L5), 5 sacrées (S1-S5), 1 coccygienne.","s":4},{"q":"Concernant les MÉNINGES, quelles affirmations sont vraies ?","o":["La dure-mère est la couche externe","L'arachnoïde est avasculaire","La pie-mère est vasculaire et adhère au tissu cérébral","La pie-mère est la couche externe","Le LCR circule dans l'espace épidural"],"r":[0,1,2],"e":"Dure-mère = externe (résistante). Arachnoïde = moyenne, AVASCULAIRE. Pie-mère = interne, VASCULAIRE, accolée au tissu. Le LCR circule dans l'espace SOUS-ARACHNOÏDIEN, pas épidural.","s":4},{"q":"Le LCR (liquide céphalo-rachidien) circule dans :","o":["L'espace épidural","L'espace sous-dural","L'espace sous-arachnoïdien et les ventricules cérébraux","La pie-mère uniquement"],"r":2,"e":"Le LCR circule dans l'espace SOUS-ARACHNOÏDIEN (entre arachnoïde et pie-mère) et dans les 4 ventricules cérébraux. Il protège des chocs.","s":4},{"q":"L'aire de Broca est située dans :","o":["Le lobe occipital","Le lobe temporal","Le lobe frontal","Le lobe pariétal"],"r":2,"e":"L'aire de Broca (langage moteur, production) est dans le lobe FRONTAL. L'aire de Wernicke (compréhension du langage) est dans le lobe temporal.","s":4},{"q":"Quelle correspondance LOBE → fonction est correcte ?","o":["Frontal → motricité volontaire + jugement","Temporal → audition + Wernicke","Pariétal → coordination/interprétation sensorielle","Occipital → vision","Frontal → vision"],"r":[0,1,2,3],"e":"Frontal = moteur + Broca + jugement. Temporal = audition + Wernicke + mémoire. Pariétal = sensoriel. Occipital = visuel. La vision n'est PAS frontale.","s":4},{"q":"Le THALAMUS a pour rôle principal :","o":["Centre de la respiration","Relais des influx vers et depuis le cortex","Régulation de la température","Sécrétion d'hormones"],"r":1,"e":"Le thalamus = grand relais : transmet les influx vers et depuis les régions cérébrales appropriées. Il distingue aussi les stimuli plaisants/déplaisants.","s":4},{"q":"L'HYPOTHALAMUS régule :","o":["La température corporelle","L'appétit","La pression artérielle","La respiration","La motricité fine volontaire"],"r":[0,1,2,3],"e":"Hypothalamus = centre autonome : T°, appétit, PA, respiration, sommeil, contrôle partiel hypophyse, réaction au stress. La motricité fine volontaire = cortex moteur.","s":4},{"q":"Quelle structure coordonne les mouvements musculaires, contrôle la posture et l'équilibre ?","o":["Le cervelet","Le bulbe rachidien","L'hippocampe","La moelle épinière"],"r":0,"e":"Le CERVELET, situé sous le cerveau à la base, coordonne les mouvements, contrôle la posture et maintient l'équilibre.","s":4},{"q":"Concernant les 3 parties du tronc cérébral :","o":["Mésencéphale = réflexes nerfs III & IV (oculaires)","Pont = régulation respiration + nerfs V à VIII","Bulbe rachidien = fonctions cardiaque/respiratoire/vasomotrice","Bulbe = nerfs IX, X, XII","Cervelet = partie du tronc cérébral"],"r":[0,1,2,3],"e":"Tronc = mésencéphale (oculomoteurs III/IV) + pont (V à VIII, respiration) + bulbe (IX/X/XII, fonctions vitales). Le cervelet n'est PAS dans le tronc.","s":4},{"q":"Jusqu'à quel niveau vertébral s'étend la moelle épinière chez l'adulte ?","o":["L1-L2","L4-L5","S1","T12"],"r":0,"e":"La moelle épinière descend jusqu'à L1-L2 chez l'adulte. En dessous, on trouve la queue de cheval (racines libres).","s":4},{"q":"Concernant les CORNES de la substance grise médullaire :","o":["Cornes postérieures = sensitif (relais d'information)","Cornes antérieures = activité motrice volontaire/réflexe","Cornes antérieures = sensitif","Cornes postérieures = moteur","Les cornes contiennent surtout des corps cellulaires neuronaux"],"r":[0,1,4],"e":"Antérieur (ventral) = MOTEUR ; Postérieur (dorsal) = SENSITIF. Les cornes contiennent les corps cellulaires des neurones.","s":4},{"q":"Le système PYRAMIDAL (corticospinal) est responsable :","o":["Des mouvements grossiers","Des mouvements fins et qualifiés des muscles squelettiques","Du contrôle viscéral","Des réflexes uniquement"],"r":1,"e":"Pyramidal/corticospinal = mouvements FINS et qualifiés. Extra-pyramidal = mouvements grossiers, posture, tonus.","s":4},{"q":"Concernant la JONCTION racine antérieure / racine postérieure des nerfs spinaux :","o":["Racine antérieure (ventrale) = fibres motrices","Racine postérieure (dorsale) = fibres sensitives","Le ganglion de la racine postérieure contient les corps des neurones sensitifs","Racine antérieure = sensitive","Racine postérieure = motrice"],"r":[0,1,2],"e":"Mnémo : antérieur=ventral=moteur ; postérieur=dorsal=sensitif. Le ganglion postérieur contient les corps cellulaires des neurones sensitifs.","s":4},{"q":"Le neurotransmetteur du système SYMPATHIQUE est :","o":["Acétylcholine","Noradrénaline","GABA","Dopamine"],"r":1,"e":"Sympathique = noradrénaline (adrénergique, combat/fuite). Parasympathique = acétylcholine (cholinergique, repos/digestion).","s":4},{"q":"La maladie d'Alzheimer touche principalement :","o":["Le cervelet","Le cortex cérébral (surtout lobes frontaux)","La moelle épinière","Les nerfs périphériques"],"r":1,"e":"Alzheimer = trouble dégénératif progressif du CORTEX CÉRÉBRAL, atrophie maximale aux lobes frontaux mais touche tout le cortex.","s":4},{"q":"Lésions tissulaires caractéristiques de la maladie d'Alzheimer :","o":["Enchevêtrements neurofibrillaires","Plaques β-amyloïdes","Dégénérescence granulovasculaire","Atrophie corticale + élargissement des ventricules","Démyélinisation des nerfs périphériques"],"r":[0,1,2,3],"e":"Alzheimer : neurofibrillaires (tau), plaques amyloïdes (Aβ), dégénérescence granulovasculaire, atrophie + ventricules dilatés. Pas d'atteinte SNP.","s":4},{"q":"Le traitement de référence d'Alzheimer cible le neurotransmetteur :","o":["GABA","Sérotonine","Acétylcholine (inhibiteurs de la cholinestérase)","Dopamine"],"r":2,"e":"Cerveaux Alzheimer = jusqu'à 10 % du taux normal d'ACh. Tx : inhibiteurs de la cholinestérase (donépézil, rivastigmine, galantamine) + mémantine (NMDA).","s":4},{"q":"Concernant la SLA (sclérose latérale amyotrophique) :","o":["Atteinte des motoneurones supérieurs ET inférieurs","Faiblesse + fasciculations + atrophie","La sensibilité et la cognition sont préservées","Tx : Riluzole (neuroprotecteur)","Atteinte exclusive des nerfs sensitifs"],"r":[0,1,2,3],"e":"SLA = atteinte des 2 types de motoneurones, signe cardinal = faiblesse (60 %), fasciculations, atrophie, dysarthrie/dysphagie. Sensibilité et COGNITION PRÉSERVÉES. Tx Riluzole.","s":4},{"q":"Une crise tonico-clonique généralisée se caractérise par :","o":["Une absence simple de quelques secondes","Une chute, phase tonique puis clonique, durée 2-5 min, parfois morsure langue/incontinence","Des secousses unilatérales sans perte de conscience","Une simple sensation de fourmillement"],"r":1,"e":"Tonico-clonique généralisée (grand mal) : cri → chute → tonique → clonique 2-5 min, morsure de langue, apnée, incontinence, confusion post-critique.","s":4},{"q":"Concernant l'épilepsie :","o":["~50 % des cas sont idiopathiques","L'EEG est l'examen clé","Le valproate est un traitement de l'absence (petit mal)","La phénytoïne traite les tonico-cloniques","L'épilepsie diminue toujours l'intelligence"],"r":[0,1,2,3],"e":"50 % idiopathiques, EEG = clé, valproate/clonazépam/ethosuximide pour absence, phénytoïne/carbamazépine pour TC. L'épilepsie n'affecte PAS l'intelligence chez la plupart des patients.","s":4},{"q":"Le syndrome de Guillain-Barré est :","o":["Une maladie tumorale","Un syndrome auto-immun aigu avec démyélinisation segmentaire des nerfs périphériques","Une infection bactérienne du SNC","Une maladie génétique"],"r":1,"e":"GBS = polyneuropathie aiguë AUTO-IMMUNE post-infectieuse avec démyélinisation segmentaire. Évolution ascendante, risque respiratoire.","s":4},{"q":"Caractéristiques du Guillain-Barré :","o":["Pattern ASCENDANT (jambes → bras → tronc → face)","Aréflexie","LCR : dissociation albumino-cytologique (↑ protéines, GB normaux)","Tx : immunoglobulines IV ou plasmaphérèse","Hyperréflexie typique"],"r":[0,1,2,3],"e":"GBS : ascendant, AREFLEXIE (pas hyperréflexie), dissociation albumino-cytologique LCR (pic 4-6 sem), Tx Ig IV ou plasmaphérèse, kinésithérapie.","s":4},{"q":"Concernant la MÉNINGITE bactérienne, quelles affirmations sont vraies ?","o":["Causes : N. meningitidis, H. influenzae, S. pneumoniae","Le LCR est trouble/lacté avec ↑ protéines et ↓ glucose","Brudzinski et Kernig sont des signes méningés positifs","Mortalité non traitée : 70-100 %","Tx 1ère intention : aspirine seule"],"r":[0,1,2,3],"e":"Méningite bactérienne : Méningocoque, Haemophilus, Pneumocoque, E. coli. LCR trouble (↑ prot, ↓ glucose, Gram+culture). Brudzinski/Kernig positifs. Tx : ATB IV ≥ 2 sem (pénicilline G, ampicilline).","s":4},{"q":"Le signe de KERNIG correspond à :","o":["Flexion de la nuque qui entraîne flexion involontaire des hanches","Flexion de hanche + genou puis extension du genou → douleur/résistance","Babinski positif","Hypertrophie pupillaire"],"r":1,"e":"Kernig : patient en décubitus, flexion de la hanche puis tentative d'extension du genou → douleur/résistance. Brudzinski : flexion du cou → flexion involontaire des hanches/genoux.","s":4},{"q":"La sclérose en plaques (SEP) est due à :","o":["Une démyélinisation du SNP","Une démyélinisation de la substance blanche du SNC","Une atteinte des motoneurones","Une carence en vitamine B12"],"r":1,"e":"SEP = démyélinisation progressive de la SUBSTANCE BLANCHE du SNC (cerveau + moelle), formant des plaques scléreuses. NE TOUCHE PAS le SNP (= GBS, lui).","s":4},{"q":"Concernant la SEP :","o":["Touche surtout les femmes jeunes (18-40 ans)","Premiers signes : troubles visuels (névrite optique) + paresthésies","IRM = examen le plus sensible","Évolution par poussées et rémissions","Atteinte fréquente du SNP"],"r":[0,1,2,3],"e":"SEP : ♀ jeunes 18-40, premiers signes = vision (névrite optique) + paresthésies, IRM lésions chez >90 %, poussées/rémissions. PAS de SNP (vs GBS).","s":4},{"q":"Le test de TENSILON (édrophonium) sert à :","o":["Diagnostiquer une SEP","Diagnostiquer la myasthénie grave et différencier crise myasthénique vs cholinergique","Diagnostiquer un Parkinson","Diagnostiquer une SLA"],"r":1,"e":"Tensilon = test diagnostique de la myasthénie grave. Différencie crise myasthénique (amélioration) vs crise cholinergique (aggravation, ↑ salivation, ↓ déglutition).","s":4},{"q":"Concernant la maladie de Parkinson :","o":["Atteinte du système EXTRA-pyramidal","Carence en dopamine dans la substance noire","Triade : rigidité + akinésie + tremblement de repos","Tx 1ère ligne : lévodopa + carbidopa","Atteinte primitive de la jonction neuromusculaire"],"r":[0,1,2,3],"e":"Parkinson : extra-pyramidal, ↓ dopamine substance noire, triade rigidité (roue dentée)/akinésie/tremblement de repos pill-rolling. Tx lévodopa+carbidopa, DBS. Pas de jonction neuromusculaire (= myasthénie).","s":4},{"q":"Concernant l'AVC :","o":["Thrombose = cause la plus fréquente (sujets âgés)","AIT = déficit < 24 h sans lésion à l'imagerie","Tx ischémique : rTPA dans les 3 premières heures","La cocaïne ↑ le risque d'AVC hémorragique","L'hémorragie est la 1ère cause d'AVC"],"r":[0,1,2,3],"e":"AVC : thrombose 1ère cause (>50 %), embolie 2ème, hémorragie 3ème (mais cocaïne ↑ risque hémorragique par HTA sévère). AIT < 24h sans lésion. Tx ischémique = rTPA dans les 3h.","s":4},{"q":"La maladie d'Alzheimer est caractérisée histologiquement par :","o":["Plaques β-amyloïdes + dégénérescences neurofibrillaires (Tau)","Inflammation aiguë","Démyélinisation","Tumeur"],"r":0,"e":"Alzheimer : plaques amyloïdes (Aβ) extracellulaires + neurofibrilles de protéine Tau hyperphosphorylée.","s":4},{"q":"Le premier symptôme habituel d'Alzheimer est :","o":["Trouble de la marche","Trouble de la mémoire récente (épisodique)","Aphasie globale","Coma"],"r":1,"e":"Alzheimer débute par troubles mnésiques récents (oubli des évènements récents), puis désorientation, aphasie.","s":4},{"q":"La SLA (Sclérose Latérale Amyotrophique) atteint :","o":["Sensibilité uniquement","Motoneurones supérieurs (1er) + inférieurs (2e)","Cognitif uniquement","Cérébellaire"],"r":1,"e":"SLA = atteinte des motoneurones (1er + 2e) → faiblesse, atrophie, fasciculations + spasticité, ROT vifs. Sensibilité préservée.","s":4},{"q":"L'épilepsie tonico-clonique généralisée comprend :","o":["Phase tonique (raideur) → phase clonique (secousses) → coma post-critique","Phase clonique pure","Absence pure","Hallucinations seulement"],"r":0,"e":"Crise tonico-clonique : phase tonique 10-20s → phase clonique 1-2 min → résolution + confusion post-critique.","s":4},{"q":"L'épilepsie absence (petit mal) :","o":["Provoque des chutes","Brève rupture de contact (5-15 s) sans convulsions, fréquente chez l'enfant","Provoque coma","Toujours convulsive"],"r":1,"e":"Absence : rupture brève de contact, pointe-onde 3 Hz à l'EEG, fréquente entre 5-12 ans.","s":4},{"q":"La méningite bactérienne se manifeste par :","o":["Triade : fièvre + céphalées + raideur de nuque","Hémorragie cérébrale","Atrophie","Aucun signe"],"r":0,"e":"Méningite : triade classique + photophobie ± purpura. PL avec LCR trouble (↑ PNN, ↑ protéines, ↓ glucose) → urgence.","s":4},{"q":"La sclérose en plaques (SEP) est :","o":["Bactérienne","Auto-immune démyélinisante du SNC","Tumorale","Génétique pure"],"r":1,"e":"SEP : maladie auto-immune chronique avec démyélinisation multifocale du SNC, poussées + remissions, jeune adulte.","s":4},{"q":"La maladie de Parkinson est due à :","o":["Atteinte cérébelleuse","Dégénérescence des neurones dopaminergiques de la substance noire","Démyélinisation","AVC"],"r":1,"e":"Parkinson : perte des neurones dopaminergiques de la substance noire (pars compacta), corps de Lewy.","s":4},{"q":"La triade parkinsonienne classique inclut :","o":["Tremblement de repos (4-6 Hz)","Rigidité (roue dentée)","Bradykinésie/akinésie","Instabilité posturale (tardif)","Démence d'emblée"],"r":[0,1,2,3],"e":"Triade : tremblement, rigidité, akinésie/bradykinésie + instabilité posturale tardive. Démence est tardive.","s":4},{"q":"La myasthénie auto-immune est due à :","o":["Démyélinisation","Anticorps anti-récepteurs de l'acétylcholine post-synaptique","Atteinte centrale","Trouble vasculaire"],"r":1,"e":"Myasthénie : Ac anti-RACh post-synaptiques → fatigabilité musculaire à l'effort, ptosis, diplopie, déglutition difficile.","s":4},{"q":"Quels sont les deux feuillets de la dure-mère ?","o":["Endostéal et méningé","Externe et vasculaire","Pariétal et viscéral","Fibreux et séreux"],"r":0,"e":"La dure-mère crânienne comporte un feuillet endostéal et un feuillet méningé ; l'arachnoïde est avasculaire et la pie-mère vascularisée.","s":4},{"q":"Quelle méninge est avasculaire ?","o":["L'arachnoïde","La pie-mère","La dure-mère","Aucune des trois"],"r":0,"e":"L'arachnoïde, membrane fine intermédiaire, est avasculaire ; la pie-mère est vascularisée.","s":4},{"q":"Quel espace méningé est virtuel ?","o":["L'espace sous-dural","L'espace épidural","L'espace sous-arachnoïdien","Aucun"],"r":0,"e":"L'espace sous-dural est virtuel ; l'épidural contient graisse et veines, le sous-arachnoïdien du LCR.","s":4},{"q":"Quelle scissure sépare le lobe frontal du lobe pariétal ?","o":["La scissure de Rolando (centrale)","La scissure de Sylvius","La scissure pariéto-occipitale","La scissure calcarine"],"r":0,"e":"Rolando sépare frontal et pariétal ; Sylvius isole le temporal.","s":4},{"q":"Quelle scissure sépare le lobe temporal des lobes frontal et pariétal ?","o":["La scissure de Sylvius (latérale)","La scissure de Rolando","La scissure pariéto-occipitale","La scissure interhémisphérique"],"r":0,"e":"La scissure latérale de Sylvius délimite le lobe temporal.","s":4},{"q":"Quelles émotions primitives la fiche attribue-t-elle au thalamus ?","o":["La peur et la distinction entre stimuli plaisants et déplaisants","La motivation et la mémoire autobiographique","L'agressivité et la faim","Aucune, il est purement sensoriel"],"r":0,"e":"Outre son rôle de relais, la fiche lui attribue ces fonctions émotionnelles primitives.","s":4},{"q":"Quelles fonctions le mésencéphale assure-t-il selon cette fiche ?","o":["Les réflexes des nerfs crâniens III et IV (réflexes pupillaires et mouvements oculaires)","La régulation de la respiration","Les fonctions cardiaque et vasomotrice","Les centres du vomissement et de la toux"],"r":0,"e":"Le pont régule la respiration et porte les réflexes V à VIII ; le bulbe abrite les fonctions vitales et les centres du vomissement.","s":4},{"q":"Quels nerfs crâniens émergent du bulbe rachidien selon la fiche ?","o":["IX, X et XII","III et IV","V à VIII","I et II"],"r":0,"e":"Le bulbe porte les nerfs IX, X et XII ; le mésencéphale III et IV, le pont V à VIII.","s":4},{"q":"Quelles structures forment la formation réticulée selon la fiche ?","o":["Le tronc cérébral, le thalamus et l'hypothalamus","Le cervelet et le pont","Les noyaux gris centraux et le thalamus","Le cortex et la substance blanche"],"r":0,"e":"Cette association constitue le réseau d'éveil et de vigilance.","s":4},{"q":"Pourquoi chaque nerf spinal se divise-t-il en rameaux avec recouvrement ?","o":["Ce recouvrement réduit la perte fonctionnelle en cas de lésion isolée","Cela accélère la conduction","Cela permet la régénération axonale","Cela protège contre les infections"],"r":0,"e":"Le chevauchement des territoires limite les conséquences d'une atteinte d'une seule racine.","s":4},{"q":"Le potentiel de membrane au repos d'un neurone est d'environ :","o":["+30 mV","-70 mV","0 mV","-100 mV"],"r":1,"e":"Le potentiel de repos est de -70 mV. Maintenu par la pompe Na⁺/K⁺ ATPase. K⁺ intra > extra ; Na⁺ extra > intra.","s":5},{"q":"Concernant les phases du potentiel d'action :","o":["Dépolarisation = entrée massive de Na⁺","Repolarisation = sortie de K⁺","Hyperpolarisation possible (overshoot K⁺)","Dépolarisation = sortie de Cl⁻","Tout-ou-rien"],"r":[0,1,2,4],"e":"PA = tout-ou-rien. Dépolarisation : entrée Na⁺ → +30 mV. Repolarisation : sortie K⁺ → retour vers -70 mV. Hyperpolarisation parfois (refractaire). Le Cl⁻ n'intervient pas dans les phases standards.","s":5},{"q":"Quelle cellule gliale myélinise les axones du SNC ?","o":["Cellule de Schwann","Astrocyte","Oligodendrocyte","Microglie"],"r":2,"e":"SNC = oligodendrocyte (1 cellule peut myéliniser plusieurs axones). SNP = cellule de Schwann (1 cellule = 1 segment d'1 seul axone).","s":5},{"q":"Concernant la transmission synaptique :","o":["L'arrivée du PA déclenche l'entrée de Ca²⁺ au bouton terminal","Le Ca²⁺ déclenche la libération de neurotransmetteur","Liaison post-synaptique → EPSP (excitateur) ou IPSP (inhibiteur)","Tous les neurotransmetteurs sont excitateurs","Le glutamate est le principal excitateur du SNC"],"r":[0,1,2,4],"e":"PA → Ca²⁺ → libération NT → liaison récepteurs → EPSP/IPSP. Glutamate = principal excitateur SNC. GABA = principal inhibiteur SNC. Tous les NT ne sont pas excitateurs.","s":5},{"q":"Le principal neurotransmetteur INHIBITEUR du SNC est :","o":["Glutamate","Acétylcholine","GABA","Dopamine"],"r":2,"e":"GABA = principal NT inhibiteur du SNC (récepteurs GABA-A et B). Glutamate = principal excitateur. Cible des benzodiazépines (potentialisent GABA).","s":5},{"q":"La barrière hémato-encéphalique (BHE) :","o":["Sépare le sang du tissu cérébral","Composée de jonctions serrées + astrocytes","Laisse passer O₂, CO₂, glucose","Bloque la majorité des médicaments","Permet librement le passage des bactéries"],"r":[0,1,2,3],"e":"BHE = jonctions serrées endothéliales + astrocytes. Imperméable à la plupart des molécules → protège. Laisse passer petites molécules liposolubles (O₂, CO₂) et substrats énergétiques (glucose via transporteurs). Bloque les pathogènes (sauf en méningite).","s":5},{"q":"Le LCR est produit par :","o":["Les méninges","Les plexus choroïdes (dans les ventricules)","La pie-mère","Le bulbe rachidien"],"r":1,"e":"LCR = produit par les plexus choroïdes des ventricules cérébraux. Volume ~150 mL, production ~500 mL/j. Réabsorbé par les granulations arachnoïdiennes (de Pacchioni).","s":5},{"q":"Concernant le système nerveux SYMPATHIQUE :","o":["Origine thoraco-lombaire (T1-L2)","Fibres post-ganglionnaires longues à noradrénaline","Mydriase, ↑ FC, bronchodilatation","Récepteurs muscariniques principalement","Effet \"combat ou fuite\""],"r":[0,1,2,4],"e":"Sympathique : T1-L2, ganglions paravertébraux, post-ganglionnaire LONGUE à NA, récepteurs α/β. Effet combat/fuite. Les muscariniques sont des récepteurs PARASYMPATHIQUES.","s":5},{"q":"Le réflexe rotulien est un exemple de :","o":["Réflexe polysynaptique","Réflexe d'étirement monosynaptique","Réflexe nociceptif","Réflexe cutané"],"r":1,"e":"Réflexe rotulien (myotatique) = monosynaptique : un neurone afférent (Ia) → un neurone efférent moteur. Sa réponse explore L4.","s":5},{"q":"Concernant la voie cordonale postérieure :","o":["Tact fin discriminatif","Vibration","Proprioception","Croisement au niveau du bulbe (lemnisque médian)","Croisement immédiat dans la moelle"],"r":[0,1,2,3],"e":"Cordon postérieur (gracile + cunéiforme) : tact fin, vibration, proprioception. Croisement au BULBE (lemnisque médian). La voie spinothalamique croise dans la moelle (1-2 segments au-dessus).","s":5},{"q":"La voie SPINOTHALAMIQUE LATÉRALE véhicule :","o":["Tact fin et proprioception","Douleur et température","Motricité volontaire","Réflexes ostéo-tendineux"],"r":1,"e":"Spinothalamique latérale = douleur + T°. Croisement dans la moelle 1-2 segments au-dessus. Spinothalamique antérieure = tact grossier, pression.","s":5},{"q":"Concernant les types de douleur :","o":["Douleur nociceptive = stimulation de récepteurs","Douleur neuropathique = lésion du système nerveux","Douleur référée = ressentie à distance de la zone lésée","Douleur du membre fantôme = post-amputation","Douleur viscérale = bien localisée"],"r":[0,1,2,3],"e":"Nociceptive = récepteurs stimulés. Neuropathique = lésion nerveuse (brûlures, décharges). Référée = à distance (épaule G dans IDM). Membre fantôme = post-amputation. La douleur viscérale est MAL localisée (vs cutanée bien localisée).","s":5},{"q":"Les fibres conduisant la douleur RAPIDE (piqûre, bien localisée) sont :","o":["Fibres C non myélinisées","Fibres Aδ myélinisées","Fibres Aα","Fibres B"],"r":1,"e":"Fibres Aδ (myélinisées, rapides) = douleur aiguë, bien localisée, rapide. Fibres C (non myélinisées, lentes) = douleur sourde, mal localisée, brûlante.","s":5},{"q":"Concernant la migraine :","o":["Unilatérale, pulsatile","Durée 4-72 h","± aura visuelle ou sensitive","Photo/phonophobie + nausées","Tx aigu : O₂ 100 %"],"r":[0,1,2,3],"e":"Migraine : unilatérale, pulsatile, 4-72 h, photo/phonophobie, nausées, ± aura. Tx aigu : triptans, AINS. L'O₂ 100 % est utilisé pour les ALGIES VASCULAIRES (cluster), pas la migraine.","s":5},{"q":"L'algie vasculaire de la face (cluster headache) est :","o":["Bilatérale, légère","Unilatérale orbitaire intense, par salves, avec larmoiement et congestion nasale","Souvent provoquée par l'effort","Disparaît spontanément après 30 sec"],"r":1,"e":"Cluster : crises courtes (15-180 min) très intenses, unilatérales orbitaires, par salves, avec signes dysautonomiques (larmoiement, congestion, ptosis). Tx : O₂ 100 %, sumatriptan SC.","s":5},{"q":"Le système PYRAMIDAL (corticospinal) :","o":["Croise au niveau du thalamus","Origine au cortex moteur primaire (M1, aire 4) avec décussation au bulbe","Contrôle les mouvements grossiers","Fait partie du cervelet"],"r":1,"e":"Pyramidal/corticospinal : origine M1 (aire 4), décussation au BULBE (75 % en latéral), contrôle des mouvements FINS et qualifiés. Lésion → spasticité, hyperréflexie, Babinski +.","s":5},{"q":"Différences UMN vs LMN :","o":["UMN = hypertonie spastique ; LMN = hypotonie","UMN = hyperréflexie ; LMN = hyporéflexie","UMN = atrophie précoce et marquée","LMN = fasciculations","UMN = Babinski positif"],"r":[0,1,3,4],"e":"UMN : spasticité, hyperréflexie, Babinski +, atrophie tardive et MODÉRÉE (de non-usage). LMN : flaccidité, hyporéflexie, atrophie PRÉCOCE et marquée, fasciculations.","s":5},{"q":"La SLA atteint :","o":["Uniquement les motoneurones supérieurs (UMN)","Uniquement les motoneurones inférieurs (LMN)","UMN ET LMN (mixte)","Uniquement les nerfs sensitifs"],"r":2,"e":"SLA = atteinte MIXTE des UMN et LMN. Mutation SOD1 dans 5-10 % des cas (chr 21). Faiblesse, atrophie, fasciculations + spasticité, Babinski. Sensibilité et cognition PRÉSERVÉES.","s":5},{"q":"Concernant la SEP :","o":["Démyélinisation auto-immune du SNC","Plaques disséminées dans le temps et l'espace","IRM = examen de référence","Bandes oligoclonales LCR (90 %)","Atteinte fréquente du SNP"],"r":[0,1,2,3],"e":"SEP : auto-immune, démyélinisation SNC (PAS du SNP, vs Guillain-Barré). Plaques disséminées temps/espace (critères de McDonald). IRM = examen clé. LCR : bandes oligoclonales chez 90 %.","s":5},{"q":"Le test diagnostique de la myasthénie grave est :","o":["EEG","Test au Tensilon (édrophonium)","Ponction lombaire","TDM cérébrale"],"r":1,"e":"Tensilon (édrophonium) = anticholinestérasique d'action courte → amélioration transitoire de la force = test diagnostique. Aussi : dosage anti-RACh, EMG (décrément), recherche thymome au TDM thoracique.","s":5},{"q":"La dystrophie de Duchenne est :","o":["Liée à l'X, récessive (garçons ++)","Autosomique dominante","Auto-immune","Acquise par carence vitaminique"],"r":0,"e":"Duchenne = transmission X-RÉCESSIVE → garçons +++. Mutation du gène de la dystrophine. Début 3-5 ans, fauteuil ~12 ans. Signe de Gowers. ↑ CPK majeure.","s":5},{"q":"Signes du SYNDROME CÉRÉBELLEUX :","o":["Ataxie","Dysmétrie","Dysdiadococinésie","Tremblement intentionnel","Tremblement de repos"],"r":[0,1,2,3],"e":"Cérébelleux : ataxie, dysmétrie, dysdiadococinésie, tremblement INTENTIONNEL (pas de repos), hypotonie, dysarthrie scandée, nystagmus. Le tremblement de REPOS = Parkinson.","s":5},{"q":"La maladie de Huntington est :","o":["Autosomique dominante (chr 4, expansion CAG)","Liée à l'X","Auto-immune","Une carence vitaminique"],"r":0,"e":"Huntington : autosomique DOMINANTE, mutation chr 4 (expansion CAG > 36). Atteinte du noyau caudé + putamen. Triade : chorée + démence + troubles psychiatriques. Début 30-50 ans.","s":5},{"q":"L'hémiballisme (mouvements violents involontaires) est typiquement causé par une lésion du :","o":["Cervelet","Noyau subthalamique (Luys)","Substance noire","Cortex moteur"],"r":1,"e":"Hémiballisme = mouvements brusques, violents, en ballant des membres. Lésion contralatérale du noyau SUBTHALAMIQUE (Luys), souvent ischémique.","s":5},{"q":"Une lésion médullaire au niveau C4-C5 entraîne :","o":["Paraplégie sans atteinte respiratoire","Tétraplégie + respiration partielle","Hémiplégie","Aucune atteinte motrice"],"r":1,"e":"C4-C5 = tétraplégie + respiration partielle (atteinte du diaphragme, innervation C3-C5 par le nerf phrénique). C1-C3 = dépendance ventilatoire totale. T1+ = paraplégie.","s":5},{"q":"La DYSRÉFLEXIE AUTONOMIQUE est :","o":["Une urgence en cas de lésion médullaire ≥ T6","Stimulus sous le niveau lésionnel → HTA sévère","Bradycardie + céphalées + sueurs profuses","Toujours bénigne","Risque d'AVC si non traitée"],"r":[0,1,2,4],"e":"Dysréflexie autonomique : urgence chez blessé médullaire (lésion ≥ T6). Stimulus nociceptif sous-lésionnel (vessie pleine, escarre, fécalome) → décharge sympathique massive → HTA paroxystique sévère, bradycardie réflexe, céphalées, sueurs. Risque AVC, OAP.","s":5},{"q":"L'échelle de Glasgow (GCS) explore :","o":["Yeux + Verbal + Moteur (total /15)","Sensibilité + motricité + réflexes (total /20)","Glycémie + PA + FC","Force /5 dans 5 territoires"],"r":0,"e":"GCS : ouverture des yeux (1-4) + réponse verbale (1-5) + réponse motrice (1-6) = total /15. ≤ 8 = coma, indication d'intubation.","s":5},{"q":"Concernant l'HTIC (hypertension intracrânienne) :","o":["Doctrine de Monro-Kellie : 3 compartiments (cerveau, sang, LCR)","Pression normale 5-15 mmHg","HTIC > 20 mmHg","Triade de Cushing : HTA + bradycardie + irrégularités respiratoires","Toujours sans conséquence"],"r":[0,1,2,3],"e":"HTIC : Monro-Kellie (3 compartiments inextensibles). Normal 5-15 mmHg. > 20 mmHg = pathologique. Triade de Cushing = signe d'engagement imminent (HTA + bradycardie + irrégularités respi). Risque mortel.","s":5},{"q":"Concernant les types d'œdème cérébral :","o":["Cytotoxique : entrée d'eau intracellulaire (hypoxie, AVC)","Vasogénique : rupture BHE → fuite extracellulaire (tumeur)","Interstitiel : passage de LCR vers parenchyme (hydrocéphalie)","Tous les œdèmes ont le même mécanisme","L'œdème est toujours bénin"],"r":[0,1,2],"e":"3 types : cytotoxique (intracellulaire, AVC), vasogénique (extracellulaire, BHE rompue, tumeur/infection), interstitiel (LCR-parenchyme, hydrocéphalie). Mécanismes différents → traitements différents.","s":5},{"q":"Un hématome ÉPIDURAL :","o":["Origine veineuse","Origine artérielle (méningée moyenne), souvent sur fracture temporale, intervalle libre","Évolution lente sur des semaines","Image en croissant à la TDM"],"r":1,"e":"Hématome épidural : ARTÉRIEL (artère méningée moyenne), sur fracture temporale ++, INTERVALLE LIBRE classique, image en LENTILLE BICONVEXE. Vs sous-dural = veines en pont, image en CROISSANT.","s":5},{"q":"La forme la plus fréquente d'AVC est :","o":["AVC ischémique (~85 %)","AVC hémorragique (~85 %)","AVC ischémique (~50 %)","Hémorragie sous-arachnoïdienne (~70 %)"],"r":0,"e":"AVC ischémique = ~85 % des AVC. Hémorragique ~15 % mais plus mortel. Tx ischémique : tPA < 4,5 h, thrombectomie < 6-24 h selon profil.","s":5},{"q":"Concernant la prise en charge de l'AVC ischémique :","o":["tPA dans les 4,5 premières heures","Thrombectomie mécanique possible jusqu'à 6-24 h selon profil","TDM en urgence pour exclure hémorragie","FAST pour reconnaître (Face, Arms, Speech, Time)","Anticoagulation immédiate à dose curative"],"r":[0,1,2,3],"e":"AVC ischémique : TDM urgent (exclut hémorragie) → tPA si < 4,5 h, thrombectomie si possible. FAST = méthode de reconnaissance. L'anticoagulation curative immédiate n'est PAS systématique (risque de transformation hémorragique).","s":5},{"q":"Une céphalée brutale en \"coup de tonnerre\" évoque :","o":["Migraine","Tension","Hémorragie sous-arachnoïdienne (rupture d'anévrisme)","Cluster headache"],"r":2,"e":"Céphalée brutale en coup de tonnerre = drapeau rouge → HSA jusqu'à preuve du contraire (rupture d'anévrisme). Urgence neurochirurgicale. TDM en urgence ± PL si TDM négatif.","s":5},{"q":"L'encéphalite herpétique (HSV) :","o":["Atteinte préférentielle des lobes temporaux à l'IRM","Confusion + convulsions + déficits focaux","Tx en urgence : aciclovir IV","Bénigne, sans traitement","Mortalité élevée si non traitée"],"r":[0,1,2,4],"e":"Encéphalite HSV : urgence ! IRM = atteinte temporale, EEG anormal, LCR avec lymphocytes + PCR HSV. Tx IMMÉDIAT par aciclovir IV (avant confirmation). Sans tx : mortalité ~70 %.","s":5},{"q":"État de mal épileptique :","o":["Crise > 5 min OU > 2 crises sans récupération","Urgence vitale","Tx 1ère ligne : benzodiazépine IV (lorazépam)","Risque d'œdème cérébral","Bénin et auto-résolutif"],"r":[0,1,2,3],"e":"État de mal = crise prolongée >5 min ou crises répétées sans reprise de conscience. URGENCE vitale → benzo IV en 1ère ligne (lorazépam, diazépam) puis phénytoïne, puis coma barbiturique si réfractaire. Risque œdème, hypoxie, décès.","s":5},{"q":"Le neurone est :","o":["La cellule de soutien du SN","La cellule fonctionnelle du SN, qui transmet l'influx nerveux","Une cellule sanguine","Une cellule musculaire"],"r":1,"e":"Neurone = unité fonctionnelle du SN (corps cellulaire + dendrites + axone). Glie = cellules de soutien.","s":5},{"q":"Le potentiel d'action (PA) repose sur :","o":["L'entrée de Na+ (dépolarisation) puis sortie de K+ (repolarisation)","Sortie de Cl- uniquement","Entrée de Ca2+","Aucun mouvement ionique"],"r":0,"e":"PA : ouverture canaux Na+ voltage-dépendants → entrée Na+ (dépol) → ouverture canaux K+ → sortie K+ (repol).","s":5},{"q":"La synapse chimique transmet l'information via :","o":["Conduction électrique directe","Libération de neurotransmetteurs","Diffusion ionique","Voie sanguine"],"r":1,"e":"Synapse chimique : PA → entrée Ca2+ → libération vésicules de NT → liaison récepteurs post-synaptiques.","s":5},{"q":"La dopamine est principalement synthétisée par :","o":["Hippocampe","Substance noire (mésencéphale)","Cervelet","Bulbe olfactif"],"r":1,"e":"Dopamine : substance noire pars compacta (voie nigro-striée), aire tegmentale ventrale (voies mésocorticales/limbiques).","s":5},{"q":"L'aire motrice primaire est située :","o":["Lobe occipital","Gyrus précentral du lobe frontal","Lobe temporal","Cervelet"],"r":1,"e":"Cortex moteur primaire (M1) = gyrus précentral du lobe frontal, contient l'homonculus moteur.","s":5},{"q":"L'aire somatosensorielle primaire est située :","o":["Gyrus postcentral du lobe pariétal","Lobe frontal","Lobe occipital","Cervelet"],"r":0,"e":"S1 = gyrus postcentral du lobe pariétal, traite les sensations tactiles et proprioceptives, homonculus sensoriel.","s":5},{"q":"Le cervelet contrôle :","o":["La mémoire","La coordination des mouvements + équilibre","L'humeur","La douleur"],"r":1,"e":"Cervelet : coordination des mouvements fins, équilibre, ajustement du tonus. Atteinte → ataxie, dysmétrie.","s":5},{"q":"L'ataxie cérébelleuse se manifeste par :","o":["Marche en demi-pas","Marche ébrieuse, dysmétrie, dysarthrie scandée, tremblement intentionnel","Akinésie","Hémiplégie"],"r":1,"e":"Atteinte cérébelleuse : ataxie (marche ébrieuse), dysmétrie, adiadococinésie, dysarthrie, nystagmus, tremblement intentionnel.","s":5},{"q":"Le syndrome extrapyramidal (Parkinson) se distingue du pyramidal par :","o":["Spasticité élastique","Rigidité plastique (roue dentée) sans déficit moteur clair, tremblement de repos","Babinski +","ROT vifs"],"r":1,"e":"Syndrome EP : rigidité plastique, tremblement de repos, akinésie. Syndrome pyramidal : spasticité élastique, déficit moteur, Babinski.","s":5},{"q":"L'hippocampe est essentiel pour :","o":["La motricité","La consolidation de la mémoire à long terme","La vision","L'audition"],"r":1,"e":"Hippocampe : structure du système limbique, consolidation des souvenirs (passage mémoire court terme → long terme).","s":5},{"q":"Que contient le soma d'un neurone selon la fiche ?","o":["Noyau, nucléole, réticulum endoplasmique rugueux et corps de Nissl","Uniquement des mitochondries","Les nœuds de Ranvier","Les boutons terminaux"],"r":0,"e":"Les corps de Nissl (RER riche en ARN) sont caractéristiques du corps cellulaire neuronal.","s":5},{"q":"Quelle différence oppose l'oligodendrocyte à la cellule de Schwann ?","o":["L'oligodendrocyte myélinise plusieurs axones, la cellule de Schwann un seul","L'oligodendrocyte myélinise un seul axone, Schwann plusieurs","Les deux myélinisent plusieurs axones","Aucune ne myélinise"],"r":0,"e":"Un oligodendrocyte du SNC envoie des prolongements vers plusieurs axones ; une cellule de Schwann n'entoure qu'un seul segment d'un seul axone.","s":5},{"q":"Quelles cellules gliales du SNP la fiche cite-t-elle, outre les cellules de Schwann ?","o":["Les cellules satellites","Les astrocytes","Les épendymocytes","La microglie"],"r":0,"e":"Astrocytes, épendymocytes et microglie sont des cellules du SNC ; les cellules satellites accompagnent les corps cellulaires des ganglions périphériques.","s":5},{"q":"Quel ion entre dans le bouton terminal pour déclencher la libération du neurotransmetteur ?","o":["Le calcium","Le sodium","Le potassium","Le chlore"],"r":0,"e":"L'arrivée du potentiel d'action ouvre les canaux calciques voltage-dépendants, ce qui déclenche l'exocytose des vésicules.","s":5},{"q":"Quel est le volume total de LCR et sa production quotidienne ?","o":["Environ 150 mL pour une production de 500 mL par jour","Environ 500 mL pour une production de 150 mL par jour","Environ 50 mL pour 100 mL par jour","Environ 1 L pour 1 L par jour"],"r":0,"e":"Le LCR est donc renouvelé environ trois fois par jour.","s":5},{"q":"L'oreille est divisée en 3 compartiments. Lesquels ?","o":["Externe (capter)","Moyenne (transmettre/amplifier)","Interne (transduction sensorielle)","Centrale","Périphérique"],"r":[0,1,2],"e":"3 parties : externe (pavillon + CAE + tympan), moyenne (osselets, trompe d'Eustache) et interne (cochlée + vestibule).","s":6},{"q":"Quels sont les 3 osselets de l'oreille moyenne (de l'extérieur vers l'intérieur) ?","o":["Étrier → Enclume → Marteau","Marteau → Enclume → Étrier","Marteau → Étrier → Enclume","Enclume → Marteau → Étrier"],"r":1,"e":"Marteau (malleus) → Enclume (incus) → Étrier (stapes). L'étrier transmet les vibrations à la fenêtre ovale de l'oreille interne.","s":6},{"q":"La trompe d'Eustache relie :","o":["L'oreille moyenne au rhinopharynx","La cochlée au cervelet","Les 2 oreilles entre elles","Le tympan au CAE"],"r":0,"e":"Trompe d'Eustache = oreille moyenne ↔ rhinopharynx. Rôle : équilibrer la pression et drainer. Sa dysfonction → otite séreuse.","s":6},{"q":"Concernant l'oreille interne :","o":["Contient le labyrinthe osseux (perilymphe) et membraneux (endolymphe)","Cochlée = audition","Vestibule + canaux semi-circulaires = équilibre","Innervation par le NC VIII (vestibulo-cochléaire)","Innervation par le NC V (trijumeau)"],"r":[0,1,2,3],"e":"Oreille interne : labyrinthe osseux (perilymphe) + membraneux (endolymphe). Cochlée audition, vestibule/canaux SC équilibre. NC VIII (vestibulo-cochléaire). Le V innerve le pavillon, pas l'oreille interne.","s":6},{"q":"Le tympan vu à l'otoscope est :","o":["Plat et opaque","Un cône concave avec umbo, manche du marteau visible, cône lumineux","Bombé et rouge en condition normale","Toujours blanc nacré uniforme"],"r":1,"e":"Tympan normal : transparent gris-perlé, cône lumineux, manche du marteau visible, umbo (apex). Bombé rouge = OMA. Concave = dépression (dysfonction tubaire).","s":6},{"q":"Pourquoi peut-on déclencher un réflexe de toux/vomissement à l'otoscopie chez l'enfant ?","o":["Stimulation du NC V","Innervation vagale (NC X) du conduit auditif externe","Stimulation du NC VIII","Réflexe oculaire"],"r":1,"e":"Le CAE postérieur est innervé en partie par le nerf vague (X) → réflexe de toux ou vomissement, surtout chez l'enfant à l'otoscopie.","s":6},{"q":"L'otite externe (\"oreille du nageur\") est typiquement causée par :","o":["S. pneumoniae","Pseudomonas aeruginosa et S. aureus","Mycobacterium tuberculosis","Virus herpes"],"r":1,"e":"Otite externe : Pseudomonas aeruginosa ++, S. aureus. Douleur intense à la traction du pavillon. Tx : gouttes ATB ± corticoïdes.","s":6},{"q":"L'otosclérose est une atteinte de :","o":["L'enclume","Le marteau","L'étrier (et la fenêtre ovale)","La cochlée"],"r":2,"e":"Otosclérose = dystrophie osseuse autour de l'étrier et de la fenêtre ovale → blocage de l'étrier → surdité de transmission progressive. Hérédité, ♀ jeune ++, aggravée par grossesse. Tx : prothèse ou stapédectomie.","s":6},{"q":"Concernant l'OMA (otite moyenne aiguë) :","o":["1ère cause de consultation pédiatrique","Germes : pneumocoque, H. influenzae, M. catarrhalis","Otalgie + fièvre + tympan rouge bombé","Tx 1ère intention : amoxicilline (si bactérienne, < 2 ans)","Toujours d'origine virale"],"r":[0,1,2,3],"e":"OMA : 1ère cause de consultation chez l'enfant, post-rhume, dysfonction tubaire. Pneumocoque, H. influenzae, Moraxella. Tympan rouge bombé. Tx : amoxicilline. Peut être virale OU bactérienne.","s":6},{"q":"Le barotraumatisme (avion, plongée) survient en cas de :","o":["Excès de cérumen","Différentiel rapide de pression non équilibré par la trompe d'Eustache","Otite chronique","Surdité de perception"],"r":1,"e":"Barotrauma : changement rapide de pression atmosphérique non compensé par la trompe d'Eustache. Otalgie, hypoacousie, hémotympan possible. Prévention : déglutition, Valsalva.","s":6},{"q":"Mécanique auditive normale (transduction) :","o":["Onde sonore → tympan","Tympan → chaîne ossiculaire (marteau-enclume-étrier)","Étrier → fenêtre ovale → onde dans la perilymphe","Vibration de la membrane basilaire → cellules ciliées de l'organe de Corti","Influx vers le NC VIII puis cortex auditif (gyrus temporal supérieur)","Déplacement de l'endolymphe dans les canaux semi-circulaires"],"r":[0,1,2,3,4],"e":"Toute la chaîne : son → tympan → osselets → étrier sur fenêtre ovale → perilymphe → membrane basilaire → cellules ciliées (organe de Corti) → NC VIII → noyaux cochléaires → colliculi inférieurs → corps géniculé médian (thalamus) → cortex auditif primaire (aire 41). Ce déplacement code les accélérations angulaires : il relève du vestibule, non de l'audition.","s":6},{"q":"La tonotopie cochléaire signifie que :","o":["Toutes les fréquences sont détectées au même endroit","Les aigus sont à la base et les graves à l'apex de la cochlée","Les graves sont à la base et les aigus à l'apex","La cochlée ne détecte qu'une seule fréquence"],"r":1,"e":"Tonotopie : la membrane basilaire est 'accordée'. Les hautes fréquences (aigus) à la BASE, les basses fréquences (graves) à l'APEX. Audition humaine 20-20 000 Hz, sensibilité max 1000-3000 Hz.","s":6},{"q":"Les acouphènes (tinnitus) sont :","o":["Toujours associés à une lésion vasculaire","Une perception de son sans stimulus externe","Une cause systématique de surdité totale","Toujours d'origine psychogène"],"r":1,"e":"Acouphènes = perception d'un son sans stimulus externe (sifflement, bourdonnement). Touchent ~1/5 personnes. Subjectifs (la majorité) ou objectifs (rares, vasculaires). Causes : bouchon, trauma sonore, ototoxiques, presbyacousie, HTA.","s":6},{"q":"Médicaments OTOTOXIQUES classiques :","o":["Aspirine à fortes doses","Aminosides (gentamycine, streptomycine)","Furosémide à fortes doses","Cisplatine","Paracétamol"],"r":[0,1,2,3],"e":"Ototoxiques : aspirine (réversible), aminosides (irréversible), diurétiques de l'anse (furosémide à hautes doses), cisplatine, vancomycine. Le paracétamol n'est pas ototoxique.","s":6},{"q":"Une surdité de TRANSMISSION (conductive) :","o":["Provient d'une atteinte de la cochlée ou du nerf VIII","Provient d'une atteinte de l'oreille externe ou moyenne","Atteinte des voies centrales auditives","Toujours bilatérale"],"r":1,"e":"Transmission : atteinte oreille externe (bouchon) ou moyenne (OMA, otosclérose, perforation tympanique). Le son n'est pas correctement transmis à l'oreille interne. Perception : atteinte interne (cochlée, VIII).","s":6},{"q":"Concernant les tests de Rinne et Weber :","o":["Rinne + (CA > CO) = normal ou perception","Rinne − (CO > CA) = transmission","Weber latéralisé vers l'oreille ATTEINTE = transmission","Weber latéralisé vers l'oreille SAINE = perception","Weber latéralisé vers l'oreille saine = transmission"],"r":[0,1,2,3],"e":"Rinne + : conduction aérienne > osseuse (normal). Rinne − : CO > CA (transmission). Weber → oreille atteinte = transmission ; → oreille saine = perception.","s":6},{"q":"La presbyacousie est :","o":["Une surdité brutale","Une perte auditive progressive bilatérale liée à l'âge, sur les fréquences aiguës d'abord","Une infection bactérienne","Une cause de surdité de transmission"],"r":1,"e":"Presbyacousie : perte auditive de PERCEPTION liée à l'âge, progressive et bilatérale, atteint les FRÉQUENCES AIGUËS en premier. Impact social et lien avec déclin cognitif/démence.","s":6},{"q":"Causes de surdité de PERCEPTION :","o":["Presbyacousie","Traumatisme sonore","Ototoxiques","Maladie de Ménière","Bouchon de cérumen"],"r":[0,1,2,3],"e":"Surdité de perception : presbyacousie, trauma sonore, ototoxiques, génétique, infection (CMV, méningite), Ménière, neurinome de l'acoustique. Le bouchon de cérumen = surdité de TRANSMISSION.","s":6},{"q":"Concernant les CANAUX SEMI-CIRCULAIRES :","o":["Au nombre de 3 : latéral, antérieur, postérieur","Disposés dans les 3 plans de l'espace","Détectent l'accélération ANGULAIRE (rotations)","Détectent la position statique de la tête","Contiennent la cupule + cellules ciliées (crista ampullaris)"],"r":[0,1,2,4],"e":"3 canaux SC perpendiculaires (latéral, antérieur, postérieur) : détectent les ROTATIONS (accélération angulaire). Cupule + crista ampullaris dans l'ampoule. La position STATIQUE est détectée par les MACULES (saccule + utricule), pas les canaux SC.","s":6},{"q":"Le saccule et l'utricule détectent :","o":["L'accélération angulaire (rotations)","L'accélération linéaire et la position de la tête (gravité)","L'audition","La proprioception articulaire"],"r":1,"e":"Saccule et utricule contiennent les MACULES avec OTOLITHES (carbonate de calcium) → détectent la gravité et l'accélération LINÉAIRE. Utricule = plan horizontal, saccule = plan vertical. Les canaux SC = rotations.","s":6},{"q":"Le réflexe vestibulo-oculaire (VOR) :","o":["Empêche les mouvements oculaires","Maintient la stabilité du regard pendant les mouvements de la tête","Provoque le nystagmus pathologique","Active uniquement le NC IV"],"r":1,"e":"VOR : déplacement de la tête → mouvement oculaire compensatoire opposé pour stabiliser l'image sur la rétine. Implique les NC III, IV, VI. Crucial pour la vision pendant la locomotion.","s":6},{"q":"Un nystagmus VERTICAL spontané évoque :","o":["Une cause périphérique bénigne","Une atteinte CENTRALE (tronc cérébral, cervelet)","Une presbyacousie","Une otite externe"],"r":1,"e":"Nystagmus vertical spontané = signe d'alerte CENTRAL (tronc cérébral, cervelet, AVC, SEP, tumeur). Le nystagmus périphérique est typiquement horizonto-rotatoire.","s":6},{"q":"Différenciation vertige PÉRIPHÉRIQUE vs CENTRAL :","o":["Périphérique : intense, brutal, bref","Central : modéré, progressif, continu","Périphérique : signes auditifs possibles (acouphènes, hypoacousie)","Central : signes neurologiques associés (ataxie, dysarthrie)","Le périphérique est plus grave que le central"],"r":[0,1,2,3],"e":"Périphérique (~85 %) : intense/bref/épisodique, signes auditifs possibles, nystagmus horizontal-rotatoire. Central (~15 %) : modéré/continu, signes neuro, nystagmus possible vertical. Le central est PLUS grave (AVC, tumeur).","s":6},{"q":"Le VPPB (BPPV) est dû à :","o":["Une infection virale","Un déplacement d'OTOLITHES de l'utricule vers les canaux semi-circulaires","Un anévrisme cérébral","Une atteinte du tronc"],"r":1,"e":"VPPB = canalolithiase : otolithes déplacés de l'utricule vers les canaux SC (postérieur ++). Ces otolithes 'libres' continuent de bouger après l'arrêt du mvt de tête → vertige. Tx : manœuvres de repositionnement (Epley).","s":6},{"q":"Caractéristiques du VPPB :","o":["Cause la plus fréquente de vertige pathologique","Vertige bref (< 1 min) déclenché par les changements de position","Diagnostic : manœuvre de Dix-Hallpike","Tx : manœuvres de repositionnement (Epley, Semont)","S'accompagne d'une hypoacousie marquée"],"r":[0,1,2,3],"e":"VPPB : cause la + fréquente, vertige bref < 1 min positionnel, dx Dix-Hallpike, tx manœuvres libératoires. PAS de troubles auditifs (différentiel avec Ménière).","s":6},{"q":"Tétrade de la maladie de MÉNIÈRE :","o":["Vertige rotatoire violent (heures)","Acouphènes","Hypoacousie fluctuante (souvent unilatérale)","Sensation de plénitude auriculaire","Céphalée frontale"],"r":[0,1,2,3],"e":"Tétrade Ménière : 1) vertige rotatoire violent (heures) ; 2) acouphènes ; 3) hypoacousie fluctuante ; 4) plénitude auriculaire. Cause idiopathique (hydrops endolymphatique). Tx : régime hyposodé, diurétiques, bétahistine.","s":6},{"q":"La neuronite vestibulaire aiguë se distingue de la maladie de Ménière par :","o":["L'absence d'hypoacousie et d'acouphènes","La présence de surdité unilatérale","Une évolution chronique sur des années","Une étiologie auto-immune systémique"],"r":0,"e":"Neuronite vestibulaire : vertige isolé brutal et durable (jours), SANS hypoacousie ni acouphènes (≠ Ménière). Souvent virale. Évolution favorable en quelques jours/semaines avec rééducation vestibulaire précoce.","s":6},{"q":"Concernant la rééducation vestibulaire en kinésithérapie :","o":["Manœuvres libératoires (Epley) pour le VPPB","Habituation : exercices répétés provoquant le vertige pour favoriser la compensation centrale","Exercices de stabilisation du regard (VOR)","Rééducation posturale et de l'équilibre","Indication uniquement chez l'enfant"],"r":[0,1,2,3],"e":"Kiné vestibulaire : manœuvres pour VPPB, habituation, stabilisation du regard, équilibre. Très efficace après neuronite vestibulaire et chez la personne âgée. Indication à tout âge selon le diagnostic.","s":6},{"q":"L'oreille externe est composée de :","o":["Cochlée + canaux semi-circulaires","Pavillon + conduit auditif externe","Marteau, enclume, étrier","Trompe d'Eustache"],"r":1,"e":"Oreille externe = pavillon + conduit auditif externe, jusqu'au tympan.","s":6},{"q":"La chaîne ossiculaire de l'oreille moyenne comprend :","o":["Marteau + enclume + étrier","Cochlée + utricule","Trompe + tympan","Saccule"],"r":0,"e":"Oreille moyenne : 3 osselets (marteau-enclume-étrier) qui transmettent les vibrations du tympan à l'oreille interne (fenêtre ovale).","s":6},{"q":"L'organe de Corti se trouve dans :","o":["Le canal semi-circulaire","La cochlée (rampe médiane)","Le saccule","La trompe d'Eustache"],"r":1,"e":"Organe de Corti = récepteur auditif dans la rampe médiane de la cochlée, contient les cellules ciliées.","s":6},{"q":"Le système vestibulaire détecte :","o":["Les sons","L'équilibre et les mouvements de la tête (canaux semi-circulaires + utricule + saccule)","La vision","La gustation"],"r":1,"e":"Vestibulaire : 3 canaux semi-circulaires (rotation) + utricule/saccule (linéaires + gravité).","s":6},{"q":"L'otite moyenne aiguë est typiquement :","o":["Bénigne, sans traitement","Une infection bactérienne (pneumocoque, Haemophilus) → otalgie + fièvre","Toujours virale","Contagieuse"],"r":1,"e":"OMA : infection bactérienne fréquente chez l'enfant (pneumocoque, Haemophilus), otalgie + fièvre + bombement tympan.","s":6},{"q":"La surdité de transmission est due à :","o":["Atteinte cochléaire","Atteinte de l'oreille externe ou moyenne (bouchon cire, OMA, otosclérose)","Atteinte du nerf VIII","Atteinte centrale"],"r":1,"e":"Surdité de transmission : obstacle à la conduction du son (cire, OMA, otosclérose). Test Rinne négatif (CO > CA).","s":6},{"q":"La surdité de perception est due à :","o":["Atteinte de l'oreille moyenne","Atteinte cochléaire (presbyacousie, traumatisme sonore) ou rétrocochléaire","Bouchon de cire","Otite externe"],"r":1,"e":"Perception (neurosensorielle) : cochlée, nerf VIII ou voies centrales. Presbyacousie, trauma sonore, ototoxiques, neurinome.","s":6},{"q":"Le BPPV (Vertige Positionnel Paroxystique Bénin) est dû à :","o":["Une infection","Des otolithes (otoconies) déplacés dans les canaux semi-circulaires","Une tumeur","Une AVC"],"r":1,"e":"BPPV : otolithes détachés migrent dans canal semi-circulaire (souvent postérieur) → vertiges brefs déclenchés par position.","s":6},{"q":"La maladie de Ménière associe :","o":["Vertiges + surdité fluctuante + acouphènes + plénitude auriculaire","Surdité isolée","Acouphènes seuls","Vertige isolé"],"r":0,"e":"Ménière : tétrade vertiges + surdité fluctuante (basse fréq.) + acouphènes + plénitude auriculaire. Hydrops endolymphatique.","s":6},{"q":"La manœuvre de Hallpike-Dix sert à diagnostiquer :","o":["Une surdité","Un BPPV (vertige positionnel)","Une otite","Une tumeur"],"r":1,"e":"Manœuvre de Dix-Hallpike : test diagnostique du BPPV, déclenche un nystagmus rotatoire bref typique.","s":6},{"q":"De quoi est fait le pavillon de l'oreille ?","o":["De cartilage élastique avec un lobule","D'os temporal","De cartilage hyalin uniquement","De tissu fibreux dense"],"r":0,"e":"Le pavillon associe cartilage élastique et lobule charnu ; l'oreille moyenne est creusée dans l'os temporal.","s":6},{"q":"Quelle est la longueur approximative du conduit auditif externe ?","o":["2 à 3 cm, avec un trajet en S","1 cm rectiligne","5 cm","0,5 cm"],"r":0,"e":"Le CAE mesure 2-3 cm et décrit un S ; le tympan mesure environ 1 cm.","s":6},{"q":"Quel rôle joue le cérumen ?","o":["Un rôle anti-microbien","Un rôle d'amplification sonore","Un rôle d'équilibration de la pression","Aucun rôle physiologique"],"r":0,"e":"Le cérumen protège le conduit ; en excès il forme un bouchon responsable d'hypoacousie réversible.","s":6},{"q":"Quelles parties distingue-t-on sur le tympan ?","o":["L'umbo, la pars tensa et la pars flaccida","Le modiolus et la scala media","La crista et la cupule","La macula et la membrane otolithique"],"r":0,"e":"Ces repères sont ceux de l'otoscopie ; les autres termes appartiennent à l'oreille interne.","s":6},{"q":"Sur quelle structure l'étrier s'applique-t-il ?","o":["La fenêtre ovale","La fenêtre ronde","Le tympan","Le modiolus"],"r":0,"e":"L'étrier transmet la vibration à la périlymphe via la fenêtre ovale.","s":6},{"q":"Quel liquide remplit le labyrinthe osseux ?","o":["La périlymphe","L'endolymphe","Le LCR","La lymphe"],"r":0,"e":"La périlymphe, riche en sodium, occupe le labyrinthe osseux ; l'endolymphe, riche en potassium, le labyrinthe membraneux.","s":6},{"q":"Quel traitement la fiche propose-t-elle pour un bouchon de cérumen ?","o":["Ramollissement par huile ou bicarbonate puis lavage","Gouttes antibiotiques","Amoxicilline orale","Stapédectomie"],"r":0,"e":"Le ramollissement puis le lavage suffisent ; les antibiotiques traitent l'otite externe.","s":6},{"q":"Quel signe clinique évoque une otite externe ?","o":["Une douleur intense à la traction du pavillon","Un tympan rouge et bombé","Une autophonie","Un hémotympan"],"r":0,"e":"La douleur à la traction du pavillon signe l'atteinte du conduit ; le tympan bombé évoque une OMA.","s":6},{"q":"Quel symptôme traduit une dysfonction de la trompe d'Eustache ?","o":["Une sensation d'oreille bouchée avec autophonie","Une douleur à la traction du pavillon","Un vertige rotatoire","Des acouphènes pulsatiles"],"r":0,"e":"La baisse de pression dans l'oreille moyenne donne cette sensation et expose à l'otite séreuse.","s":6},{"q":"Quelle manœuvre prévient le barotraumatisme ?","o":["La déglutition ou la manœuvre de Valsalva","La manœuvre d'Epley","La manœuvre de Dix-Hallpike","La manœuvre de Semont"],"r":0,"e":"Valsalva et déglutition ouvrent la trompe ; Epley, Semont et Dix-Hallpike concernent le VPPB.","s":6},{"q":"Quels germes sont responsables de l'otite moyenne aiguë ?","o":["S. pneumoniae, H. influenzae, M. catarrhalis","Pseudomonas aeruginosa et S. aureus","Neisseria meningitidis et E. coli","Borrelia et CMV"],"r":0,"e":"Ces trois germes dominent l'OMA ; Pseudomonas et S. aureus causent l'otite externe.","s":6},{"q":"Quel antibiotique la fiche propose-t-elle en première intention dans l'OMA bactérienne ?","o":["L'amoxicilline","La pénicilline G intraveineuse","La gentamycine","La ciprofloxacine en gouttes"],"r":0,"e":"L'amoxicilline est le traitement de première intention, notamment chez l'enfant de moins de 2 ans.","s":6},{"q":"La physiopathologie est définie comme :","o":["L'étude du fonctionnement normal du corps","La science qui étudie les causes des maladies et les mécanismes de leur développement","L'étude des médicaments","L'étude de la classification des maladies"],"r":1,"e":"La physiopathologie = science qui étudie les causes (étiologie) et les mécanismes (pathogenèse) des maladies, ainsi que les signes/symptômes qu'ils entraînent.","s":7},{"q":"Selon l'OMS (1948), la santé est :","o":["L'absence de maladie","Un état de complet bien-être physique, mental et social","Une bonne forme physique","L'absence de symptômes"],"r":1,"e":"OMS 1948 : la santé est 'un état de complet bien-être physique, mental et social, et pas seulement l'absence de maladie ou d'infirmité'.","s":7},{"q":"Parmi les agents pouvant déclencher une maladie, on retrouve :","o":["Agents biologiques (virus, bactéries)","Agents physiques (traumatismes, radiations)","Agents chimiques (poisons, médicaments)","Susceptibilité génétique","Mode de vie / stress","La rétroaction négative de l'homéostasie"],"r":[0,1,2,3,4],"e":"Les facteurs étiologiques sont multiples : biologiques, physiques, chimiques, génétiques, mode de vie/stress, et idiopathiques (cause inconnue). Toutes ces propositions sont correctes. La rétroaction négative est le mécanisme qui corrige un écart : elle protège de la maladie au lieu de la déclencher.","s":7},{"q":"L'étiologie d'une maladie répond à la question :","o":["Comment se développe-t-elle ?","Pourquoi survient-elle ?","Quand apparaît-elle ?","Où est-elle localisée ?"],"r":1,"e":"Étiologie = cause/origine (POURQUOI). Pathogenèse = mécanisme de développement (COMMENT).","s":7},{"q":"La pathogenèse correspond à :","o":["La cause d'une maladie","Le mécanisme par lequel se déroule le développement de la maladie","La classification des symptômes","Le traitement de la maladie"],"r":1,"e":"Pathogenèse = séquence d'événements cellulaires et tissulaires depuis le contact initial avec l'agent étiologique jusqu'à l'expression finale de la maladie. Répond au COMMENT.","s":7},{"q":"Concernant les manifestations cliniques, quelles affirmations sont vraies ?","o":["Un symptôme est subjectif (signalé par le patient)","Un signe est objectif (observable par le clinicien)","La fièvre est un symptôme","La douleur est un symptôme","Un syndrome est un ensemble de signes et symptômes caractéristiques"],"r":[0,1,3,4],"e":"Symptôme = subjectif (douleur, vertiges, céphalées). Signe = objectif (fièvre, tachycardie, œdème). La fièvre est un SIGNE (objectivable). Syndrome = ensemble caractéristique de signes/symptômes.","s":7},{"q":"Une maladie aiguë se caractérise par :","o":["Une longue durée (mois/années)","Un début brutal et un développement rapide","Des exacerbations et rémissions","Un début insidieux"],"r":1,"e":"Maladie aiguë : courte durée, début brutal, développement rapide, causes facilement identifiables, souvent spontanément résolutive. Chronique = mois/années, exacerbations/rémissions.","s":7},{"q":"Combien de niveaux d'organisation hiérarchique compte le corps humain ?","o":["3","4","5","6"],"r":3,"e":"6 niveaux : chimique → cellulaire → tissulaire → organique → systémique → organisme.","s":7},{"q":"Quels sont les 4 types de tissus fondamentaux du corps humain ?","o":["Épithélial","Conjonctif","Adipeux","Musculaire","Nerveux"],"r":[0,1,3,4],"e":"Les 4 tissus fondamentaux : épithélial, conjonctif, musculaire, nerveux. Le tissu adipeux est un sous-type de tissu conjonctif.","s":7},{"q":"L'homéostasie est définie comme :","o":["Un état totalement statique du corps","Un état d'équilibre dynamique de l'environnement interne","L'absence de toute variation physiologique","Un mécanisme uniquement nerveux"],"r":1,"e":"Homéostasie = état d'équilibre DYNAMIQUE de l'environnement interne, maintenu par les processus régulateurs. Les valeurs varient dans une fourchette étroite compatible avec la vie.","s":7},{"q":"Quels sont les principaux systèmes régulateurs de l'homéostasie ?","o":["Système nerveux (réponse rapide)","Système endocrinien (réponse lente mais durable)","Système digestif","Système respiratoire","Système lymphatique"],"r":[0,1],"e":"Les deux systèmes régulateurs principaux sont : le système nerveux (signaux électriques rapides) et le système endocrinien (hormones, plus lent mais durable).","s":7},{"q":"Le syndrome général d'adaptation (de Selye) comprend, dans l'ordre :","o":["Résistance → alerte → épuisement","Alerte → résistance → épuisement","Épuisement → alerte → résistance","Alerte → épuisement → résistance"],"r":1,"e":"Syndrome général d'adaptation : 1) phase d'alerte (réactions immédiates) → 2) phase de résistance (tentative de retour à l'homéostasie) → 3) phase d'épuisement (les défenses sont dépassées, maladies).","s":7},{"q":"Quels sont les 3 composants fondamentaux d'un système de rétroaction ?","o":["Récepteur","Centre de contrôle","Effecteur","Amplificateur","Mémoire"],"r":[0,1,2],"e":"Système de rétroaction : récepteur (surveille) → centre de contrôle (évalue) → effecteur (répond). Voie afférente vers le centre, efférente depuis le centre.","s":7},{"q":"Une rétroaction NÉGATIVE :","o":["Renforce le stimulus initial","Inverse / annule le changement causé par le stimulus","Reste sans effet","Provoque toujours une pathologie"],"r":1,"e":"Rétroaction négative = inverse le changement (ramène à la normale). C'est le mécanisme le plus fréquent (PA, glycémie, température). Elle s'arrête seule quand la condition est restaurée.","s":7},{"q":"Parmi les exemples suivants, lesquels relèvent d'une rétroaction NÉGATIVE ?","o":["Régulation de la pression artérielle","Régulation de la glycémie (insuline/glucagon)","Régulation de la température","Accouchement","Coagulation sanguine"],"r":[0,1,2],"e":"Rétroactions négatives : PA, glycémie, température (les classiques). Accouchement et coagulation = rétroactions POSITIVES (amplifient le stimulus).","s":7},{"q":"L'accouchement est un exemple classique de :","o":["Rétroaction négative","Rétroaction positive","Mécanisme étiologique","Pathogenèse"],"r":1,"e":"L'accouchement = rétroaction positive : étirement du col → ocytocine → contractions plus fortes → plus d'étirement... Cycle interrompu par la naissance.","s":7},{"q":"Lors d'une rétroaction négative pour la glycémie élevée, quelle hormone intervient ?","o":["Glucagon","Insuline","Adrénaline","Cortisol"],"r":1,"e":"Glycémie élevée → cellules β du pancréas libèrent l'insuline → glucose entre dans les cellules + foie stocke en glycogène → glycémie ↓. Le glucagon (cellules α) fait l'inverse.","s":7},{"q":"Une lésion cellulaire RÉVERSIBLE survient typiquement :","o":["Après un stimulus intense et prolongé","Après un stimulus léger ou transitoire","Toujours après une lésion physique","Jamais — les lésions sont toujours irréversibles"],"r":1,"e":"Stimulus léger/transitoire → lésion réversible (la cellule peut revenir à l'homéostasie). Stimulus intense/progressif → lésion irréversible (nécrose ou apoptose).","s":7},{"q":"Quelles techniques font partie de l'examen objectif non invasif ?","o":["Inspection","Palpation","Auscultation","Percussion","Biopsie"],"r":[0,1,2,3],"e":"Examen objectif non invasif : inspection, palpation, auscultation, percussion + signes vitaux. La biopsie est INVASIVE (prélèvement).","s":7},{"q":"La SENSIBILITÉ d'un test diagnostique correspond à :","o":["La proportion de personnes saines correctement identifiées comme négatives","La proportion de personnes malades correctement identifiées comme positives","La capacité d'un test à mesurer ce qu'il est censé mesurer","La reproductibilité du test"],"r":1,"e":"Sensibilité = vrais positifs / (vrais positifs + faux négatifs) = capacité du test à détecter les vrais malades. Spécificité = vrais négatifs / (vrais négatifs + faux positifs).","s":7},{"q":"Si un test très SENSIBLE est négatif, on peut :","o":["Confirmer la maladie","Exclure la maladie (rule out)","Demander un autre examen sans plus","Annoncer une rémission"],"r":1,"e":"Test très sensible négatif → maladie exclue (rule out). Un test très spécifique positif → maladie confirmée (rule in).","s":7},{"q":"Concernant la fiabilité (reliability) et la validité (validity), quelles affirmations sont vraies ?","o":["Fiabilité = répétabilité du résultat","Validité = mesurer réellement ce qu'on veut mesurer","Un test peut être fiable sans être valide","La validité dépend de la prévalence","Fiabilité et validité sont synonymes"],"r":[0,1,2],"e":"Fiabilité = même résultat si on répète. Validité = mesure ce qu'elle prétend mesurer. Un test peut être très répétable mais mesurer la mauvaise chose ! Ce sont des notions distinctes.","s":7},{"q":"L'INCIDENCE d'une maladie correspond à :","o":["Le nombre total de cas existants à un moment donné","Le nombre de NOUVEAUX cas dans une population à risque sur une période","Le nombre de décès liés à la maladie","La proportion de population guérie"],"r":1,"e":"Incidence = NOUVEAUX cas/période (mesure le risque de développer la maladie). Prévalence = cas existants à un instant T (mesure la charge dans la population).","s":7},{"q":"La prévention SECONDAIRE consiste à :","o":["Empêcher l'apparition de la maladie (vaccination)","Dépister précocement et traiter rapidement","Réhabiliter les patients atteints","Soulager les symptômes en fin de vie"],"r":1,"e":"Prévention primaire = empêcher l'apparition (vaccination, hygiène de vie). Secondaire = dépistage + traitement précoce. Tertiaire = réhabilitation, réduction des séquelles.","s":7},{"q":"Parmi les types d'études épidémiologiques, on retrouve :","o":["Études transversales","Études cas-témoins","Études de cohorte","Méta-analyses systématiques","Études philosophiques"],"r":[0,1,2,3],"e":"Études épidémio : transversales (instantané), cas-témoins (comparaison rétrospective), cohortes (suivi prospectif), essais cliniques randomisés, méta-analyses (synthèse). Pas d'études philosophiques en épidémio !","s":7},{"q":"Une maladie multifactorielle se définit par :","o":["Une seule cause clairement identifiée","L'interaction de plusieurs gènes et facteurs environnementaux","Une cause uniquement environnementale","Une cause toujours infectieuse"],"r":1,"e":"Maladie multifactorielle : interaction gènes × environnement (ex : cancer, diabète, maladies cardiovasculaires). Cause unique = monofactorielle (ex : génétique pure).","s":7},{"q":"Concernant les fluides corporels, quelles affirmations sont vraies ?","o":["L'ICF est le liquide intracellulaire","L'ECF est le liquide extracellulaire","Le plasma sanguin est de l'ECF","Le LCR est dans le cerveau et la moelle","Le liquide interstitiel est intracellulaire"],"r":[0,1,2,3],"e":"ICF = intracellulaire ; ECF = extracellulaire (incluant plasma, lymphe, LCR, liquide interstitiel). Le liquide interstitiel est EXTRACELLULAIRE (entre les cellules).","s":7},{"q":"Le terme « Physiopathologie » vient étymologiquement de :","o":["Physis + Pathos + Logia","Bios + Patho + Logos","Pharma + Pathos + Logos","Anatomos + Patho + Logos"],"r":0,"e":"Du grec : Physis (nature) + Pathos (souffrance) + Logia (étude) = science qui étudie les causes des maladies.","s":7},{"q":"La distinction entre Pathologie et Physiologie est :","o":["Pathologie = changements anormaux ; Physiologie = fonctions normales","Synonymes","Pathologie = traitement ; Physiologie = diagnostic","Pathologie = aiguë ; Physiologie = chronique"],"r":0,"e":"Pathologie = études des changements structurels/fonctionnels (maladie) ; Physiologie = fonctions normales du corps.","s":7},{"q":"Une maladie peut être :","o":["Aiguë ou chronique","Acquise ou congénitale","Idiopathique","Multifactorielle (gènes × environnement)","Toujours mortelle"],"r":[0,1,2,3],"e":"Maladies : aiguës/chroniques, acquises/congénitales, idiopathiques, multifactorielles. Pas toujours mortelles.","s":7},{"q":"L'étiologie répond à la question :","o":["COMMENT ?","POURQUOI ?","QUAND ?","OÙ ?"],"r":1,"e":"Étiologie = origine/cause = POURQUOI. Pathogenèse = mécanisme = COMMENT.","s":7},{"q":"Le syndrome se définit comme :","o":["Une maladie unique","Un ensemble de signes et symptômes caractéristiques d'une condition","Un traitement","Un symptôme isolé"],"r":1,"e":"Syndrome = ensemble de signes et symptômes formant une entité clinique caractéristique.","s":7},{"q":"Le syndrome général d'adaptation (Selye) comprend dans l'ordre :","o":["Alerte → Résistance → Épuisement","Résistance → Alerte → Épuisement","Choc → Stress → Récupération","Épuisement → Récupération → Adaptation"],"r":0,"e":"Selye : (1) Alerte (réactions immédiates) → (2) Résistance (tentative homéostasie) → (3) Épuisement (défenses dépassées).","s":7},{"q":"Les composants d'un système de rétroaction sont :","o":["Récepteur","Centre de contrôle","Effecteur","Amplificateur","Mémoire"],"r":[0,1,2],"e":"3 composants : récepteur (surveille) → centre de contrôle (évalue) → effecteur (répond).","s":7},{"q":"La prévention PRIMAIRE consiste à :","o":["Dépister la maladie à un stade précoce et asymptomatique","Agir avant l'apparition de la maladie pour en réduire l'incidence (vaccination, hygiène, éducation)","Limiter les séquelles et les récidives d'une maladie déjà installée","Traiter les complications en phase terminale"],"r":1,"e":"Prévention primaire : empêcher la maladie d'apparaître (elle fait baisser l'incidence). Secondaire : la détecter tôt, au stade infraclinique (dépistage). Tertiaire : en limiter les conséquences et réadapter — c'est le terrain habituel du kinésithérapeute.","s":7},{"q":"La prévention tertiaire consiste à :","o":["Empêcher l'apparition (vaccination)","Dépister précocement","Réhabiliter et limiter les séquelles","Soulager en fin de vie uniquement"],"r":2,"e":"Primaire = empêcher ; Secondaire = dépister + traiter précoce ; Tertiaire = réhabilitation, réduction des séquelles.","s":7},{"q":"Une étude de cohorte est :","o":["Rétrospective avec cas et témoins","Prospective, suit une population dans le temps","Une seule mesure transversale","Une revue systématique"],"r":1,"e":"Cohorte = suivi prospectif d'une population, observe l'apparition de la maladie.","s":7},{"q":"Que signifie la racine grecque « physis » dans le mot physiopathologie ?","o":["Nature, croissance","Souffrance","Science, étude","Maladie"],"r":0,"e":"Physis = nature/croissance, pathos = souffrance, logia = science.","s":7},{"q":"D'où vient étymologiquement le mot « maladie » selon la fiche ?","o":["Du latin dolentia, douleur ou souffrance","Du grec pathos","Du grec homeo","Du latin morbus"],"r":0,"e":"La fiche indique le latin dolentia ; pathos est la racine de pathologie.","s":7},{"q":"Quels sont les objectifs de la physiopathologie en physiothérapie ?","o":["Comprendre les mécanismes, orienter le diagnostic, guider la thérapeutique et développer l'esprit critique","Établir un traitement médicamenteux","Réaliser des analyses histologiques","Élaborer des politiques de santé publique"],"r":0,"e":"Ces quatre objectifs sont ceux énoncés dans la fiche pour le kinésithérapeute.","s":7},{"q":"Quels modèles de la santé la fiche oppose-t-elle ?","o":["Le modèle biomédical et le modèle biopsychosocial","Le modèle aigu et le modèle chronique","Le modèle préventif et le modèle curatif","Le modèle génétique et le modèle environnemental"],"r":0,"e":"La définition de l'OMS ouvre sur cette opposition entre approche strictement biologique et approche globale.","s":7},{"q":"Qu'est-ce qu'une cause interne de maladie selon la fiche ?","o":["L'hérédité, l'âge, le sexe et les modifications des structures ou systèmes","Un agent infectieux","Une brûlure","Une intoxication médicamenteuse"],"r":0,"e":"Les causes externes proviennent de l'environnement ; les internes tiennent au terrain.","s":7},{"q":"Comment définit-on une maladie congénitale ?","o":["Par des anomalies présentes à la naissance, génétiques ou environnementales","Par une cause inconnue","Par un événement post-natal","Par une interaction gènes-environnement à l'âge adulte"],"r":0,"e":"Congénital renvoie à la présence à la naissance ; acquis à un événement post-natal.","s":7},{"q":"Que sont les séquelles d'une maladie ?","o":["Les lésions ou déficiences causées par la maladie","Les extensions indésirables de la maladie","L'ensemble des signes et symptômes","La cause initiale"],"r":0,"e":"Les complications sont les extensions indésirables, les séquelles les déficiences résiduelles.","s":7},{"q":"Qu'est-ce que la morphologie dans le processus pathologique ?","o":["L'étude de la structure ou de la forme des cellules et tissus, aux niveaux macro et microscopique","L'étude des fonctions normales","La séquence de développement de la maladie","L'identification de la maladie"],"r":0,"e":"L'histologie, plus restreinte, étudie les cellules et la matrice extracellulaire.","s":7},{"q":"Comment la fiche définit-elle une lésion ?","o":["Une discontinuité pathologique ou traumatique d'un organe ou d'un tissu","Toute anomalie fonctionnelle","Un ensemble de signes et symptômes","Un déséquilibre homéostatique"],"r":0,"e":"La lésion est une discontinuité structurelle, visible en morphologie.","s":7},{"q":"Que recouvre l'anamnèse ?","o":["Les antécédents médicaux passés et actuels du patient","L'inspection et la palpation","Les examens de laboratoire","L'interprétation du pronostic"],"r":0,"e":"L'anamnèse est l'interrogatoire ; l'examen objectif regroupe inspection, palpation, auscultation et percussion.","s":7},{"q":"Comment se caractérise une maladie subaiguë ?","o":["Elle est intermédiaire : moins grave que l'aiguë, moins longue que la chronique","Elle dure des années","Elle est toujours spontanément résolutive","Elle débute toujours brutalement"],"r":0,"e":"La forme subaiguë occupe une position intermédiaire entre aigu et chronique.","s":7},{"q":"Quelles particularités évolutives une maladie chronique peut-elle présenter ?","o":["Des exacerbations et des rémissions","Une résolution spontanée systématique","Un début toujours brutal","Une guérison en quelques jours"],"r":0,"e":"La chronicité s'accompagne souvent d'une alternance de poussées et de périodes calmes.","s":7},{"q":"Quel est le niveau 4 de l'organisation hiérarchique du corps ?","o":["Le niveau organique","Le niveau tissulaire","Le niveau systémique","Le niveau cellulaire"],"r":0,"e":"Chimique (1), cellulaire (2), tissulaire (3), organique (4), systémique (5), organisme (6).","s":7},{"q":"L'hypertrophie correspond à :","o":["Une augmentation du NOMBRE de cellules","Une augmentation de la TAILLE des cellules","Une diminution du nombre de cellules","Une mort cellulaire"],"r":1,"e":"Hypertrophie = ↑ TAILLE des cellules (↑ protéines, organites). Hyperplasie = ↑ NOMBRE de cellules. Souvent associées dans certains organes.","s":8},{"q":"L'hyperplasie correspond à :","o":["Une augmentation de la taille des cellules","Une augmentation du nombre de cellules par prolifération","Une mort cellulaire programmée","Un changement de type cellulaire"],"r":1,"e":"Hyperplasie = augmentation du NOMBRE de cellules (prolifération). Concerne les cellules capables de se diviser (épiderme, intestin, épithélium glandulaire). Pas applicable aux cardiomyocytes.","s":8},{"q":"Concernant l'hypertrophie, quelles affirmations sont vraies ?","o":["Concerne les cellules à capacité de division limitée","L'hypertrophie utérine pendant la grossesse en est un exemple physiologique","L'hypertrophie cardiaque (HTA) en est un exemple pathologique","Elle implique la création de nouvelles cellules","La musculation est un exemple physiologique"],"r":[0,1,2,4],"e":"L'hypertrophie concerne les cellules à division limitée (myocytes cardiaques, lisses). Pas de nouvelles cellules. Exemples : utérus en grossesse (physio), muscle squelettique entraîné (physio), cœur en HTA (patho).","s":8},{"q":"L'atrophie correspond à :","o":["Une diminution du nombre de cellules vivantes","Une diminution de la taille des cellules avec perte de substance","Un changement irréversible de type cellulaire","Une mort cellulaire massive"],"r":1,"e":"Atrophie = diminution de la TAILLE des cellules (les cellules ne sont pas mortes). Mécanismes : ↓ synthèse protéique, ↑ dégradation (ubiquitine-protéasome, autophagie). Réversible.","s":8},{"q":"La métaplasie correspond à :","o":["Le remplacement d'un type cellulaire par un autre, mieux adapté","La mort programmée des cellules","Une augmentation du nombre de cellules","Un retour de la cellule à son état normal"],"r":0,"e":"Métaplasie = remplacement d'un type cellulaire différencié par un autre. Reprogrammation des cellules souches tissulaires. Réversible, mais peut prédisposer au cancer si stimulus persiste.","s":8},{"q":"Concernant la métaplasie, quels exemples sont corrects ?","o":["Tabagisme → métaplasie malpighienne des voies respiratoires","Reflux gastrique → œsophage de Barrett","Hypoxie → métaplasie cardiaque","Inflammation chronique → métaplasie épidermoïde","Grossesse → métaplasie utérine"],"r":[0,1,3],"e":"Métaplasie classique : tabagisme (épithélium cilié → pavimenteux), Barrett (malpighien → cylindrique intestinal sur reflux), inflammation chronique. La métaplasie cardiaque ou utérine de grossesse n'existe pas en tant que telles.","s":8},{"q":"La dysplasie est :","o":["Toujours irréversible","Un état adaptatif réversible considéré comme précurseur du cancer","Une forme de mort cellulaire","Une réaction inflammatoire"],"r":1,"e":"Dysplasie = perturbation de la croissance cellulaire (variation taille/forme/organisation). Adaptative et réversible si stimulus supprimé, MAIS peut être un précurseur du cancer (col utérin +++).","s":8},{"q":"Quels sont les 2 caractéristiques classiques de la lésion cellulaire RÉVERSIBLE ?","o":["Gonflement cellulaire (tuméfaction)","Dégénérescence graisseuse","Pycnose nucléaire","Caryorrhexie","Caryolyse"],"r":[0,1],"e":"Lésion réversible : gonflement cellulaire (défaillance pompe Na/K) + dégénérescence graisseuse (foie surtout). Pycnose, caryorrhexie, caryolyse = signes de NÉCROSE (irréversible).","s":8},{"q":"Concernant les mécanismes fondamentaux de lésion cellulaire, on retrouve :","o":["Déplétion en ATP / hypoxie","Formation de radicaux libres (ROS)","Perturbation de l'homéostasie calcique","Augmentation excessive du glycogène","Démyélinisation"],"r":[0,1,2],"e":"Mécanismes fondamentaux : 1) déplétion ATP/hypoxie ; 2) ROS (stress oxydatif) ; 3) ↑ Ca²⁺ intracellulaire (active phospholipases, protéases, endonucléases). Le reste = mécanismes spécifiques.","s":8},{"q":"La nécrose est :","o":["Une mort cellulaire programmée physiologique","Une mort cellulaire pathologique avec inflammation locale","Une adaptation réversible","Un changement de type cellulaire"],"r":1,"e":"Nécrose = mort cellulaire PATHOLOGIQUE (jamais physiologique), suivie d'autolyse + dénaturation des protéines + fuite du contenu cellulaire + INFLAMMATION locale. Apoptose = sans inflammation.","s":8},{"q":"Quels sont les changements nucléaires de la nécrose ?","o":["Pycnose (condensation de la chromatine)","Caryorrhexie (fragmentation du noyau)","Caryolyse (dissolution du noyau)","Hyperchromasie","Apoptose"],"r":[0,1,2],"e":"Évolution nucléaire dans la nécrose : pycnose → caryorrhexie → caryolyse. L'apoptose a un mécanisme propre (corps apoptotiques, sans rupture membranaire).","s":8},{"q":"La nécrose de COAGULATION est typique de :","o":["L'infarctus cérébral","L'infarctus du myocarde / rein (organes solides ischémiés)","La tuberculose","Les abcès cérébraux"],"r":1,"e":"Nécrose de coagulation = ischémie d'organes solides (cœur, rein), architecture préservée. Liquéfactive = SNC. Caséeuse = tuberculose. Gangrène = membres, intestin.","s":8},{"q":"La nécrose LIQUÉFACTIVE est typique de :","o":["L'infarctus du myocarde","Le système nerveux central (AVC) et abcès","La tuberculose","Les calcifications cardiaques"],"r":1,"e":"Nécrose liquéfactive = digestion enzymatique, formation d'un liquide visqueux. Typique du SNC (AVC, abcès cérébral) et des infections bactériennes (pus).","s":8},{"q":"La nécrose CASÉEUSE est typique de :","o":["L'infarctus du rein","La tuberculose","La gangrène sèche","L'AVC ischémique"],"r":1,"e":"Nécrose caséeuse = aspect 'fromage blanc', typique de la tuberculose. C'est une combinaison de nécrose de coagulation et de liquéfaction.","s":8},{"q":"Concernant l'apoptose, quelles affirmations sont vraies ?","o":["C'est une mort cellulaire programmée","Elle est généralement physiologique","Elle s'accompagne d'inflammation locale","Elle implique des caspases","Elle produit des corps apoptotiques phagocytés"],"r":[0,1,3,4],"e":"Apoptose : mort programmée, souvent PHYSIO (élimination cellules sénescentes/inutiles), SANS inflammation, médiée par les caspases, formation de corps apoptotiques phagocytés sans réaction inflammatoire.","s":8},{"q":"La voie INTRINSÈQUE de l'apoptose implique :","o":["La liaison FasL → Fas","La libération de cytochrome c mitochondrial → caspase-9","Une activation des récepteurs membranaires uniquement","La phagocytose par les macrophages"],"r":1,"e":"Voie intrinsèque (mitochondriale) : BAX/BAK → perméabilisation membrane externe → cytochrome c → APAF-1 → apoptosome → caspase-9 → caspases exécutrices. Voie extrinsèque = FasL/Fas → caspase-8.","s":8},{"q":"La voie EXTRINSÈQUE de l'apoptose passe par :","o":["Le cytochrome c et la caspase-9","Les récepteurs membranaires (Fas, TNFR1) et la caspase-8","Le calcium intracellulaire","L'ATP mitochondrial"],"r":1,"e":"Voie extrinsèque : FasL → Fas (ou TNF → TNFR1) → FADD → caspase-8 → caspases exécutrices. Élimine les lymphocytes auto-réactifs et les cellules infectées par virus.","s":8},{"q":"Différences entre NÉCROSE et APOPTOSE :","o":["Nécrose = inflammation ; Apoptose = pas d'inflammation","Nécrose = pathologique ; Apoptose = souvent physiologique","Apoptose = caspases ; Nécrose = pas de caspases","Apoptose = cellules entières gonflent et explosent","Apoptose = corps apoptotiques phagocytés"],"r":[0,1,2,4],"e":"Nécrose : inflammation, gonflement puis rupture, contenu déversé. Apoptose : caspases, condensation, corps apoptotiques phagocytés, PAS d'inflammation. Le gonflement-explosion = nécrose.","s":8},{"q":"La calcification DYSTROPHIQUE :","o":["Survient sur tissu normal en cas d'hypercalcémie","Survient dans des zones de nécrose, avec calcémie normale","Est physiologique","N'existe que chez l'enfant"],"r":1,"e":"Calcification dystrophique : dépôt de calcium dans des tissus NÉCROSÉS / lésionnels, avec calcémie sérique NORMALE. Métastatique = tissus normaux + hypercalcémie.","s":8},{"q":"La calcification MÉTASTATIQUE :","o":["Survient sur des zones nécrotiques","Survient sur des tissus normaux en cas d'hypercalcémie","Est limitée aux poumons","N'a pas de signification pathologique"],"r":1,"e":"Calcification métastatique : dépôts de calcium dans des tissus NORMAUX en présence d'hypercalcémie (hyperparathyroïdie, métastases osseuses). Touche reins, poumons, vaisseaux.","s":8},{"q":"La stéatose hépatique correspond à :","o":["Une accumulation anormale de protéines","Une accumulation de glycogène","Une accumulation de lipides (triglycérides) dans les hépatocytes","Une accumulation de fer"],"r":2,"e":"Stéatose hépatique = accumulation de triglycérides dans les hépatocytes (cytoplasme). Causes principales : alcoolisme, obésité, diabète, médicaments hépatotoxiques.","s":8},{"q":"Quels sont les 4 mécanismes d'accumulation intracellulaire ?","o":["Métabolisme anormal d'une substance normale","Défaut de repliement / transport (mutation)","Déficit enzymatique héréditaire","Substance exogène non digestible","Hyperréplication virale obligatoire"],"r":[0,1,2,3],"e":"4 mécanismes : 1) métabolisme anormal (stéatose) ; 2) défaut de repliement (α1-antitrypsine) ; 3) déficit enzymatique (Tay-Sachs, surcharge lysosomale) ; 4) substance exogène non digestible (silice, carbone).","s":8},{"q":"Le ROS (reactive oxygen species) provoque des lésions par :","o":["Activation directe des caspases","Peroxydation des lipides membranaires + oxydation des protéines + lésions de l'ADN","Compression mécanique","Acidose seule"],"r":1,"e":"Les ROS = espèces avec électron non apparié, très réactives. Elles provoquent peroxydation lipidique (membranes), oxydation protéique, lésions ADN. Stress oxydatif = ROS > antioxydants.","s":8},{"q":"Concernant l'hypoxie / déplétion en ATP, quelles conséquences observe-t-on ?","o":["Défaillance de la pompe Na/K ATPase","Gonflement cellulaire","Acidose lactique (glycolyse anaérobie)","Augmentation de la phosphorylation oxydative","Désorganisation du cytosquelette"],"r":[0,1,2,4],"e":"Hypoxie → ↓ ATP → 1) défaillance pompe Na/K → gonflement cellulaire ; 2) glycolyse anaérobie → acidose lactique ; 3) désorganisation cytosquelette ; 4) ↓ synthèse protéique. La phospho oxydative DIMINUE (mitochondries souffrent).","s":8},{"q":"Le rôle clé du Ca²⁺ dans la lésion cellulaire est :","o":["De stabiliser les membranes","D'activer phospholipases, protéases, endonucléases","D'inhiber les caspases","De fournir de l'énergie"],"r":1,"e":"L'augmentation pathologique du Ca²⁺ intracellulaire active : phospholipases (lésion membrane), protéases (cytosquelette), ATPase (épuise ATP), endonucléases (fragmentation ADN). Cascade de mort cellulaire.","s":8},{"q":"Concernant les manifestations cliniques (signes vs symptômes), quelles affirmations sont vraies ?","o":["Symptôme = subjectif (rapporté par le patient)","Signe = objectif (observable par le clinicien)","La douleur est un signe objectif","La fièvre est un signe","Un syndrome regroupe signes ET symptômes"],"r":[0,1,3,4],"e":"Symptôme = subjectif (douleur, vertige). Signe = objectif (fièvre, œdème, tachycardie). La douleur est un SYMPTÔME, pas un signe. Syndrome = ensemble caractéristique de signes/symptômes.","s":8},{"q":"L'apoptose est :","o":["Une mort cellulaire accidentelle","Une mort cellulaire programmée et contrôlée","Une nécrose","Une infection"],"r":1,"e":"Apoptose = mort cellulaire programmée, propre, sans inflammation. Nécrose = mort accidentelle.","s":8},{"q":"L'hypertrophie cellulaire est :","o":["L'augmentation du nombre de cellules","L'augmentation de la taille des cellules","La diminution de la taille","La transformation en autre type"],"r":1,"e":"Hypertrophie = ↑ taille (ex : muscles à l'entraînement). Hyperplasie = ↑ nombre.","s":8},{"q":"Les corps apoptotiques sont :","o":["Des débris cellulaires qui déclenchent une inflammation locale","Des fragments cellulaires entourés de membrane, rapidement phagocytés sans inflammation","Des dépôts de calcium intracellulaires","Des inclusions virales"],"r":1,"e":"L'apoptose fragmente la cellule en vésicules limitées par une membrane intacte, qui exposent la phosphatidylsérine et sont reconnues puis phagocytées par les macrophages. Le contenu cytoplasmique ne se répand jamais dans le milieu : d'où l'absence d'inflammation, contrairement à la nécrose.","s":8},{"q":"La métaplasie est :","o":["La mort cellulaire","Le remplacement réversible d'un type cellulaire par un autre","Une mutation génétique","La prolifération anarchique"],"r":1,"e":"Métaplasie = adaptation, remplacement d'un tissu par un autre type (ex : épithélium bronchique chez le fumeur).","s":8},{"q":"L'autophagie cellulaire correspond à :","o":["La digestion par la cellule de ses propres organites dans des lysosomes, souvent en cas de carence nutritionnelle","La destruction de la cellule par les lymphocytes T cytotoxiques","La transformation d'un épithélium en un autre","L'accumulation de lipides dans le cytoplasme"],"r":0,"e":"L'autophagie séquestre des organites vieillis ou endommagés dans un autophagosome qui fusionne avec un lysosome. C'est d'abord un mécanisme de survie (recyclage en période de jeûne ou d'ischémie) ; poussée à l'extrême, elle peut mener à la mort cellulaire.","s":8},{"q":"Les causes de lésion cellulaire incluent :","o":["Hypoxie/ischémie","Agents physiques (chaleur, radiations)","Agents chimiques","Agents biologiques (virus, bactéries)","Vieillissement","Un apport normal en oxygène et en nutriments"],"r":[0,1,2,3,4],"e":"Toutes ces causes peuvent provoquer des lésions cellulaires. L'hypoxie est la cause la plus fréquente. Des conditions métaboliques normales préservent la cellule ; c'est leur défaut (hypoxie, carence) qui lèse.","s":8},{"q":"Les radicaux libres sont :","o":["Des protéines normales","Des molécules réactives qui endommagent l'ADN, lipides, protéines","Des hormones","Des enzymes"],"r":1,"e":"Radicaux libres (ROS) = molécules instables qui causent stress oxydatif et lésions cellulaires.","s":8},{"q":"La nécrose se distingue de l'apoptose par :","o":["Aucune différence","La présence d'inflammation et atteinte de plusieurs cellules","La rapidité","Sa réversibilité"],"r":1,"e":"Nécrose : ↑ volume cellulaire, lyse, libération de contenu, INFLAMMATION. Apoptose : pas d'inflammation.","s":8},{"q":"La nécrose graisseuse (cytostéatonécrose) est typique de :","o":["L'infarctus du myocarde","La tuberculose","La pancréatite aiguë, où les lipases digèrent la graisse péri-pancréatique","L'accident vasculaire cérébral ischémique"],"r":2,"e":"Les lipases pancréatiques libérées hydrolysent les triglycérides du tissu adipeux voisin ; les acides gras libérés se combinent au calcium (saponification) et forment les taches blanc crayeux caractéristiques. On l'observe aussi après un traumatisme du sein.","s":8},{"q":"L'œdème intracellulaire résulte typiquement de :","o":["Une déshydratation","Une dysfonction de la pompe Na+/K+/ATPase","Une augmentation de la pression artérielle","Une carence en glucose"],"r":1,"e":"Dysfonction Na/K ATPase → entrée Na+ → eau suit par osmose → œdème intracellulaire (ballonisation).","s":8},{"q":"Quels facteurs déterminent si une lésion cellulaire sera réversible ou irréversible ?","o":["Le type, la durée et la gravité de la lésion, ainsi que la capacité d'adaptation de l'hôte","Uniquement l'intensité du stimulus","Uniquement la durée d'exposition","Le seul patrimoine génétique"],"r":0,"e":"La fiche retient ces quatre déterminants, dont la variabilité individuelle.","s":8},{"q":"Quel type cellulaire est concerné par l'hypertrophie ?","o":["Les cellules à capacité de division limitée, comme les myocytes cardiaques et lisses","Les cellules épithéliales de l'intestin","Les cellules souches hématopoïétiques","Les cellules de l'épiderme"],"r":0,"e":"Les cellules qui ne peuvent se diviser grossissent ; celles qui se divisent font de l'hyperplasie.","s":8},{"q":"Quelle voie de signalisation la fiche associe-t-elle à l'hypertrophie myocardique physiologique ?","o":["La voie PI3K/AKT","Les récepteurs couplés aux protéines G","La voie des caspases","La voie ubiquitine-protéasome"],"r":0,"e":"PI3K/AKT correspond à l'hypertrophie physiologique, les RCPG à l'hypertrophie pathologique.","s":8},{"q":"Quels facteurs de transcription sont activés dans l'hypertrophie myocardique ?","o":["GATA4, NFAT et MEF2","BAX et BAK","APAF-1 et FADD","BCL2 et BCL-XL"],"r":0,"e":"Ces trois facteurs augmentent la synthèse de protéines contractiles ; les autres appartiennent à l'apoptose.","s":8},{"q":"Quelles structures détectent l'augmentation de charge dans l'hypertrophie myocardique ?","o":["Les intégrines, capteurs mécaniques","Les récepteurs Fas","Les canaux calciques voltage-dépendants","Les barorécepteurs"],"r":0,"e":"Les intégrines transduisent la contrainte mécanique en signal intracellulaire.","s":8},{"q":"Quel exemple d'hyperplasie compensatoire la fiche donne-t-elle ?","o":["Le foie après résection partielle","Le sein à la puberté","L'endomètre en cas de déséquilibre hormonal","L'utérus pendant la grossesse"],"r":0,"e":"L'hyperplasie compensatoire du foie lui permet de retrouver son poids ; le sein et l'utérus relèvent de l'hyperplasie hormonale.","s":8},{"q":"Pourquoi l'hyperplasie constitue-t-elle un terrain favorable à la transformation maligne ?","o":["Parce que l'augmentation du nombre de divisions augmente le risque de mutations","Parce qu'elle détruit la membrane basale","Parce qu'elle bloque l'apoptose","Parce qu'elle provoque une inflammation chronique"],"r":0,"e":"Plus il y a de divisions, plus le risque d'erreur de réplication augmente.","s":8},{"q":"Quels mécanismes moléculaires sous-tendent l'atrophie ?","o":["Baisse de la synthèse protéique, hausse de la dégradation par la voie ubiquitine-protéasome et hausse de l'autophagie","Activation des caspases","Perméabilisation mitochondriale","Peroxydation lipidique"],"r":0,"e":"L'atrophie est un remodelage métabolique, sans mort cellulaire.","s":8},{"q":"Quel exemple d'atrophie physiologique liée au vieillissement la fiche cite-t-elle ?","o":["L'atrophie cérébrale sénile","L'atrophie musculaire sous plâtre","L'atrophie par dénervation","La cachexie néoplasique"],"r":0,"e":"Le vieillissement et la baisse hormonale donnent des atrophies physiologiques ; immobilisation, dénervation et cachexie sont pathologiques.","s":8},{"q":"Par quel mécanisme la métaplasie se produit-elle ?","o":["Par reprogrammation des cellules souches tissulaires","Par transformation directe d'une cellule différenciée en une autre","Par prolifération des cellules matures","Par fusion cellulaire"],"r":0,"e":"La fiche insiste : ce n'est pas une transdifférenciation directe mais une reprogrammation des cellules souches.","s":8},{"q":"Quel cancer risque de compliquer une métaplasie malpighienne bronchique ?","o":["Le carcinome épidermoïde","L'adénocarcinome","Le mélanome","Le sarcome"],"r":0,"e":"L'œsophage de Barrett expose à l'adénocarcinome, la métaplasie bronchique au carcinome épidermoïde.","s":8},{"q":"Quel type de métaplasie caractérise l'œsophage de Barrett ?","o":["Un épithélium malpighien remplacé par un épithélium cylindrique de type intestinal","Un épithélium cylindrique remplacé par un épithélium pavimenteux","Une formation osseuse ectopique","Une dysplasie de haut grade"],"r":0,"e":"C'est la métaplasie inverse de celle des voies respiratoires.","s":8},{"q":"Où la dysplasie est-elle le mieux étudiée ?","o":["Au col de l'utérus","Dans le foie","Dans le myocarde","Dans le rein"],"r":0,"e":"Le col utérin sert de modèle, ses degrés mineurs étant liés à l'irritation ou l'inflammation chronique.","s":8},{"q":"Quelle est la conséquence métabolique immédiate de l'hypoxie cellulaire ?","o":["Un passage au métabolisme anaérobie, avec accumulation d'acide lactique et baisse du pH","Une activation des caspases","Une peroxydation lipidique isolée","Une hypercalcémie sanguine"],"r":0,"e":"La chute d'ATP entraîne aussi la défaillance de la pompe Na⁺/K⁺ et le gonflement cellulaire.","s":8},{"q":"L'INFECTION correspond à :","o":["La présence de micro-organismes sans multiplication ni dommage","La pénétration et la multiplication d'un agent pathogène dans un organisme avec dommages","La présence de parasites externes (ectoparasites) sur la peau","Une réaction allergique"],"r":1,"e":"Infection = pénétration + multiplication d'un agent pathogène dans l'hôte avec lésions tissulaires/réaction immunitaire. Différent de la colonisation (sans dommage) ou de l'infestation (parasites externes).","s":9},{"q":"La COLONISATION se distingue de l'infection par :","o":["Une multiplication plus rapide","Une absence de dommage tissulaire ou de réaction de l'hôte","La présence systématique de symptômes","Une transmission obligatoire"],"r":1,"e":"Colonisation = présence de micro-organismes sur/dans l'hôte SANS dommage ni réaction de l'hôte. Beaucoup d'individus sont colonisés sans être infectés (ex : Staphylococcus aureus nasal).","s":9},{"q":"L'INFESTATION concerne :","o":["Les bactéries intracellulaires","Les parasites externes (ectoparasites)","Les virus","Les champignons systémiques"],"r":1,"e":"Infestation = présence/multiplication d'ECTOPARASITES sur la surface du corps (poux, gale, tiques). Différent de l'infection (agent pénétrant).","s":9},{"q":"Concernant les modes de TRANSMISSION DIRECTE, quels exemples sont corrects ?","o":["Contact sexuel","Goutelettes (toux, éternuement) à courte distance","Contact peau à peau","Aliments contaminés","Eau contaminée"],"r":[0,1,2],"e":"Transmission directe : contact entre personnes (sexuel, peau à peau, gouttelettes courtes). Aliments/eau contaminés = transmission INDIRECTE (par véhicule).","s":9},{"q":"Concernant les modes de TRANSMISSION INDIRECTE, quels exemples sont corrects ?","o":["Aliments / eau contaminés","Vecteur (moustique pour le paludisme)","Aérosols sur longue distance","Objets contaminés (fomites)","Embrassade"],"r":[0,1,2,3],"e":"Transmission indirecte : via véhicule (eau, aliments, objets/fomites), vecteur (moustique, tique), aérosols longue distance. L'embrassade = directe.","s":9},{"q":"La chaîne épidémiologique commence par :","o":["L'hôte sensible","La porte d'entrée","L'agent infectieux","La porte de sortie"],"r":2,"e":"Chaîne épidémiologique : agent → réservoir → porte de sortie → mode de transmission → porte d'entrée → hôte sensible. Elle commence par l'agent infectieux.","s":9},{"q":"Parmi les principaux AGENTS INFECTIEUX, on compte :","o":["Bactéries","Virus","Champignons","Parasites","Prions","Les allergènes polliniques"],"r":[0,1,2,3,4],"e":"Les 5 grands types d'agents infectieux : bactéries, virus, champignons (mycètes), parasites (protozoaires, helminthes), prions (protéines infectieuses, ex : Creutzfeldt-Jakob). Un pollen déclenche une réaction immunitaire d'hypersensibilité, mais ne se multiplie pas dans l'hôte : ce n'est pas un agent infectieux.","s":9},{"q":"Une infection NOSOCOMIALE est :","o":["Acquise dans la communauté","Acquise dans une structure de soins (hôpital)","Toujours d'origine virale","Toujours bénigne"],"r":1,"e":"Infection nosocomiale = acquise lors d'un séjour en structure de soins (hôpital, EHPAD), apparue ≥ 48h après l'admission. Souvent à germes résistants (MRSA, etc.).","s":9},{"q":"Le COMMENSALISME correspond à :","o":["Le micro-organisme bénéficie sans nuire à l'hôte","Le micro-organisme et l'hôte bénéficient mutuellement","Le micro-organisme nuit à l'hôte","Une absence d'interaction"],"r":0,"e":"Commensalisme : un partenaire (microbe) en tire bénéfice, l'autre (hôte) n'en subit ni bien ni mal. Mutualisme = bénéfice réciproque (ex : flore intestinale). Parasitisme = pathogène nuit à l'hôte.","s":9},{"q":"Le MUTUALISME correspond à :","o":["Une situation où l'agent infectieux nuit à l'hôte","Un bénéfice réciproque entre l'hôte et le micro-organisme","Une absence de relation entre les deux","Une élimination immédiate du microbe"],"r":1,"e":"Mutualisme = bénéfice réciproque (ex : microbiote intestinal qui aide la digestion et reçoit nutriments). Le parasitisme est unilatéralement nuisible pour l'hôte.","s":9},{"q":"Quels facteurs AUGMENTENT la susceptibilité de l'hôte à l'infection ?","o":["Âge extrême (très jeune ou très âgé)","Immunodéficience","Malnutrition","Maladies chroniques (diabète)","Vaccination"],"r":[0,1,2,3],"e":"Facteurs ↑ susceptibilité : âges extrêmes, immunodéficience (VIH, traitements immunosuppresseurs), malnutrition, maladies chroniques (diabète), grossesse. La vaccination DIMINUE la susceptibilité.","s":9},{"q":"Quelles sont des PORTES D'ENTRÉE classiques d'agents infectieux ?","o":["Pénétration cutanée (effraction, piqûre)","Contact (peau intacte, muqueuses)","Ingestion (voie digestive)","Inhalation (voie respiratoire)","Voie transplacentaire","La sécrétion de lysozyme par les larmes"],"r":[0,1,2,3,4],"e":"Portes d'entrée : pénétration (effraction cutanée, piqûre), contact (peau, muqueuses), ingestion (digestif), inhalation (respiratoire), transplacentaire (mère-enfant). Le lysozyme est une défense de l'hôte, donc l'inverse d'une porte d'entrée.","s":9},{"q":"La phase PRODROMIQUE d'une maladie infectieuse correspond à :","o":["L'absence de tout symptôme","L'apparition de symptômes non spécifiques avant la phase d'état","La phase de convalescence","La rechute"],"r":1,"e":"Phase prodromique : symptômes vagues et non spécifiques (malaise, fébricule) précédant la phase d'état (symptômes caractéristiques de la maladie).","s":9},{"q":"Une maladie AIGUË se caractérise par :","o":["Une longue durée (mois/années)","Une apparition brutale et durée courte","Des poussées et rémissions","Un début insidieux"],"r":1,"e":"Maladie aiguë = début brutal, courte durée, évolution rapide. Subaiguë = intermédiaire. Chronique = longue durée, parfois insidieuse, peut comporter exacerbations/rémissions.","s":9},{"q":"Concernant l'histoire naturelle de la maladie infectieuse :","o":["Elle commence par l'incubation","Suivie d'une phase prodromique","Puis la phase d'état (clinique)","Et enfin la convalescence ou résolution","Elle ne comporte que 2 phases"],"r":[0,1,2,3],"e":"Histoire naturelle : incubation (silencieuse) → prodromes (symptômes vagues) → phase d'état (signes spécifiques) → convalescence/résolution (ou complications/séquelles).","s":9},{"q":"Les niveaux de prévention sont :","o":["Primaire, secondaire, tertiaire","Primaire seulement","Aiguë et chronique","Active et passive"],"r":0,"e":"3 niveaux : Primaire (avant la maladie : vaccination, hygiène) ; Secondaire (dépistage précoce + traitement rapide) ; Tertiaire (rééducation, limitation des séquelles).","s":9},{"q":"Une maladie TRANSMISSIBLE est :","o":["Toujours d'origine virale","Capable de se propager d'un hôte à un autre","Toujours d'origine génétique","Forcément chronique"],"r":1,"e":"Maladie transmissible = peut se propager d'un hôte (ou réservoir) à un autre. Non transmissible = pas de transmission interhumaine ou animale (cancer, diabète, maladies cardiovasculaires).","s":9},{"q":"Parmi ces maladies, lesquelles sont TRANSMISSIBLES ?","o":["Tuberculose","Grippe","Diabète de type 1","Hypertension","COVID-19"],"r":[0,1,4],"e":"Transmissibles : tuberculose, grippe, COVID-19, IST, etc. Non transmissibles : diabète, HTA, cancer, maladies cardiovasculaires (origine multifactorielle, pas d'agent infectieux).","s":9},{"q":"Une infection ENDOGÈNE provient :","o":["De l'environnement","De la flore microbienne propre du patient","D'un soignant","D'un autre patient"],"r":1,"e":"Infection endogène = à partir de la flore commensale du patient (ex : translocation digestive). Exogène = source externe. Nosocomiale = liée aux soins.","s":9},{"q":"Quels éléments constituent le SYSTÈME DE DÉFENSE de l'hôte ?","o":["Barrières mécaniques (peau, muqueuses)","Sécrétions (lysozyme, mucus, suc gastrique)","Microbiote commensal","Immunité innée","Immunité adaptative (lymphocytes)","L'effraction cutanée par piqûre"],"r":[0,1,2,3,4],"e":"Défenses : barrières (peau, muqueuses), sécrétions (lysozyme, HCl, mucus), microbiote (compétition), immunité innée (PNN, macrophages, complément), immunité adaptative (LT, LB, anticorps). Une effraction est une porte d'entrée : elle rompt la défense au lieu de la constituer.","s":9},{"q":"Le RÉSERVOIR de l'agent infectieux peut être :","o":["Uniquement humain","Humain, animal ou environnemental","Uniquement environnemental","Uniquement vectoriel"],"r":1,"e":"Réservoirs : humain (porteur sain ou malade), animal (zoonoses : rage, brucellose), environnemental (eau pour Legionella, sol pour tétanos).","s":9},{"q":"Une zoonose est :","o":["Une infection transmise d'humain à humain","Une infection transmise de l'animal à l'humain","Une infection environnementale","Une infection auto-immune"],"r":1,"e":"Zoonose = infection transmise de l'animal à l'humain (rage, brucellose, leptospirose, grippe aviaire, COVID-19). Le réservoir est animal.","s":9},{"q":"Quelles affirmations sur les bactéries sont vraies ?","o":["Procaryotes (sans noyau)","Peuvent être Gram+ ou Gram-","Sensibles aux antibiotiques (en général)","Possèdent un noyau membranaire","Possèdent une paroi"],"r":[0,1,2,4],"e":"Bactéries : procaryotes (PAS de noyau), Gram+/Gram-, sensibles aux antibiotiques (sauf résistances), possèdent une paroi. Le noyau membranaire est une caractéristique eucaryote.","s":9},{"q":"Un VIRUS est :","o":["Un être vivant complet","Un agent obligatoirement intracellulaire","Sensible aux antibiotiques","Toujours bactérien"],"r":1,"e":"Virus = parasite intracellulaire OBLIGATOIRE (a besoin du métabolisme cellulaire pour se répliquer). Insensible aux antibiotiques (qui ciblent les bactéries). Traitement antiviral spécifique.","s":9},{"q":"Un PRION est :","o":["Une bactérie atypique","Un virus à ARN","Une protéine mal repliée infectieuse","Un parasite eucaryote"],"r":2,"e":"Prion = protéine mal repliée (PrPsc) qui induit le mauvais repliement des protéines normales (PrPc). Cause la maladie de Creutzfeldt-Jakob, ESB. Pas d'acide nucléique → résistant aux traitements classiques.","s":9},{"q":"Le concept de prévention TERTIAIRE inclut :","o":["Vaccination","Dépistage précoce","Réhabilitation des séquelles","Limitation des incapacités","Hygiène de vie générale"],"r":[2,3],"e":"Tertiaire = limitation des séquelles, rééducation, qualité de vie chez un sujet déjà atteint. Vaccination = primaire ; dépistage = secondaire.","s":9},{"q":"Concernant la fréquence des maladies dans une population :","o":["Sporadique = survient occasionnellement","Endémique = toujours présente, fréquence stable","Épidémique = touche un grand nombre en peu de temps","Pandémique = vaste zone géographique, parfois mondiale","Endémique signifie qu'elle a disparu"],"r":[0,1,2,3],"e":"Sporadique (occasionnel) ; endémique (toujours présente à fréquence stable, ex paludisme dans certaines régions) ; épidémique (poussée localisée) ; pandémique (mondiale, ex COVID-19).","s":9},{"q":"Les agents infectieux incluent :","o":["Virus","Bactéries","Champignons","Parasites","Prions","Les toxiques chimiques industriels"],"r":[0,1,2,3,4],"e":"5 grands groupes d'agents : virus, bactéries, champignons, parasites, prions. Un toxique lèse directement les tissus mais ne se réplique pas : il relève des agents chimiques, pas infectieux.","s":9},{"q":"La virulence d'un microorganisme est :","o":["Sa capacité de reproduction","Sa capacité à causer une maladie sévère","Sa résistance aux antibiotiques","Sa taille"],"r":1,"e":"Virulence = degré de pathogénicité, capacité à causer une maladie grave.","s":9},{"q":"La période d'incubation est :","o":["Le temps entre exposition et apparition des symptômes","Le temps des symptômes","La période contagieuse uniquement","La convalescence"],"r":0,"e":"Incubation = délai entre l'exposition à l'agent et l'apparition des premiers symptômes.","s":9},{"q":"La fièvre est :","o":["Une élévation pathologique de la T° due à une infection","Une diminution de la T°","Toujours grave","Sans rapport avec les infections"],"r":0,"e":"Fièvre = ↑ T° corporelle au-dessus de la normale, médiée par les pyrogènes (IL-1, TNF).","s":9},{"q":"Les modes de transmission incluent :","o":["Aérienne (gouttelettes/aérosols)","Contact direct ou indirect","Vecteur (moustique, tique)","Alimentaire/hydrique","Sexuelle","Sanguine","La transmission par prédisposition génétique"],"r":[0,1,2,3,4,5],"e":"Tous ces modes existent : aérien, contact, vecteur, oro-fécal, sexuel, sanguin (parentéral). Une prédisposition génétique modifie la susceptibilité de l'hôte ; elle ne transmet aucun agent.","s":9},{"q":"Une endotoxine bactérienne est :","o":["Une toxine sécrétée activement","Un composant de la paroi (LPS) libéré à la lyse","Un anticorps","Un antibiotique"],"r":1,"e":"Endotoxine = LPS de la paroi des Gram- ; exotoxine = sécrétée activement (Gram+ et -).","s":9},{"q":"L'immunité acquise active s'obtient par :","o":["Le placenta (mère→bébé)","Vaccination ou infection naturelle","Injection d'anticorps","Aucune"],"r":1,"e":"Active = production propre d'anticorps après vaccination/infection. Passive = anticorps reçus (ex : sérum, allaitement).","s":9},{"q":"La résistance aux antibiotiques est favorisée par :","o":["Une utilisation rare","Une utilisation appropriée","Une utilisation excessive et inappropriée","La diversité des bactéries"],"r":2,"e":"L'utilisation excessive/inappropriée d'antibiotiques sélectionne les souches résistantes.","s":9},{"q":"Un porteur sain (porteur asymptomatique) est :","o":["Un sujet guéri qui ne peut plus transmettre l'agent","Un sujet hébergeant et pouvant transmettre l'agent infectieux sans présenter de symptômes","Un sujet vacciné","Un sujet en période d'incubation uniquement"],"r":1,"e":"Le porteur sain est un maillon majeur de la chaîne épidémiologique, précisément parce que rien ne le signale : il alimente la transmission sans être repéré ni isolé. C'est le cas pour le méningocoque, le staphylocoque doré nasal ou les porteurs chroniques du VHB.","s":9},{"q":"La sepsie est :","o":["Une infection localisée","Une réponse systémique inflammatoire à une infection avec dysfonction d'organe","Une maladie auto-immune","Une allergie"],"r":1,"e":"Sepsie = SIRS + infection avec dysfonction d'organe. Choc septique = sepsie + hypotension réfractaire.","s":9},{"q":"Quelle différence la fiche fait-elle entre maladie infectieuse et maladie contagieuse ?","o":["Toute maladie contagieuse est infectieuse, mais l'inverse n'est pas vrai","Toute maladie infectieuse est contagieuse","Les deux termes sont synonymes","Une maladie contagieuse ne nécessite pas d'agent infectieux"],"r":0,"e":"La rougeole est contagieuse, le paludisme est infectieux mais non contagieux car il exige un vecteur.","s":9},{"q":"Qu'est-ce qu'un hôte selon la fiche ?","o":["Tout organisme capable de subvenir aux besoins nutritionnels d'un autre","Un micro-organisme pathogène","Le milieu où vit et se multiplie l'agent","Le vecteur transportant l'agent"],"r":0,"e":"L'hôte nourrit l'agent ; le réservoir est son environnement de vie et de multiplication.","s":9},{"q":"Qu'est-ce qu'un saprophyte ?","o":["Un micro-organisme peu nuisible se nourrissant de matières organiques mortes","Un agent toujours pathogène","Un vecteur de transmission","Une protéine infectieuse"],"r":0,"e":"La majorité des micro-organismes sont saprophytes, mais peuvent devenir opportunistes.","s":9},{"q":"Quelle particularité structurelle définit un prion ?","o":["Il est fait de protéines seules, sans acide nucléique","Il possède un ADN et une capside","Il possède un ARN et une enveloppe","C'est un eucaryote unicellulaire"],"r":0,"e":"L'absence d'acide nucléique explique qu'aucun traitement ne soit efficace (Creutzfeldt-Jakob, Kuru, ESB).","s":9},{"q":"Pourquoi les virus sont-ils dits intracellulaires obligatoires ?","o":["Parce qu'ils ne peuvent pas se reproduire hors des cellules","Parce qu'ils sont trop petits pour survivre à l'air","Parce qu'ils n'ont pas de capside","Parce qu'ils se nourrissent de matières mortes"],"r":0,"e":"Le virus détourne la machinerie cellulaire ; les antiviraux ne font que ralentir sa réplication.","s":9},{"q":"Quelle est la structure des bactéries ?","o":["Des cellules procaryotes, sans noyau, capables de se reproduire de façon autonome","Des eucaryotes unicellulaires","Des organismes multicellulaires","Des protéines sans acide nucléique"],"r":0,"e":"Leur autonomie de reproduction et leur nature procaryote les rendent sensibles aux antibiotiques.","s":9},{"q":"À quelle catégorie appartiennent les levures et les moisissures ?","o":["Aux champignons","Aux protozoaires","Aux helminthes","Aux bactéries"],"r":0,"e":"Les champignons sont unicellulaires (levures) ou multicellulaires (moisissures) et se traitent par antifongiques.","s":9},{"q":"Quelles maladies la fiche associe-t-elle aux protozoaires ?","o":["Le paludisme, la dysenterie amibienne et la maladie du sommeil","La trichinose et les vers plats","La candidose et le pied d'athlète","La tuberculose et la gonorrhée"],"r":0,"e":"Les protozoaires sont des eucaryotes unicellulaires, fréquents dans l'eau des pays en développement.","s":9},{"q":"Qu'est-ce qu'une infection endogène ?","o":["Une infection acquise à partir de la flore propre de l'hôte","Une infection contractée à l'hôpital","Une infection transmise par un animal","Une infection d'origine alimentaire"],"r":0,"e":"Les infections opportunistes de la flore commensale sont endogènes ; l'origine hospitalière définit le caractère nosocomial.","s":9},{"q":"Quel exemple de mutualisme la fiche donne-t-elle ?","o":["Les bactéries intestinales produisant la vitamine K","Les streptocoques de la bouche","Les staphylocoques de la peau","Les poux du cuir chevelu"],"r":0,"e":"Le mutualisme profite aux deux partenaires ; les streptocoques buccaux illustrent le commensalisme.","s":9},{"q":"Quelle porte de sortie la fiche associe-t-elle à la rage ?","o":["La salive","Le sang","Les selles","Les sécrétions respiratoires"],"r":0,"e":"Le Rhabdovirus de la rage se transmet par la salive lors de la morsure.","s":9},{"q":"Quelle porte de sortie la fiche associe-t-elle à l'amibiase ?","o":["Les selles","Le sperme","Le sang","La salive"],"r":0,"e":"L'amibiase est une maladie à transmission féco-orale.","s":9},{"q":"Quelles défenses protègent la voie d'entrée respiratoire ?","o":["Le mucus, les cils vibratiles, la toux, les anticorps et les phagocytes","Le pH acide et les enzymes digestives","La kératine et les acides gras cutanés","La miction répétée"],"r":0,"e":"Chaque porte d'entrée a ses défenses propres ; celles citées en second concernent le tube digestif.","s":9},{"q":"Quels sont les SIGNES CARDINAUX de l'inflammation aiguë (4 signes de Celse + 1 de Galien) ?","o":["Rougeur (rubor)","Chaleur (calor)","Tuméfaction / œdème (tumor)","Douleur (dolor)","Perte de fonction (functio laesa)","Pâleur (pallor)"],"r":[0,1,2,3,4],"e":"5 signes cardinaux : rubor (rougeur), calor (chaleur), tumor (œdème), dolor (douleur), functio laesa (perte de fonction). Les 4 premiers décrits par Celse, le 5e ajouté par Galien/Virchow. La pâleur traduit une vasoconstriction ou une anémie ; l'inflammation aiguë donne au contraire une rougeur par vasodilatation.","s":10},{"q":"L'inflammation AIGUË :","o":["Dure plusieurs mois","Est de courte durée (heures à jours)","Est dominée par les lymphocytes","Implique toujours une fibrose"],"r":1,"e":"Inflammation aiguë : durée courte (minutes-jours), prédominance de PNN (polynucléaires neutrophiles), réversible. Chronique : durée prolongée, lymphocytes/macrophages, fibrose.","s":10},{"q":"L'inflammation CHRONIQUE est caractérisée par :","o":["Prédominance de macrophages et lymphocytes","Persistance dans le temps","Souvent accompagnée de fibrose","Prédominance de polynucléaires neutrophiles","Réponse adaptative"],"r":[0,1,2,4],"e":"Chronique : durée prolongée, macrophages + lymphocytes (réponse adaptative), fibrose, néoangiogenèse. Les PNN sont des cellules de l'aiguë.","s":10},{"q":"Lors de la phase VASCULAIRE de l'inflammation aiguë, quelle est la première modification ?","o":["Vasoconstriction puis vasodilatation","Vasodilatation immédiate puis vasoconstriction","Vasoconstriction prolongée","Aucune modification vasculaire"],"r":0,"e":"Phase vasculaire : courte vasoconstriction réflexe → vasodilatation marquée → ↑ flux sanguin (rougeur, chaleur) → ↑ perméabilité (œdème).","s":10},{"q":"Un EXSUDAT inflammatoire se distingue d'un transsudat par :","o":["Une teneur en protéines basse","Une teneur en protéines élevée et présence de cellules","Une couleur claire et limpide","Une absence de fibrine"],"r":1,"e":"Exsudat : ↑ protéines (>30 g/L), riche en cellules, fibrine — signe d'INFLAMMATION (perméabilité ↑). Transsudat : pauvre en protéines, sans cellules — origine MÉCANIQUE (insuffisance cardiaque, hypoalbuminémie).","s":10},{"q":"Quels types d'EXSUDATS existent ?","o":["Séreux","Fibrineux","Purulent","Hémorragique","Lymphatique"],"r":[0,1,2,3],"e":"Exsudats : séreux (clair, brûlure), fibrineux (péricardite), purulent (pus, pyogènes), hémorragique (très inflammatoire). Pas d'exsudat lymphatique en tant que catégorie.","s":10},{"q":"Concernant le RECRUTEMENT LEUCOCYTAIRE (étapes), elles incluent :","o":["Margination","Roulement","Adhésion","Transmigration / diapédèse","Chimiotactisme","Opsonisation"],"r":[0,1,2,3,4],"e":"Étapes du recrutement leucocytaire (MRATCH) : Margination → Roulement → Adhésion → Transmigration → Chimiotactisme → Phagocytose. Sélectines pour le roulement, intégrines pour l'adhésion. L'opsonisation appartient à la phagocytose, qui suit l'arrivée du leucocyte dans le tissu ; elle ne fait pas partie du recrutement.","s":10},{"q":"Le PHÉNOMÈNE de PHAGOCYTOSE comprend :","o":["1 étape","2 étapes","3 étapes (reconnaissance, ingestion, dégradation)","5 étapes"],"r":2,"e":"Phagocytose en 3 étapes : 1) reconnaissance (opsonines : IgG, C3b) ; 2) ingestion (pseudopodes, phagosome) ; 3) dégradation (fusion lysosome → phagolysosome → enzymes + ROS).","s":10},{"q":"Quel est le LEUCOCYTE prédominant dans les premières heures de l'inflammation aiguë ?","o":["Lymphocyte","Macrophage","Polynucléaire neutrophile (PNN)","Éosinophile"],"r":2,"e":"PNN = première cellule à arriver (premières 24h). Puis macrophages prennent le relais (24-48h). Lymphocytes en cas d'inflammation chronique ou virale.","s":10},{"q":"Parmi les médiateurs chimiques de l'inflammation, on trouve :","o":["Histamine (mastocytes)","Prostaglandines","Leucotriènes","Cytokines (TNF, IL-1)","Insuline"],"r":[0,1,2,3],"e":"Médiateurs : histamine (vasodilatation, perméabilité), prostaglandines/leucotriènes (douleur, fièvre), cytokines (TNF, IL-1, IL-6), complément, NO. L'insuline est une hormone métabolique, pas un médiateur inflammatoire.","s":10},{"q":"Les AINS (anti-inflammatoires non stéroïdiens) inhibent principalement :","o":["L'histamine","Les cyclo-oxygénases (COX 1 et 2) → ↓ prostaglandines","Le complément","Les caspases"],"r":1,"e":"AINS = inhibiteurs des COX → ↓ synthèse de prostaglandines → effet anti-inflammatoire, antalgique, antipyrétique. Effet indésirable digestif (COX-1).","s":10},{"q":"Concernant les EFFETS SYSTÉMIQUES de l'inflammation (réponse de phase aiguë) :","o":["Fièvre","Leucocytose","↑ protéines de phase aiguë (CRP, fibrinogène)","Augmentation de la VS","Hypothermie"],"r":[0,1,2,3],"e":"Réponse phase aiguë : fièvre (IL-1, IL-6, TNF), leucocytose, ↑ CRP/fibrinogène, ↑ VS, fatigue. L'hypothermie peut survenir en cas de SEPSIS sévère mais ce n'est pas typique.","s":10},{"q":"Un GRANULOME est :","o":["Un type de cellule cancéreuse","Une accumulation focale de macrophages activés (cellules épithélioïdes)","Une bactérie","Une cytokine"],"r":1,"e":"Granulome = lésion d'inflammation chronique : macrophages activés (cellules épithélioïdes), parfois cellules géantes, lymphocytes. Typique : tuberculose, sarcoïdose, mycoses, corps étrangers.","s":10},{"q":"Quelles maladies sont caractérisées par une inflammation GRANULOMATEUSE ?","o":["Tuberculose","Sarcoïdose","Maladie de Crohn","Grippe","Lèpre"],"r":[0,1,2,4],"e":"Inflammation granulomateuse : tuberculose (granulome caséeux), sarcoïdose (non caséeux), Crohn, lèpre, mycoses. La grippe = inflammation aiguë virale, pas granulomateuse.","s":10},{"q":"Concernant la classification des tissus selon leur capacité de prolifération :","o":["Tissus labiles : se renouvellent en permanence (épithéliums, moelle)","Tissus stables : peuvent proliférer si stimulus (foie, rein)","Tissus permanents : ne se divisent pas (neurones, cardiomyocytes)","Tous les tissus se régénèrent à l'identique","Les neurones se régénèrent comme la peau"],"r":[0,1,2],"e":"3 catégories : labiles (renouvellement constant), stables (quiescents mais capables de proliférer), permanents (post-mitotiques : neurones, myocytes cardiaques → pas de régénération vraie).","s":10},{"q":"La cicatrisation par PREMIÈRE INTENTION concerne :","o":["Les plaies à bords nets, peu de perte de substance","Les plaies larges avec perte de substance","Les plaies infectées uniquement","Les brûlures profondes"],"r":0,"e":"1ère intention : plaies bords nets, rapprochés, peu de perte (ex : sutures chirurgicales) → cicatrice fine. 2e intention : perte de substance importante → bourgeon charnu, cicatrice large.","s":10},{"q":"Quels facteurs ALTÈRENT la réparation tissulaire ?","o":["Diabète (hyperglycémie)","Tabagisme","Malnutrition","Infection","Jeune âge"],"r":[0,1,2,3],"e":"Altèrent : diabète, tabac (vasoconstriction), malnutrition (protéines, vitamine C), infections, corticothérapie, ischémie, corps étrangers. Le jeune âge FAVORISE la réparation.","s":10},{"q":"Une cicatrice CHÉLOÏDE est :","o":["Une cicatrice fine et discrète","Une cicatrice hypertrophique débordant les limites de la plaie","Une absence de cicatrice","Une cicatrice rouge mais qui s'estompe rapidement"],"r":1,"e":"Chéloïde : cicatrice hypertrophique qui DÉBORDE les limites initiales de la plaie (excès de collagène). Plus fréquente chez les peaux foncées. Différente de l'hypertrophie simple (limitée à la plaie).","s":10},{"q":"Concernant la réparation tissulaire, quelles affirmations sont vraies ?","o":["Régénération = remplacement par le même tissu","Cicatrisation = remplacement par tissu fibreux","La régénération est possible pour les tissus labiles et stables","Les neurones du SNC se régénèrent facilement","La fibrose excessive peut altérer la fonction"],"r":[0,1,2,4],"e":"Régénération (à l'identique) possible pour tissus labiles/stables. Cicatrisation = fibrose (collagène) si la régénération ne suffit pas. Le SNC ne se régénère pas (cicatrice gliale).","s":10},{"q":"Concernant la réaction des 5 R en inflammation :","o":["Reconnaissance de l'agent","Recrutement des leucocytes","Reconnaissance de l'antigène","Régulation de la réponse","Résolution"],"r":[0,1,3,4],"e":"5 R : Reconnaissance de l'agent → Recrutement leucocytaire → Removal/élimination → Régulation → Résolution. Pas de 'reconnaissance d'antigène' en tant qu'étape (c'est plutôt l'immunité adaptative).","s":10},{"q":"Le médiateur clé de la VASODILATATION précoce est :","o":["L'IL-1","L'histamine","Le TNF-α","La fibrine"],"r":1,"e":"Histamine (mastocytes, basophiles) = médiateur précoce de la vasodilatation et de l'augmentation de perméabilité vasculaire (œdème). Action rapide, courte durée.","s":10},{"q":"La FIÈVRE est principalement provoquée par :","o":["L'histamine","La sérotonine","Les cytokines pyrogènes (IL-1, IL-6, TNF) → prostaglandines E2","Le calcium"],"r":2,"e":"Fièvre : cytokines pyrogènes endogènes (IL-1, IL-6, TNF) → ↑ PGE2 → centre thermorégulateur hypothalamique → augmentation du point de consigne thermique.","s":10},{"q":"Le BOURGEON CHARNU est constitué de :","o":["Cellules cancéreuses","Tissu de granulation : néovaisseaux + fibroblastes + collagène + leucocytes","Pus seul","Tissu nécrotique seul"],"r":1,"e":"Bourgeon charnu = tissu de granulation : néoangiogenèse + fibroblastes + collagène + cellules inflammatoires. Étape clé de la cicatrisation par 2e intention. Aspect rouge framboise.","s":10},{"q":"Quels sont des effets du TNF-α ?","o":["Activation de l'endothélium","Stimulation de la production de cytokines","Cachexie (en chronique)","Apoptose dans certaines cellules","Diminution de la fièvre"],"r":[0,1,2,3],"e":"TNF-α : active endothélium (adhésion leucocytes), stimule production de cytokines, cause cachexie (terme = 'cachectine'), peut induire apoptose. Il PARTICIPE à la fièvre, ne la diminue pas.","s":10},{"q":"Une perte de fonction (functio laesa) est typiquement liée à :","o":["L'état général excellent","La douleur + œdème + altération tissulaire","L'absence d'inflammation","Une cicatrice mature"],"r":1,"e":"Functio laesa : perte de fonction de la zone enflammée, liée à la douleur (limitation volontaire du mouvement), l'œdème (ankylose), et l'altération tissulaire. C'est le 5e signe cardinal.","s":10},{"q":"Les 5 signes cardinaux de l'inflammation aiguë (Celse + Galien) sont :","o":["Rougeur (rubor)","Chaleur (calor)","Tuméfaction (tumor)","Douleur (dolor)","Perte de fonction (functio laesa)","Cyanose"],"r":[0,1,2,3,4],"e":"5 signes : rubor, calor, tumor, dolor, functio laesa. La cyanose signe une désaturation en oxygène et ne figure pas parmi les signes de Celse et Galien.","s":10},{"q":"La vasodilatation locale dans l'inflammation est médiée par :","o":["Adrénaline","Histamine, prostaglandines, NO","Insuline","Cortisol"],"r":1,"e":"Médiateurs de la vasodilatation : histamine (mastocytes), prostaglandines, NO.","s":10},{"q":"L'exsudat inflammatoire est :","o":["Pauvre en protéines","Riche en protéines et leucocytes","Identique au transsudat","Toxique"],"r":1,"e":"Exsudat = riche en protéines et cellules (inflammation). Transsudat = pauvre (↑ pression hydrostatique).","s":10},{"q":"Les cellules dominantes de l'inflammation aiguë sont :","o":["Les lymphocytes","Les neutrophiles (PNN)","Les macrophages","Les éosinophiles"],"r":1,"e":"PNN = première ligne, dominent les premières 24-48h. Macrophages prennent ensuite le relais.","s":10},{"q":"L'inflammation chronique se caractérise par :","o":["PNN dominants","Lymphocytes, macrophages, plasmocytes","Œdème massif","Disparition immédiate des tissus"],"r":1,"e":"Inflammation chronique = infiltrat de cellules mononucléées (lymphocytes, macrophages, plasmocytes), persistance + tentative de réparation.","s":10},{"q":"Un granulome est typique de :","o":["L'inflammation aiguë","L'inflammation chronique granulomateuse (TB, sarcoïdose)","Une infection virale","Un cancer"],"r":1,"e":"Granulome = agglomérat de macrophages activés (cellules épithélioïdes), typique TB, sarcoïdose, certains corps étrangers.","s":10},{"q":"Les phases de la cicatrisation sont :","o":["Hémostase","Inflammation","Prolifération (granulation)","Remodelage / maturation","Lyse"],"r":[0,1,2,3],"e":"4 phases : hémostase → inflammation → prolifération (granulation, angiogenèse) → remodelage.","s":10},{"q":"La cicatrisation par SECONDE intention se caractérise par :","o":["Des berges nettes rapprochées et une cicatrice fine","Une perte de substance importante, un comblement par tissu de granulation, une contraction et une cicatrice large","Une absence totale de tissu de granulation","Une réparation plus rapide que la première intention"],"r":1,"e":"Quand les berges ne peuvent être rapprochées (plaie large, ulcère, brûlure), la perte de substance se comble par un bourgeon charnu, puis les myofibroblastes contractent la plaie. Il en résulte une cicatrisation plus longue, plus inflammatoire et une cicatrice plus étendue, source de rétractions.","s":10},{"q":"Une chéloïde est :","o":["Une cicatrisation normale","Une cicatrice excessive dépassant les limites de la plaie","Un kyste","Une pus"],"r":1,"e":"Chéloïde = cicatrice hypertrophique débordant les limites de la plaie initiale (excès collagène).","s":10},{"q":"Les facteurs retardant la cicatrisation incluent :","o":["Jeune âge","Bonne nutrition","Diabète, ischémie, infection, corticoïdes","Repos"],"r":2,"e":"Diabète, ischémie, infection, corticoïdes, dénutrition, âge avancé retardent la cicatrisation.","s":10},{"q":"Sur quels tissus l'inflammation peut-elle se produire ?","o":["Uniquement les tissus vascularisés","Tous les tissus, vascularisés ou non","Uniquement les épithéliums","Uniquement le tissu conjonctif"],"r":0,"e":"La définition insiste sur les tissus vascularisés, puisque la réponse achemine leucocytes et molécules depuis la circulation.","s":10},{"q":"Quels sont les trois rôles protecteurs de l'inflammation ?","o":["Éliminer la cause, éliminer les conséquences de la lésion, déclencher la réparation","Produire de la fibrose, recruter des fibroblastes, cicatriser","Créer de la douleur, de la chaleur et du gonflement","Activer le complément, la coagulation et les kinines"],"r":0,"e":"Ces trois rôles rendent l'inflammation essentielle à la survie, malgré ses effets délétères possibles.","s":10},{"q":"Quelles cytokines en excès provoquent un choc septique ?","o":["Le TNF et l'IL-1","L'IL-4 et l'IL-13","Le TGF-β et l'IL-10","L'IL-17 seule"],"r":0,"e":"De très hauts taux de TNF et d'IL-1 causent hypotension, CIVD et résistance à l'insuline ; IL-4/IL-13 et TGF-β/IL-10 orientent vers la réparation.","s":10},{"q":"Quelle modification vasculaire précède la vasodilatation dans l'inflammation aiguë ?","o":["Une brève vasoconstriction de quelques secondes","Une stase immédiate","Une augmentation de perméabilité","Une margination leucocytaire"],"r":0,"e":"La séquence est : vasoconstriction brève, vasodilatation, hyperperméabilité puis stase.","s":10},{"q":"Quel est le mécanisme le plus fréquent d'augmentation de la perméabilité vasculaire ?","o":["La contraction endothéliale, rapide et brève (15-30 min)","La lésion endothéliale directe","La transcytose","La formation du complexe d'attaque membranaire"],"r":0,"e":"La contraction endothéliale induite par histamine, bradykinine et leucotriènes est le mécanisme dominant.","s":10},{"q":"Quelle conséquence a la stase dans l'inflammation aiguë ?","o":["Le ralentissement du flux, la concentration des globules rouges et la margination des leucocytes","Une vasoconstriction réflexe","Une baisse de la perméabilité","Une résolution immédiate"],"r":0,"e":"La stase place les leucocytes en périphérie du courant, première étape de leur recrutement.","s":10},{"q":"Quel signe clinique distingue un transsudat d'un exsudat ?","o":["Le signe du godet (pitting edema), présent dans le transsudat","Le signe du godet, présent dans l'exsudat","La chaleur locale","La perte de fonction"],"r":0,"e":"Le transsudat pauvre en protéines prend le godet ; l'exsudat riche en fibrine donne un œdème « en casier », non pitting.","s":10},{"q":"Quel type d'exsudat caractérise une péricardite ?","o":["L'exsudat fibrineux","L'exsudat séreux","L'exsudat purulent","L'exsudat hémorragique"],"r":0,"e":"Riche en fibrinogène, épais et collant, l'exsudat fibrineux est typique des séreuses.","s":10},{"q":"Quel type d'exsudat correspond à une vésicule cutanée ?","o":["L'exsudat séreux","L'exsudat fibrineux","L'exsudat purulent","L'exsudat nécrotique"],"r":0,"e":"La phlyctène contient un fluide aqueux pauvre en protéines.","s":10},{"q":"Quelles molécules assurent le roulement des leucocytes ?","o":["Les sélectines","Les intégrines","PECAM-1","Les chimiokines"],"r":0,"e":"Sélectines pour le roulement, intégrines pour l'adhésion ferme, PECAM-1 pour la transmigration.","s":10},{"q":"Quelle molécule permet la transmigration des leucocytes ?","o":["PECAM-1 (CD31)","La L-sélectine","LFA-1","ICAM-1"],"r":0,"e":"PECAM-1 assure le passage entre les cellules endothéliales.","s":10},{"q":"Quels sont les ligands endothéliaux des intégrines ?","o":["ICAM-1 et VCAM-1","La P-sélectine et la E-sélectine","IL-8 et MCP-1","C5a et C3b"],"r":0,"e":"ICAM-1 et VCAM-1 fixent les intégrines LFA-1 et MAC-1 pour l'adhésion ferme.","s":10},{"q":"Quelle chimiokine attire spécifiquement les monocytes ?","o":["MCP-1","IL-8 (CXCL8)","L'éotaxine","LTB4"],"r":0,"e":"IL-8 attire les neutrophiles, l'éotaxine les éosinophiles et MCP-1 les monocytes.","s":10},{"q":"Par quel mécanisme cytosquelettique les leucocytes se déplacent-ils lors de la chimiotaxie ?","o":["Par polymérisation d'actine à l'avant de la cellule","Par contraction des myofibrilles","Par flux de calcium passif","Par battement ciliaire"],"r":0,"e":"La polymérisation d'actine au front de migration propulse la cellule vers le gradient.","s":10},{"q":"Pourquoi les neutrophiles dominent-ils les premières 24 heures ?","o":["Ils sont plus nombreux, répondent plus vite aux chimiokines et adhèrent fortement aux sélectines P et E","Ils survivent plus longtemps que les macrophages","Ils prolifèrent dans les tissus","Ils sont recrutés par l'IL-4"],"r":0,"e":"La survie longue et la prolifération tissulaire caractérisent au contraire les macrophages, qui prennent le relais à 24-48 h.","s":10},{"q":"Parmi les fonctions du système squelettique, on retrouve :","o":["Soutien du corps","Protection des organes","Mouvement (insertion musculaire)","Stockage minéral (Ca, P)","Hématopoïèse","Production d'insuline"],"r":[0,1,2,3,4],"e":"Fonctions de l'os : soutien, protection (crâne, thorax), mouvement (levier des muscles), homéostasie minérale (Ca, P), production sanguine (moelle rouge), stockage de lipides (moelle jaune). L'insuline est sécrétée par le pancréas endocrine ; l'os stocke le calcium et le phosphore, il ne produit pas d'insuline.","s":11},{"q":"Quelle proportion du calcium corporel est stockée dans l'os ?","o":["~30%","~50%","~70%","~99%"],"r":3,"e":"~99% du calcium corporel est stocké dans le tissu osseux (sous forme d'hydroxyapatite). C'est la principale réserve calcique de l'organisme.","s":11},{"q":"Concernant le tissu osseux COMPACT (cortical), quelles affirmations sont vraies ?","o":["Représente ~80% du squelette adulte","Organisé en ostéones (systèmes de Havers)","Très résistant aux contraintes mécaniques","Présent surtout dans la diaphyse des os longs","Très poreux et léger"],"r":[0,1,2,3],"e":"Os compact : ~80% du squelette, ostéones (canaux de Havers + lamelles concentriques), résistant, diaphyse des os longs. L'os SPONGIEUX est poreux et léger (épiphyses).","s":11},{"q":"Le tissu osseux SPONGIEUX (trabéculaire) :","o":["Est très dense et compact","Est constitué de travées osseuses, contient la moelle rouge","Ne contient pas de moelle","Est inerte et ne se remodèle pas"],"r":1,"e":"Os spongieux : organisation en travées (trabécules), réseau alvéolaire abritant la moelle rouge hématopoïétique. Présent dans les épiphyses des os longs et les os plats. Très actif métaboliquement.","s":11},{"q":"Quels sont les principaux types CELLULAIRES du tissu osseux ?","o":["Ostéoblastes (formation osseuse)","Ostéocytes (cellules matures)","Ostéoclastes (résorption)","Cellules de Schwann","Cellules bordantes"],"r":[0,1,2,4],"e":"4 cellules : ostéoblastes (synthèse de matrice), ostéocytes (matures, dans les ostéoplastes), ostéoclastes (résorption multinucléés), cellules bordantes (quiescentes). Les cellules de Schwann appartiennent au SNP.","s":11},{"q":"Les OSTÉOBLASTES sont responsables de :","o":["La résorption osseuse","La formation osseuse (synthèse de matrice)","La phagocytose","L'immunité"],"r":1,"e":"Ostéoblastes = formation osseuse : synthétisent la matrice organique (ostéoïde, surtout collagène I) qui se minéralise (hydroxyapatite). Quand emmurés, ils deviennent ostéocytes.","s":11},{"q":"Les OSTÉOCLASTES sont responsables de :","o":["La formation de l'os","La résorption osseuse","La synthèse du collagène","La sécrétion de calcitonine"],"r":1,"e":"Ostéoclastes = cellules multinucléées (issues de la lignée monocytaire) qui résorbent l'os : acidification + enzymes (cathepsine K) → libération de Ca, P et fragments de collagène.","s":11},{"q":"L'OSSIFICATION INTRAMEMBRANEUSE concerne :","o":["Les os plats du crâne (voûte)","La clavicule","Les os longs (diaphyse)","La mandibule","Les vertèbres"],"r":[0,1,3],"e":"Ossification intramembraneuse : à partir de membranes mésenchymateuses, sans modèle cartilagineux. Concerne les os plats du crâne, la clavicule, la mandibule. Les os longs et vertèbres = ossification ENDOCHONDRALE.","s":11},{"q":"L'OSSIFICATION ENDOCHONDRALE :","o":["Forme l'os à partir de membranes mésenchymateuses","Forme l'os à partir d'un modèle cartilagineux préexistant","Concerne uniquement le crâne","Ne se produit pas chez l'enfant"],"r":1,"e":"Ossification endochondrale : remplace progressivement un MODÈLE CARTILAGINEUX par de l'os. Concerne la majorité des os (longs, courts, vertèbres, base du crâne). Permet la croissance en longueur (cartilage de conjugaison).","s":11},{"q":"La croissance EN LONGUEUR des os longs se fait au niveau :","o":["De la diaphyse","Du périoste","Du cartilage de conjugaison (plaque épiphysaire)","Du canal médullaire"],"r":2,"e":"Croissance en longueur = cartilage de conjugaison (plaque épiphysaire), entre épiphyse et diaphyse. Croissance en épaisseur = périoste (apposition). Les plaques se ferment à la fin de la puberté.","s":11},{"q":"Le REMODELAGE OSSEUX correspond à :","o":["Une croissance osseuse continue","Un cycle équilibré de résorption (ostéoclastes) + formation (ostéoblastes)","Une simple usure progressive","Un phénomène pathologique"],"r":1,"e":"Remodelage = cycle continu (BMU - Bone Multicellular Unit) : ostéoclastes résorbent → ostéoblastes reconstruisent. Permet adaptation aux contraintes, réparation des micro-lésions, maintien de la calcémie. Cycle de ~3 mois.","s":11},{"q":"Quelles hormones régulent la calcémie ?","o":["PTH (parathormone)","Calcitonine","Vitamine D (calcitriol)","Insuline","Cortisol"],"r":[0,1,2],"e":"Régulation calcique : PTH (↑ Ca, sécrétée par les parathyroïdes en cas d'hypocalcémie) ; calcitonine (↓ Ca, thyroïde) ; vitamine D (↑ absorption intestinale Ca). Insuline = glycémie ; cortisol = stress.","s":11},{"q":"La PTH (parathormone) :","o":["Diminue la calcémie","Augmente la calcémie en stimulant la résorption osseuse","Augmente la calcémie en inhibant les ostéoclastes","N'a aucun effet sur le calcium"],"r":1,"e":"PTH = sécrétée en cas d'HYPOcalcémie. Augmente la calcémie par : 1) stimulation indirecte des ostéoclastes (résorption), 2) ↑ réabsorption rénale, 3) ↑ activation de la vitamine D → ↑ absorption intestinale.","s":11},{"q":"La CALCITONINE :","o":["Augmente la calcémie","Diminue la calcémie en inhibant les ostéoclastes","Stimule la résorption osseuse","Est sécrétée par les parathyroïdes"],"r":1,"e":"Calcitonine = produite par les cellules C de la thyroïde, sécrétée en cas d'HYPERcalcémie. Diminue la calcémie en inhibant les ostéoclastes. Effet relativement faible chez l'humain.","s":11},{"q":"La VITAMINE D active (calcitriol) augmente la calcémie principalement par :","o":["Inhibition des ostéoclastes","Augmentation de l'absorption intestinale du calcium","Diminution de l'absorption rénale","Sécrétion par la thyroïde"],"r":1,"e":"Calcitriol (1,25(OH)₂D₃) = forme active de la vitamine D. Augmente l'absorption intestinale du calcium et du phosphate. Sa carence cause le rachitisme (enfant) et l'ostéomalacie (adulte).","s":11},{"q":"Quels sont les rôles VITAUX du calcium ?","o":["Contraction musculaire","Coagulation sanguine","Transmission nerveuse","Activité enzymatique","Vision"],"r":[0,1,2,3],"e":"Rôles du Ca²⁺ : contraction musculaire (couplage excitation-contraction), coagulation (facteur IV), transmission synaptique, activation enzymatique, signalisation cellulaire, structure osseuse. La vision implique surtout la vitamine A.","s":11},{"q":"L'OSTÉOPOROSE est définie par :","o":["Une infection osseuse","Une diminution de la masse osseuse + altération de la microarchitecture → ↑ risque fracturaire","Une tumeur osseuse maligne","Une inflammation osseuse"],"r":1,"e":"Ostéoporose = ↓ DMO (densité minérale osseuse) + altération microarchitecturale → fragilité, ↑ risque fracturaire. Diagnostic par DEXA : T-score ≤ -2,5 (OMS). Touche surtout femmes ménopausées.","s":11},{"q":"Parmi les facteurs de risque d'OSTÉOPOROSE, on retrouve :","o":["Ménopause","Âge avancé","Carence en calcium / vitamine D","Sédentarité","Activité physique régulière"],"r":[0,1,2,3],"e":"Facteurs de risque : ménopause (carence œstrogène), âge, ATCD familiaux, carence Ca/vit D, sédentarité, alcool/tabac, corticoïdes au long cours. L'activité physique en charge est PROTECTRICE.","s":11},{"q":"L'OSTÉOMALACIE chez l'adulte correspond à :","o":["Une infection osseuse","Une minéralisation insuffisante de la matrice osseuse (carence en vitamine D)","Une tumeur osseuse","Une fracture de fatigue"],"r":1,"e":"Ostéomalacie = trouble de la MINÉRALISATION (matrice ostéoïde présente mais peu minéralisée), souvent par carence en vitamine D. Équivalent du rachitisme chez l'adulte. Os mou, douloureux, déformations.","s":11},{"q":"Le RACHITISME concerne :","o":["L'adulte uniquement","L'enfant en croissance avec carence en vitamine D","Toutes les fractures pathologiques","Les sujets âgés"],"r":1,"e":"Rachitisme = équivalent enfantin de l'ostéomalacie. Carence en vitamine D pendant la croissance → trouble de la minéralisation osseuse → déformations (genu varum, chapelet costal, retard de croissance).","s":11},{"q":"Concernant la maladie de PAGET osseuse, quelles affirmations sont vraies ?","o":["Trouble du remodelage osseux","Hyperactivité ostéoclastique puis ostéoblastique","Os épais mais désorganisé et fragile","Touche surtout l'enfant","Souvent localisée (bassin, vertèbres, crâne)"],"r":[0,1,2,4],"e":"Paget : remodelage ANARCHIQUE (résorption excessive puis formation désorganisée), os épais, déformé et fragile. Touche le sujet âgé (>50 ans), souvent ATCD familiaux. Localisations : bassin, vertèbres, crâne, fémur.","s":11},{"q":"L'OSTÉOMYÉLITE est :","o":["Une tumeur de l'os","Une infection osseuse","Une carence en calcium","Une fracture de fatigue"],"r":1,"e":"Ostéomyélite = infection osseuse (bactérienne le plus souvent : Staphylococcus aureus +++). Aiguë (enfant : voie hématogène) ou chronique. Risque de séquestre osseux.","s":11},{"q":"Quel TYPE DE FRACTURE survient sur un os pathologique ?","o":["Fracture transversale","Fracture comminutive","Fracture pathologique (sur os fragilisé)","Fracture en bois vert"],"r":2,"e":"Fracture pathologique : survient sur un os déjà fragilisé (ostéoporose, métastase, kyste osseux, Paget) après un traumatisme minime ou même spontanément.","s":11},{"q":"Concernant la cicatrisation d'une fracture, dans l'ordre chronologique :","o":["1. Hématome fracturaire","2. Cal mou (cartilagineux)","3. Cal dur (osseux)","4. Remodelage final","5. Apparition des ostéoclastes uniquement à la fin"],"r":[0,1,2,3],"e":"Cicatrisation osseuse : 1) hématome fracturaire (inflammation) → 2) cal mou (fibrocartilagineux, ~3 sem) → 3) cal dur (os immature, ~6-12 sem) → 4) remodelage (os lamellaire, des mois). Les ostéoclastes interviennent dès le début pour résorber l'os mort.","s":11},{"q":"L'effet PIÉZOÉLECTRIQUE de l'os signifie que :","o":["L'os ne réagit jamais aux contraintes","L'os génère des signaux électriques sous contrainte mécanique, stimulant le remodelage","L'os est totalement isolant","L'os ne se remodèle qu'après fracture"],"r":1,"e":"Effet piézoélectrique : sous contrainte mécanique, l'os génère des micro-courants électriques qui stimulent le remodelage selon la loi de Wolff (l'os s'adapte aux contraintes mécaniques).","s":11},{"q":"La loi de WOLFF dit que :","o":["L'os est uniquement génétiquement déterminé","L'os s'adapte aux contraintes mécaniques (forme suit fonction)","L'os ne change pas après l'enfance","L'os n'est pas vivant"],"r":1,"e":"Loi de Wolff : l'os s'adapte (en architecture et densité) aux contraintes mécaniques qu'il subit. Sport en charge → ↑ densité. Immobilisation → ostéoporose de non-usage. Base de la rééducation osseuse.","s":11},{"q":"Les fonctions de l'os incluent :","o":["Soutien","Protection des organes","Mouvement (insertion musculaire)","Stockage minéraux (Ca, P)","Hématopoïèse (moelle rouge)","Digestion"],"r":[0,1,2,3,4],"e":"Fonctions os : soutien, protection, mouvement, réservoir minéral, hématopoïèse. Pas de digestion.","s":11},{"q":"L'os compact se trouve :","o":["Au centre des os longs","Dans la diaphyse (couche externe)","Dans les épiphyses uniquement","Aux articulations"],"r":1,"e":"Os compact = couche externe dense (diaphyse). Os spongieux/trabéculaire = épiphyses.","s":11},{"q":"Les ostéoblastes :","o":["Détruisent la matrice osseuse","Synthétisent la matrice osseuse (formation)","Sont des cellules musculaires","Produisent l'hémoglobine"],"r":1,"e":"Ostéoblastes = formation osseuse (synthèse matrice). Ostéoclastes = résorption.","s":11},{"q":"Les ostéoclastes :","o":["Synthétisent l'os","Détruisent / résorbent la matrice osseuse","Stockent le Ca","Produisent l'EPO"],"r":1,"e":"Ostéoclastes = cellules multinucléées qui résorbent l'os (équilibre formation-résorption).","s":11},{"q":"Les ostéocytes sont :","o":["Des ostéoblastes inactifs piégés dans la matrice","Des cellules sanguines","Des cellules musculaires","Des ostéoclastes mûrs"],"r":0,"e":"Ostéocytes = ostéoblastes mûrs emprisonnés dans la matrice qu'ils ont sécrétée, dans les lacunes (canalicules).","s":11},{"q":"Le remodelage osseux est régulé par :","o":["Vitamine D, PTH, calcitonine, hormones sexuelles","Insuline uniquement","ADH","Adrénaline"],"r":0,"e":"Régulateurs : vit D, PTH (↑ résorption), calcitonine (↓ résorption), œstrogènes/testostérone (anti-résorption).","s":11},{"q":"La parathormone (PTH) :","o":["Diminue la calcémie","Augmente la calcémie en activant les ostéoclastes","N'a pas d'effet sur l'os","Stocke le Ca dans l'os"],"r":1,"e":"PTH ↑ calcémie : active ostéoclastes, ↑ réabsorption rénale Ca, ↑ activation vit D → ↑ absorption intestinale Ca.","s":11},{"q":"Le cartilage articulaire est :","o":["Très vascularisé","Avascularisé, nourri par le liquide synovial","Innervé","Capable de cicatriser parfaitement"],"r":1,"e":"Cartilage articulaire = avascularisé, sans nerf, nourri par diffusion via liquide synovial. Faible capacité de réparation.","s":11},{"q":"L'épiphyse fertile (cartilage de croissance) :","o":["Persiste toute la vie","Se ferme à la fin de la croissance","Est inutile","Ne contient pas de cartilage"],"r":1,"e":"Cartilage de croissance (plaque épiphysaire) actif pendant la croissance, se ferme à l'âge adulte (ossification).","s":11},{"q":"Le tissu osseux contient :","o":["Eau seulement","Phase organique (collagène I) + phase minérale (hydroxyapatite)","Que des minéraux","Que des cellules"],"r":1,"e":"Os = matrice organique (90% collagène I, ostéoïde) + phase minérale (cristaux d'hydroxyapatite Ca/P).","s":11},{"q":"Quelle proportion du poids corporel le tissu osseux représente-t-il ?","o":["Environ 18 %","Environ 5 %","Environ 30 %","Environ 50 %"],"r":0,"e":"La fiche indique environ 18 % du poids corporel.","s":11},{"q":"Pourquoi chaque os est-il considéré comme un organe ?","o":["Parce qu'il est composé de plusieurs tissus : osseux, cartilage, conjonctif dense, épithélium, adipeux et nerveux","Parce qu'il contient de la moelle","Parce qu'il est vascularisé","Parce qu'il stocke du calcium"],"r":0,"e":"La présence de plusieurs types de tissus définit un organe.","s":11},{"q":"Où se trouve la moelle osseuse rouge chez l'adulte ?","o":["Hanches, côtes, sternum, vertèbres, crâne et extrémités de l'humérus et du fémur","Dans toute la cavité médullaire des os longs","Uniquement dans le crâne","Uniquement dans les diaphyses"],"r":0,"e":"La moelle jaune, adipeuse, occupe la cavité médullaire diaphysaire chez l'adulte.","s":11},{"q":"Qu'est-ce que la métaphyse ?","o":["La zone entre diaphyse et épiphyse, contenant la plaque épiphysaire chez l'enfant","Le corps central de l'os","L'extrémité articulaire","La membrane recouvrant l'os"],"r":0,"e":"La plaque épiphysaire y devient ligne épiphysaire chez l'adulte.","s":11},{"q":"Comment le périoste est-il fixé à l'os ?","o":["Par les fibres de Sharpey","Par les canalicules","Par les fibres de collagène de type IV","Par l'endoste"],"r":0,"e":"Les fibres de Sharpey ancrent le périoste dans la matrice osseuse.","s":11},{"q":"Quelles sont les deux couches du périoste ?","o":["Une couche fibreuse externe et une couche ostéogénique interne","Une couche compacte et une couche spongieuse","Une couche minéralisée et une couche cartilagineuse","Une couche vasculaire et une couche nerveuse"],"r":0,"e":"La couche ostéogénique interne contient les cellules capables de former de l'os.","s":11},{"q":"Pourquoi le cartilage articulaire se répare-t-il mal ?","o":["Parce qu'il est avasculaire","Parce qu'il est trop dense","Parce qu'il ne contient pas de collagène","Parce qu'il est constamment comprimé"],"r":0,"e":"L'absence de vascularisation limite fortement la capacité de réparation du cartilage hyalin.","s":11},{"q":"Quelle est la composition de la matrice osseuse ?","o":["55 % de sels minéraux, 30 % de fibres de collagène et 15 % d'eau","30 % de sels minéraux, 55 % de collagène et 15 % d'eau","70 % de sels minéraux et 30 % de collagène","50 % d'eau et 50 % de minéraux"],"r":0,"e":"Les sels minéraux donnent la dureté, le collagène la souplesse et l'eau le milieu de diffusion.","s":11},{"q":"Quelle est la formule de l'hydroxyapatite ?","o":["Ca₁₀(PO₄)₆(OH)₂","CaCO₃","Ca(OH)₂","CaSO₄"],"r":0,"e":"L'hydroxyapatite est le cristal minéral principal de l'os, accompagné de carbonate de calcium et d'ions Mg, F, K et SO₄.","s":11},{"q":"Quelles sont les seules cellules osseuses capables de se diviser ?","o":["Les cellules ostéogéniques","Les ostéoblastes","Les ostéocytes","Les ostéoclastes"],"r":0,"e":"Issues du mésenchyme, les cellules ostéogéniques donnent les ostéoblastes ; les autres ne se divisent pas.","s":11},{"q":"De quoi les ostéoclastes proviennent-ils ?","o":["De la fusion d'environ 50 monocytes","De cellules mésenchymateuses","D'ostéoblastes piégés dans la matrice","De chondroblastes"],"r":0,"e":"Leur origine monocytaire explique leur capacité de résorption ; les ostéocytes proviennent des ostéoblastes.","s":11},{"q":"Comment les ostéocytes communiquent-ils entre eux ?","o":["Par les canalicules et des jonctions communicantes","Par les canaux de Volkmann uniquement","Par la circulation sanguine","Ils ne communiquent pas"],"r":0,"e":"Les prolongements cytoplasmiques cheminent dans les canalicules qui relient les lacunes.","s":11},{"q":"Qu'est-ce qu'un ostéon ?","o":["Un système de lamelles concentriques autour d'un canal central de Havers","Une trabécule d'os spongieux","Une lacune contenant un ostéocyte","Un canal transversal reliant le périoste à l'endoste"],"r":0,"e":"L'ostéon, ou système de Havers, est l'unité de l'os compact ; le canal transversal est celui de Volkmann.","s":11},{"q":"Quelle proportion du squelette l'os compact représente-t-il ?","o":["80 %","20 %","50 %","95 %"],"r":0,"e":"80 % d'os compact pour 20 % d'os spongieux.","s":11},{"q":"La POLYARTHRITE RHUMATOÏDE (PR) est :","o":["Une maladie dégénérative","Une maladie auto-immune chronique inflammatoire","Une maladie infectieuse","Une fracture pathologique"],"r":1,"e":"PR = polyarthrite chronique inflammatoire AUTO-IMMUNE. Atteinte symétrique, prédominant aux petites articulations (mains, pieds), avec destruction articulaire progressive et manifestations extra-articulaires.","s":12},{"q":"Quels sont les signes typiques de la PR ?","o":["Atteinte symétrique","Polyarthrite des petites articulations (mains, poignets, pieds)","Raideur matinale > 30-60 min","Signes radiographiques : pincement articulaire, érosions","Déformations en col de cygne / boutonnière","Ostéophytes marginaux à la radiographie"],"r":[0,1,2,3,4],"e":"PR typique : symétrique, petites articulations (MCP, IPP, poignets, MTP), raideur matinale prolongée (>30-60 min, vs arthrose <15 min), déformations caractéristiques (col de cygne, boutonnière), signes biologiques (FR, anti-CCP). Les ostéophytes sont le signe radiographique de l'arthrose ; la polyarthrite rhumatoïde donne des érosions.","s":12},{"q":"L'ARTHROSE est :","o":["Une maladie auto-immune","Une maladie dégénérative du cartilage articulaire","Une fracture","Une infection"],"r":1,"e":"Arthrose (osteoarthritis) = maladie DÉGÉNÉRATIVE du cartilage articulaire, avec remaniement de l'os sous-chondral, ostéophytes, et inflammation modérée. Pas auto-immune. Très fréquente avec l'âge.","s":12},{"q":"Quels sont les signes radiologiques typiques de l'ARTHROSE ?","o":["Pincement articulaire","Ostéophytes (becs)","Sclérose sous-chondrale","Géodes (kystes sous-chondraux)","Érosions marginales"],"r":[0,1,2,3],"e":"Arthrose RX : 'POSG' = Pincement articulaire, Ostéophytes, Sclérose sous-chondrale, Géodes. Les ÉROSIONS marginales sont signes de POLYARTHRITE inflammatoire (PR).","s":12},{"q":"La douleur d'ARTHROSE est typiquement :","o":["Inflammatoire (matinale, prolongée)","Mécanique (calmée par le repos, augmentée à l'effort)","Permanente sans facteur déclenchant","Aiguë avec fièvre"],"r":1,"e":"Douleur arthrosique = MÉCANIQUE : ↑ à l'effort/marche, calmée par le repos, raideur matinale courte (<15 min, dérouillage). PR = douleur INFLAMMATOIRE : nuit, raideur matinale prolongée.","s":12},{"q":"La GOUTTE est due à :","o":["Une infection bactérienne","Un dépôt de cristaux d'urate de sodium dans les articulations","Une auto-immunité","Une carence en calcium"],"r":1,"e":"Goutte = arthropathie microcristalline due au dépôt de cristaux d'urate monosodique liés à une hyperuricémie. Crise aiguë : monoarthrite très inflammatoire (souvent gros orteil = podagre).","s":12},{"q":"Concernant la crise de GOUTTE, quelles affirmations sont vraies ?","o":["Souvent au gros orteil (1ère MTP) = podagre","Monoarthrite très inflammatoire (rouge, chaude, douloureuse)","Hyperuricémie","Traitement aigu : colchicine ou AINS","Toujours bilatérale"],"r":[0,1,2,3],"e":"Goutte aiguë : podagre (50% des cas), monoarthrite intense, hyperuricémie (mais pas toujours en crise !). Tx aigu = colchicine ou AINS. Tx fond = allopurinol (inhibiteur xanthine oxydase). Souvent UNILATÉRALE.","s":12},{"q":"Le LUPUS érythémateux disséminé est :","o":["Une maladie infectieuse","Une maladie auto-immune systémique","Une maladie dégénérative","Une fracture pathologique"],"r":1,"e":"LED = maladie auto-immune SYSTÉMIQUE (multi-organique : peau, articulations, rein, SNC, cœur, sang). Plus fréquent chez les femmes jeunes. Anticorps caractéristiques : anti-ADN natif, anti-Sm.","s":12},{"q":"Manifestations classiques du LUPUS :","o":["Érythème en ailes de papillon (vespertilio) sur le visage","Photosensibilité","Atteinte rénale (glomérulonéphrite lupique)","Polyarthrite non érosive","Tassements vertébraux ostéoporotiques"],"r":[0,1,2,3],"e":"LED : rash malaire en ailes de papillon, photosensibilité, atteinte rénale (souvent grave), polyarthrite non érosive (vs PR), atteinte hématologique, sérites, neurologiques. Tassements ostéoporotiques = autre pathologie.","s":12},{"q":"La SCLÉRODERMIE (sclérose systémique) est caractérisée par :","o":["Une démyélinisation du SNC","Une fibrose excessive de la peau et des organes internes","Une infection chronique","Une carence vitaminique"],"r":1,"e":"Sclérodermie = maladie auto-immune avec FIBROSE excessive de la peau (scléroderme) et des organes (poumons, rein, œsophage, cœur). Peut être limitée (CREST) ou diffuse. Phénomène de Raynaud quasi constant.","s":12},{"q":"Concernant les SPONDYLARTHROPATHIES, quelles affirmations sont vraies ?","o":["Atteinte préférentielle du squelette axial (rachis, sacro-iliaques)","Inflammation des enthèses (enthésites)","Souvent associées au HLA-B27","La spondylarthrite ankylosante en fait partie","Atteignent surtout les femmes âgées"],"r":[0,1,2,3],"e":"Spondylarthropathies : atteinte axiale (rachis, SI), enthésites, dactylites, association HLA-B27, exemples = spondylarthrite ankylosante, rhumatisme psoriasique, arthrite réactionnelle, MICI. Touchent l'adulte jeune (homme +).","s":12},{"q":"Une OSTÉOMYÉLITE est :","o":["Une infection osseuse","Une tumeur","Une carence vitaminique","Une malformation congénitale"],"r":0,"e":"Ostéomyélite = infection bactérienne de l'os (Staphylococcus aureus +++). Voie hématogène (enfant, métaphyse) ou contiguïté/inoculation (adulte). Peut chroniciser → séquestre osseux.","s":12},{"q":"L'OSTÉONÉCROSE aseptique correspond à :","o":["Une infection sans germe","Une mort osseuse par défaut de vascularisation","Une fracture pathologique","Une décalcification"],"r":1,"e":"Ostéonécrose aseptique = mort osseuse par interruption de la vascularisation. Site classique : tête fémorale. FdR : corticoïdes, alcool, traumatisme (fracture col), drépanocytose, lupus.","s":12},{"q":"Quels sont des facteurs de risque d'OSTÉONÉCROSE de la tête fémorale ?","o":["Corticothérapie au long cours","Alcoolisme chronique","Drépanocytose","Traumatisme (fracture du col)","Hypertension"],"r":[0,1,2,3],"e":"FdR ostéonécrose tête fémorale : corticoïdes, alcool, drépanocytose, fracture du col, lupus, plongée (maladie des caissons), idiopathique. L'HTA n'est pas un FdR direct.","s":12},{"q":"Les TUMEURS osseuses les plus fréquentes chez l'adulte sont :","o":["Les tumeurs primaires","Les MÉTASTASES osseuses","Les ostéosarcomes","Les chondromes"],"r":1,"e":"Chez l'adulte, les tumeurs osseuses sont surtout des MÉTASTASES (sein, poumon, prostate, rein, thyroïde — moyen mnémo : 'PSPRT' ou 'RPS'). Les tumeurs primaires sont plus rares.","s":12},{"q":"L'OSTÉOSARCOME est :","o":["Une tumeur bénigne","Une tumeur osseuse maligne primitive de l'adolescent / adulte jeune","Une métastase","Un kyste osseux"],"r":1,"e":"Ostéosarcome = tumeur osseuse PRIMITIVE MALIGNE la plus fréquente, pic à l'adolescence (10-20 ans), localisation classique : métaphyse des os longs (fémur distal, tibia proximal). Pronostic amélioré (chimio + chirurgie).","s":12},{"q":"Quels critères différencient PR et ARTHROSE ?","o":["PR = inflammatoire, arthrose = mécanique","PR = symétrique, arthrose = souvent asymétrique (sauf nodale)","PR = raideur matinale longue, arthrose = courte","PR = érosions, arthrose = ostéophytes","PR et arthrose ont les mêmes traitements"],"r":[0,1,2,3],"e":"PR : auto-immune, symétrique, raideur matinale >60 min, érosions, FR/anti-CCP. Arthrose : dégénérative, asymétrique, douleur mécanique, ostéophytes. Traitements TRÈS différents (DMARDs vs antalgiques + kiné).","s":12},{"q":"L'ankylose articulaire correspond à :","o":["Une raideur passagère","Une perte définitive de la mobilité articulaire (fusion)","Une inflammation aiguë","Une luxation"],"r":1,"e":"Ankylose = perte définitive de la mobilité articulaire par fusion fibreuse ou osseuse des surfaces articulaires. Peut compliquer une PR sévère, une spondylarthrite ankylosante, une arthrose terminale.","s":12},{"q":"Le syndrome du CANAL CARPIEN est dû à :","o":["Une compression du nerf médian au poignet","Une compression du nerf ulnaire au coude","Une compression du nerf radial au bras","Une rupture du tendon fléchisseur"],"r":0,"e":"Canal carpien = compression du nerf MÉDIAN dans le canal carpien au poignet. Paresthésies des 3 premiers doigts + bord radial du 4e, recrudescence nocturne, faiblesse de l'opposition du pouce.","s":12},{"q":"L'arthrose des doigts (nodale) se caractérise par :","o":["Atteinte des MCP en priorité","Nodules d'Heberden (IPD) et de Bouchard (IPP)","Pannus synovial érosif","Symétrique avec raideur matinale prolongée"],"r":1,"e":"Arthrose digitale nodale : nodules d'Heberden (IPD), Bouchard (IPP). PAS d'atteinte des MCP (sinon évoquer PR). Touche surtout les femmes ménopausées, souvent familial.","s":12},{"q":"Quels examens biologiques sont utiles dans la PR ?","o":["Facteur Rhumatoïde (FR)","Anticorps anti-CCP (anti-peptides citrullinés)","CRP / VS","ASLO","HLA-B27"],"r":[0,1,2],"e":"PR : FR (peu spécifique), anti-CCP (très spécifique +++), CRP/VS (inflammation). HLA-B27 = spondylarthrite. ASLO = streptocoque (RAA). Anti-ADN natif = lupus.","s":12},{"q":"Le pannus synovial est typique de :","o":["L'arthrose","La polyarthrite rhumatoïde","La goutte","L'ostéoporose"],"r":1,"e":"Pannus = tissu synovial inflammatoire prolifératif et invasif qui érode l'os et le cartilage dans la PR. Responsable de la destruction articulaire (érosions, géodes, déformations).","s":12},{"q":"Concernant les MALADIES MÉTABOLIQUES osseuses, on retrouve :","o":["Ostéoporose","Ostéomalacie / rachitisme","Maladie de Paget","Hyperparathyroïdie","Polyarthrite rhumatoïde"],"r":[0,1,2,3],"e":"Maladies métaboliques osseuses : ostéoporose (↓ masse), ostéomalacie/rachitisme (↓ minéralisation), Paget (remodelage anarchique), hyperparathyroïdie (résorption excessive), ostéogenèse imparfaite. La PR est rhumatismale, pas métabolique.","s":12},{"q":"Le RHUMATISME ARTICULAIRE AIGU (RAA) est une complication :","o":["D'une infection à staphylocoque","D'une infection à streptocoque β-hémolytique du groupe A","D'une infection virale","D'une carence vitaminique"],"r":1,"e":"RAA : complication post-infectieuse d'une angine à streptocoque β-hémolytique A. Survient 2-3 semaines après. Atteinte articulaire (polyarthrite), cardiaque (cardite ++ valvulaire) et neurologique (chorée). Critères de Jones.","s":12},{"q":"La maladie de PAGET est :","o":["Une infection","Un trouble du remodelage osseux avec hyperactivité ostéoclastique puis ostéoblastique anarchique","Une carence en calcium","Une auto-immunité"],"r":1,"e":"Paget : trouble localisé du remodelage avec phase ostéoclastique excessive puis phase ostéoblastique désorganisée → os hypertrophique mais fragile. Sites : bassin, vertèbres, crâne, fémur. Souvent asymptomatique.","s":12},{"q":"La chondrocalcinose (« pseudo-goutte ») est due au dépôt intra-articulaire de :","o":["Cristaux d'urate monosodique","Cristaux de pyrophosphate de calcium","Cristaux de cholestérol","Cristaux d'oxalate de calcium"],"r":1,"e":"La goutte est liée aux cristaux d'urate monosodique (en aiguilles, biréfringence négative) ; la chondrocalcinose aux cristaux de pyrophosphate de calcium (rhomboédriques, biréfringence positive), visibles en radiographie sous forme de liserés calciques du cartilage, notamment aux ménisques et au ligament triangulaire du carpe.","s":12},{"q":"Les ostéophytes sont :","o":["Des trous osseux","Des excroissances osseuses (becs de perroquet) typiques de l'arthrose","Des fractures","Des cellules cancéreuses"],"r":1,"e":"Ostéophytes = excroissances osseuses péri-articulaires, signes radiologiques typiques de l'arthrose.","s":12},{"q":"Une luxation est :","o":["Une fissure osseuse","Une perte de contact permanente entre 2 surfaces articulaires","Une contusion","Une déchirure musculaire"],"r":1,"e":"Luxation = perte permanente du contact normal entre les surfaces articulaires.","s":12},{"q":"Une entorse correspond à :","o":["Une fracture","Une lésion ligamentaire (étirement, rupture)","Une luxation","Une déchirure musculaire"],"r":1,"e":"Entorse = lésion ligamentaire (grade 1: étirement, 2: déchirure partielle, 3: rupture complète).","s":12},{"q":"Le syndrome du canal carpien est :","o":["Une fracture","Une compression du nerf médian au poignet","Une rupture musculaire","Une infection osseuse"],"r":1,"e":"Canal carpien = compression du nerf médian dans le canal carpien (paresthésies pouce, index, majeur).","s":12},{"q":"Une tendinite est :","o":["Une rupture totale","Une inflammation d'un tendon (souvent par surcharge)","Une infection","Une fracture"],"r":1,"e":"Tendinite/tendinopathie = atteinte inflammatoire ou dégénérative d'un tendon, souvent par surcharge.","s":12},{"q":"La bursite est :","o":["Inflammation d'une bourse synoviale","Fracture","Tumeur","Infection cutanée"],"r":0,"e":"Bursite = inflammation d'une bourse synoviale (épaule, coude, hanche, genou).","s":12},{"q":"L'épicondylite latérale (« tennis elbow ») touche :","o":["Le coude médial","L'insertion des extenseurs du poignet sur l'épicondyle latéral","Le poignet","L'épaule"],"r":1,"e":"Tennis elbow = tendinopathie d'insertion des extenseurs sur l'épicondyle latéral du coude.","s":12},{"q":"La rupture du tendon d'Achille est typique :","o":["De l'enfant","Du sportif d'âge moyen lors d'un effort en flexion plantaire","De la femme enceinte","Du nourrisson"],"r":1,"e":"Rupture tendon d'Achille : hommes 30-50 ans, sport (squash, badminton), claquement audible.","s":12},{"q":"Une fracture en bois vert touche :","o":["L'adulte âgé","L'enfant (os flexible, fracture incomplète)","La personne ostéoporotique","Le sportif"],"r":1,"e":"Fracture en bois vert = enfant, os flexible, une corticale rompue, l'autre intacte (incomplète).","s":12},{"q":"Quelle est la première cause de mortalité chez l'adulte de moins de 44 ans selon la fiche ?","o":["Les accidents de la route à grande vitesse","Les chutes accidentelles","Les blessures sportives","Les fractures ostéoporotiques"],"r":0,"e":"Les chutes sont la première cause de blessures non mortelles chez les 0-19 ans.","s":12},{"q":"Quelle proportion des personnes de 65 ans et plus chute au moins une fois par an ?","o":["Une sur trois","Une sur dix","Une sur deux","Une sur vingt"],"r":0,"e":"Ces chutes expliquent la majorité des fractures vertébrales, du radius distal et de la hanche.","s":12},{"q":"Quelle part des blessures sportives de l'enfant relève d'une utilisation excessive ?","o":["50 %","10 %","80 %","25 %"],"r":0,"e":"La fiche oppose les lésions aiguës aux lésions de surmenage, à parts égales chez l'enfant.","s":12},{"q":"Quel traitement la fiche propose-t-elle pour une contusion ?","o":["Élévation et froid 20 minutes toutes les 4 heures","Suture après nettoyage","Aspiration systématique","Immobilisation plâtrée"],"r":0,"e":"La suture concerne la lacération et l'aspiration éventuellement l'hématome.","s":12},{"q":"Quel risque infectieux particulier présente une plaie perforante par objet rouillé ?","o":["Le tétanos et la gangrène gazeuse, dus à des anaérobies","Une ostéomyélite hématogène","Une tuberculose osseuse","Une nécrose avasculaire"],"r":0,"e":"Les germes anaérobies profitent de l'anoxie de la plaie profonde.","s":12},{"q":"Quels sites sont les plus fréquents pour un claquage musculaire ?","o":["Bas du dos, cervicales, coude, épaule et pied","La cheville","Le genou","La hanche"],"r":0,"e":"La cheville est le site n°1 d'entorse, pas de claquage.","s":12},{"q":"Qu'est-ce qui distingue cliniquement l'entorse du claquage ?","o":["L'entorse donne un gonflement rapide, de la chaleur et une décoloration, avec une atténuation plus lente","Le claquage gonfle plus vite","L'entorse est toujours indolore","Le claquage touche les ligaments"],"r":0,"e":"Le claquage atteint l'unité musculo-tendineuse sans signe extérieur marqué.","s":12},{"q":"Combien de temps la résistance à la traction reste-t-elle insuffisante après une lésion tendineuse ?","o":["Environ 2 mois","Environ 2 semaines","Environ 1 semaine","Environ 6 mois"],"r":0,"e":"Les faisceaux de collagène se forment dès les deux premières semaines, mais la solidité tarde.","s":12},{"q":"Qu'est-ce qu'une subluxation ?","o":["Une luxation partielle, où un contact articulaire est maintenu","Une luxation complète","Une fracture articulaire","Une entorse de grade 3"],"r":0,"e":"La luxation vraie sépare complètement les extrémités osseuses.","s":12},{"q":"Quels sont les trois types de luxations selon leur cause ?","o":["Congénitales, traumatiques et pathologiques","Antérieures, postérieures et centrales","Complètes, partielles et récidivantes","Aiguës, subaiguës et chroniques"],"r":0,"e":"Les formes pathologiques compliquent une infection, une PR ou une paralysie.","s":12},{"q":"Quel muscle de la coiffe des rotateurs est le plus souvent atteint ?","o":["Le supraspinatus","Le teres minor","L'infraspinatus","Le subscapularis"],"r":0,"e":"Le sus-épineux est le plus exposé, la récupération postopératoire prenant 6 à 12 mois.","s":12},{"q":"Qu'est-ce que la chondromalacie ?","o":["Un ramollissement du cartilage rotulien, chez le jeune adulte","Une déchirure méniscale","Une rupture du ligament croisé antérieur","Une luxation de rotule"],"r":0,"e":"La subluxation rotulienne représente environ 10 % des blessures sportives, avec prédominance féminine.","s":12},{"q":"Pourquoi la luxation postérieure de hanche est-elle une urgence ?","o":["À cause du risque de nécrose avasculaire de la tête fémorale","À cause du risque d'infection","À cause du risque de syndrome des loges","À cause du risque d'embolie graisseuse"],"r":0,"e":"La réduction précoce vise à restaurer la vascularisation.","s":12},{"q":"Quels facteurs de risque de fracture de hanche la fiche cite-t-elle ?","o":["Faible IMC, grande taille, benzodiazépines, troubles de la vision et ostéoporose","Obésité et tabagisme","Diabète et hypertension","Sport intensif"],"r":0,"e":"Les localisations sont le col fémoral, la région intertrochantérienne et la région sous-trochantérienne.","s":12},{"q":"Quelle complication menace une fracture déplacée du col fémoral ?","o":["Une nécrose avasculaire et une non-consolidation par perturbation vasculaire","Un syndrome des loges","Une embolie graisseuse constante","Une ostéomyélite hématogène"],"r":0,"e":"Le caractère intracapsulaire compromet la vascularisation de la tête.","s":12},{"q":"L'OSTÉOPÉNIE correspond, à la DEXA, à un T-score :","o":["≥ -1","Entre -1 et -2,5","≤ -2,5","≤ -2,5 + fracture"],"r":1,"e":"OMS : Normal T-score > -1 ; Ostéopénie : -1 à -2,5 ; Ostéoporose : ≤ -2,5 ; Ostéoporose sévère : ≤ -2,5 + fracture de fragilité.","s":13},{"q":"L'ostéoporose est définie (DEXA) par un T-score :","o":["> -1","Entre -1 et -2,5","≤ -2,5","≤ -3,5"],"r":2,"e":"Ostéoporose densitométrique : T-score ≤ -2,5 (≥ 2,5 écarts-types sous la moyenne d'un adulte jeune de référence).","s":13},{"q":"L'examen de référence pour le diagnostic densitométrique d'ostéoporose est :","o":["IRM osseuse","Scintigraphie","DEXA (absorptiométrie biphotonique)","Radiographie standard"],"r":2,"e":"DEXA = examen de référence : mesure la DMO (densité minérale osseuse) au rachis lombaire et au col fémoral. Donne le T-score (vs adulte jeune) et le Z-score (vs même âge).","s":13},{"q":"Parmi les facteurs de risque MAJEURS d'ostéoporose, on retrouve :","o":["Sexe féminin","Ménopause précoce","Antécédent de fracture de fragilité","Corticothérapie prolongée","Activité physique régulière en charge"],"r":[0,1,2,3],"e":"Facteurs majeurs : sexe féminin, ménopause précoce, ATCD personnel/familial de fracture de fragilité, corticoïdes au long cours, IMC bas, alcoolisme, tabagisme. L'activité en charge est PROTECTRICE.","s":13},{"q":"L'ostéoporose POST-MÉNOPAUSIQUE est principalement due à :","o":["Une carence en calcium","Une carence en œstrogènes","Un excès de PTH","Une carence en vitamine K"],"r":1,"e":"Post-ménopause : carence œstrogénique → ↑ activité ostéoclastique → ↑ résorption osseuse > formation → perte osseuse rapide les premières années (jusqu'à 3-5%/an au début).","s":13},{"q":"Quels sites anatomiques sont les plus exposés aux fractures ostéoporotiques ?","o":["Col fémoral","Vertèbres (tassements)","Poignet (fracture de Pouteau-Colles)","Crâne","Humérus proximal"],"r":[0,1,2,4],"e":"Sites typiques : col fémoral (gravissime, mortalité 20-25% à 1 an), vertèbres (tassements souvent silencieux), poignet (Pouteau-Colles), humérus proximal. Le crâne n'est pas un site classique.","s":13},{"q":"La fracture de POUTEAU-COLLES est :","o":["Une fracture du col fémoral","Une fracture distale du radius en extension du poignet","Une fracture vertébrale","Une fracture de l'humérus"],"r":1,"e":"Pouteau-Colles : fracture de l'extrémité inférieure du radius, à déplacement postérieur, sur chute en hyperextension du poignet. Très fréquente chez la femme ménopausée.","s":13},{"q":"Concernant les fractures VERTÉBRALES ostéoporotiques :","o":["Souvent silencieuses (asymptomatiques)","Provoquent un tassement vertébral","Peuvent diminuer la taille","Apparaissent souvent sans traumatisme évident","Toujours symptomatiques"],"r":[0,1,2,3],"e":"Tassements vertébraux : souvent silencieux (50% asymptomatiques), perte de taille progressive, cyphose dorsale, parfois douleur aiguë. Découverte fréquemment fortuite.","s":13},{"q":"Quels traitements sont utilisés dans l'ostéoporose ?","o":["Bisphosphonates (alendronate)","Dénosumab","Calcium + vitamine D","Tériparatide (PTH 1-34)","Antibiotiques"],"r":[0,1,2,3],"e":"Traitements : antirésorbeurs (bisphosphonates, dénosumab, raloxifène), anaboliques (tériparatide, romosozumab), supplémentation Ca + vit D systématique. Antibiotiques = ostéomyélite, pas ostéoporose.","s":13},{"q":"Les BISPHOSPHONATES agissent en :","o":["Stimulant les ostéoblastes","Inhibant les ostéoclastes","Apportant directement du calcium","Stimulant la PTH"],"r":1,"e":"Bisphosphonates (alendronate, risédronate, acide zolédronique) : se fixent à l'os et inhibent l'activité ostéoclastique → ↓ résorption → stabilisation/gain de DMO.","s":13},{"q":"Un trait de fracture TRANSVERSAL résulte typiquement de :","o":["Une force de torsion","Une force directe perpendiculaire à l'os","Une compression axiale","Une fracture pathologique"],"r":1,"e":"Trait transversal : force directe (choc perpendiculaire). Spiroïde = torsion. Comminutif = haute énergie. En bois vert = enfant.","s":13},{"q":"Une fracture EN BOIS VERT survient :","o":["Chez l'adulte âgé","Chez l'enfant (os flexible)","Sur os nécrosé","Sur métastase"],"r":1,"e":"Fracture en bois vert : typique de l'enfant (os flexible) → la corticale se rompt d'un seul côté, l'autre se plie sans rompre. Ressemble à une branche verte qu'on plie.","s":13},{"q":"Concernant la consolidation osseuse, dans l'ordre :","o":["1. Hématome inflammatoire","2. Cal mou (fibrocartilagineux)","3. Cal dur (osseux)","4. Remodelage","5. La consolidation est en 2 étapes"],"r":[0,1,2,3],"e":"Consolidation en 4 étapes : hématome (jours), cal mou (3-6 sem), cal dur (6-12 sem), remodelage (mois-années pour retrouver l'architecture).","s":13},{"q":"Quels facteurs RETARDENT la consolidation osseuse ?","o":["Tabagisme","Diabète","Anti-inflammatoires (AINS) au long cours","Mauvaise vascularisation locale","Jeune âge"],"r":[0,1,2,3],"e":"Retardateurs : tabac (vasoconstriction), diabète, AINS chroniques (↓ COX-2 et inflammation utile), mauvaise vascularisation, infection, mobilité excessive du foyer, âge avancé. Le jeune âge favorise.","s":13},{"q":"L'OSTÉONÉCROSE de la tête fémorale survient :","o":["Toujours après une infection","Après une perte de vascularisation (ex : fracture du col, alcool, corticoïdes)","Uniquement chez l'enfant","Sans aucun facteur de risque"],"r":1,"e":"Ostéonécrose aseptique : interruption de la vascularisation → mort osseuse. FdR : corticoïdes, alcoolisme, fracture du col, drépanocytose, lupus, traumatisme. Site classique : tête fémorale.","s":13},{"q":"Une OSTÉOMYÉLITE est :","o":["Une tumeur osseuse","Une infection osseuse, souvent à Staphylococcus aureus","Une décalcification","Une carence en vitamine D"],"r":1,"e":"Ostéomyélite : infection osseuse, le plus souvent bactérienne (S. aureus +++). Voie hématogène (enfant) ou par contiguïté/inoculation directe (adulte, post-chirurgie/fracture ouverte).","s":13},{"q":"Parmi les COMPLICATIONS d'une fracture, on retrouve :","o":["Pseudarthrose (non-consolidation)","Cal vicieux","Embolie graisseuse","Syndrome de loge","Aucune complication possible"],"r":[0,1,2,3],"e":"Complications : pseudarthrose (>6 mois sans consolidation), cal vicieux (mauvaise position), embolie graisseuse (fracture os longs), syndrome de loge (urgence !), nécrose avasculaire, infection.","s":13},{"q":"Le syndrome de LOGE est :","o":["Une infection osseuse","Une augmentation de pression dans une loge musculaire fermée → ischémie","Une fracture multiple","Une rupture ligamentaire"],"r":1,"e":"Syndrome de loge : ↑ pression intra-compartimentale (œdème, hématome) → compression vasculo-nerveuse → ischémie musculaire/nerveuse. URGENCE chirurgicale (fasciotomie). Signe : douleur disproportionnée.","s":13},{"q":"Concernant l'ENTORSE :","o":["Atteinte d'un ligament","Grades 1 (étirement) à 3 (rupture complète)","Survient lors d'un mouvement forcé","Concerne souvent la cheville (LLE)","C'est une fracture"],"r":[0,1,2,3],"e":"Entorse = atteinte ligamentaire (étirement à rupture). Grades I (bénigne), II (rupture partielle), III (rupture totale ± instabilité). Cheville (LLE) = la plus fréquente. Pas une fracture (concerne l'os).","s":13},{"q":"Une LUXATION est :","o":["Une fracture osseuse","Une perte de contact totale et permanente entre 2 surfaces articulaires","Un simple étirement","Une déchirure musculaire"],"r":1,"e":"Luxation = perte complète et permanente du contact articulaire (subluxation = perte partielle). Articulations souvent touchées : épaule (la +), interphalangienne, hanche prothétique.","s":13},{"q":"Une CLAQUAGE musculaire correspond à :","o":["Une rupture des fibres musculaires","Une fracture","Une luxation","Un étirement musculaire"],"r":0,"e":"Claquage = déchirure (rupture) de fibres musculaires (grade 2). Crampe = contraction involontaire ; courbatures = micro-lésions. Élongation (grade 1) < claquage (grade 2) < rupture (grade 3).","s":13},{"q":"Quels sont les bénéfices de l'activité physique en CHARGE pour l'os ?","o":["Stimulation du remodelage osseux (loi de Wolff)","Amélioration de la DMO","Prévention de l'ostéoporose","Amélioration de l'équilibre (↓ chutes)","Aucun effet sur les os"],"r":[0,1,2,3],"e":"Activité en charge : stimule le remodelage osseux (loi de Wolff), ↑ DMO, prévient l'ostéoporose, améliore l'équilibre/musculature → ↓ risque de chute et de fracture.","s":13},{"q":"Le score FRAX permet :","o":["Le diagnostic d'ostéomyélite","D'estimer le risque fracturaire à 10 ans","La mesure de la calcémie","L'évaluation cardio-vasculaire"],"r":1,"e":"FRAX = outil OMS qui calcule le risque de fracture majeure ostéoporotique et de col fémoral à 10 ans, en intégrant ATCD, FdR et DMO (col).","s":13},{"q":"Concernant le rôle du KINÉSITHÉRAPEUTE dans la prise en charge de l'ostéoporose :","o":["Renforcement musculaire (en charge ++)","Travail proprioceptif et d'équilibre (prévention des chutes)","Éducation posturale","Mobilisations actives","Massage exclusivement"],"r":[0,1,2,3],"e":"Le kiné a un rôle clé : renforcement (en charge), proprioception/équilibre (chutes), éducation posturale, mobilisations, contre-indications (mouvements en flexion + rotation rachidienne, sauts à risque).","s":13},{"q":"L'ostéomalacie chez l'adulte se distingue de l'ostéoporose par :","o":["Une atteinte de la masse osseuse uniquement","Un trouble de la MINÉRALISATION (carence en vitamine D)","Une infection osseuse","Une cause uniquement génétique"],"r":1,"e":"Ostéomalacie = trouble de la MINÉRALISATION (matrice ostéoïde non minéralisée), souvent par carence en vit D. Ostéoporose = ↓ masse osseuse avec minéralisation normale. Symptômes différents : douleurs diffuses pour ostéomalacie.","s":13},{"q":"L'ostéopénie correspond à :","o":["Une densité osseuse normale","Une diminution modérée de la densité minérale osseuse (T-score entre -1 et -2,5)","Une fracture","Une infection osseuse"],"r":1,"e":"Ostéopénie : T-score entre -1 et -2,5 (perte modérée). Ostéoporose : T-score ≤ -2,5.","s":13},{"q":"L'ostéoporose se définit par un T-score :","o":["≥ -1","Entre -1 et -2,5","≤ -2,5","≥ 0"],"r":2,"e":"OMS : Ostéoporose = T-score ≤ -2,5. Ostéoporose sévère : T-score ≤ -2,5 + fracture.","s":13},{"q":"Les facteurs de risque de l'ostéoporose incluent :","o":["Femme post-ménopause","Âge avancé","Sédentarité","Carence Ca/vit D","Corticothérapie prolongée","Tabagisme/alcool","Indice de masse corporelle élevé"],"r":[0,1,2,3,4,5],"e":"Tous : ménopause (chute œstrogènes), âge, sédentarité, malnutrition, corticoïdes, tabac, alcool. Une charge mécanique élevée stimule l'ostéoformation : la maigreur est un facteur de risque, pas le surpoids.","s":13},{"q":"Le DEXA mesure :","o":["La pression artérielle","La densité minérale osseuse (DMO)","La masse musculaire seule","Les minéraux sanguins"],"r":1,"e":"DEXA (DXA) = absorptiométrie biphotonique à rayons X : examen de référence pour la DMO.","s":13},{"q":"Une fracture pathologique survient :","o":["Sur os sain après traumatisme important","Sur os fragilisé après traumatisme minime","Toujours après chute","Uniquement chez l'enfant"],"r":1,"e":"Fracture pathologique = sur os déjà fragilisé (ostéoporose, métastases) avec traumatisme minime.","s":13},{"q":"La fracture du col du fémur est typique de :","o":["L'enfant","La personne âgée ostéoporotique","Le sportif jeune","Le nouveau-né"],"r":1,"e":"Fracture col du fémur : très fréquente chez la personne âgée ostéoporotique après chute.","s":13},{"q":"Le traitement de l'ostéoporose inclut souvent :","o":["Antibiotiques","Bisphosphonates (alendronate, risédronate)","Bêta-bloquants","Anticoagulants"],"r":1,"e":"Bisphosphonates = inhibent les ostéoclastes → freinent la résorption osseuse.","s":13},{"q":"La consolidation d'une fracture passe par :","o":["Hématome","Cal mou (fibro-cartilagineux)","Cal dur (osseux)","Remodelage","Désintégration"],"r":[0,1,2,3],"e":"4 phases : hématome → cal mou (cartilage/fibres) → cal dur (os primitif) → remodelage (os mature).","s":13},{"q":"L'ostéomalacie chez l'adulte est due à :","o":["Carence en vitamine D","Excès de calcium","Cancer","Infection virale"],"r":0,"e":"Ostéomalacie = défaut de minéralisation par carence en vit D (équivalent du rachitisme chez l'enfant).","s":13},{"q":"Pour prévenir l'ostéoporose, on recommande :","o":["Sédentarité","Activité physique en charge + apport Ca/vit D + arrêt tabac","Régime hypercalorique","Aucune mesure"],"r":1,"e":"Prévention : exercice en charge (marche, musculation) + Ca 1000-1200mg/j + vit D + arrêt tabac/alcool.","s":13},{"q":"Quelle est la prévalence mondiale de l'ostéopénie selon la fiche ?","o":["40,4 %","19,7 %","5,6 %","14,4 %"],"r":0,"e":"19,7 % pour l'ostéoporose et 40,4 % pour l'ostéopénie.","s":13},{"q":"Quelle proportion de femmes est touchée après 50 ans ?","o":["3 sur 5","1 sur 5","1 sur 2","4 sur 5"],"r":0,"e":"La fiche indique 3 femmes sur 5 après 50 ans.","s":13},{"q":"Quelle part des cas portugais d'ostéoporose concerne les femmes ?","o":["80,4 %","50 %","19,6 %","95 %"],"r":0,"e":"80,4 % de femmes contre 19,6 % d'hommes, sur 681 000 individus en 2019.","s":13},{"q":"Quelle est la projection du nombre de fractures ostéoporotiques au Portugal en 2034 ?","o":["91 200, soit +28,9 %","70 700, stable","120 000, soit +70 %","50 000, en baisse"],"r":0,"e":"De 70 700 fractures en 2019 à 91 200 projetées en 2034.","s":13},{"q":"Quel est le risque de fracture de hanche chez une femme de plus de 50 ans ?","o":["14,4 %","5,6 %","19,7 %","40,4 %"],"r":0,"e":"La fiche donne 14,4 % de risque vie entière de fracture de hanche.","s":13},{"q":"Par quel mécanisme le tabac altère-t-il l'os ?","o":["Il réduit l'apport sanguin osseux, augmente les radicaux libres et altère l'ostéogenèse","Il inhibe directement les ostéoblastes par effet toxique du calcium","Il interfère avec l'absorption du calcium comme le café","Il augmente la PTH"],"r":0,"e":"L'alcool inhibe les ostéoblastes et réduit l'absorption du calcium ; le café interfère avec le métabolisme calcique.","s":13},{"q":"Pourquoi la chirurgie gastrique constitue-t-elle un facteur de risque ?","o":["Elle diminue le calcium et la vitamine D et augmente la PTH","Elle augmente directement l'activité des ostéoclastes","Elle réduit l'exposition aux contraintes mécaniques","Elle abaisse les œstrogènes"],"r":0,"e":"La malabsorption calcique et vitaminique entraîne une hyperparathyroïdie secondaire.","s":13},{"q":"Quelles causes endocriniennes secondaires d'ostéoporose la fiche cite-t-elle ?","o":["Diabète de type 1, hyperparathyroïdie, dysthyroïdies, maladie d'Addison, tumeurs hypophysaires, myélome multiple","Insuffisance hépatique et malabsorption","Corticostéroïdes et anticonvulsants","Immobilisation et ostéogenèse imparfaite"],"r":0,"e":"Les autres réponses appartiennent aux catégories gastro-intestinale/autres et médicamenteuse.","s":13},{"q":"Quel médicament la fiche signale-t-elle comme cause secondaire majeure d'ostéoporose ?","o":["Les corticostéroïdes","Le paracétamol","Les bêtabloquants","Les statines"],"r":0,"e":"Les glucocorticoïdes inhibent les ostéoblastes, réduisent la vitamine D et les hormones sexuelles, et activent les ostéoclastes.","s":13},{"q":"Quel antinéoplasique est cité comme facteur de risque en pré-ménopause ?","o":["Le tamoxifène","Le raloxifène","Le dénosumab","Le zolédronate"],"r":0,"e":"Le tamoxifène a un effet osseux défavorable avant la ménopause, contrairement au raloxifène qui est un traitement.","s":13},{"q":"Quelles cytokines augmentent dans l'ostéoporose post-ménopausique ?","o":["IL-1, IL-6 et TNF","IL-4 et IL-13","TGF-β et IL-10","IL-17 seule"],"r":0,"e":"La chute des œstrogènes lève le frein sur ces cytokines, qui stimulent RANK/RANKL et les ostéoclastes.","s":13},{"q":"Quel système de signalisation est surexprimé dans l'ostéoporose post-ménopausique ?","o":["Le système RANK/RANKL","Le système PI3K/AKT","Le système COX-1/COX-2","Le système MMP/TIMP"],"r":0,"e":"L'axe RANK/RANKL commande la différenciation et l'activité des ostéoclastes.","s":13},{"q":"Qu'est-ce qui caractérise l'ostéoporose sénile ?","o":["Une baisse de l'activité réplicative des cellules ostéoprogénitrices et de l'activité synthétique des ostéoblastes","Une hausse de l'activité des ostéoclastes par chute œstrogénique","Une carence isolée en vitamine D","Une hyperparathyroïdie primaire"],"r":0,"e":"La forme sénile est un déficit de formation, la forme post-ménopausique un excès de résorption.","s":13},{"q":"Quel risque supplémentaire les glucocorticoïdes font-ils courir à l'os, outre l'ostéoporose ?","o":["La nécrose avasculaire","L'ostéomalacie","La maladie de Paget","L'ostéomyélite"],"r":0,"e":"La fiche signale ce risque spécifique de l'ostéoporose cortico-induite.","s":13},{"q":"Quel rôle les vitamines K et B12 jouent-elles dans l'os ?","o":["Elles participent à la synthèse des protéines osseuses","Elles augmentent l'absorption intestinale du calcium","Elles durcissent la matrice extracellulaire","Elles inhibent les ostéoclastes"],"r":0,"e":"Leur déficit abaisse la densité osseuse ; l'absorption calcique dépend de la vitamine D.","s":13},{"q":"La POSTURE est définie comme :","o":["Une position figée prise par le corps","La position relative des différentes parties du corps les unes par rapport aux autres et à la gravité","Une réflexe inné permanent","Un trouble musculo-squelettique"],"r":1,"e":"Posture = position relative des segments corporels les uns par rapport aux autres ET à la gravité. Elle implique un équilibre tonique entre muscles agonistes et antagonistes.","s":14},{"q":"Concernant les COURBURES RACHIDIENNES, quelles affirmations sont vraies ?","o":["Cyphose dorsale = courbure primaire","Lordose lombaire = courbure secondaire","Lordose cervicale = courbure secondaire","Cyphose sacrée = courbure primaire","Toutes les courbures sont primaires"],"r":[0,1,2,3],"e":"Courbures primaires (présentes à la naissance, à concavité antérieure) : dorsale + sacrée. Secondaires (apparaissent avec la mise en charge, à concavité postérieure) : cervicale (port de tête) + lombaire (marche).","s":14},{"q":"À quel âge apparaît la lordose CERVICALE ?","o":["À la naissance","Quand l'enfant tient sa tête (~3 mois)","Quand l'enfant marche (~12 mois)","À l'adolescence"],"r":1,"e":"La lordose cervicale apparaît vers 3 mois quand le nourrisson commence à tenir sa tête. La lordose lombaire apparaît plus tard, lors de la station debout/marche.","s":14},{"q":"À quel âge apparaît la lordose LOMBAIRE ?","o":["À la naissance","Quand l'enfant tient sa tête (~3 mois)","Quand l'enfant s'assoit (~6-8 mois)","À l'adolescence"],"r":2,"e":"Selon le cours : lordose lombaire apparaît à 6-8 mois (lorsque l'enfant s'assoit). Elle se complète avec la marche (~12-18 mois). La lordose cervicale apparaît à ~3 mois (tenue de tête).","s":14},{"q":"La SCOLIOSE est :","o":["Une courbure normale du rachis","Une déviation TRIDIMENSIONNELLE du rachis (frontale + sagittale + rotation vertébrale)","Une simple inclinaison latérale réversible","Une fracture vertébrale"],"r":1,"e":"Scoliose = déformation 3D du rachis : déviation latérale (frontale) + modification de courbure sagittale + ROTATION vertébrale (gibbosité). Différent de l'attitude scoliotique (réversible, sans rotation).","s":14},{"q":"Quels signes différencient la SCOLIOSE STRUCTURELLE de l'attitude scoliotique ?","o":["Présence d'une rotation vertébrale (gibbosité au test d'Adams)","Réversibilité en position couchée","Persistance en flexion antérieure","Évolutivité possible","Toujours indolore"],"r":[0,2,3],"e":"Scoliose vraie : NON réversible, gibbosité au test d'Adams (flexion ant.), évolutive (surtout durant croissance). Attitude scoliotique : réversible, pas de rotation, sans gibbosité.","s":14},{"q":"Le test d'ADAMS consiste à :","o":["Toucher ses pieds en flexion latérale","Faire fléchir le patient vers l'avant pour rechercher une gibbosité","Mesurer la lordose lombaire","Vérifier l'équilibre debout"],"r":1,"e":"Test d'Adams : patient debout, flexion antérieure du tronc bras pendants. On observe par derrière → recherche d'une GIBBOSITÉ (saillie costale ou paravertébrale signant la rotation vertébrale).","s":14},{"q":"L'angle de COBB permet de :","o":["Mesurer la longueur des membres","Mesurer l'angle de la courbure scoliotique sur radiographie","Évaluer la force musculaire","Quantifier la lordose lombaire seulement"],"r":1,"e":"Angle de Cobb : mesure radiologique de la courbure scoliotique (frontale). Définit la sévérité : <10° pas de scoliose, 10-25° légère, 25-40° modérée, >40° sévère (chirurgie envisagée).","s":14},{"q":"Concernant la SCOLIOSE IDIOPATHIQUE de l'adolescent (SIA) :","o":["Cause inconnue","Plus fréquente chez les filles","Risque évolutif maximal pendant la croissance pubertaire","Toujours douloureuse","Disparaît à l'âge adulte"],"r":[0,1,2],"e":"SIA : étiologie inconnue (idiopathique), prédominance féminine (4-7:1 pour formes évolutives), pic évolutif lors du pic de croissance pubertaire. Souvent INDOLORE chez l'ado. Persiste à l'âge adulte.","s":14},{"q":"Une CYPHOSE pathologique correspond à :","o":["Une courbure cervicale exagérée","Une augmentation de la convexité postérieure du rachis dorsal (dos rond)","Une lordose lombaire excessive","Une scoliose sévère"],"r":1,"e":"Hypercyphose dorsale = accentuation pathologique de la courbure dorsale → 'dos rond'. Causes : posturale, congénitale (Scheuermann), ostéoporose (tassements), ankylosante.","s":14},{"q":"Une HYPERLORDOSE LOMBAIRE est :","o":["Une perte de la courbure lombaire","Une accentuation de la lordose lombaire","Une cyphose cervicale","Une scoliose"],"r":1,"e":"Hyperlordose lombaire = augmentation de la concavité postérieure lombaire (creux du dos accentué). Causes : faiblesse abdominale, antéversion bassin, grossesse, obésité abdominale.","s":14},{"q":"Concernant la maladie de SCHEUERMANN :","o":["Affecte les adolescents","Hypercyphose dorsale rigide","Aspect cunéiforme des vertèbres","Souvent indolore","Toujours d'origine traumatique"],"r":[0,1,2,3],"e":"Scheuermann (cyphose juvénile) : ostéochondrose vertébrale de l'adolescent, hypercyphose dorsale rigide, vertèbres cunéiformes (≥5° d'angulation sur 3 vertèbres consécutives), nodules de Schmorl. Souvent indolore.","s":14},{"q":"Le GENU VARUM correspond à :","o":["Genoux qui se touchent en X","Genoux écartés en O","Genoux normalement alignés","Une luxation patellaire"],"r":1,"e":"Genu varum = jambes en O (genoux écartés). Genu valgum = jambes en X (genoux rapprochés). Physiologique chez nourrisson (varum) puis valgum vers 3-4 ans, normal vers 7 ans.","s":14},{"q":"Le GENU VALGUM correspond à :","o":["Genoux en O","Genoux en X (rapprochés)","Hyperextension","Hyperflexion"],"r":1,"e":"Genu valgum = genoux qui se touchent (en X), pieds écartés. Physiologique entre 2 et 4 ans, mais pathologique si persistant ou asymétrique chez l'enfant plus grand.","s":14},{"q":"Parmi les facteurs influençant la POSTURE, on retrouve :","o":["Anatomiques (longueur des membres, structure osseuse)","Physiologiques (tonus musculaire, équilibre)","Psychologiques (confiance, dépression)","Pathologiques (douleur, déformations)","Habitudes professionnelles","Le groupe sanguin"],"r":[0,1,2,3,4],"e":"La posture est influencée par : facteurs anatomiques, physiologiques, psychologiques, pathologiques, habitudes (poste de travail, sports), âge, état émotionnel. Approche multifactorielle. Le groupe sanguin n'a aucune influence connue sur l'organisation posturale.","s":14},{"q":"La LIGNE DE GRAVITÉ idéale (vue latérale) passe par :","o":["L'oreille, l'épaule, le grand trochanter, le genou et l'avant de la malléole externe","Le nez, le sternum et le pubis","La colonne vertébrale uniquement","L'arrière du crâne et les talons"],"r":0,"e":"Ligne de gravité idéale (latérale) : conduit auditif externe → acromion → grand trochanter → légèrement en avant du genou → légèrement en avant de la malléole externe.","s":14},{"q":"Une HALLUX VALGUS correspond à :","o":["Une déviation latérale (en valgus) du gros orteil","Une griffe d'orteils","Une fasciite plantaire","Un pied creux"],"r":0,"e":"Hallux valgus ('oignon') : déviation latérale (vers le 2e orteil) de la phalange du gros orteil avec saillie médiale de la 1ère articulation métatarso-phalangienne. Plus fréquent chez la femme.","s":14},{"q":"Quelles sont des OSTÉOCHONDROSES juvéniles ?","o":["Maladie d'Osgood-Schlatter (tubérosité tibiale)","Maladie de Sever (calcanéum)","Maladie de Scheuermann (rachis)","Maladie de Legg-Calvé-Perthes (tête fémorale)","Polyarthrite rhumatoïde"],"r":[0,1,2,3],"e":"Ostéochondroses juvéniles : Osgood-Schlatter (tubérosité tibiale, ado sportif), Sever (calcanéum), Scheuermann (rachis), Legg-Calvé-Perthes (tête fémorale, garçon 4-8 ans), Köhler (os naviculaire). PR = adulte, auto-immune.","s":14},{"q":"La maladie d'OSGOOD-SCHLATTER touche :","o":["L'épaule du nageur","La tubérosité tibiale antérieure de l'adolescent sportif","Le rachis lombaire","La tête humérale"],"r":1,"e":"Osgood-Schlatter : ostéochondrose de l'apophyse tibiale antérieure (insertion du tendon rotulien), chez l'adolescent sportif (10-15 ans). Douleur antérieure du genou, aggravée à l'effort. Évolution favorable à la fin de la croissance.","s":14},{"q":"Concernant le PIED PLAT :","o":["Affaissement de la voûte longitudinale interne","Physiologique chez le jeune enfant (<3-4 ans)","Souvent associé à un valgus calcanéen","Toujours pathologique","Peut être souple ou rigide"],"r":[0,1,2,4],"e":"Pied plat = affaissement de l'arche médiale, valgus calcanéen. Physiologique chez le jeune enfant (la voûte se forme vers 5-6 ans). Pathologique si persistant, douloureux ou rigide.","s":14},{"q":"Une POLYDACTYLIE est :","o":["Une absence de doigt(s)","La présence d'un nombre supérieur de doigts/orteils (>5)","Une fusion des doigts","Une raideur des doigts"],"r":1,"e":"Polydactylie = présence de doigts/orteils SURNUMÉRAIRES. Syndactylie = fusion entre 2 doigts/orteils. Souvent congénitales, parfois isolées ou syndromiques.","s":14},{"q":"Le port d'un CORSET dans la scoliose vise à :","o":["Corriger définitivement la courbure","Empêcher l'aggravation pendant la croissance","Renforcer les muscles du tronc","Soulager la douleur uniquement"],"r":1,"e":"Corset (Cheneau, Boston…) : indication pour scoliose 25-40° en croissance. Vise à PRÉVENIR l'aggravation (pas à corriger la courbure existante). Port quotidien long (16-23h/j) jusqu'à fin de croissance.","s":14},{"q":"Concernant le rôle du KINÉSITHÉRAPEUTE dans la scoliose :","o":["Renforcement musculaire global du tronc","Auto-allongements axiaux","Travail postural et proprioceptif","Méthodes spécifiques (Schroth, Méziere)","Réduction de la courbure structurelle à long terme"],"r":[0,1,2,3],"e":"Rôle kiné : renforcement, auto-grandissement, postural, méthodes spécifiques (Schroth, RPG), respiration. Le kiné NE RÉDUIT PAS une scoliose structurelle ; il accompagne, prévient et complète corset/chirurgie.","s":14},{"q":"Une scoliose ≥ 40-45° d'angle de Cobb à la fin de la croissance évoque :","o":["Surveillance simple","Indication d'un corset","Indication chirurgicale (arthrodèse)","Pas de prise en charge"],"r":2,"e":"Scoliose >40-45° : indication chirurgicale (arthrodèse rachidienne avec instrumentation). En dessous : surveillance ou corset selon angle et stade de croissance.","s":14},{"q":"Une scoliose se définit dès une déviation latérale frontale de :","o":["≥ 5°","≥ 10° (angle de Cobb)","≥ 25°","≥ 40°"],"r":1,"e":"Définition de la scoliose : angle de Cobb ≥ 10°. En dessous : attitude scoliotique simple. La sévérité est ensuite graduée par paliers (10-25 légère, 25-40 modérée, >40 sévère).","s":14},{"q":"La cyphose pathologique correspond à :","o":["Courbure latérale du rachis","Exagération de la courbure dorsale postérieure","Exagération de la lordose lombaire","Inversion de courbure"],"r":1,"e":"Cyphose = courbure dorsale (thoracique) postérieure exagérée. Hyperlordose = lombaire. Scoliose = latérale.","s":14},{"q":"Le genu recurvatum correspond à :","o":["Une déviation du genou en dedans dans le plan frontal","Une déviation du genou en dehors dans le plan frontal","Une hyperextension du genou dans le plan sagittal","Une rotation permanente du tibia"],"r":2,"e":"Le recurvatum se lit dans le plan sagittal : le genou dépasse la position neutre en extension. Le varum (jambes arquées) et le valgum (genoux en X) sont, eux, des déviations frontales. Le recurvatum accompagne souvent une hyperlaxité ou un déficit du quadriceps.","s":14},{"q":"L'hyperlordose lombaire est associée à :","o":["Une déformation cervicale","Une accentuation de la courbure lombaire","Une cyphose","Un effondrement vertébral"],"r":1,"e":"Hyperlordose = courbure lombaire concave postérieure exagérée.","s":14},{"q":"La cyphose de la personne âgée est typiquement liée à :","o":["Une croissance excessive","Une scoliose congénitale","Des fractures vertébrales par compression (ostéoporose)","Une posture sportive"],"r":2,"e":"Cyphose dorsale du sujet âgé : tassements vertébraux ostéoporotiques (cunéiformisation).","s":14},{"q":"La maladie de Scheuermann correspond à :","o":["Une scoliose adulte","Une cyphose juvénile par dystrophie de croissance","Une lordose congénitale","Une infection"],"r":1,"e":"Scheuermann = cyphose juvénile (10-16 ans), cunéiformisation antérieure de ≥3 vertèbres adjacentes.","s":14},{"q":"La scoliose idiopathique de l'adolescent :","o":["Est rare","Est la forme la plus fréquente, principalement chez la fille","Survient à la naissance","Est toujours douloureuse"],"r":1,"e":"Scoliose idiopathique = forme la plus fréquente, prédominance féminine (4-7:1), pic 10-15 ans.","s":14},{"q":"L'angle de Cobb mesure :","o":["L'amplitude articulaire","La sévérité de la déformation scoliotique","La force musculaire","La vitesse marche"],"r":1,"e":"Angle de Cobb = mesure de l'angle entre les vertèbres terminales sur radio, sévérité scoliose.","s":14},{"q":"Une scoliose sévère peut entraîner :","o":["Une amélioration spontanée","Insuffisance respiratoire (restrictive)","Une augmentation de la taille","Une accélération motrice"],"r":1,"e":"Scoliose sévère (>90°) → restriction thoracique → insuffisance respiratoire restrictive.","s":14},{"q":"Le traitement par corset est indiqué :","o":["Pour toutes les scolioses","Pour scolioses évolutives 25-40° en croissance","Uniquement chez l'adulte","Jamais"],"r":1,"e":"Corset : indiqué pour scolioses 25-40° pendant la croissance pour ralentir l'évolution.","s":14},{"q":"La chirurgie est envisagée pour scoliose :","o":["≤ 10°","≤ 20°","≥ 45-50° évolutive","Jamais"],"r":2,"e":"Chirurgie (arthrodèse) : scoliose ≥ 45-50° évolutive ou très douloureuse.","s":14},{"q":"Combien d'os le squelette perd-il entre la naissance et l'âge adulte ?","o":["94, par fusion osseuse","50","206","300"],"r":0,"e":"Environ 300 os à la naissance contre 206 chez l'adulte, soit 94 de moins par fusion.","s":14},{"q":"Quelles structures relient un os à un autre ?","o":["Les ligaments","Les tendons","Les fascias","Les aponévroses"],"r":0,"e":"Les ligaments relient os à os, les tendons muscle à os.","s":14},{"q":"Pourquoi les malformations de l'appareil locomoteur du jeune enfant sont-elles fréquentes ?","o":["Parce que des ligaments souples subissent des forces de torsion","Parce que les os sont déjà rigides","Parce que les muscles sont trop puissants","Parce que le cartilage de croissance est absent"],"r":0,"e":"La laxité ligamentaire du jeune, combinée aux forces de rotation intra-utérines ou familiales, explique ces anomalies.","s":14},{"q":"Qu'est-ce que la macrodactylie ?","o":["L'hypertrophie d'un ou plusieurs doigts ou orteils","La présence de doigts surnuméraires","La fusion de deux doigts adjacents","L'absence d'un doigt"],"r":0,"e":"La polydactylie ajoute des doigts, la syndactylie les fusionne.","s":14},{"q":"Qu'est-ce que la syndactylie ?","o":["La fusion partielle ou complète de deux doigts ou orteils adjacents","Un doigt surnuméraire","Un doigt hypertrophié","Une déviation latérale du gros orteil"],"r":0,"e":"La syndactylie est une fusion ; la polydactylie et la macrodactylie sont d'autres anomalies digitales.","s":14},{"q":"Quel est l'autre nom de l'ostéogenèse imparfaite ?","o":["La maladie d'Ekman-Lobstein, ou maladie des os de verre","La maladie de Legg-Calvé-Perthes","La maladie d'Osgood-Schlatter","La maladie de Scheuermann"],"r":0,"e":"C'est une maladie héréditaire du collagène responsable d'une fragilité osseuse majeure.","s":14},{"q":"Quel est le mécanisme de la maladie de Legg-Calvé-Perthes ?","o":["Une nécrose de la tête fémorale","Une surcharge du tendon rotulien","Une dystrophie vertébrale de croissance","Une luxation congénitale"],"r":0,"e":"Perthes touche la hanche par nécrose, Osgood-Schlatter le genou par surcharge du tendon rotulien.","s":14},{"q":"Comment la fiche définit-elle une posture correcte ?","o":["Une position exerçant le moins de pression possible sur les articulations avec un minimum d'activité musculaire","Une position esthétiquement droite","Une position parfaitement symétrique","Une position sans aucun mouvement"],"r":0,"e":"La posture correcte est une posture économe, pas une posture esthétique.","s":14},{"q":"Quelles situations articulaires rendent la posture pathogène ?","o":["Des articulations raides, hyper- ou hypomobiles, avec des muscles faibles, étirés ou raccourcis","Des articulations parfaitement mobiles","Des muscles équilibrés","Une bonne proprioception"],"r":0,"e":"Maintenir la posture coûte alors davantage, générant un stress répété source de pathologie.","s":14},{"q":"Quelles sont les courbures primaires du rachis ?","o":["La cyphose thoracique et la concavité sacro-coccygienne","La lordose cervicale et la lordose lombaire","La lordose cervicale et la cyphose thoracique","Les courbures frontales"],"r":0,"e":"Les courbures primaires, concaves en avant, sont présentes dès la naissance ; les secondaires sont des lordoses.","s":14},{"q":"Dans quel sens apparaissent les courbures secondaires ?","o":["Dans le sens céphalo-caudal : d'abord cervicale, puis lombaire","Dans le sens caudo-céphalique","Simultanément","De façon aléatoire"],"r":0,"e":"Lordose cervicale vers 3 mois, lombaire vers 6-8 mois, en suivant le développement moteur.","s":14},{"q":"À quel acquis moteur correspond l'apparition de la lordose cervicale ?","o":["La tenue de tête en position ventrale","La station assise","La marche","Le retournement"],"r":0,"e":"Le nourrisson soutient sa tête vers 3 mois, ce qui crée la lordose cervicale.","s":14},{"q":"Par quel repère crânien la ligne de gravité idéale passe-t-elle de profil ?","o":["Le conduit auditif externe","Le vertex","L'angle de la mâchoire","La protubérance occipitale externe"],"r":0,"e":"La ligne passe en arrière de la suture coronale, par le conduit auditif externe puis l'odontoïde de C2.","s":14},{"q":"Où passe la ligne de gravité par rapport au genou ?","o":["Légèrement en avant de l'axe du genou","Nettement en arrière du genou","Exactement sur l'axe articulaire","Au niveau du creux poplité"],"r":0,"e":"Elle passe légèrement en avant de l'axe (base de rotule, tête du péroné), puis en avant de la malléole latérale.","s":14},{"q":"Quelle règle s'applique au rachis dans le plan frontal ?","o":["Il n'existe normalement aucune courbure : toute déviation latérale est pathologique","Une légère courbure droite est normale","Une courbure compensatrice est physiologique","Les courbures frontales apparaissent après 3 mois"],"r":0,"e":"C'est ce qui fait de la scoliose une déviation pathologique par définition.","s":14},{"q":"L'arthrose (osteoarthritis) est :","o":["Une maladie auto-immune systémique","Une maladie dégénérative et inflammatoire de l'articulation, atteignant principalement le cartilage hyalin","Une infection","Un cancer osseux"],"r":1,"e":"Arthrose = maladie articulaire dégénérative caractérisée par la dégradation progressive du cartilage hyalin, avec atteinte de l'os sous-chondral, de la synoviale et des structures péri-articulaires. Composante inflammatoire modérée.","s":15},{"q":"Le cartilage HYALIN articulaire est constitué essentiellement de :","o":["Chondrocytes + matrice (collagène II + protéoglycanes)","Ostéoblastes + os","Fibres élastiques","Cellules sanguines"],"r":0,"e":"Cartilage hyalin : chondrocytes (peu nombreux) + matrice extracellulaire riche en collagène de type II et protéoglycanes (agrécane = aggregat avec acide hyaluronique). NON vascularisé, NON innervé.","s":15},{"q":"Le cartilage articulaire est :","o":["Vascularisé","Non vascularisé","Innervé","Non innervé","Nourri par diffusion à partir du liquide synovial"],"r":[1,3,4],"e":"Le cartilage hyalin est NON vascularisé et NON innervé. Sa nutrition se fait par diffusion à partir du liquide synovial (mouvement = pompe à diffusion). C'est pourquoi sa cicatrisation est très limitée.","s":15},{"q":"Quels sont les principaux FACTEURS DE RISQUE de l'arthrose ?","o":["Âge avancé","Surpoids / obésité","Antécédents traumatiques articulaires","Génétique","Activité physique régulière modérée"],"r":[0,1,2,3],"e":"FdR : âge, sexe féminin, obésité (genou ++), traumatismes (entorse, fracture articulaire), génétique, anomalies axiales (varus, valgus), surcharge professionnelle/sportive intensive. L'activité MODÉRÉE est protectrice.","s":15},{"q":"Le critère DOULEUR dans l'arthrose est typiquement :","o":["Inflammatoire (nuit, raideur matinale > 1h)","Mécanique (déclenchée par l'activité, calmée par le repos)","Permanente sans relation avec l'activité","Spontanée et fébrile"],"r":1,"e":"Douleur arthrosique = MÉCANIQUE : ↑ à la mise en charge/activité, ↓ au repos, raideur matinale courte (<15-30 min, dérouillage). PR = douleur inflammatoire (nuit, raideur matinale prolongée).","s":15},{"q":"Quels sont les signes RADIOLOGIQUES de l'arthrose (4 signes classiques) ?","o":["Pincement articulaire (perte de cartilage)","Ostéophytes (becs)","Sclérose sous-chondrale (condensation osseuse)","Géodes sous-chondrales","Érosions marginales"],"r":[0,1,2,3],"e":"4 signes radiologiques de l'arthrose ('POSG') : Pincement, Ostéophytes, Sclérose sous-chondrale, Géodes (kystes). Les ÉROSIONS sont caractéristiques des polyarthrites inflammatoires (PR).","s":15},{"q":"L'arthrose la plus fréquente du membre inférieur est :","o":["Coxarthrose (hanche)","Gonarthrose (genou)","Arthrose tibio-tarsienne","Arthrose métatarso-phalangienne"],"r":1,"e":"La GONARTHROSE (genou) est la localisation la plus fréquente d'arthrose, devant la coxarthrose (hanche). Souvent fémoro-tibiale interne (varus) ou fémoro-patellaire.","s":15},{"q":"L'arthrose digitale NODALE comprend les nodules de :","o":["Heberden (IPP)","Bouchard (IPD)","Heberden (IPD) et Bouchard (IPP)","Heberden (MCP) uniquement"],"r":2,"e":"Nodules d'Heberden = arthrose des IPD (inter-phalangiennes distales). Nodules de Bouchard = IPP (inter-phalangiennes proximales). Pas d'atteinte des MCP en arthrose nodale (sinon évoquer PR).","s":15},{"q":"Concernant le tableau CLINIQUE de l'arthrose :","o":["Douleur mécanique","Raideur matinale courte (< 30 min)","Limitation progressive des mouvements","Crépitements articulaires possibles","Tuméfaction inflammatoire intense, rougeur, chaleur"],"r":[0,1,2,3],"e":"Clinique arthrosique : douleur mécanique, raideur matinale brève, ↓ amplitude, crépitements/craquements, parfois épanchement articulaire. Inflammation locale modérée. Rougeur/chaleur intenses = arthrite (à distinguer).","s":15},{"q":"La PRINCIPALE prise en charge de l'arthrose est :","o":["La chirurgie immédiate","La rééducation, exercice physique adapté + perte de poids + antalgiques","Les antibiotiques","Les corticoïdes IV au long cours"],"r":1,"e":"Prise en charge de 1ère intention : non médicamenteuse (exercice adapté +++, perte de poids, kiné, éducation), puis antalgiques (paracétamol, AINS, infiltrations), enfin chirurgie (PTH/PTG) en dernier recours.","s":15},{"q":"Concernant le RÔLE DU KINÉSITHÉRAPEUTE dans l'arthrose, quelles propositions sont correctes ?","o":["Renforcement musculaire (stabilisation articulaire)","Mobilisations articulaires douces","Étirements et amélioration de l'amplitude","Éducation du patient (économie articulaire)","Remplacer le cartilage perdu"],"r":[0,1,2,3],"e":"Le kiné : renforce (stabilité), mobilise, étire, conseille (économie articulaire, charge, équilibre poids), travaille la proprioception, l'équilibre. Il NE PEUT PAS remplacer le cartilage (régénération limitée).","s":15},{"q":"Le cartilage articulaire a une capacité de RÉGÉNÉRATION :","o":["Très bonne (totale)","Bonne","Très limitée (peu de cellules, pas de vascularisation)","Inexistante absolument"],"r":2,"e":"Le cartilage régénère TRÈS PEU : pauvre en cellules (chondrocytes), pas de vascularisation. C'est pourquoi les lésions cartilagineuses cicatrisent mal et l'arthrose est chronique et progressive.","s":15},{"q":"Les TRAITEMENTS médicamenteux de l'arthrose comprennent :","o":["Paracétamol","AINS (par voie générale ou topique)","Infiltrations de corticoïdes","Acide hyaluronique intra-articulaire","Antibiotiques"],"r":[0,1,2,3],"e":"Médicaments : paracétamol (1ère intention), AINS, infiltrations (corticoïdes ou acide hyaluronique = visco-supplémentation). Les antibiotiques n'ont pas leur place (sauf arthrite septique surajoutée).","s":15},{"q":"L'épanchement articulaire dans le genou arthrosique est :","o":["Toujours absent","Possible, souvent modéré (ponction → liquide mécanique)","Massif et purulent","Toujours hémorragique"],"r":1,"e":"Épanchement arthrosique = possible, modéré, liquide mécanique (peu cellulaire, jaune citrin). Si très inflammatoire ou purulent → suspecter arthrite septique. Hémarthrose → traumatisme ou trouble de coagulation.","s":15},{"q":"Concernant les MYTHES sur l'arthrose, quels sont des FAUSSES idées ?","o":["L'arthrose touche uniquement les personnes âgées","Le repos absolu est le meilleur traitement","Faire de l'exercice aggrave l'arthrose","La perte de poids améliore les symptômes du genou","La douleur est toujours proportionnelle aux lésions radiologiques"],"r":[0,1,2,4],"e":"FAUX : L'arthrose peut survenir avant 65 ans (post-traumatique). Le repos AGGRAVE (atrophie). L'exercice ADAPTÉ est BÉNÉFIQUE. Perte de poids = vrai bénéfice. La douleur n'est PAS proportionnelle aux images (dissociation radio-clinique fréquente).","s":15},{"q":"Le traitement chirurgical de référence dans l'arthrose AVANCÉE de la hanche/genou est :","o":["L'arthroscopie de propreté","La prothèse totale articulaire (PTH/PTG)","La greffe cartilagineuse","La désarticulation"],"r":1,"e":"Arthrose terminale invalidante (échec du traitement médical) → PTH (prothèse totale de hanche) ou PTG (prothèse totale de genou). Arthroscopie = peu d'intérêt prouvé. Greffe cartilagineuse réservée à des indications très spécifiques.","s":15},{"q":"L'OBÉSITÉ est un facteur de risque PARTICULIÈREMENT important pour :","o":["L'arthrose des doigts","La gonarthrose (genou)","L'arthrose temporo-mandibulaire","L'arthrose lombaire isolée"],"r":1,"e":"L'obésité augmente massivement le risque de gonarthrose (charge mécanique sur le genou). Effet majeur aussi par les adipokines (rôle inflammatoire). La perte de poids améliore significativement la douleur.","s":15},{"q":"L'ARTHROSE PRIMITIVE est :","o":["Toujours secondaire à un traumatisme","Sans cause identifiable, liée à l'âge et facteurs intrinsèques","Toujours d'origine génétique pure","D'origine infectieuse"],"r":1,"e":"Arthrose primitive (idiopathique) = pas de cause identifiable, multifactorielle (âge, génétique, hormonale). Arthrose secondaire = liée à une cause précise (traumatisme, malformation, surcharge pondérale, anomalie axiale).","s":15},{"q":"Quels sont des EFFETS du vieillissement sur le cartilage ?","o":["↓ teneur en eau","↓ protéoglycanes","↑ rigidité","Modification du collagène","↑ prolifération chondrocytaire"],"r":[0,1,2,3],"e":"Vieillissement cartilage : ↓ eau, ↓ protéoglycanes, fibres collagène modifiées, ↑ rigidité, ↓ capacité à supporter les charges. Les chondrocytes deviennent moins actifs (sénescence), ne prolifèrent pas davantage.","s":15},{"q":"Un OSTÉOPHYTE est :","o":["Un kyste osseux","Un bec osseux marginal résultant de la prolifération osseuse","Une zone de nécrose osseuse","Une calcification ligamentaire"],"r":1,"e":"Ostéophyte (bec, exostose) = production osseuse en périphérie de l'articulation arthrosique. Tentative d'adaptation à la perte de cartilage. Visible à la radiographie, peut limiter les amplitudes.","s":15},{"q":"L'ARTHROSE FÉMORO-PATELLAIRE provoque typiquement :","o":["Une douleur lors de la marche en terrain plat","Une douleur lors de la montée/descente des escaliers et station assise prolongée (signe du cinéma)","Une douleur uniquement nocturne","Pas de douleur"],"r":1,"e":"Arthrose fémoro-patellaire : douleur antérieure du genou, ↑ aux escaliers (descente +++), accroupissement, station assise prolongée (signe du cinéma/Soulier). Crépitements rotuliens fréquents.","s":15},{"q":"Concernant les CRITÈRES DIAGNOSTIQUES de l'arthrose du genou (ACR), on retrouve :","o":["Douleur du genou","Âge > 50 ans","Raideur matinale < 30 min","Crépitements","Œdème malléolaire"],"r":[0,1,2,3],"e":"Critères ACR gonarthrose : douleur + ≥3 critères parmi (âge >50 ans, raideur matinale <30 min, crépitements, sensibilité osseuse, hypertrophie osseuse, pas de chaleur palpable). Œdème malléolaire = autre cause.","s":15},{"q":"Une INFILTRATION de corticoïdes intra-articulaire dans l'arthrose :","o":["Doit être faite tous les mois","Peut soulager les poussées douloureuses inflammatoires (effet de quelques semaines)","Régénère le cartilage","Est toxique systémiquement à dose locale"],"r":1,"e":"Infiltration de corticoïde : effet anti-inflammatoire local lors d'une poussée. Effet temporaire (semaines à mois), à ne pas répéter trop souvent (max 3-4/an). Pas d'effet sur le cartilage. Effet systémique faible à dose locale.","s":15},{"q":"L'acide HYALURONIQUE intra-articulaire vise à :","o":["Supprimer définitivement l'arthrose","Améliorer la lubrification et amortir (visco-supplémentation)","Régénérer l'os","Détruire les ostéophytes"],"r":1,"e":"Visco-supplémentation par acide hyaluronique : améliore la viscoélasticité du liquide synovial, lubrifie, amortit. Effet symptomatique (semaines à mois). Pas de régénération du cartilage.","s":15},{"q":"Concernant la PHYSIOPATHOLOGIE de l'arthrose, quelles affirmations sont vraies ?","o":["Déséquilibre entre dégradation et synthèse de la matrice cartilagineuse","Activation des chondrocytes (libération de cytokines, métalloprotéases)","Atteinte SECONDAIRE de l'os sous-chondral et de la synoviale","Atteinte PRIMITIVE de l'os sous-chondral","Inflammation purement systémique"],"r":[0,1,2],"e":"Arthrose : déséquilibre dégradation (MMP, ADAMTS) > synthèse cartilagineuse, chondrocytes activés (IL-1, TNF), atteinte secondaire de l'os sous-chondral (sclérose, géodes) et de la synoviale (synovite modérée). Atteinte cartilagineuse primaire.","s":15},{"q":"La polyarthrite rhumatoïde (PR) est :","o":["Une maladie dégénérative","Une maladie auto-immune systémique chronique avec atteinte articulaire","Une infection","Un cancer"],"r":1,"e":"PR = maladie auto-immune chronique, synovite proliférative, destruction articulaire progressive.","s":15},{"q":"Les caractéristiques cliniques de la PR incluent :","o":["Atteinte symétrique","Petites articulations (mains, pieds)","Raideur matinale > 30 min","Atteinte asymétrique grosses articulations seules","Déformations en boutonnière, col de cygne"],"r":[0,1,2,4],"e":"PR : symétrique, mains/pieds, raideur matinale prolongée, déformations caractéristiques. L'asymétrie grosses articulations = arthrose ou spondyloarthrites.","s":15},{"q":"Les anticorps caractéristiques de la PR sont :","o":["Facteur rhumatoïde (FR)","Anti-CCP (anti-peptides citrullinés)","Anti-DNA","ANCA","Anti-RNP"],"r":[0,1],"e":"PR : FR (peu spécifique) et anti-CCP (très spécifique). Anti-DNA = lupus.","s":15},{"q":"Le lupus érythémateux systémique (LED) :","o":["Atteint un seul organe","Maladie auto-immune systémique multi-organes","Infection bactérienne","Cancer"],"r":1,"e":"LED = maladie auto-immune multisystémique : peau, articulations, rein, SNC, séreuses, cellules sanguines.","s":15},{"q":"Le rash en aile de papillon (vespertilio) est typique de :","o":["La PR","Le lupus","L'arthrose","La spondylarthrite"],"r":1,"e":"Érythème en aile de papillon (visage, joues, nez) = signe cutané typique du lupus.","s":15},{"q":"La spondylarthrite ankylosante :","o":["Atteint surtout les femmes âgées","Atteint surtout les hommes jeunes, rachis et sacro-iliaques","Touche les petites articulations","Aucun marqueur génétique"],"r":1,"e":"SPA : homme jeune, atteinte axiale (sacro-iliite + rachis), HLA-B27 +, raideur inflammatoire.","s":15},{"q":"L'antigène HLA-B27 est associé à :","o":["La PR","Les spondyloarthrites","L'arthrose","La goutte"],"r":1,"e":"HLA-B27 : association forte avec spondyloarthrites (SPA, Reiter, psoriasis arthropathique, MICI).","s":15},{"q":"La goutte est causée par :","o":["Dépôts de cristaux d'urate de sodium","Dépôts de Ca","Auto-anticorps","Infection bactérienne"],"r":0,"e":"Goutte = dépôt de cristaux d'urate monosodique (UMS) dans les articulations, hyperuricémie.","s":15},{"q":"L'articulation typiquement touchée dans la crise aiguë de goutte est :","o":["Le coude","La 1ère articulation métatarso-phalangienne (gros orteil)","La hanche","Le poignet"],"r":1,"e":"Crise de goutte : podagre = arthrite aiguë de la 1ère MTP du gros orteil, ultra-douloureuse, rouge.","s":15},{"q":"Le traitement de fond de la PR repose sur :","o":["Antibiotiques","DMARDs (méthotrexate) ± biothérapies (anti-TNF)","Chirurgie d'emblée","Aucun"],"r":1,"e":"PR : DMARDs synthétiques (MTX en 1ère ligne) ± biothérapies (anti-TNF, anti-IL-6, etc.).","s":15},{"q":"Combien de maladies différentes le terme « rhumatisme » recouvre-t-il ?","o":["Plus de 200","Environ 20","Environ 50","Environ 1 000"],"r":0,"e":"La fiche indique plus de 200 maladies, l'arthrose étant la plus fréquente.","s":15},{"q":"Quelles sont les six maladies rhumatismales les plus courantes citées ?","o":["Arthrose, polyarthrite rhumatoïde, lupus, fibromyalgie, goutte et spondylarthrite","Arthrose, ostéoporose, ostéomalacie, Paget, ostéomyélite et arthrite septique","Arthrose, tendinite, bursite, capsulite, entorse et luxation","Arthrose, scoliose, cyphose, lordose, genu varum et genu valgum"],"r":0,"e":"La fiche liste ces six entités comme les plus courantes du groupe rhumatismal.","s":15},{"q":"Combien de personnes l'arthrose touche-t-elle dans le monde ?","o":["Environ 520 millions","Environ 100 millions","Environ 1 milliard","Environ 50 millions"],"r":0,"e":"La fiche donne 520 millions de personnes, avec 60 % de gonarthroses.","s":15},{"q":"Quelle proportion des cas d'arthrose concerne le genou ?","o":["60 %","30 %","90 %","11 %"],"r":0,"e":"La gonarthrose représente 60 % des cas d'arthrose.","s":15},{"q":"De combien le nombre de cas d'arthrose a-t-il augmenté entre 1990 et 2019 ?","o":["+48 %","+10 %","+100 %","Il a diminué"],"r":0,"e":"La fiche indique une progression de 48 % sur cette période.","s":15},{"q":"À quelle place l'arthrose se situe-t-elle parmi les causes mondiales d'incapacité ?","o":["11e","1re","25e","50e"],"r":0,"e":"Sur une étude portant sur 291 conditions, l'arthrose occupe le 11e rang.","s":15},{"q":"Combien d'années vécues avec un handicap l'arthrose a-t-elle représenté en 2017 ?","o":["9,6 millions","520 millions","1 million","100 000"],"r":0,"e":"La fiche cite 9,6 millions d'années vécues avec handicap.","s":15},{"q":"Quels sont les trois grands facteurs de risque d'arthrose retenus par la fiche ?","o":["Surpoids/obésité, antécédents de lésion ou chirurgie articulaire, et génétique","Tabac, alcool et café","Carence en vitamine D, sédentarité et âge","Infection, inflammation et auto-immunité"],"r":0,"e":"La cause exacte reste inconnue, mais ces trois facteurs sont identifiés.","s":15},{"q":"Quel type de collagène domine dans le cartilage hyalin ?","o":["Le type II, à 95 %","Le type I","Le type III","Le type IV"],"r":0,"e":"Le collagène de type II représente 95 % des fibres du cartilage articulaire.","s":15},{"q":"Quels composants forment la matrice du cartilage hyalin, outre le collagène ?","o":["Des polysaccharides (glycosaminoglycanes), des protéines et beaucoup d'eau","Des sels d'hydroxyapatite","Des fibres élastiques et de la réticuline","Des lipides et du glycogène"],"r":0,"e":"L'eau est un composant principal ; l'hydroxyapatite appartient à l'os.","s":15},{"q":"Quelle est la première étape du mécanisme lésionnel de l'arthrose ?","o":["Une lésion mécanique avec surcharge cartilagineuse, microfractures et remodelage de l'os sous-chondral","La dérégulation enzymatique","L'intervention des médiateurs inflammatoires","La mort des chondrocytes"],"r":0,"e":"La fiche décrit une séquence en quatre temps commençant par la surcharge mécanique.","s":15},{"q":"Quelle est l'étape finale du mécanisme lésionnel de l'arthrose ?","o":["Une dérégulation enzymatique détruisant les fibres de collagène et altérant la matrice","La surcharge mécanique initiale","Les microfractures de l'os sous-chondral","La mort des chondrocytes"],"r":0,"e":"La destruction enzymatique du collagène clôture la cascade.","s":15},{"q":"Quel âge figure parmi les critères de diagnostic clinique de l'arthrose ?","o":["45 ans ou plus","50 ans ou plus","65 ans ou plus","30 ans ou plus"],"r":0,"e":"45 ans, avec douleur liée à l'activité et raideur matinale absente ou inférieure à 30 minutes ; un diagnostic reste possible plus jeune après traumatisme.","s":15},{"q":"Quelle durée maximale de raideur matinale est compatible avec le diagnostic d'arthrose ?","o":["Moins de 30 minutes","Moins de 2 heures","Moins de 5 minutes","La raideur matinale exclut l'arthrose"],"r":0,"e":"Une raideur matinale prolongée oriente plutôt vers un rhumatisme inflammatoire.","s":15},{"q":"Que traduit une sclérose sous-chondrale sur une radiographie ?","o":["Une condensation de l'os sous-chondral","Une prolifération osseuse marginale","Une réduction de l'espace articulaire","Une géode osseuse"],"r":0,"e":"Les quatre signes radiologiques sont le pincement, les ostéophytes, la sclérose et les kystes sous-chondraux.","s":15},{"q":"La RÉGÉNÉRATION tissulaire correspond à :","o":["Le remplacement par un tissu fibreux cicatriciel","Le remplacement à l'identique du tissu lésé","Une mort cellulaire","Une fibrose excessive"],"r":1,"e":"Régénération = remplacement à l'identique du tissu lésé (restitution ad integrum). Possible pour les tissus à fort potentiel prolifératif (labiles, stables). La cicatrisation = remplacement par tissu fibreux.","s":16},{"q":"La CICATRISATION tissulaire correspond à :","o":["Le remplacement à l'identique","Le remplacement du tissu détruit par un tissu conjonctif fibreux (cicatrice)","Une infection chronique","Un cancer"],"r":1,"e":"Cicatrisation = remplacement par tissu conjonctif fibreux (collagène) lorsque la régénération est insuffisante ou impossible. Survient quand l'agression est sévère ou que le tissu est à faible potentiel régénératif.","s":16},{"q":"Concernant les CELLULES LABILES :","o":["Se renouvellent en permanence","Exemples : épithéliums, moelle hématopoïétique","Capacité régénérative très bonne","Exemples : neurones, cardiomyocytes","Cellules en G0 quiescentes"],"r":[0,1,2],"e":"Cellules labiles : renouvellement permanent (cycle continu) → épiderme, épithélium digestif, moelle, gamètes. Excellente régénération. Les neurones/cardiomyocytes = cellules permanentes (post-mitotiques).","s":16},{"q":"Concernant les CELLULES STABLES :","o":["Quiescentes en G0","Capables de se diviser en cas de stimulation","Foie, rein, cellules endothéliales","Cardiomyocytes","Régénération possible si stimulus"],"r":[0,1,2,4],"e":"Cellules stables : quiescentes (G0), prolifèrent si stimulus (lésion). Foie, rein, glandes endocrines, endothélium, fibroblastes. Le foie a une remarquable capacité de régénération. Cardiomyocytes = permanents.","s":16},{"q":"Les CELLULES PERMANENTES :","o":["Se renouvellent en permanence","Ne se divisent plus chez l'adulte (post-mitotiques) : neurones, cardiomyocytes","Sont identiques aux cellules labiles","Régénèrent facilement"],"r":1,"e":"Cellules permanentes : post-mitotiques, ne se divisent plus chez l'adulte. Neurones, cardiomyocytes, myocytes squelettiques. Lésion → cicatrisation par tissu fibreux (gliose pour SNC, cicatrice fibreuse pour le cœur).","s":16},{"q":"Quelles sont les ÉTAPES classiques de la cicatrisation cutanée ?","o":["1. Hémostase (coagulation, plaquettes)","2. Inflammation (PNN puis macrophages)","3. Prolifération (fibroblastes, néoangiogenèse, bourgeon charnu)","4. Remodelage (maturation collagène, contraction)","5. Métaplasie obligatoire"],"r":[0,1,2,3],"e":"4 étapes de la cicatrisation : 1) hémostase (clou plaquettaire, coagulation) → 2) inflammation (PNN, macrophages) → 3) prolifération (fibroblastes, angiogenèse, tissu de granulation) → 4) remodelage (maturation collagène). La métaplasie n'est PAS une étape normale.","s":16},{"q":"Concernant le tissu de GRANULATION (bourgeon charnu) :","o":["Apparaît durant la phase proliférative","Néovaisseaux + fibroblastes + matrice extracellulaire + cellules inflammatoires","Aspect rouge framboise","Caractéristique de la cicatrisation par 2e intention","Composé uniquement de collagène mature"],"r":[0,1,2,3],"e":"Bourgeon charnu : apparaît en phase proliférative, mélange de néovaisseaux, fibroblastes (myofibroblastes), matrice (collagène jeune type III), cellules inflammatoires. Aspect rouge granulaire. Sera remodelé en cicatrice mature.","s":16},{"q":"La cicatrisation par PREMIÈRE INTENTION concerne :","o":["Les plaies à bords nets, peu de perte de substance","Les plaies infectées avec perte importante","Les brûlures profondes","Les plaies chroniques"],"r":0,"e":"1ère intention : plaies bords nets, rapprochés (sutures chirurgicales), peu de perte de substance → cicatrice fine et rapide. 2e intention : plaies béantes, perte de substance → bourgeon charnu, cicatrice large.","s":16},{"q":"La cicatrisation par DEUXIÈME INTENTION :","o":["Concerne les plaies suturées","Implique la formation d'un bourgeon charnu volumineux","Donne une cicatrice toujours invisible","Est plus rapide que la 1ère intention"],"r":1,"e":"2e intention : plaie béante avec perte de substance importante → bourgeon charnu volumineux, comblement progressif, contraction des berges, cicatrice plus large et plus longue. Plus risquée (infection, fibrose excessive).","s":16},{"q":"Quels FACTEURS EXTRINSÈQUES retardent la cicatrisation ?","o":["Infection","Corps étranger","Déshydratation de la plaie","Mobilisation excessive","Tabac","Le diabète"],"r":[0,1,2,3,4],"e":"Facteurs extrinsèques : infection, corps étranger, déshydratation, mobilité excessive de la plaie, tabac (vasoconstriction), traumatisme répété, mauvaise hygiène. Tous retardent la cicatrisation. Le diabète est un facteur intrinsèque, lié au terrain du patient et non à l'environnement de la plaie.","s":16},{"q":"Quels FACTEURS INTRINSÈQUES retardent la cicatrisation ?","o":["Diabète (hyperglycémie chronique)","Carences nutritionnelles (protéines, vitamines C, A, zinc)","Âge avancé","Anémie / hypoxie","Corticothérapie au long cours","La présence d'un corps étranger dans la plaie"],"r":[0,1,2,3,4],"e":"Facteurs intrinsèques : diabète, malnutrition (protéines, Vit C/A, zinc), âge, anémie, hypoxie, corticothérapie (↓ inflammation utile, ↓ collagène), immunosuppresseurs, maladies chroniques. Un corps étranger est un facteur extrinsèque : il vient du milieu, pas du terrain du patient.","s":16},{"q":"Une CHÉLOÏDE est :","o":["Une cicatrice fine et discrète","Une cicatrice hypertrophique qui DÉBORDE les limites de la plaie initiale","Une absence de cicatrice","Une infection cicatricielle"],"r":1,"e":"Chéloïde : cicatrice exubérante qui DÉBORDE les limites de la plaie d'origine, par excès de production de collagène. Plus fréquente sur peaux foncées, en zones spécifiques (sternum, épaule, lobes d'oreille).","s":16},{"q":"Une cicatrice HYPERTROPHIQUE se distingue d'une chéloïde par :","o":["Elle dépasse les limites de la plaie","Elle reste limitée à la plaie initiale (mais épaisse et rouge)","Elle disparaît spontanément en quelques jours","Elle ne saigne jamais"],"r":1,"e":"Hypertrophique : épaisse, rouge, mais limitée aux contours de la plaie. Chéloïde : déborde les limites. Hypertrophique tend à régresser dans le temps ; chéloïde persiste, voire s'étend.","s":16},{"q":"Concernant le COLLAGÈNE de cicatrisation :","o":["Type III (immature) prédomine au début","Type I (mature) prédomine en fin de remodelage","La cicatrice n'atteint jamais 100% de la résistance du tissu original (~70-80% maximum)","Le remodelage peut durer plusieurs mois à un an","Aucun changement dans le temps"],"r":[0,1,2,3],"e":"Cicatrisation : phase proliférative = collagène III (jeune, désorganisé) → remodelage = collagène I (mature, organisé). La cicatrice atteint ~80% de la résistance du tissu sain au mieux. Remodelage ~6-12 mois.","s":16},{"q":"Le rôle du MYOFIBROBLASTE est :","o":["Synthétiser du collagène uniquement","Combiner les fonctions de fibroblaste (collagène) ET de cellule musculaire lisse (CONTRACTION) → contraction de la plaie","Phagocyter les débris","Produire des anticorps"],"r":1,"e":"Myofibroblaste = fibroblaste différencié exprimant l'α-actine musculaire lisse. Synthétise le collagène ET contracte → rapprochement des berges (contraction de la plaie) durant la phase proliférative.","s":16},{"q":"Quels sont des MODES DE COMMUNICATION cellulaire impliqués dans la réparation ?","o":["Autocrine (la cellule agit sur elle-même)","Paracrine (cellules voisines)","Endocrine (à distance via le sang)","Synaptique (cellules nerveuses)","Aucune communication"],"r":[0,1,2,3],"e":"Modes : autocrine (la cellule sur elle-même), paracrine (voisinage, ex : facteurs de croissance), endocrine (à distance, hormones), juxtacrine (contact direct), synaptique (neurones). Tous interviennent dans la réparation.","s":16},{"q":"Parmi les FACTEURS DE CROISSANCE impliqués dans la réparation, on trouve :","o":["PDGF (Platelet-Derived Growth Factor)","FGF (Fibroblast Growth Factor)","TGF-β (Transforming Growth Factor)","VEGF (Vascular Endothelial GF)","ATP"],"r":[0,1,2,3],"e":"Facteurs de croissance : PDGF (plaquettes, recrute fibroblastes), FGF (prolifération), TGF-β (production de collagène, fibrose), VEGF (angiogenèse), EGF, IGF. ATP n'est pas un facteur de croissance mais une source d'énergie.","s":16},{"q":"L'ANGIOGENÈSE durant la cicatrisation est :","o":["Inutile","Indispensable pour apporter oxygène et nutriments au tissu en formation","Pathologique","Spontanément délétère"],"r":1,"e":"L'angiogenèse (formation de nouveaux vaisseaux à partir de vaisseaux existants) est CRUCIALE : apporte O₂ et nutriments, permet la migration cellulaire, stimule la prolifération. Médiée par VEGF, FGF.","s":16},{"q":"Concernant le BOURGEON CHARNU pathologique (excessif) :","o":["Aspect framboisé exubérant","Saigne facilement","Ralentit l'épithélialisation","Traitement : nitrate d'argent ou ablation","Toujours inoffensif"],"r":[0,1,2,3],"e":"Bourgeonnement excessif : framboisé, fragile, saignant, déborde de la plaie, retarde l'épithélialisation (les kératinocytes ne peuvent pas migrer). Tx : nitrate d'argent, corticoïdes locaux, ablation chirurgicale.","s":16},{"q":"L'ÉPITHÉLIALISATION d'une plaie cutanée se fait :","o":["Par migration de kératinocytes des berges","Par division des cellules fibroblastiques","Par migration des macrophages","Par formation de tissu osseux"],"r":0,"e":"Épithélialisation : kératinocytes des berges (et des annexes pilo-sébacées) prolifèrent et migrent pour recouvrir la plaie. Nécessite un lit de plaie propre, humide, sans infection.","s":16},{"q":"La CONTRACTION de la plaie est due principalement à :","o":["Aux fibroblastes seuls","Aux myofibroblastes (contractiles)","Aux PNN","Aux mastocytes"],"r":1,"e":"La contraction de la plaie (réduction de la surface) est due à l'action contractile des myofibroblastes (fibroblastes exprimant l'α-actine de muscle lisse). Très importante pour les plaies de 2e intention.","s":16},{"q":"Concernant les CICATRICES PATHOLOGIQUES (anomalies) :","o":["Cicatrice hypertrophique","Cicatrice chéloïde","Cicatrice atrophique (déprimée)","Cicatrice rétractile (limitant le mouvement)","Cicatrice toujours esthétique"],"r":[0,1,2,3],"e":"Anomalies cicatricielles : hypertrophique (limitée), chéloïde (déborde), atrophique (déprimée, ex : varicelle, acné), rétractile (limite la mobilité, ex : brûlures). Toutes peuvent altérer la fonction et l'esthétique.","s":16},{"q":"L'ÉCHEC complet de cicatrisation aboutit à :","o":["Une cicatrice normale","Une PLAIE CHRONIQUE (ex : ulcère)","Une régénération parfaite","Une chéloïde toujours"],"r":1,"e":"Échec de cicatrisation = plaie chronique (>4-6 semaines sans cicatrisation). Exemples : ulcères veineux/artériels/diabétiques, escarres. Causes multiples : infection, ischémie, diabète, malnutrition.","s":16},{"q":"La cicatrisation OPTIMALE nécessite un environnement :","o":["Sec","Humide et chaud","Stérile glacial","Acide"],"r":1,"e":"Cicatrisation idéale : milieu HUMIDE et chaud (favorise la migration cellulaire, l'angiogenèse, et limite la formation de croûtes qui ralentissent). Principe des pansements modernes (hydrocolloïdes, hydrogels).","s":16},{"q":"La FIBROSE EXCESSIVE post-cicatricielle peut entraîner :","o":["Une amélioration fonctionnelle","Une perte de fonction (rétraction, ankylose, organe non fonctionnel)","Une régénération améliorée","Aucune conséquence"],"r":1,"e":"Fibrose excessive : remplace le tissu fonctionnel → perte de fonction. Ex : cirrhose hépatique (hépatocytes → fibrose), fibrose pulmonaire (alvéoles → fibrose), rétractions cutanées post-brûlures.","s":16},{"q":"La cicatrisation de TROISIÈME intention correspond à :","o":["Plaie suturée bord-à-bord (1ère intention)","Plaie laissée ouverte avec bourgeon charnu (2ème intention)","Correction chirurgicale APRÈS formation du tissu de granulation pour de meilleurs résultats fonctionnels/esthétiques","Cicatrisation chéloïdienne automatique"],"r":2,"e":"3 types de cicatrisation : 1ère intention (plaie nette suturée) ; 2ème intention (perte de substance, bourgeon charnu, contraction) ; 3ème intention (suture différée après formation du tissu de granulation, ex : plaies infectées initialement laissées ouvertes puis suturées secondairement).","s":16},{"q":"Les phases de la cicatrisation d'une plaie sont :","o":["Hémostase","Inflammation","Prolifération (granulation, ré-épithélialisation)","Remodelage","Calcification"],"r":[0,1,2,3],"e":"4 phases : hémostase (caillot) → inflammation → prolifération → remodelage.","s":16},{"q":"L'angiogenèse est :","o":["La formation de nouveaux vaisseaux à partir des existants","La destruction des vaisseaux","La fonction du foie","Une mort cellulaire"],"r":0,"e":"Angiogenèse = formation de nouveaux vaisseaux (essentielle pour la cicatrisation, induite par VEGF).","s":16},{"q":"Le tissu de granulation est :","o":["Du pus","Tissu conjonctif richement vascularisé qui remplit la plaie","Cicatrice mature","Os"],"r":1,"e":"Granulation = tissu jeune, rouge, vascularisé (capillaires + fibroblastes + matrice), précurseur de la cicatrice.","s":16},{"q":"Les fibroblastes synthétisent :","o":["Anticorps","Collagène et matrice extracellulaire","Insuline","Hormones"],"r":1,"e":"Fibroblastes = synthèse collagène, élastine, glycosaminoglycanes ; clés du remodelage.","s":16},{"q":"Le collagène prédominant dans la peau cicatricielle initiale est :","o":["Type I","Type III (puis remplacé par I lors du remodelage)","Type IV","Type V"],"r":1,"e":"Collagène III déposé d'abord, puis remplacé progressivement par le collagène I (résistance) lors du remodelage.","s":16},{"q":"La cicatrisation par seconde intention concerne :","o":["Plaies suturées propres","Plaies béantes avec perte de substance, comblées par granulation","Brûlures superficielles uniquement","Petites coupures"],"r":1,"e":"Seconde intention : plaie ouverte, comblement par granulation, ré-épithélialisation depuis les bords. Cicatrice plus large.","s":16},{"q":"Les facteurs locaux retardant la cicatrisation incluent :","o":["Infection","Ischémie locale","Présence de corps étrangers","Mauvaise apposition des berges","Bonne irrigation"],"r":[0,1,2,3],"e":"Locaux : infection, ischémie, corps étrangers, bords mal rapprochés, hématome, exposition aux UV.","s":16},{"q":"Les facteurs systémiques retardant la cicatrisation incluent :","o":["Diabète","Corticothérapie","Carence nutritionnelle","Tabagisme","Âge avancé","Sport"],"r":[0,1,2,3,4],"e":"Systémiques : diabète, corticoïdes, dénutrition, tabac, âge, immunodépression. Le sport modéré aide.","s":16},{"q":"Une chéloïde se distingue d'une cicatrice hypertrophique par :","o":["Aucune différence","Elle dépasse les limites initiales de la plaie","Elle est moins épaisse","Elle disparaît seule"],"r":1,"e":"Chéloïde déborde la plaie (formation excessive collagène). Cicatrice hypertrophique reste dans les limites.","s":16},{"q":"L'escarre (ulcère de pression) est due à :","o":["Une infection","Une compression prolongée des tissus mous → ischémie","Un traumatisme","Une brûlure"],"r":1,"e":"Escarre = lésion ischémique par compression prolongée (alité, fauteuil) sur saillies osseuses (sacrum, talons).","s":16},{"q":"De quoi dépend le choix entre régénération et cicatrisation ?","o":["Du type d'organe ou de tissu, du type cellulaire et de l'étendue de la lésion","Uniquement de l'âge du patient","Uniquement de la localisation anatomique","Uniquement de la présence d'une infection"],"r":0,"e":"Les deux mécanismes peuvent d'ailleurs coexister dans un même tissu.","s":16},{"q":"Quels épithéliums font partie des cellules labiles ?","o":["Peau, cavité buccale, vagin, col utérin, épithélium gastro-intestinal et urinaire de transition","Hépatocytes et cellules rénales","Neurones et cardiomyocytes","Cellules musculaires lisses et fibroblastes"],"r":0,"e":"Les cellules labiles se divisent en permanence ; les hépatocytes et fibroblastes sont stables.","s":16},{"q":"Dans quelle phase du cycle cellulaire les cellules stables se trouvent-elles normalement ?","o":["En phase G0, quiescentes","En phase M","En phase S","Elles ne sont jamais dans le cycle"],"r":0,"e":"Les cellules stables sortent du cycle mais peuvent y rentrer si un stimulus approprié survient.","s":16},{"q":"Quelles cellules la fiche classe-t-elle parmi les cellules stables ?","o":["Hépatocytes, cellules rénales, muscles lisses, endothélium vasculaire et fibroblastes","Cellules de la moelle osseuse","Neurones et cardiomyocytes","Épithélium de transition urinaire"],"r":0,"e":"Moelle osseuse et épithélium urinaire sont labiles ; neurones et cardiomyocytes sont permanents.","s":16},{"q":"Qu'est-ce que l'inhibition par contact ?","o":["Un signal d'arrêt de la prolifération lorsque les cellules se touchent","Une stimulation de la prolifération par contact","Un blocage de la migration des fibroblastes","Une inhibition de l'angiogenèse"],"r":0,"e":"Ce stimulus négatif évite la formation de néoplasmes ; sa défaillance est en cause dans la chéloïde.","s":16},{"q":"Quelles conditions sont nécessaires à la régénération ?","o":["Intégrité de la matrice extracellulaire, signaux de facteurs de croissance, maturation cellulaire et contrôle du cycle","Une matrice extracellulaire détruite","Une inflammation persistante","La présence de myofibroblastes"],"r":0,"e":"Sans matrice intacte, la réparation ne peut se faire que par cicatrisation.","s":16},{"q":"Qu'est-ce qu'une libération autocrine de facteur de croissance ?","o":["La cellule produit son propre facteur de croissance","Des cellules voisines libèrent le facteur","Le facteur est transporté par le sang","Le facteur est libéré dans la matrice extracellulaire uniquement"],"r":0,"e":"La voie paracrine part des cellules voisines, la voie endocrine de la circulation.","s":16},{"q":"Quel est le stimulateur le plus important de l'angiogenèse ?","o":["Le VEGF","Le PDGF","L'EGF","Le TGF-β"],"r":0,"e":"Le VEGF agit sur les cellules endothéliales ; le FGF et l'EGF y contribuent aussi mais moins spécifiquement.","s":16},{"q":"Quelles actions le PDGF exerce-t-il ?","o":["Chimiotaxie des macrophages et prolifération des cellules épithéliales, des muscles lisses et des fibroblastes","Inhibition des cellules épithéliales","Angiogenèse exclusive","Production d'interleukines"],"r":0,"e":"Le TGF-β, lui, inhibe les cellules épithéliales tout en stimulant les fibroblastes.","s":16},{"q":"Quel rôle les interleukines jouent-elles dans la réparation ?","o":["Elles induisent la prolifération et la chimiotaxie des fibroblastes","Elles inhibent l'angiogenèse","Elles dégradent le collagène","Elles assurent l'inhibition par contact"],"r":0,"e":"Libérées par les cellules inflammatoires, elles recrutent et activent les fibroblastes.","s":16},{"q":"Quelles cellules dominent la première vague de la phase inflammatoire ?","o":["Les neutrophiles","Les macrophages","Les fibroblastes","Les myofibroblastes"],"r":0,"e":"Les neutrophiles nettoient, puis les macrophages produisent les facteurs de croissance essentiels.","s":16},{"q":"Quelles molécules dominent la matrice entre J0 et J4 ?","o":["La fibronectine et le collagène III","Le collagène I","L'élastine","Les protéoglycanes seuls"],"r":0,"e":"Le collagène I monte de J6 à J12 et devient dominant au-delà de J12.","s":16},{"q":"Quelle est la dernière étape de la phase proliférative ?","o":["La prolifération des cellules épithéliales en surface","La migration des fibroblastes","L'angiogenèse","La formation du caillot"],"r":0,"e":"La réépithélialisation clôt la phase proliférative, après la granulation.","s":16},{"q":"Quelle est la durée approximative de la phase de remodelage ?","o":["De la 3e semaine à 6 mois et au-delà","De J0 à J4","De J4 à 3 semaines","Moins d'une semaine"],"r":0,"e":"Inflammatoire J0-J4, proliférative J4-3 semaines, remodelage à partir de 3 semaines.","s":16},{"q":"La SEPSIE (sepsis) est définie comme :","o":["Une infection localisée sans gravité","Une infection avec dysfonction d'organes potentiellement mortelle (réponse dysrégulée de l'hôte)","Une bactériémie isolée sans symptômes","Une simple fièvre"],"r":1,"e":"Sepsis (Sepsis-3) = dysfonction d'organes potentiellement létale due à une réponse DYSRÉGULÉE de l'hôte à une infection. Plus grave que l'infection simple, moins que le choc septique.","s":17},{"q":"Le CHOC SEPTIQUE est :","o":["Une infection sans retentissement","Un sepsis avec hypotension persistante nécessitant des vasopresseurs malgré le remplissage + lactates >2 mmol/L","Une simple fièvre","Une infection bactérienne urinaire"],"r":1,"e":"Choc septique = sepsis avec hypotension persistante nécessitant amines vasopressives pour maintenir PAM ≥65 mmHg + lactates >2 mmol/L malgré remplissage adéquat. Mortalité élevée (>40%).","s":17},{"q":"Concernant le CONTINUUM INFECTION → CHOC SEPTIQUE :","o":["Infection localisée → bactériémie","Sepsis (dysfonction d'organes)","Choc septique (hypotension réfractaire + hyperlactatémie)","Défaillance multi-organique (MODS) possible","Régression spontanée garantie"],"r":[0,1,2,3],"e":"Continuum : infection → bactériémie → sepsis → choc septique → MODS (défaillance multi-organique) → décès. Aggravation progressive si non traité, mortalité croissante.","s":17},{"q":"Le CHOC se définit par :","o":["Une augmentation de la pression artérielle","Une insuffisance circulatoire aiguë avec hypoperfusion tissulaire et hypoxie cellulaire","Une fièvre élevée isolée","Une douleur intense"],"r":1,"e":"Choc = défaillance circulatoire aiguë → ↓ perfusion tissulaire → hypoxie cellulaire → métabolisme anaérobie → acidose lactique → dysfonction d'organes. Urgence vitale absolue.","s":17},{"q":"Quels sont les TYPES DE CHOC ?","o":["Choc hypovolémique","Choc cardiogénique","Choc obstructif","Choc distributif (septique, anaphylactique, neurogénique)","Choc artérithérapique"],"r":[0,1,2,3],"e":"4 types principaux : hypovolémique (perte volémique : hémorragie, brûlure), cardiogénique (défaillance pompe : IDM), obstructif (obstacle au remplissage : EP, tamponnade, pneumothorax), distributif (vasodilatation : sepsis, anaphylaxie, neurogénique).","s":17},{"q":"Le choc HYPOVOLÉMIQUE est typiquement causé par :","o":["Une infection","Une perte de volume circulant (hémorragie, brûlures, déshydratation)","Une défaillance cardiaque","Une réaction allergique"],"r":1,"e":"Choc hypovolémique = ↓ volume sanguin circulant : hémorragie (intra/extra-corporelle), brûlures étendues, déshydratation sévère, 3e secteur (péritonite). Tx = REMPLISSAGE rapide.","s":17},{"q":"Le choc ANAPHYLACTIQUE est :","o":["Un choc cardiogénique","Un choc DISTRIBUTIF allergique avec vasodilatation massive et bronchoconstriction","Un choc hypovolémique","Un choc obstructif"],"r":1,"e":"Choc anaphylactique = choc distributif d'origine immunoallergique. Histamine massive → vasodilatation, ↑ perméabilité, bronchoconstriction. Tx urgence = ADRÉNALINE IM (cuisse) + remplissage + corticoïdes/antihistaminiques.","s":17},{"q":"Concernant le CHOC CARDIOGÉNIQUE :","o":["Défaillance de la pompe cardiaque","Cause typique : infarctus du myocarde","↓ débit cardiaque malgré remplissage normal","Hypoxie tissulaire","Bénin sans séquelles"],"r":[0,1,2,3],"e":"Choc cardiogénique : défaillance ventriculaire (IDM, myocardite, arythmies, valvulopathies). Mortalité élevée. Tx = inotropes, support mécanique (BCPIA, ECMO), revascularisation.","s":17},{"q":"Une CIVD (Coagulation Intra-Vasculaire Disséminée) :","o":["Augmente la formation de thrombus partout dans le corps puis épuise les facteurs → saignements","Empêche tout saignement","Est bénigne","Améliore la coagulation"],"r":0,"e":"CIVD : activation diffuse de la coagulation → microthrombi → consommation des facteurs et plaquettes → SAIGNEMENTS paradoxaux. Complication majeure du sepsis. Diagnostic : ↓ plaquettes, ↑ D-dimères, ↓ fibrinogène, ↑ TP/TCA.","s":17},{"q":"Le SDRA / ARDS / 'poumon de choc' correspond à :","o":["Un poumon hyperventilé physiologiquement","Une atteinte alvéolo-capillaire diffuse → œdème non cardiogénique → hypoxémie sévère","Une infection bronchique simple","Une tumeur pulmonaire"],"r":1,"e":"SDRA (Syndrome de détresse respiratoire aiguë) : lésion alvéolo-capillaire diffuse → œdème lésionnel non cardiogénique → hypoxémie réfractaire (PaO2/FiO2 ≤300). Complication majeure du sepsis. Tx = ventilation protectrice.","s":17},{"q":"Concernant l'INSUFFISANCE RÉNALE AIGUË (IRA) lors du choc :","o":["Souvent due à une nécrose tubulaire aiguë (NTA)","↓ diurèse (oligurie/anurie)","↑ créatinine","Souvent réversible si traitement précoce","Sans gravité"],"r":[0,1,2,3],"e":"IRA septique : NTA par hypoperfusion + toxicité. Oligurie (<400 mL/24h) ou anurie, ↑ créatinine. Réversible si pris à temps mais peut nécessiter dialyse temporaire. Mortalité élevée si MODS.","s":17},{"q":"Le MODS (Multi-Organ Dysfunction Syndrome) :","o":["Atteinte d'un seul organe","Défaillance progressive de PLUSIEURS organes (rein, foie, cœur, poumon, cerveau)","Toujours réversible","Une simple fièvre"],"r":1,"e":"MODS = défaillance simultanée ou successive de plusieurs systèmes (≥2 organes). Mortalité augmente avec le nombre d'organes touchés. Complication terminale fréquente du sepsis non contrôlé.","s":17},{"q":"Concernant la PHYSIOPATHOLOGIE du choc septique :","o":["Réaction inflammatoire systémique excessive","Vasodilatation périphérique massive","Augmentation de la perméabilité capillaire (œdèmes, hypovolémie relative)","Dépression myocardique secondaire","Augmentation des résistances vasculaires"],"r":[0,1,2,3],"e":"Choc septique : libération massive de cytokines (TNF, IL-1, IL-6) → vasodilatation (NO), ↑ perméabilité, dépression myocardique, microthrombi (CIVD), ↓ extraction d'oxygène. Résistances vasculaires DIMINUENT (vasodilatation).","s":17},{"q":"Le score qSOFA permet :","o":["Le diagnostic d'infection","Le dépistage rapide de sepsis (FR≥22, conscience altérée, PAS≤100)","La mesure de la glycémie","L'évaluation cardiologique"],"r":1,"e":"qSOFA (quick SOFA) : 3 critères au lit du patient (Glasgow <15, PA syst ≤100, FR ≥22). ≥2 critères positifs → suspicion de sepsis avec mortalité élevée → urgence.","s":17},{"q":"Concernant la PRISE EN CHARGE du choc septique, dans la 1ère heure ('bundle 1h') :","o":["Lactates","Hémocultures avant antibiothérapie","Antibiotiques à large spectre","Remplissage cristalloïde (30 mL/kg si hypotension/lactates)","Vasopresseurs si PAM <65 mmHg malgré remplissage","Kinésithérapie respiratoire intensive"],"r":[0,1,2,3,4],"e":"Bundle 1 heure (Surviving Sepsis Campaign) : 1) lactates, 2) hémocultures, 3) antibiothérapie large spectre rapide, 4) remplissage cristalloïde 30 mL/kg, 5) vasopresseurs si hypotension persistante (NORADRÉNALINE en 1ère ligne). À la première heure, la priorité est hémodynamique et anti-infectieuse ; la kinésithérapie vient une fois le patient stabilisé.","s":17},{"q":"Le vasopresseur de PREMIÈRE LIGNE dans le choc septique est :","o":["L'adrénaline","La noradrénaline","La dobutamine","La dopamine"],"r":1,"e":"Noradrénaline = vasopresseur de 1ère ligne dans le choc septique (vasoconstriction α-adrénergique). Adrénaline en 2e ligne. Dobutamine si dysfonction cardiaque associée.","s":17},{"q":"Quels sont des AGENTS BACTÉRIENS classiques de sepsie ?","o":["E. coli (BGN)","Staphylococcus aureus","Streptococcus pneumoniae","Klebsiella","Aucune bactérie ne provoque de sepsis"],"r":[0,1,2,3],"e":"Sepsis communautaire : E. coli, S. pneumoniae, S. aureus, Streptococcus, méningocoque. Sepsis nosocomial : Pseudomonas, Klebsiella, Enterobacter, S. aureus résistant (MRSA). Champignons aussi (Candida).","s":17},{"q":"Le SIRS (Systemic Inflammatory Response Syndrome) inclut :","o":["Un seul critère","≥2 critères : T° anormale, FC>90, FR>20, GB anormaux","Uniquement la fièvre","Uniquement la tachycardie"],"r":1,"e":"SIRS = ≥2 critères parmi : T°<36 ou >38°C, FC>90/min, FR>20/min ou PaCO2<32, leucocytes <4 ou >12×10⁹/L (ou >10% de formes immatures). Réponse inflammatoire pas nécessairement infectieuse.","s":17},{"q":"L'hyperlactatémie (>2 mmol/L) en contexte de choc traduit :","o":["Une bonne perfusion","Une hypoxie tissulaire avec métabolisme anaérobie (acidose lactique)","Une hypoglycémie","Une hypoxie cellulaire absente"],"r":1,"e":"Hyperlactatémie = marqueur d'hypoxie tissulaire (passage en glycolyse anaérobie). >2 mmol/L = signe de gravité (sepsis). >4 mmol/L = très sévère. Suivi du lactate = indicateur de réponse au traitement.","s":17},{"q":"Concernant le RÔLE DU KINÉSITHÉRAPEUTE en réanimation auprès du patient septique :","o":["Mobilisation précoce (lutte contre la fonte musculaire ICU-AW)","Kinésithérapie respiratoire (drainage, mobilisation thoracique)","Prévention des escarres (positionnement)","Verticalisation progressive","Initier l'antibiothérapie"],"r":[0,1,2,3],"e":"Le kiné en réa : mobilisation précoce (ICU-AW = ICU acquired weakness), kiné respiratoire, prévention escarres/TVP, verticalisation. NE prescrit PAS d'antibiotiques (rôle médical).","s":17},{"q":"L'ICU-AW (faiblesse acquise en réanimation) :","o":["Est rare et bénigne","Est fréquente et causes : alitement, sepsis, corticoïdes, curare → polyneuromyopathie","Régresse spontanément en 24h","Est exclusivement neurologique"],"r":1,"e":"ICU-AW : faiblesse musculaire généralisée acquise en réanimation (polyneuromyopathie de réa). Causes : sepsis, immobilité, corticoïdes, curares, hyperglycémie. Récupération longue (mois). Prévention : mobilisation précoce.","s":17},{"q":"Le choc OBSTRUCTIF est typiquement causé par :","o":["Une infection","Un obstacle au remplissage cardiaque (embolie pulmonaire massive, tamponnade péricardique, pneumothorax compressif)","Une perte de sang","Une défaillance ventriculaire intrinsèque"],"r":1,"e":"Choc obstructif : obstacle au remplissage ou à l'éjection cardiaque. Causes : EP massive, tamponnade, pneumothorax compressif, dissection aortique. Tx = lever l'obstacle (drainage, fibrinolyse...).","s":17},{"q":"Concernant les COMPLICATIONS du choc septique :","o":["SDRA (poumon de choc)","Insuffisance rénale aiguë","CIVD","MODS / défaillance multi-organique","Rémission immédiate sans séquelle"],"r":[0,1,2,3],"e":"Complications : SDRA, IRA (NTA), CIVD, MODS, ictère cholestatique, choc cardiogénique secondaire, syndrome post-réanimation (cognitif, ICU-AW, troubles psy). Mortalité élevée (>40%).","s":17},{"q":"La PORTE D'ENTRÉE la plus fréquente d'un sepsis chez l'adulte est :","o":["Cutanée","Pulmonaire (pneumonie)","Méningée","Articulaire"],"r":1,"e":"Portes d'entrée : pulmonaire (~50%, pneumonie), urinaire, abdominale (péritonite), cutanée (DHBN), cathéters (nosocomial). Toujours rechercher et traiter le foyer primaire (drainage si pertinent).","s":17},{"q":"Les SIGNES CLINIQUES classiques du choc à un stade avancé incluent :","o":["Hypotension","Tachycardie","Marbrures cutanées (peau froide, livide)","Oligurie","Altération de la conscience","Polyurie abondante"],"r":[0,1,2,3,4],"e":"Signes de choc : hypotension, tachycardie, peau froide pâle marbrée (sauf phase chaude initiale du choc septique : peau chaude rouge), oligurie, polypnée, troubles de conscience (somnolence à coma), acidose lactique. Le choc entraîne une oligurie par hypoperfusion rénale, exactement l'inverse.","s":17},{"q":"Le SIRS (Syndrome de Réponse Inflammatoire Systémique) requiert :","o":["1 critère","≥ 2 critères parmi : T°, FC, FR/PaCO2, leucocytes","Aucun critère","Une hospitalisation seule"],"r":1,"e":"SIRS : ≥ 2 critères : T°<36 ou >38°C, FC>90, FR>20 ou PaCO2<32, leucocytes<4000 ou >12000 ou >10% bandes.","s":17},{"q":"La sepsie est définie comme :","o":["Une infection localisée","Dysfonction d'organe menaçant la vie causée par une réponse dérégulée à l'infection","Choc cardiogénique","Une intoxication"],"r":1,"e":"Sepsie (Sepsis-3, 2016) = dysfonction d'organe menaçant la vie causée par une dérégulation de la réponse à l'infection.","s":17},{"q":"Le score qSOFA inclut :","o":["FC, T°, glycémie","Glasgow ≤ 14, TAS ≤ 100, FR ≥ 22","Hb, plaquettes, créat","Lactate seul"],"r":1,"e":"qSOFA = Glasgow≤14 + TAS≤100 mmHg + FR≥22/min ; ≥2 → suspicion sepsie.","s":17},{"q":"Le choc septique se définit par :","o":["Sepsie + hypotension nécessitant vasopresseurs + lactate >2 mmol/L","Sepsie sans hypotension","Une infection bénigne","Une déshydratation"],"r":0,"e":"Choc septique = sepsie avec hypotension persistante nécessitant vasopresseurs pour PAM≥65 + lactate >2 mmol/L.","s":17},{"q":"Le lactate sanguin élevé dans le sepsis traduit :","o":["Une bonne perfusion","Une hypoperfusion tissulaire / métabolisme anaérobie","Une déshydratation simple","Une infection bénigne"],"r":1,"e":"Lactate ↑ = anaérobiose tissulaire par hypoperfusion → marqueur de gravité du sepsis.","s":17},{"q":"La prise en charge initiale du sepsis inclut :","o":["Hémocultures avant antibiothérapie","Antibiothérapie large spectre dans la 1ère heure","Remplissage cristalloïdes 30 mL/kg","Lactate de contrôle","Vasopresseurs si hypotension persistante","Corticothérapie systématique d'emblée"],"r":[0,1,2,3,4],"e":"Bundle 1h sepsis : hémocs, ATB large spectre, lactate, remplissage 30 mL/kg, vasopresseurs (noradrénaline) si nécessaire. Les corticoïdes ne sont envisagés qu'en cas de choc réfractaire aux vasopresseurs, jamais en systématique initiale.","s":17},{"q":"Le remplissage vasculaire initial recommandé devant un sepsis avec hypoperfusion est de :","o":["5 mL/kg de cristalloïdes en 6 heures","30 mL/kg de cristalloïdes dans les 3 premières heures","100 mL/kg de colloïdes en 1 heure","Aucun remplissage avant le vasopresseur"],"r":1,"e":"Les recommandations de la Surviving Sepsis Campaign fixent 30 mL/kg de cristalloïdes dans les trois premières heures, avant ou en même temps que la noradrénaline si la pression reste basse. Le remplissage précède le vasopresseur, sauf hypotension profonde d'emblée.","s":17},{"q":"Le foyer infectieux primaire le plus fréquent du sepsis est :","o":["Cutané","Pulmonaire","ORL","Articulaire"],"r":1,"e":"Sources fréquentes : pulmonaire (1ère), abdominale, urinaire, cathéter, peau.","s":17},{"q":"La mortalité du choc septique est :","o":["< 5%","10-15%","30-50% voire plus","Toujours > 90%"],"r":2,"e":"Mortalité du choc septique reste élevée : 30-50% selon les séries, dépend du terrain et précocité de la PEC.","s":17},{"q":"La défaillance multiviscérale (MOF) :","o":["Est rare en sepsis","Est l'évolution grave du sepsis non contrôlé (rein, foie, poumon, coag, SNC)","Est sans gravité","Touche un seul organe"],"r":1,"e":"MOF/MODS = défaillance simultanée de ≥2 organes, conséquence du choc septique non contrôlé.","s":17},{"q":"Quel est le taux de mortalité du choc septique aux États-Unis selon la fiche ?","o":["Environ 50 %","Environ 10 %","Environ 25 %","Environ 80 %"],"r":0,"e":"La fiche indique 50 % aux États-Unis et 40 % de mortalité hospitalière au Portugal.","s":17},{"q":"Combien de cas de sepsie sont recensés chaque année aux États-Unis ?","o":["Plus de 750 000","Environ 50 000","Environ 10 millions","Environ 100 000"],"r":0,"e":"La fiche cite plus de 750 000 cas annuels.","s":17},{"q":"Quelle mortalité la fiche associe-t-elle à un score SOFA supérieur ou égal à 2 ?","o":["Environ 10 %","Environ 40 %","Environ 1 %","Environ 70 %"],"r":0,"e":"Une élévation de 2 points du SOFA définit le dysfonctionnement organique, avec environ 10 % de mortalité.","s":17},{"q":"De quand date la définition Sepsis-3 ?","o":["2016, publiée dans le JAMA","2001","2010","2020"],"r":0,"e":"Sepsis-3 (Singer et al., JAMA 2016) a redéfini sepsie et choc septique.","s":17},{"q":"Pourquoi le terme « septicémie grave » a-t-il été abandonné ?","o":["Parce que le terme « sepsie » implique déjà un dysfonctionnement organique","Parce qu'il est trop imprécis sur l'agent causal","Parce qu'il désigne désormais le choc septique","Parce qu'il ne s'applique qu'à l'enfant"],"r":0,"e":"Depuis Sepsis-3, l'expression est redondante.","s":17},{"q":"Pourquoi le SIRS n'est-il plus utilisé seul pour diagnostiquer la sepsie ?","o":["Sa sensibilité est faible","Il est trop spécifique","Il exige un dosage du lactate","Il n'existe plus de critères"],"r":0,"e":"Le SIRS reste utile pour repérer une infection, mais ne suffit plus au diagnostic.","s":17},{"q":"Quel critère de fréquence respiratoire figure dans le SIRS ?","o":["Plus de 20/min ou une PaCO₂ inférieure à 32 mmHg","Au moins 22/min","Plus de 30/min","Moins de 12/min"],"r":0,"e":"22/min est le seuil du qSOFA ; le SIRS retient 20/min ou une hypocapnie.","s":17},{"q":"Quels seuils de globules blancs définissent le critère hématologique du SIRS ?","o":["Plus de 12 000 ou moins de 4 000/mm³","Plus de 20 000 uniquement","Moins de 1 000/mm³","Plus de 15 000 uniquement"],"r":0,"e":"Leucocytose ou leucopénie sont l'un des quatre critères du SIRS.","s":17},{"q":"Quelle anomalie métabolique figure parmi les signes précoces de sepsie ?","o":["Une hyperglycémie sans diabète","Une hypoglycémie profonde","Une hypercalcémie","Une hyponatrémie"],"r":0,"e":"TNF, IL-1 et catécholamines induisent une résistance à l'insuline.","s":17},{"q":"Quel seuil de diurèse définit l'oligurie dans le choc septique ?","o":["Moins de 0,5 mL/kg/h","Moins de 2 mL/kg/h","Moins de 1 L/24 h","Moins de 100 mL/h"],"r":0,"e":"L'oligurie figure parmi les signes tardifs, avec l'hypotension réfractaire et l'acidose lactique.","s":17},{"q":"Que sont les PAMPs ?","o":["Des motifs moléculaires associés aux pathogènes, reconnus par les récepteurs Toll-like","Des cytokines anti-inflammatoires","Des facteurs de coagulation","Des anticorps antibactériens"],"r":0,"e":"Leur reconnaissance par les TLR active NF-κB et la cascade cytokinique.","s":17},{"q":"Quel facteur de transcription relaie l'activation des TLR ?","o":["NF-κB","GATA4","APAF-1","BCL2"],"r":0,"e":"NF-κB déclenche la production de TNF, IL-1, IL-6, IL-8 et HMGB1.","s":17},{"q":"Quel mécanisme explique la vasodilatation du choc septique ?","o":["La production de monoxyde d'azote","La libération d'adrénaline","La contraction endothéliale isolée","La thrombose microvasculaire"],"r":0,"e":"Le NO provoque la vasodilatation et l'hypotension systémique, tandis que le relâchement des jonctions serrées crée l'œdème.","s":17},{"q":"Quelle molécule procoagulante augmente dans la CIVD du sepsis ?","o":["Le facteur tissulaire (TF)","La protéine C","La thrombomoduline","Le TFPI"],"r":0,"e":"Le TF et le PAI-1 augmentent tandis que protéine C, TFPI et thrombomoduline diminuent.","s":17},{"q":"Quelle molécule antifibrinolytique s'élève dans le sepsis ?","o":["Le PAI-1","Le TFPI","La protéine C","La thrombomoduline"],"r":0,"e":"L'élévation du PAI-1 bloque la fibrinolyse et aggrave la thrombose microvasculaire.","s":17},{"q":"Les VOIES RESPIRATOIRES SUPÉRIEURES comprennent :","o":["Nez et fosses nasales","Pharynx","Larynx","Sinus paranasaux","Bronches"],"r":[0,1,2,3],"e":"VRS : nez/fosses nasales, sinus paranasaux, pharynx, larynx (jusqu'aux cordes vocales). Les bronches font partie des VRI (voies respiratoires inférieures).","s":18},{"q":"Le RHUME (rhinite aiguë) est principalement d'origine :","o":["Bactérienne (streptocoque)","Virale (rhinovirus surtout, coronavirus, adénovirus)","Allergique","Mycosique"],"r":1,"e":"Le rhume est principalement viral : rhinovirus (>50%), coronavirus, adénovirus, VRS, parainfluenza. Pas d'antibiothérapie indiquée. Auto-résolutif en 7-10 jours.","s":18},{"q":"Symptômes typiques du RHUME :","o":["Rhinorrhée (claire puis muqueuse)","Obstruction nasale","Éternuements","Maux de gorge","Fièvre élevée >39°C systématique"],"r":[0,1,2,3],"e":"Rhume : rhinorrhée, obstruction nasale, éternuements, irritation pharyngée, parfois fébricule (faible). Une fièvre élevée doit faire suspecter une grippe ou une surinfection bactérienne.","s":18},{"q":"La SINUSITE BACTÉRIENNE aiguë est suspectée si :","o":["Symptômes de rhume durant <3 jours","Persistance/aggravation des symptômes >10 jours, fièvre >39°C, douleur faciale, écoulement purulent","Toujours après un rhume sans complication","Sans aucun signe clinique"],"r":1,"e":"Sinusite bactérienne : symptômes >10 jours sans amélioration, ou aggravation après amélioration initiale, douleur faciale, fièvre >39°C, rhinorrhée purulente. Sinusite virale = la majorité, auto-résolutive.","s":18},{"q":"Quels SINUS sont concernés par la sinusite ?","o":["Maxillaires (les plus fréquents)","Frontaux","Ethmoïdaux","Sphénoïdaux","Mastoïdiens (sinus crâniens)"],"r":[0,1,2,3],"e":"4 paires de sinus paranasaux : maxillaires (+ fréquents en sinusite), frontaux, ethmoïdaux, sphénoïdaux. Les sinus mastoïdiens font partie de l'oreille moyenne (mastoïdite).","s":18},{"q":"La PHARYNGITE STREPTOCOCCIQUE (à streptocoque β-hémolytique du groupe A) doit être traitée par :","o":["Antiviraux","Antibiotiques (amoxicilline) pendant 6 jours","Aucun traitement","Antifongiques"],"r":1,"e":"Pharyngite à SBHA : antibiothérapie obligatoire pour prévenir les complications post-streptococciques (RAA, glomérulonéphrite). Amoxicilline 6 jours en France. Diagnostic : TROD streptococcique ou culture.","s":18},{"q":"Concernant les complications post-streptococciques de la pharyngite à SBHA :","o":["Rhumatisme articulaire aigu (RAA)","Glomérulonéphrite aiguë post-streptococcique","Phlegmon péri-amygdalien","Otite moyenne aiguë","Diabète"],"r":[0,1,2,3],"e":"Complications : précoces (phlegmon, OMA, sinusite, abcès rétropharyngé), tardives non suppuratives = RAA (cardite, polyarthrite, chorée) et GN aiguë. Le diabète n'a pas de lien direct.","s":18},{"q":"La LARYNGITE aiguë chez l'adulte est principalement :","o":["Virale","Bactérienne","Toujours mycosique","Auto-immune"],"r":0,"e":"Laryngite aiguë = principalement virale (suite d'une infection des VRS). Symptômes : dysphonie/aphonie, toux sèche. Auto-résolutive en quelques jours. Tx : repos vocal, hydratation.","s":18},{"q":"La LARYNGITE SOUS-GLOTTIQUE de l'enfant (croup) :","o":["Provoque une dyspnée laryngée avec stridor inspiratoire et toux aboyante","Est une urgence respiratoire potentielle","Est principalement virale (parainfluenza)","Toutes les propositions ci-dessus"],"r":3,"e":"Croup : laryngite sous-glottique virale (parainfluenza) chez 6 mois-3 ans. Triade : toux aboyante (rauque), stridor inspiratoire, dyspnée. Tx = corticoïdes (dexaméthasone) ± adrénaline en aérosol si grave.","s":18},{"q":"La GRIPPE (influenza) est causée par :","o":["Un virus à ADN","Le virus Influenza (A, B, C — virus à ARN segmenté)","Une bactérie","Un champignon"],"r":1,"e":"Grippe = virus Influenza, ARN segmenté (Orthomyxoviridae). 3 types : A (le + grave, pandémies, épidémies, animal+humain), B (épidémies humaines), C (formes bénignes).","s":18},{"q":"Symptômes typiques de la GRIPPE :","o":["Début brutal","Fièvre élevée (>39°C)","Myalgies, arthralgies, asthénie marquée","Céphalées","Rhinorrhée abondante isolée sans autre symptôme"],"r":[0,1,2,3],"e":"Grippe : début BRUTAL, fièvre élevée, frissons, myalgies/arthralgies, céphalées, asthénie majeure ('sentiment d'être passé sous un camion'), toux sèche. Distinct du rhume (progressif, peu fébrile).","s":18},{"q":"Concernant les COMPLICATIONS de la grippe :","o":["Pneumonie virale","Surinfection bactérienne (pneumonie à pneumocoque ou staphylocoque)","Décompensation de comorbidités (insuffisance cardiaque, BPCO)","Sd de Reye chez l'enfant traité par aspirine","Aucune complication possible"],"r":[0,1,2,3],"e":"Complications : pneumonie virale primaire, surinfection bactérienne (pneumocoque, staph), décompensation cardio-respiratoire, encéphalite, péricardite, syndrome de Reye (enfant + aspirine = CONTRE-INDIQUÉ).","s":18},{"q":"Le VACCIN antigrippal est :","o":["À ARN messager","Inactivé (saisonnier, recomposé chaque année)","Vivant atténué uniquement","Inutile"],"r":1,"e":"Vaccin antigrippal saisonnier : inactivé (injection IM), recomposé chaque année selon les souches OMS prédites (3 ou 4 souches : A/H1N1, A/H3N2, B). Recommandé : >65 ans, malades chroniques, soignants, enceintes.","s":18},{"q":"Le COVID-19 est causé par :","o":["Le virus Influenza","Le SARS-CoV-2 (coronavirus à ARN)","Une bactérie","Un parasite"],"r":1,"e":"COVID-19 = SARS-CoV-2 : coronavirus à ARN simple brin positif. Famille Coronaviridae. Découvert fin 2019, pandémie déclarée mars 2020.","s":18},{"q":"Symptômes possibles du COVID-19 :","o":["Fièvre","Toux","Anosmie / agueusie (très évocatrices)","Dyspnée","Diarrhées","Ictère cutanéo-muqueux"],"r":[0,1,2,3,4],"e":"COVID-19 : très polymorphe. Fièvre, toux, anosmie/agueusie (très évocateurs), dyspnée, asthénie, myalgies, céphalées, troubles digestifs, formes asymptomatiques fréquentes. Formes graves = SDRA. L'ictère traduit une atteinte hépatique ou hémolytique et ne fait pas partie du tableau du COVID-19.","s":18},{"q":"La voie d'entrée principale du SARS-CoV-2 dans les cellules est le récepteur :","o":["ACE2","Hémagglutinine","CD4","TLR4"],"r":0,"e":"Le SARS-CoV-2 utilise la protéine spike (S) pour se lier au récepteur ACE2 (Angiotensin Converting Enzyme 2) sur les cellules épithéliales (poumon, intestin, vaisseaux). Activation par TMPRSS2.","s":18},{"q":"Concernant la PRÉVENTION des infections respiratoires saisonnières :","o":["Lavage des mains","Port du masque en cas de symptômes","Hygiène respiratoire (tousser dans le coude)","Vaccination (grippe, COVID, pneumocoque)","Antibiothérapie systématique"],"r":[0,1,2,3],"e":"Prévention : hygiène (mains, masque, hygiène respiratoire), vaccination, distanciation. L'antibiothérapie systématique est INUTILE et néfaste (résistances, déséquilibre microbiote) pour les infections virales.","s":18},{"q":"Une OTITE MOYENNE AIGUË (OMA) est :","o":["Une inflammation/infection de l'oreille externe","Une inflammation/infection de l'oreille moyenne (caisse du tympan)","Une atteinte cochléaire","Une atteinte vestibulaire"],"r":1,"e":"OMA = inflammation de l'oreille moyenne, fréquemment chez l'enfant. Souvent bactérienne (pneumocoque, Haemophilus, Moraxella) compliquant un rhume. Symptômes : otalgie, fièvre, parfois écoulement (perforation).","s":18},{"q":"La principale étiologie BACTÉRIENNE des sinusites aiguës est :","o":["Streptococcus pneumoniae","Mycobacterium tuberculosis","Pseudomonas","E. coli"],"r":0,"e":"Sinusites bactériennes (rares vs virales) : Streptococcus pneumoniae +++, Haemophilus influenzae, Moraxella catarrhalis. Tx = amoxicilline (souvent + acide clavulanique).","s":18},{"q":"Concernant le DRAINAGE BRONCHIQUE / kinésithérapie respiratoire :","o":["Aide à mobiliser les sécrétions","Indiquée dans la bronchiolite, mucoviscidose, BPCO décompensée","Techniques : AFE, désencombrement, drainage autogène","Toujours indiquée dans le rhume","Indiquée en post-opératoire pulmonaire"],"r":[0,1,2,4],"e":"Kiné respi : mobilise les sécrétions (techniques expiratoires lentes ou rapides). Indications : encombrement (bronchiolite, BPCO, mucoviscidose, post-op). Le rhume ne nécessite pas de kiné respi.","s":18},{"q":"Le mécanisme de transmission majeur des virus respiratoires est :","o":["Voie sanguine","Voie sexuelle","Goutelettes (toux, éternuements) + contact avec surfaces contaminées + aérosols","Voie digestive uniquement"],"r":2,"e":"Virus respiratoires : transmission par gouttelettes (>5µm, courte distance), aérosols (<5µm, longue distance, surtout en milieu fermé), contact direct ou indirect (mains, surfaces, fomites).","s":18},{"q":"Les ANTIVIRAUX antigrippaux (oseltamivir = Tamiflu) :","o":["Tuent le virus","Inhibent la neuraminidase virale → ↓ libération virale","Sont efficaces sur tous les virus","Doivent être donnés au stade tardif"],"r":1,"e":"Oseltamivir/zanamivir : inhibiteurs de la neuraminidase. Efficacité optimale si donnés dans les 48h après le début des symptômes. Réduisent la durée et la sévérité des symptômes. Indiqués chez les patients à risque.","s":18},{"q":"L'incubation du COVID-19 est en moyenne de :","o":["1 jour","3-5 jours (jusqu'à 14 jours)","3 semaines","2 mois"],"r":1,"e":"COVID-19 : incubation médiane 5 jours, possible 1-14 jours. Période de contagion : commence ~2 jours avant les symptômes, max le jour des symptômes, dure ~7-10 jours en cas léger.","s":18},{"q":"Concernant l'évolution naturelle du rhume :","o":["Toujours grave avec hospitalisation","Auto-résolutive en 7-10 jours","Nécessite des antibiotiques systématiques","Ne se résout jamais"],"r":1,"e":"Rhume : évolution bénigne, auto-résolutive en 7-10 jours. Tx symptomatique uniquement (antalgiques, antipyrétiques, désinfection nasale). Pas d'antibiotiques (virus). Surveillance d'éventuelles complications (sinusite, OMA).","s":18},{"q":"Les facteurs FAVORISANT les infections des VRS chez l'adulte :","o":["Alimentation équilibrée","Tabagisme actif (paralyse les cils, altère muqueuse)","Immunité optimale","Sport modéré"],"r":1,"e":"Facteurs de risque : tabac (paralyse les cils muco-ciliaires, altère la muqueuse), pollution, immunodépression, allergies, RGO, déviation septale, terrain ORL (amygdales hypertrophiées). Le sport modéré PROTÈGE.","s":18},{"q":"La rhinite allergique est due à :","o":["Une infection bactérienne","Une réaction d'hypersensibilité IgE-médiée à un allergène","Une déshydratation","Une carence vitaminique"],"r":1,"e":"Rhinite allergique = hypersensibilité type I (IgE) → libération d'histamine par les mastocytes → rhinorrhée, prurit, éternuements.","s":18},{"q":"La sinusite aiguë se caractérise par :","o":["Douleur faciale + obstruction nasale + rhinorrhée purulente","Toux chronique seule","Fièvre isolée","Vertiges"],"r":0,"e":"Sinusite : douleur sinusale (frontale/maxillaire), obstruction, rhinorrhée purulente, ± fièvre.","s":18},{"q":"L'angine streptococcique se traite par :","o":["Antiviraux","Antibiotiques (pénicilline / amoxicilline)","Aucun traitement","Corticoïdes"],"r":1,"e":"Angine à streptocoque A : antibiothérapie (pénicilline) pour prévenir RAA, glomérulonéphrite, abcès.","s":18},{"q":"L'épiglottite aiguë de l'enfant est :","o":["Bénigne","Une urgence médicale (risque d'asphyxie)","Une maladie chronique","Une allergie"],"r":1,"e":"Épiglottite (Haemophilus influenzae b) : urgence vitale, risque d'obstruction aiguë des voies respiratoires supérieures.","s":18},{"q":"L'apnée obstructive du sommeil (SAOS) est :","o":["Un trouble psychiatrique","Des collapsus répétés des voies aériennes supérieures pendant le sommeil","Une infection","Une maladie hépatique"],"r":1,"e":"SAOS : pauses respiratoires répétées par collapsus pharyngé → désaturations, micro-éveils, somnolence diurne.","s":18},{"q":"Les facteurs de risque du SAOS incluent :","o":["Obésité","Sexe masculin","Cou court / large","Prise d'alcool ou sédatifs","Anomalies maxillo-mandibulaires","Activité sportive"],"r":[0,1,2,3,4],"e":"SAOS : obésité, homme, cou large (>43 cm H), alcool/sédatifs, micrognatie. Le sport est protecteur.","s":18},{"q":"La laryngite aiguë de l'adulte se manifeste par :","o":["Diarrhée","Dysphonie / aphonie","Constipation","Vertige"],"r":1,"e":"Laryngite : dysphonie/aphonie + toux sèche, souvent virale et auto-résolutive.","s":18},{"q":"L'examen clé du SAOS est :","o":["EEG seul","Polysomnographie (enregistrement nocturne)","Radio thorax","Échocardiographie"],"r":1,"e":"Polysomnographie : compte les apnées/hypopnées par heure → IAH (Index Apnée Hypopnée). >5 = SAOS.","s":18},{"q":"Le traitement principal du SAOS modéré-sévère est :","o":["Antibiotiques","CPAP (pression positive continue) nocturne","Antitussif","Trachéotomie d'emblée"],"r":1,"e":"CPAP = traitement de référence du SAOS modéré-sévère ; maintient les voies aériennes ouvertes.","s":18},{"q":"Une rhinorrhée claire prolongée + obstruction nasale chronique évoque :","o":["Une rhinite allergique chronique","Un cancer ORL","Une fracture nasale","Une amygdalite"],"r":0,"e":"Rhinite allergique chronique = rhinorrhée claire, obstruction, éternuements, prurit, parfois conjonctivite.","s":18},{"q":"Combien de personnes les infections respiratoires supérieures ont-elles touché en 2021, hors COVID ?","o":["Environ 13 milliards de cas","Environ 1 milliard","Environ 100 millions","Environ 500 millions"],"r":0,"e":"La fiche cite 13 milliards d'épisodes en 2021, hors COVID.","s":18},{"q":"Combien d'épisodes de rhume un enfant de 5 à 9 ans fait-il par an ?","o":["6 à 8","2 à 5","1 à 2","10 à 15"],"r":0,"e":"6 à 8 épisodes chez l'enfant de 5-9 ans contre 2 à 5 chez l'adulte.","s":18},{"q":"Quelle est la mortalité liée au rhume selon la fiche ?","o":["1 pour 20 000","1 pour 100","1 pour 1 000","Nulle"],"r":0,"e":"La fiche mentionne une mortalité de 1/20 000.","s":18},{"q":"De quoi dépendent les symptômes d'une infection respiratoire supérieure ?","o":["De la structure touchée, de la gravité du processus et de l'état de santé ou de l'âge de la personne","Uniquement de l'agent en cause","Uniquement de la saison","Uniquement du terrain allergique"],"r":0,"e":"C'est le principe clé énoncé par la fiche.","s":18},{"q":"Combien de sous-types de rhinovirus existe-t-il ?","o":["Environ 160","Environ 3","Environ 20","Environ 1 000"],"r":0,"e":"Cette diversité explique l'absence d'immunité durable et la répétition des rhumes.","s":18},{"q":"À quelle saison le pic de rhinovirus survient-il ?","o":["À l'automne et au printemps","En hiver uniquement","En été","Toute l'année de façon stable"],"r":0,"e":"Grippe et VRS piquent en hiver, les rhinovirus à l'automne et au printemps.","s":18},{"q":"Quelle est la durée d'incubation du rhume ?","o":["1 à 4 jours","1 à 5 jours","3 à 7 jours","2 semaines"],"r":0,"e":"1 à 4 jours pour le rhume, 1 à 5 pour la grippe, 3 à 7 pour le COVID-19.","s":18},{"q":"Quel est le réservoir du rhume ?","o":["Le nasopharynx","Le larynx","Les alvéoles","Le tube digestif"],"r":0,"e":"La transmission se fait par aérosols, surfaces et auto-inoculation nasale ou conjonctivale.","s":18},{"q":"Quel médiateur la fiche associe-t-elle au mal de gorge et à l'écoulement nasal du rhume ?","o":["La bradykinine","L'histamine","Le TNF-α","L'acétylcholine"],"r":0,"e":"Le rhinovirus augmente les médiateurs inflammatoires, la bradykinine produisant ces symptômes.","s":18},{"q":"Quel est le premier symptôme du rhume ?","o":["Le mal de gorge, dès le premier jour","L'écoulement nasal","La toux","La congestion nasale"],"r":0,"e":"Mal de gorge à J1, écoulement et éternuements à J2-J3, puis congestion, pharyngite et toux.","s":18},{"q":"Pourquoi le terme « rhinosinusite » est-il préféré à « sinusite » ?","o":["Parce que la muqueuse nasale est généralement aussi touchée","Parce que l'atteinte est toujours nasale et jamais sinusienne","Parce que la sinusite n'existe pas chez l'adulte","Parce que le terme sinusite désigne une forme chronique"],"r":0,"e":"L'atteinte est en pratique naso-sinusienne.","s":18},{"q":"Quelle proportion des sinusites est bactérienne ?","o":["0,5 à 2 %","20 à 30 %","50 %","80 %"],"r":0,"e":"L'immense majorité est virale, ce qui limite l'indication des antibiotiques.","s":18},{"q":"Quelles causes non infectieuses de sinusite la fiche cite-t-elle ?","o":["Allergie, déviation de la cloison nasale, barotraumatisme, corps étrangers et tumeurs","Tabagisme uniquement","Reflux gastro-œsophagien","Traumatisme vocal"],"r":0,"e":"Ces causes créent une obstruction ou une inflammation sans infection initiale.","s":18},{"q":"À partir de quelle durée parle-t-on de rhinosinusite chronique ?","o":["Plus de 12 semaines","Plus de 4 semaines","Plus de 2 semaines","Plus de 6 mois"],"r":0,"e":"Aiguë sous 4 semaines, subaiguë de 4 à 12, chronique au-delà de 12 ; récurrente si au moins 4 épisodes par an.","s":18},{"q":"Quels critères permettent de poser le diagnostic clinique de rhinosinusite ?","o":["Deux critères majeurs, ou un majeur et un mineur","Trois critères majeurs","Un seul critère majeur","Deux critères mineurs"],"r":0,"e":"La combinaison majeure/mineure est la règle diagnostique retenue.","s":18},{"q":"Une PNEUMONIE est :","o":["Une infection limitée aux bronches","Une infection du parenchyme pulmonaire (alvéoles + tissu interstitiel)","Une atteinte pleurale isolée","Une simple bronchite"],"r":1,"e":"Pneumonie = infection du parenchyme pulmonaire (alvéoles, espace interstitiel). À distinguer de la bronchite (atteinte des bronches) et de la pleurésie (atteinte de la plèvre).","s":19},{"q":"L'agent BACTÉRIEN le plus fréquent de la pneumonie communautaire est :","o":["Mycobacterium tuberculosis","Streptococcus pneumoniae (pneumocoque)","Pseudomonas aeruginosa","Staphylococcus aureus"],"r":1,"e":"Streptococcus pneumoniae (pneumocoque) = 1ère cause de pneumonie communautaire. Tableau classique : début brutal, fièvre élevée, frissons, point de côté, toux + crachats rouillés, foyer de condensation.","s":19},{"q":"Symptômes typiques d'une pneumonie LOBAIRE (alvéolaire, bactérienne) :","o":["Début brutal","Fièvre élevée + frissons","Toux + expectoration purulente","Point de côté","Évolution insidieuse sans symptômes"],"r":[0,1,2,3],"e":"Pneumonie lobaire bactérienne (pneumocoque ++) : début BRUTAL, fièvre/frissons, toux purulente parfois rouillée, douleur thoracique (point de côté), polypnée, foyer de condensation à l'auscultation.","s":19},{"q":"Concernant la PNEUMONIE ATYPIQUE :","o":["Début progressif","Fièvre modérée","Toux sèche tenace","Symptômes extra-pulmonaires (céphalées, myalgies)","Agents : Mycoplasma, Chlamydia, Legionella","Expectorations « rouille » abondantes"],"r":[0,1,2,3,4],"e":"Pneumonie atypique : début progressif, signes généraux + extra-pulmonaires (céphalées, myalgies, troubles digestifs), toux sèche, dissociation radio-clinique. Agents : Mycoplasma pneumoniae, Chlamydophila, Legionella (sévère). Ces crachats évoquent la pneumonie franche lobaire aiguë à pneumocoque, forme typique et non atypique.","s":19},{"q":"À l'examen physique, le syndrome de CONDENSATION pulmonaire associe :","o":["Matité, augmentation des vibrations vocales, râles crépitants/souffle tubaire","Hypersonorité, abolition du murmure vésiculaire","Tympanisme, silence auscultatoire","Sibilants diffus uniquement"],"r":0,"e":"Sd de condensation (alvéolaire) : MATITÉ percussion, ↑ vibrations vocales, râles crépitants ± souffle tubaire (alvéoles remplies). Pneumothorax = hypersonorité + abolition. Asthme = sibilants.","s":19},{"q":"Quels examens diagnostiques sont utiles dans la PNEUMONIE ?","o":["Radiographie thoracique (foyer de condensation)","CRP / NFS","Procalcitonine (orientation bactérienne)","Hémocultures si fièvre","Échographie cardiaque systématique"],"r":[0,1,2,3],"e":"Diagnostic : RX thorax (foyer alvéolaire systématisé), CRP/NFS, procalcitonine (↑ si bactérien), hémocultures, ECBC, antigénurie pneumocoque/Legionella. Échographie cardiaque pas systématique.","s":19},{"q":"Le score CRB-65 permet :","o":["Le diagnostic de tuberculose","D'évaluer la gravité d'une pneumonie communautaire en ambulatoire (Confusion, FR≥30, PA basse, Âge≥65)","La mesure de la calcémie","Le suivi cardiaque"],"r":1,"e":"CRB-65 = score de gravité pour pneumonie communautaire en ambulatoire. 4 critères : Confusion, FR ≥30, PA basse (PAS <90 ou PAD ≤60), Âge ≥65. ≥1 critère → hospitalisation à envisager.","s":19},{"q":"L'antibiothérapie de PREMIÈRE INTENTION dans la pneumonie communautaire à pneumocoque chez l'adulte sans comorbidité est :","o":["Vancomycine","Amoxicilline","Cotrimoxazole","Métronidazole"],"r":1,"e":"Pneumocoque (suspecté/confirmé) : amoxicilline 1g x3/j en 1ère intention (PO ou IV selon gravité). Si allergie : pristinamycine ou macrolides. Adapter selon antibiogramme.","s":19},{"q":"La TUBERCULOSE est causée par :","o":["Streptococcus pneumoniae","Mycobacterium tuberculosis (BAAR)","Un virus","Un champignon"],"r":1,"e":"Tuberculose = Mycobacterium tuberculosis (bacille de Koch), BAAR (Bacille Acido-Alcoolo-Résistant) à coloration de Ziehl-Neelsen. Croissance lente. Transmission aérienne interhumaine.","s":19},{"q":"Quels sont les SYMPTÔMES classiques de la TB pulmonaire ?","o":["Toux chronique > 2-3 semaines","Hémoptysie","Fièvre vespérale + sueurs nocturnes","Amaigrissement / asthénie","Évolution toujours aiguë sur 1 jour"],"r":[0,1,2,3],"e":"TB pulmonaire : signes constitutionnels (fièvre vespérale, sueurs nocturnes, amaigrissement, asthénie) + toux chronique (>3 sem), hémoptysie possible. Évolution INSIDIEUSE et CHRONIQUE (semaines/mois).","s":19},{"q":"L'examen de référence pour le diagnostic bactériologique de la TB est :","o":["Radio thoracique","Bacilloscopie directe (BAAR au Ziehl) + CULTURE (référence)","Sérologie","Antibiogramme uniquement"],"r":1,"e":"Diagnostic TB : crachats x3 → bacilloscopie directe (Ziehl) + CULTURE sur milieu de Löwenstein-Jensen (référence, lente : 4-6 semaines) ou MGIT (plus rapide). Tests moléculaires (GeneXpert) : rapides + résistance.","s":19},{"q":"L'IDR à la TUBERCULINE (test de Mantoux) :","o":["Diagnostique la TB-maladie","Met en évidence un contact ancien avec le BK ou une vaccination BCG (induration cutanée)","Permet de prescrire des antibiotiques","Est obsolète"],"r":1,"e":"IDR : injection ID de tuberculine, lecture à 72h (induration). Témoigne d'une exposition au BK ou d'un BCG. NE distingue PAS infection latente vs maladie active. Tests IGRA (Quantiferon, T-SPOT) plus spécifiques (non interférés par BCG).","s":19},{"q":"Le TRAITEMENT antituberculeux standard comprend :","o":["Phase intensive (2 mois) : isoniazide + rifampicine + pyrazinamide + éthambutol (RIPE)","Phase de continuation (4 mois) : isoniazide + rifampicine","Durée totale : 6 mois (forme sensible non compliquée)","DOT (directly observed therapy) recommandée","Antibiothérapie de 5 jours"],"r":[0,1,2,3],"e":"Tx TB standard (forme sensible) : 2 mois RIPE (isoniazide H, rifampicine R, pyrazinamide Z, éthambutol E) puis 4 mois HR. Total 6 mois. Observance cruciale (DOT). Surveiller hépatotoxicité et neuropathie (B6).","s":19},{"q":"Le vaccin BCG :","o":["Empêche complètement la TB","Réduit le risque des formes graves de TB de l'enfant (méningite, miliaire)","Est inefficace","Doit être fait chaque année"],"r":1,"e":"BCG : protection partielle, surtout contre les formes graves chez l'enfant (méningite tuberculeuse, miliaire). Inefficace contre les formes pulmonaires de l'adulte. Recommandé chez enfants à risque (pays de forte endémie, contact avec patient bacillifère).","s":19},{"q":"Quels sont des FACTEURS DE RISQUE de tuberculose ?","o":["VIH / immunodépression","Précarité, promiscuité","Diabète","Origine de pays endémique","Tabagisme","Une vaccination BCG récente"],"r":[0,1,2,3,4],"e":"FdR : VIH (RR x100), immunodépression (corticoïdes, biothérapies), précarité, milieu carcéral, sans-abri, contact étroit avec patient bacillifère, origine de pays endémique, diabète, tabac, dénutrition, alcoolisme. Le BCG protège des formes graves de l'enfant : c'est un facteur protecteur, non un facteur de risque.","s":19},{"q":"La maladie de POTT correspond à :","o":["Une TB pulmonaire","Une TB vertébrale (spondylite tuberculeuse)","Une TB méningée","Une TB rénale"],"r":1,"e":"Maladie de Pott = tuberculose VERTÉBRALE (spondylite tuberculeuse). Atteinte des vertèbres dorsales surtout, abcès paravertébral, cyphose typique ('gibbosité'). Risque neurologique (compression médullaire).","s":19},{"q":"Une TUBERCULOSE MILIAIRE est :","o":["Une forme bénigne","Une dissémination hématogène avec atteinte multi-organique (poumons, méninges, foie...)","Une simple toux","Une pneumonie atypique"],"r":1,"e":"TB miliaire = dissémination hématogène du BK → multiples micro-granulomes dans tous les organes (aspect de 'grains de mil' à la RX). Forme grave, urgence thérapeutique, risque méningite.","s":19},{"q":"Concernant la PHYSIOPATHOLOGIE de la TB :","o":["Phagocytose du BK par les macrophages alvéolaires","Formation de granulome avec cellules épithélioïdes et géantes (Langhans) + nécrose caséeuse","Contrôle si immunité cellulaire (LT) efficace","Réactivation possible en cas d'immunodépression","Toujours symptomatique"],"r":[0,1,2,3],"e":"TB : inhalation BK → phagocytose macrophages → granulome caséeux (Langhans, lymphocytes) → contrôle immunitaire (90% restent ASYMPTOMATIQUES en TB latente) ou évolution maladie (10%). Réactivation si immunodépression.","s":19},{"q":"L'EMBOLIE PULMONAIRE est :","o":["Une infection pulmonaire","L'obstruction aiguë d'une artère pulmonaire par un caillot (souvent venu d'une TVP)","Une pneumonie","Un asthme aigu"],"r":1,"e":"EP = obstruction d'une branche de l'artère pulmonaire, le plus souvent par un thrombus migré depuis une TVP des membres inférieurs. Symptômes : douleur thoracique, dyspnée brutale, tachycardie, parfois hémoptysie.","s":19},{"q":"L'ASPECT MILLET / 'grains de mil' à la radio thoracique évoque :","o":["Une pneumonie lobaire","Une tuberculose miliaire","Un épanchement pleural","Une bronchiolite"],"r":1,"e":"Image en 'grains de mil' (millet) = micronodules disséminés dans les 2 champs pulmonaires = TB miliaire (dissémination hématogène). Urgence thérapeutique.","s":19},{"q":"Concernant la PRISE EN CHARGE KINÉSITHÉRAPIQUE en pathologie respiratoire :","o":["Désencombrement bronchique","Réentraînement à l'effort (BPCO, post-pneumonie)","Éducation respiratoire (respiration diaphragmatique)","Verticalisation post-aiguë","Antibiothérapie directe"],"r":[0,1,2,3],"e":"Kiné respi : drainage des sécrétions, réentrainement à l'effort, éducation, ventilation dirigée, désinsufflation. Pas de prescription d'antibiotiques (rôle médical).","s":19},{"q":"Une COMPLICATION grave d'une pneumonie est :","o":["Pleurésie / empyème","Une simple congestion","Une rhinorrhée","Une éruption cutanée bénigne"],"r":0,"e":"Complications de pneumonie : pleurésie purulente (empyème), abcès pulmonaire, sepsis, SDRA, IRA, choc septique. Risque ↑ chez personnes âgées et fragiles.","s":19},{"q":"Concernant la BPCO (bronchopneumopathie chronique obstructive) :","o":["Maladie respiratoire chronique","Cause principale : tabagisme","Spirométrie : VEMS/CV < 70%","Réversible totalement","Caractérisée par un trouble ventilatoire OBSTRUCTIF non totalement réversible"],"r":[0,1,2,4],"e":"BPCO : maladie inflammatoire chronique des bronches, liée au tabac essentiellement. Trouble ventilatoire OBSTRUCTIF (VEMS/CV <70%) NON réversible (vs asthme). Évolution progressive avec exacerbations.","s":19},{"q":"Un PNEUMOTHORAX est :","o":["De l'air dans les bronches","De l'air dans la cavité pleurale → collapsus pulmonaire","De l'eau dans les poumons","Une infection bronchique"],"r":1,"e":"Pneumothorax = présence d'air dans la cavité pleurale → décollement pulmonaire → ↓ ventilation. Causes : spontané (jeune homme grand maigre), traumatique, iatrogène. Peut être compressif (urgence).","s":19},{"q":"Les PRÉCAUTIONS pour TUBERCULOSE pulmonaire bacillifère sont :","o":["Aucune précaution","Isolement RESPIRATOIRE (chambre seule, masque FFP2 pour soignants), masque chirurgical pour le patient","Isolement gouttelettes simples","Isolement contact uniquement"],"r":1,"e":"TB bacillifère = précautions AÉRIENNES : chambre individuelle (pression négative idéalement), masque FFP2 pour soignants, masque chirurgical pour le patient. Isolement maintenu jusqu'à négativation des crachats (2-3 semaines de tx efficace).","s":19},{"q":"La bronchite aiguë est le plus souvent :","o":["Bactérienne","Virale (auto-résolutive)","Cancéreuse","Allergique"],"r":1,"e":"Bronchite aiguë : 90% virale, toux ± expectorations, auto-résolutive en 1-3 semaines.","s":19},{"q":"La pneumonie communautaire la plus fréquente est due à :","o":["Mycobacterium tuberculosis","Streptococcus pneumoniae (pneumocoque)","Aspergillus","HIV"],"r":1,"e":"Pneumocoque (Streptococcus pneumoniae) = 1ère cause de pneumonie communautaire.","s":19},{"q":"Les signes d'une pneumonie incluent :","o":["Fièvre","Toux productive","Douleur thoracique","Dyspnée","Râles crépitants à l'auscultation","Apyrexie totale"],"r":[0,1,2,3,4],"e":"Pneumonie : fièvre + toux + expectorations + douleur thoracique + crépitants ± dyspnée. Foyer radiographique.","s":19},{"q":"La tuberculose pulmonaire est causée par :","o":["Streptococcus","Mycobacterium tuberculosis (BK)","Virus","Champignon"],"r":1,"e":"BK = Mycobacterium tuberculosis, bacille acido-alcoolo-résistant (BAAR).","s":19},{"q":"La transmission de la tuberculose est :","o":["Sexuelle","Aérienne (gouttelettes < 5µm)","Sanguine uniquement","Alimentaire"],"r":1,"e":"TB : transmission par voie aérienne (toux, parole), gouttelettes/aérosols, contagiosité forme bacillifère.","s":19},{"q":"L'IDR (intradermo-réaction) à la tuberculine teste :","o":["L'infection actuelle uniquement","Le contact passé ou présent avec le BK / BCG","Les anticorps","Le génome viral"],"r":1,"e":"IDR : réaction d'hypersensibilité retardée → positive si contact (BCG, infection latente ou active).","s":19},{"q":"Le traitement standard de la TB pulmonaire est :","o":["1 antibiotique 1 mois","Quadrithérapie 2 mois (RIPE) + bithérapie 4 mois","Antiviraux","Aucun traitement"],"r":1,"e":"TB : quadrithérapie INH+RMP+EMB+PZA 2 mois → bithérapie INH+RMP 4 mois.","s":19},{"q":"L'embolie pulmonaire (EP) est :","o":["Une infection","Une obstruction de l'artère pulmonaire (souvent caillot)","Une tumeur primaire pulmonaire","Une bronchite"],"r":1,"e":"EP : obstruction d'une branche de l'artère pulmonaire par un thrombus migré (souvent depuis MI - TVP).","s":19},{"q":"Les signes évocateurs d'EP sont :","o":["Dyspnée brutale","Douleur thoracique","Tachycardie","Hémoptysie","Syncope","Bradycardie"],"r":[0,1,2,3,4],"e":"EP : dyspnée +++, douleur, tachycardie, hémoptysie, syncope (massive), désaturation. Tachy >> brady.","s":19},{"q":"L'examen de référence pour confirmer une EP est :","o":["Radio thorax","Angio-scanner thoracique (CT-angio)","Échographie cardiaque","ECG"],"r":1,"e":"Angio-scanner thoracique = examen de référence pour le diagnostic de l'EP.","s":19},{"q":"Combien de causes respiratoires figurent dans le top 10 mondial des décès en 2021 ?","o":["4 sur 10","2 sur 10","6 sur 10","1 sur 10"],"r":0,"e":"BPCO, infections respiratoires inférieures, cancers broncho-pulmonaires et tuberculose.","s":19},{"q":"À quel rang mondial la tuberculose se situe-t-elle parmi les causes de décès en 2021 ?","o":["10e","4e","1re","20e"],"r":0,"e":"La BPCO est 4e, les infections respiratoires inférieures 5e et la tuberculose 10e.","s":19},{"q":"De quoi la pneumonie est-elle la première cause dans le monde ?","o":["De la mortalité infantile","De la mortalité chez les plus de 65 ans","Des cancers pulmonaires","Des hospitalisations en réanimation"],"r":0,"e":"La fiche souligne ce rôle dans la mortalité de l'enfant.","s":19},{"q":"Quels sont les trois mécanismes de défense physiologiques des voies respiratoires ?","o":["La modification du flux expiratoire, le transport mucociliaire et la barrière mécanique","La toux, la fièvre et l'inflammation","Les macrophages, les neutrophiles et les lymphocytes","Le surfactant, le mucus et la vasoconstriction"],"r":0,"e":"La pneumonie survient quand ces défenses sont altérées ou l'immunité faible.","s":19},{"q":"Quelles situations suppriment le réflexe de toux selon la fiche ?","o":["Douleur thoracique, chirurgie, médicaments, anesthésie, AVC, sonde nasogastrique et troubles neuromusculaires","Tabagisme et inhalation de fumée toxique","Alcool et tabac","Fibrose kystique et obstruction bronchique"],"r":0,"e":"Le tabac altère plutôt la fonction mucociliaire et l'alcool les macrophages.","s":19},{"q":"Qu'est-ce qui réduit la capacité des macrophages alvéolaires ?","o":["L'alcool et le tabagisme","La fibrose kystique","Une sonde nasogastrique","Une anesthésie générale"],"r":0,"e":"La fiche associe alcool et tabac à cette baisse de capacité phagocytaire.","s":19},{"q":"Quelle est la deuxième étape histologique de la pneumonie ?","o":["L'hépatisation rouge, avec capillaires congestifs, globules rouges et neutrophiles","L'hépatisation grise","La résolution","L'œdème alvéolaire initial"],"r":0,"e":"Inhalation-œdème, hépatisation rouge, hépatisation grise puis résolution.","s":19},{"q":"Qu'est-ce qui caractérise l'hépatisation grise ?","o":["Le remplacement des leucocytes par des macrophages, avec fibrine et consolidation","La congestion capillaire avec globules rouges","L'exsudat œdémateux initial","La restitution de l'architecture normale"],"r":0,"e":"Les macrophages assurent le nettoyage tardif, les neutrophiles la phase aiguë.","s":19},{"q":"Quelle cellule alvéolaire produit le surfactant ?","o":["Le pneumocyte de type II","Le pneumocyte de type I","Le macrophage alvéolaire","Le neutrophile"],"r":0,"e":"Le pneumocyte I forme la paroi alvéolaire, le pneumocyte II sécrète le surfactant.","s":19},{"q":"Quelle proportion des pneumonies est communautaire ?","o":["60 à 80 %","20 %","95 %","40 %"],"r":0,"e":"La pneumonie communautaire est diagnostiquée dans les 48 h suivant l'admission.","s":19},{"q":"Quelle est la mortalité de la pneumonie nosocomiale ?","o":["20 à 50 %","Moins de 5 %","60 à 80 %","Environ 10 %"],"r":0,"e":"Elle est diagnostiquée au moins 48 h après l'admission, souvent à germes résistants.","s":19},{"q":"Quels germes dominent la pneumonie nosocomiale ?","o":["S. aureus (dont MRSA), Pseudomonas et entérobactéries comme Klebsiella et Serratia","S. pneumoniae et H. influenzae","Mycoplasma et Chlamydia","La flore anaérobie buccale"],"r":0,"e":"La flore anaérobie buccale est responsable des pneumonies d'aspiration.","s":19},{"q":"Quel lobe est préférentiellement atteint dans la pneumonie d'aspiration ?","o":["Le lobe inférieur droit","Le lobe supérieur gauche","Le lobe moyen","Les apex"],"r":0,"e":"L'anatomie bronchique droite, plus verticale, explique cette localisation.","s":19},{"q":"Quel aspect radiologique caractérise la bronchopneumonie ?","o":["Un aspect hétérogène, segmentaire ou multifocal","Une condensation lobaire homogène","Des opacités interstitielles réticulaires","Une image cavitaire apicale"],"r":0,"e":"Elle est souvent associée à la BPCO et aux bronchectasies.","s":19},{"q":"Quels germes sont responsables des pneumonies atypiques ?","o":["Mycoplasma, Chlamydia, virus, Legionella et Coxiella burnetii","S. pneumoniae et S. aureus","Klebsiella et Serratia","Bacteroides et Prevotella"],"r":0,"e":"Le début est insidieux, sans consolidation alvéolaire.","s":19},{"q":"Un trouble ventilatoire OBSTRUCTIF se définit en spirométrie par :","o":["Un VEMS/CV (Tiffeneau) > 80%","Un VEMS/CV < 70%","Une CV diminuée seule","Une diffusion alvéolo-capillaire diminuée seule"],"r":1,"e":"Trouble ventilatoire obstructif (TVO) : VEMS/CV (rapport de Tiffeneau) <70% (post-bronchodilatateur). Caractérise BPCO, asthme, bronchectasies, mucoviscidose.","s":20},{"q":"La BPCO est caractérisée par :","o":["Une obstruction bronchique TOTALEMENT réversible","Une obstruction bronchique NON ENTIÈREMENT réversible, avec inflammation chronique liée au tabac","Une infection chronique","Une auto-immunité"],"r":1,"e":"BPCO = trouble ventilatoire obstructif PERSISTANT, NON entièrement réversible (vs asthme), inflammatoire chronique des bronches/poumons, principalement liée au tabac. Évolution progressive avec exacerbations.","s":20},{"q":"Quels sont les facteurs DE RISQUE de la BPCO ?","o":["Tabagisme actif","Tabagisme passif","Pollution atmosphérique / professionnelle","Déficit en α1-antitrypsine (génétique)","Activité physique régulière"],"r":[0,1,2,3],"e":"FdR BPCO : tabac (~90% des cas), tabac passif, pollution (extérieure et intérieure : biomasse), expositions professionnelles (silice, poussières), déficit en α1-antitrypsine. L'activité physique est protectrice.","s":20},{"q":"La classification GOLD de la BPCO repose principalement sur :","o":["L'âge du patient","Le VEMS post-bronchodilatateur (% prédit) + symptômes + exacerbations","La radiographie","La SpO2 uniquement"],"r":1,"e":"Classification GOLD : sévérité spirométrique (GOLD 1 ≥80%, 2 50-79%, 3 30-49%, 4 <30% du VEMS prédit) + groupes symptômes/exacerbations (A, B, E).","s":20},{"q":"Symptômes typiques de la BPCO :","o":["Dyspnée d'effort (puis de repos en évoluant)","Toux chronique productive (bronchite chronique)","Expectoration","Sibilants à l'auscultation","Apparition aiguë sans antécédent tabagique"],"r":[0,1,2,3],"e":"Symptômes BPCO : dyspnée chronique progressive, toux + expectoration (>3 mois/an, 2 ans = bronchite chronique), sibilants, distension thoracique. Évolution INSIDIEUSE chez fumeur (≥10 paquets-année).","s":20},{"q":"Quels TRAITEMENTS sont utilisés dans la BPCO stable ?","o":["Sevrage tabagique (mesure essentielle)","Bronchodilatateurs (β2 mimétiques, anticholinergiques) longue/courte durée","Corticoïdes inhalés (selon profil)","Réhabilitation respiratoire (kinésithérapie)","Antibiotiques systématiques au long cours"],"r":[0,1,2,3],"e":"Tx BPCO : sevrage tabagique (le PLUS efficace), bronchodilatateurs LABA/LAMA, ICS si éosinophilie/exacerbations, vaccination grippe + pneumocoque, oxygénothérapie longue durée si IRC, kiné/réhabilitation respiratoire. Antibiotiques uniquement en exacerbation.","s":20},{"q":"L'ASTHME se distingue de la BPCO par :","o":["Une obstruction COMPLÈTEMENT réversible (sous bronchodilatateurs)","Une obstruction non réversible","Une absence d'inflammation","Une cause exclusivement tabagique"],"r":0,"e":"Asthme = obstruction RÉVERSIBLE (totalement ou partiellement) sous bronchodilatateurs ou spontanément. BPCO = obstruction non/peu réversible. Asthme : inflammation à éosinophiles, allergique souvent.","s":20},{"q":"Quels sont les SYMPTÔMES typiques de l'ASTHME ?","o":["Dyspnée variable / paroxystique","Sibilants","Toux (souvent nocturne)","Oppression thoracique","Stable et constante"],"r":[0,1,2,3],"e":"Asthme : symptômes VARIABLES dans le temps, ↑ la nuit / au petit matin, déclenchés par allergènes, effort, infection, froid, irritants. Typiquement : dyspnée + sibilants + toux + oppression thoracique.","s":20},{"q":"Concernant la PHYSIOPATHOLOGIE de l'asthme :","o":["Inflammation chronique des bronches","Hyperréactivité bronchique","Bronchospasme (contraction muscle lisse)","Hypersécrétion de mucus","Lésion alvéolaire avec emphysème"],"r":[0,1,2,3],"e":"Asthme = triade : inflammation chronique (éosinophiles, IgE), hyperréactivité bronchique, obstruction (bronchospasme + œdème + mucus). L'emphysème est une caractéristique de la BPCO, pas de l'asthme.","s":20},{"q":"Quels FACTEURS DÉCLENCHANTS d'une crise d'asthme ?","o":["Allergènes (acariens, pollens, animaux)","Effort physique (asthme d'effort)","Infections virales","Air froid, fumée","Aspirine et AINS chez certains patients","Les bêta-2 mimétiques inhalés"],"r":[0,1,2,3,4],"e":"Déclencheurs : allergènes, effort, infections virales (rhume), air froid, fumée, irritants chimiques, aspirine/AINS (asthme à AINS), reflux gastro-œsophagien, stress émotionnel. Les bêta-2 mimétiques sont le traitement de la crise : ils bronchodilatent au lieu de la déclencher.","s":20},{"q":"Le traitement de SECOURS de la crise d'asthme est :","o":["Corticoïdes inhalés","β2-mimétiques de courte durée d'action (salbutamol = Ventoline)","Antibiotiques","Antihistaminiques"],"r":1,"e":"Tx de crise : β2-mimétiques courte durée (salbutamol/Ventoline) en aérosols-doseurs ou nébulisation. Si crise sévère : corticoïdes systémiques (oraux ou IV). Bronchodilatateur d'urgence.","s":20},{"q":"Le traitement de FOND de l'asthme persistant repose sur :","o":["Salbutamol seul","Corticoïdes inhalés (CSI), associés à un β2 longue durée si modéré-sévère","Antibiotiques","Antihistaminiques uniquement"],"r":1,"e":"Tx de fond asthme : CSI = pierre angulaire (anti-inflammatoire), associés à un LABA (β2 longue durée) si nécessaire. Selon sévérité : palier de Salford/GINA. Éducation thérapeutique cruciale.","s":20},{"q":"Une BRONCHIECTASIE / DDB (dilatation des bronches) est :","o":["Une dilatation transitoire et bénigne","Une dilatation IRRÉVERSIBLE et anormale des bronches, avec destruction des parois","Une inflammation alvéolaire","Un cancer bronchique"],"r":1,"e":"DDB = dilatation IRRÉVERSIBLE et permanente des bronches avec destruction de la paroi (élastique, musculaire), entraînant accumulation de sécrétions et infections récurrentes. Causes : post-infectieuses, mucoviscidose, déficit immunitaire.","s":20},{"q":"Symptômes des BRONCHIECTASIES :","o":["Toux chronique productive","Bronchorrhée importante (expectoration abondante)","Hémoptysies récurrentes","Infections respiratoires à répétition","Apparition brutale en 1 jour"],"r":[0,1,2,3],"e":"DDB : toux + bronchorrhée chronique (parfois plusieurs verres/jour, expectoration jaune-verte), hémoptysies fréquentes, infections récidivantes (Pseudomonas, H. influenzae). Évolution chronique progressive.","s":20},{"q":"L'examen de référence pour le diagnostic de BRONCHIECTASIES est :","o":["Radiographie thoracique","Scanner thoracique haute résolution (TDM HR)","ECG","IRM cardiaque"],"r":1,"e":"TDM HR thoracique = examen de référence pour DDB : visualise la dilatation bronchique (bronches > artère adjacente, image 'en bague à chaton'), épaississement pariétal, mucus, atteintes sacculaires/cylindriques.","s":20},{"q":"L'EMPHYSÈME pulmonaire est :","o":["Une inflammation aiguë","Une destruction des parois alvéolaires avec hyperdistension irréversible","Une infection bactérienne","Une tumeur bénigne"],"r":1,"e":"Emphysème : destruction irréversible des parois alvéolaires → hyperdistension distale, ↓ surface d'échange. Souvent associé à la BPCO. Centrolobulaire (tabac) ou panlobulaire (déficit α1-antitrypsine).","s":20},{"q":"Une EXACERBATION de BPCO est définie par :","o":["Une amélioration transitoire des symptômes","Une aggravation aiguë des symptômes nécessitant un changement thérapeutique (souvent infectieuse)","Le diagnostic initial","La fin de l'évolution"],"r":1,"e":"Exacerbation BPCO = aggravation aiguë des symptômes (dyspnée, toux, expectoration ± purulence) au-delà des variations quotidiennes, nécessitant une modification du traitement. Souvent infectieuse (virale ou bactérienne).","s":20},{"q":"Concernant la KINÉSITHÉRAPIE RESPIRATOIRE dans la BPCO :","o":["Désencombrement bronchique","Réentraînement à l'effort","Éducation thérapeutique (ventilation dirigée, économie d'effort)","Réhabilitation respiratoire en programme structuré","Aucun bénéfice prouvé"],"r":[0,1,2,3],"e":"Kiné BPCO : désencombrement (AFE, ELTGOL), réentraînement à l'effort (vélo, marche), éducation, ventilation diaphragmatique, lèvres pincées, technique de toux. Réhabilitation respiratoire = bénéfice MAJEUR prouvé sur dyspnée et qualité de vie.","s":20},{"q":"Le SEVRAGE TABAGIQUE est :","o":["Inutile car les lésions sont irréversibles","La mesure la plus efficace pour ralentir l'évolution de la BPCO et réduire la mortalité","Réservé aux jeunes","Recommandé uniquement après 70 ans"],"r":1,"e":"Le sevrage tabagique est LA SEULE intervention qui ralentit le déclin du VEMS et améliore la survie en BPCO. À tout âge ! Outils : substitution nicotinique, varénicline, bupropion, accompagnement psychologique.","s":20},{"q":"L'OXYGÉNOTHÉRAPIE de longue durée (OLD) en BPCO est indiquée si :","o":["SpO2 normale","PaO2 ≤ 55 mmHg (ou 56-59 si HTAP/œdème) en air ambiant à l'état stable, ≥15h/jour","Dyspnée légère sans hypoxémie","Toujours en cas de BPCO"],"r":1,"e":"OLD : indiquée si PaO2 ≤55 mmHg en AA à l'état stable (ou 56-59 + HTAP, polyglobulie, ICD), ≥15h/jour (idéalement 18h+). Améliore la survie chez insuffisant respiratoire chronique hypoxémique.","s":20},{"q":"Le tableau du « PINK PUFFER » (BPCO emphysémateuse) typique :","o":["Cyanosé, en surcharge, polypnée minimale","Maigre, dyspnée importante, peu cyanosé, distension thoracique","Obèse, somnolent, cyanosé","Asymptomatique au repos sans signes"],"r":1,"e":"Pink puffer (souffleur rose) : type EMPHYSÉMATEUX → maigre, distension thoracique majeure, dyspnée +++, peu cyanosé (PaO2 préservée par hyperventilation). Vs blue bloater (bronchitique chronique : obèse, cyanose, ICD).","s":20},{"q":"Un signe de DÉTRESSE RESPIRATOIRE majeur lors d'une crise d'asthme grave est :","o":["Sibilants intenses","Cyanose, mise en jeu des muscles inspiratoires accessoires, FR>30, silence auscultatoire","Toux légère","FC normale"],"r":1,"e":"Crise d'asthme grave : tachycardie, polypnée, tirage, cyanose, difficulté à parler, agitation. SILENCE AUSCULTATOIRE = très grave (obstruction quasi-totale, plus de sibilants !). Urgence vitale → réa.","s":20},{"q":"Concernant la MUCOVISCIDOSE :","o":["Maladie génétique (autosomique récessive, gène CFTR)","Mucus épais, encombrement bronchique chronique","Atteinte multiviscérale (poumons, pancréas, intestins, foie)","Diagnostic par test de la sueur (chlorures sudoraux ↑)","Maladie acquise par tabac"],"r":[0,1,2,3],"e":"Mucoviscidose : maladie génétique (CFTR), mucus visqueux → encombrement bronchique chronique, infections récurrentes (Pseudomonas, S. aureus), insuffisance pancréatique. Diagnostic : test sueur, génétique. Pas tabac.","s":20},{"q":"L'ASTHME D'EFFORT (AIE) :","o":["Survient au repos","Apparaît typiquement 5-15 minutes après le début/fin d'un effort intense","Ne peut être prévenu","N'est pas un asthme vrai"],"r":1,"e":"Asthme d'effort : bronchospasme post-effort (5-15 min après), surtout après effort intense en air froid/sec. Prévention : β2-CDA 15 min avant l'effort, échauffement progressif, contrôle de l'asthme de fond.","s":20},{"q":"Le rôle des CORTICOSTÉROÏDES INHALÉS (CSI) dans l'asthme est :","o":["Bronchodilatateur","Anti-inflammatoire (réduit l'inflammation chronique des bronches)","Antibiotique","Antitussif"],"r":1,"e":"CSI (béclométhasone, fluticasone, budésonide) : effet ANTI-INFLAMMATOIRE local. Pierre angulaire du Tx de fond. PAS de bronchodilatation immédiate (vs β2). À prendre quotidiennement même asymptomatique. Rincer la bouche après.","s":20},{"q":"Une maladie obstructive est caractérisée par :","o":["Diminution de la capacité pulmonaire totale","Limitation des débits expiratoires (VEMS/CVF < 0,7)","Atteinte interstitielle pure","Atteinte musculaire"],"r":1,"e":"Obstructif : ↓ VEMS/CVF (Tiffeneau < 0,7) → asthme, BPCO, bronchectasies, mucoviscidose.","s":20},{"q":"L'asthme est :","o":["Une obstruction fixe","Une obstruction bronchique réversible (au moins partiellement)","Une fibrose","Une infection chronique"],"r":1,"e":"Asthme = obstruction réversible (spontanément ou sous bronchodilatateurs), inflammation chronique des bronches.","s":20},{"q":"Les médiateurs de la crise d'asthme incluent :","o":["Histamine","Leucotriènes","Prostaglandines","IgE","Insuline"],"r":[0,1,2,3],"e":"Asthme allergique : IgE → mastocytes → histamine, leucotriènes, prostaglandines → bronchoconstriction + inflammation.","s":20},{"q":"Le bronchodilatateur d'urgence dans la crise d'asthme est :","o":["Salbutamol (β2-mimétique courte action)","Antibiotique","Antihistaminique","Diurétique"],"r":0,"e":"Salbutamol (Ventolin) = β2-agoniste de courte durée, traitement de la crise.","s":20},{"q":"La BPCO se définit par :","o":["Asthme aigu","Obstruction NON entièrement réversible (VEMS/CVF<0,7 post-BD)","Fibrose pulmonaire","Tumeur"],"r":1,"e":"BPCO : obstruction non entièrement réversible (VEMS/CVF<0,7 après bronchodilatateur), souvent liée au tabac.","s":20},{"q":"La cause principale de BPCO dans les pays développés est :","o":["Asthme","Tabagisme actif ou passif","Infections récurrentes","Pollution seule"],"r":1,"e":"BPCO : 80-90% liée au tabagisme (actif ou passif). Autres : pollution, professions exposées, déficit α1-antitrypsine.","s":20},{"q":"La BPCO englobe :","o":["Bronchite chronique (toux + expectos ≥ 3 mois/an, 2 ans consécutifs)","Emphysème","Asthme allergique pur","Mucoviscidose"],"r":[0,1],"e":"BPCO = bronchite chronique (clinique) + emphysème (anatomopathologique : destruction alvéolaire).","s":20},{"q":"L'emphysème pan-lobulaire est associé à :","o":["Le tabac","Le déficit en α1-antitrypsine","L'asthme","L'allergie"],"r":1,"e":"Emphysème pan-lobulaire = destruction homogène, associé à déficit α1-antitrypsine. Centro-lobulaire = tabac.","s":20},{"q":"La saturation en O₂ (SpO₂) normale est :","o":["≥ 95%","85%","70%","100% obligatoire"],"r":0,"e":"SpO₂ normale ≥ 95% à l'air ambiant. < 90% = insuffisance respiratoire (hypoxémie).","s":20},{"q":"L'oxygénothérapie longue durée (OLD) dans la BPCO est indiquée :","o":["Si SpO₂ < 95%","Si PaO₂ < 55 mmHg ou < 60 mmHg avec polyglobulie/HTAP","Pour tous les patients","Jamais"],"r":1,"e":"OLD : PaO₂ < 55 mmHg, ou < 60 mmHg + polyglobulie/HTAP/cœur pulmonaire chronique. ≥ 15h/jour.","s":20},{"q":"Quelle est la prévalence mondiale actuelle de la BPCO selon la fiche ?","o":["10,3 %","23 %","6 %","56 %"],"r":0,"e":"La prévision est de 23 % d'ici 2050.","s":20},{"q":"Quelle part des dépenses de santé de l'Union européenne les maladies respiratoires représentent-elles ?","o":["6 %, dont 56 % liés à la BPCO","23 %","10,3 %","1 %"],"r":0,"e":"La BPCO pèse pour plus de la moitié de ce poste de dépenses.","s":20},{"q":"Quelle mutation génétique est associée au déficit en alpha-1-antitrypsine ?","o":["SERPINA1","SOD1","APOE-ε4","CFTR"],"r":0,"e":"Ce déficit est le principal facteur génétique de BPCO.","s":20},{"q":"Quel déséquilibre enzymatique aboutit à la destruction de la paroi alvéolaire ?","o":["Le déséquilibre protéase / antiprotéase","Le déséquilibre MMP / TIMP osseux","Le déséquilibre RANK / RANKL","Le déséquilibre COX-1 / COX-2"],"r":0,"e":"Le stress oxydatif et l'inflammation aboutissent à cet excès de protéases.","s":20},{"q":"Quelles conséquences mécaniques l'obstruction bronchique entraîne-t-elle dans la BPCO ?","o":["Un piégeage d'air et une hyperinflation","Une réduction de la capacité pulmonaire totale","Une augmentation de la compliance alvéolaire uniquement","Une baisse du volume résiduel"],"r":0,"e":"Le piégeage et l'hyperinflation s'accompagnent d'anomalies des échanges gazeux.","s":20},{"q":"Quelles causes la fiche donne-t-elle aux modifications musculaires de la BPCO ?","o":["Hypoxémie, inflammation, âge, stress oxydatif et inactivité physique","Uniquement le tabagisme","Uniquement la dénutrition","Uniquement les corticoïdes"],"r":0,"e":"L'inactivité physique est un facteur aggravant sur lequel la rééducation peut agir.","s":20},{"q":"Quel VEMS définit le stade GOLD 3 ?","o":["Entre 30 et 50 % de la valeur prédite","Au moins 80 %","Entre 50 et 80 %","Moins de 30 %"],"r":0,"e":"GOLD 1 ≥ 80 %, GOLD 2 50-80 %, GOLD 3 30-50 %, GOLD 4 < 30 %.","s":20},{"q":"Sur quel VEMS la classification GOLD est-elle fondée ?","o":["Le VEMS post-bronchodilatateur","Le VEMS pré-bronchodilatateur","La capacité vitale forcée","La capacité pulmonaire totale"],"r":0,"e":"Tous les grades supposent en outre un rapport VEMS/CVF inférieur à 0,7.","s":20},{"q":"Qu'est-ce que la pré-BPCO ?","o":["Un tableau avec VEMS bas, piégeage gazeux ou hyperinflation, mais un rapport VEMS/CVF préservé","Un stade GOLD 1 débutant","Une BPCO sans symptôme","Un asthme ancien"],"r":0,"e":"Le ratio préservé exclut le critère diagnostique classique.","s":20},{"q":"Quel traitement initial la GOLD 2024 propose-t-elle pour le groupe A ?","o":["Un bronchodilatateur","LABA + LAMA","LABA + LAMA + ICS","Une corticothérapie orale"],"r":0,"e":"Les groupes B et E reçoivent d'emblée LABA + LAMA.","s":20},{"q":"Quel critère définit le groupe E de la classification ABE ?","o":["Au moins 2 exacerbations modérées ou au moins 1 hospitalisation","Un score mMRC supérieur ou égal à 2","Un VEMS inférieur à 30 %","Aucune exacerbation"],"r":0,"e":"Le groupe E peut recevoir un ICS si les éosinophiles sont ≥ 300/µL.","s":20},{"q":"Quel seuil d'éosinophiles justifie l'ajout d'un corticoïde inhalé dans le groupe E ?","o":["300/µL ou plus","100/µL","1 000/µL","50/µL"],"r":0,"e":"Ce seuil oriente vers une inflammation de type 2, sensible aux corticoïdes inhalés.","s":20},{"q":"Que recouvre la méthode 5A d'aide au sevrage tabagique ?","o":["Ask, Advise, Assess, Assist, Arrange","Assess, Analyse, Adapt, Act, Assure","Ask, Act, Apply, Adjust, Assess","Advise, Avoid, Assist, Adapt, Arrange"],"r":0,"e":"Identifier, conseiller, évaluer la motivation, soutenir et organiser le suivi.","s":20},{"q":"Quelles vaccinations la fiche recommande-t-elle dans la BPCO ?","o":["Grippe, pneumocoque, COVID, zona, coqueluche et VRS","Grippe uniquement","BCG","Hépatite B"],"r":0,"e":"Ces vaccinations réduisent les exacerbations infectieuses.","s":20},{"q":"Quelle association a démontré une réduction de mortalité dans les essais IMPACT et ETHOS ?","o":["LABA + LAMA + ICS","LAMA seul","LABA seul","Les corticoïdes oraux"],"r":0,"e":"Cette trithérapie concerne les patients symptomatiques à exacerbations fréquentes ou sévères.","s":20},{"q":"Un trouble ventilatoire RESTRICTIF se définit en spirométrie par :","o":["VEMS/CV diminué","Une CPT (Capacité Pulmonaire Totale) diminuée < 80% prédit","Une CV augmentée","Une obstruction des bronches"],"r":1,"e":"Trouble ventilatoire restrictif (TVR) = ↓ CPT (<80% prédit), avec CV ↓ et VEMS/CV NORMAL ou augmenté. Distinction importante avec le trouble obstructif (VEMS/CV <70%).","s":21},{"q":"Concernant les TROUBLES RESTRICTIFS EXTRINSÈQUES (cage thoracique) :","o":["Cyphoscoliose sévère","Obésité majeure","Maladies neuromusculaires (myasthénie, SLA)","Pleurésies massives","Fibrose pulmonaire idiopathique"],"r":[0,1,2,3],"e":"Restrictifs extrinsèques : déformations rachidiennes (cyphoscoliose), obésité, troubles neuromusculaires (paralysie diaphragmatique, SLA, Guillain-Barré, myopathies), pathologie pleurale, ascite massive. La fibrose = INTRINSÈQUE (parenchyme).","s":21},{"q":"Concernant les TROUBLES RESTRICTIFS INTRINSÈQUES (parenchyme) :","o":["Fibrose pulmonaire idiopathique (FPI)","Sarcoïdose","Pneumoconioses (silicose, asbestose)","Connectivites avec atteinte pulmonaire","Asthme bronchique"],"r":[0,1,2,3],"e":"Restrictifs intrinsèques (parenchyme) : MIP (maladies interstitielles), FPI, sarcoïdose, pneumoconioses (silice, amiante), connectivites (PR, sclérodermie), pneumonies organisées. L'asthme = OBSTRUCTIF.","s":21},{"q":"La FIBROSE PULMONAIRE IDIOPATHIQUE (FPI) est :","o":["Réversible avec corticoïdes","Une maladie chronique progressive de cause inconnue, avec fibrose interstitielle","Une infection","Une tumeur"],"r":1,"e":"FPI : maladie chronique progressive de cause inconnue, fibrose interstitielle prédominante aux bases. Pronostic réservé (médiane de survie 3-5 ans). Tx : antifibrotiques (pirfénidone, nintédanib), transplantation.","s":21},{"q":"Manifestations cliniques classiques des MALADIES INTERSTITIELLES PULMONAIRES (MIP) :","o":["Dyspnée d'effort progressive","Toux sèche persistante","Râles crépitants 'velcro' aux bases","Hippocratisme digital","Sibilants et ronchi prédominants"],"r":[0,1,2,3],"e":"MIP : dyspnée d'effort progressive, toux sèche, crépitants 'secs' type velcro aux bases (fin d'inspiration), hippocratisme digital (fibrose chronique), désaturation à l'effort. Sibilants/ronchi = obstructif.","s":21},{"q":"La SARCOÏDOSE est :","o":["Une infection bactérienne","Une maladie inflammatoire systémique avec granulomes non caséeux (sans cause identifiée)","Une tumeur maligne","Une maladie infectieuse virale"],"r":1,"e":"Sarcoïdose : maladie inflammatoire systémique avec granulomes EPITHELIOÏDES sans nécrose CASÉEUSE (vs TB). Atteinte préférentielle pulmonaire (adénopathies hilaires, MIP), peau, yeux, foie, etc. Étiologie inconnue.","s":21},{"q":"Une PNEUMOCONIOSE est :","o":["Une infection respiratoire","Une fibrose pulmonaire causée par l'inhalation chronique de poussières (silice, amiante, charbon)","Une tumeur bénigne","Une affection allergique"],"r":1,"e":"Pneumoconioses = maladies professionnelles dues à l'inhalation chronique de poussières minérales : silicose (silice), asbestose (amiante), anthracose (charbon), bérylliose, etc. Évolution vers fibrose.","s":21},{"q":"L'ASBESTOSE :","o":["Est due à l'amiante","Est due au tabagisme","Est une infection","Est une tumeur"],"r":0,"e":"Asbestose : fibrose pulmonaire due à l'exposition chronique à l'AMIANTE (asbeste). Risque accru de mésothéliome pleural et de cancer bronchique (synergique avec tabac). Maladie professionnelle reconnue.","s":21},{"q":"L'ÉPANCHEMENT PLEURAL est :","o":["De l'air dans la cavité pleurale","Une accumulation anormale de LIQUIDE dans la cavité pleurale","Une fibrose pleurale","Une tumeur pleurale"],"r":1,"e":"Épanchement pleural = accumulation de liquide dans l'espace pleural. Pneumothorax = AIR. Hémothorax = SANG. Pyothorax/empyème = pus. Chylothorax = lymphe.","s":21},{"q":"Concernant les TRANSSUDATS pleuraux :","o":["Liquide pauvre en protéines (<30 g/L)","Causes : insuffisance cardiaque, cirrhose, syndrome néphrotique","Bilatéraux souvent","Sans cellules inflammatoires","Riche en protéines avec inflammation"],"r":[0,1,2,3],"e":"Transsudat : ↓ protéines, peu cellulaire, mécanisme MÉCANIQUE (↑ pression hydrostatique = ICC ou ↓ pression oncotique = cirrhose, hypoalbuminémie). Souvent bilatéral. Pas inflammatoire.","s":21},{"q":"Concernant les EXSUDATS pleuraux :","o":["Liquide riche en protéines (>30 g/L)","Causes : pneumonie (parapneumonique), cancer, embolie pulmonaire, TB","Origine inflammatoire","Souvent unilatéral","Toujours d'origine cardiaque"],"r":[0,1,2,3],"e":"Exsudat : ↑ protéines, cellulaire, origine INFLAMMATOIRE (perméabilité capillaire ↑ ou drainage lymphatique altéré). Causes : pneumonie, cancer, EP, TB, connectivites. Critères de Light pour différencier.","s":21},{"q":"L'EMPYÈME est :","o":["Un transsudat","Un exsudat avec PUS dans la cavité pleurale (infection)","De l'air pleural","Du sang pleural"],"r":1,"e":"Empyème = présence de pus dans la cavité pleurale (pleurésie purulente), souvent compliquant une pneumonie bactérienne. Diagnostic : ponction → liquide trouble/purulent, pH bas, glucose bas. Tx = drainage + antibiothérapie.","s":21},{"q":"L'examen physique d'un épanchement pleural montre typiquement :","o":["Tympanisme + sibilants","Matité + abolition des vibrations vocales + abolition du murmure vésiculaire","Râles crépitants diffus","Wheezing"],"r":1,"e":"Sd d'épanchement pleural liquidien : MATITÉ percussion + ABOLITION des vibrations vocales + ABOLITION du murmure vésiculaire (parfois souffle pleural en haut de l'épanchement).","s":21},{"q":"Le PNEUMOTHORAX est :","o":["Du liquide pleural","De l'AIR dans la cavité pleurale → collapsus pulmonaire partiel/total","Du sang dans le poumon","Une infection"],"r":1,"e":"Pneumothorax = présence d'air dans la cavité pleurale. Spontané (rupture de bulle, jeune homme grand maigre), traumatique, iatrogène (post-ponction, ventilation). Peut être COMPRESSIF (urgence).","s":21},{"q":"Symptômes typiques du PNEUMOTHORAX :","o":["Douleur thoracique brutale en coup de poignard","Dyspnée","Toux sèche","Examen : hypersonorité + abolition murmure vésiculaire","Râles crépitants"],"r":[0,1,2,3],"e":"Pneumothorax : douleur thoracique brutale latéralisée, dyspnée, toux sèche. Examen : HYPERSONORITÉ percussion + abolition du murmure vésiculaire + abolition des vibrations vocales. RX confirme.","s":21},{"q":"Un pneumothorax COMPRESSIF (suffocant) est :","o":["Bénin","Une URGENCE VITALE avec compression médiastinale → exsufflation immédiate","Sans symptôme","Spontanément résolutif"],"r":1,"e":"Pneumothorax compressif/suffocant : air sous tension comprime médiastin, vaisseaux, poumon controlatéral → choc obstructif → décès rapide. URGENCE : exsufflation à l'aiguille en 2e EIC ligne médio-claviculaire puis drainage thoracique.","s":21},{"q":"Un HÉMOTHORAX correspond à :","o":["De l'air pleural","Du SANG dans la cavité pleurale (souvent traumatique)","De l'eau pleurale","Du pus pleural"],"r":1,"e":"Hémothorax = sang dans la cavité pleurale. Causes : traumatique (le plus souvent), iatrogène, néoplasique, anévrismale. Tx = drainage thoracique, surveillance saignement, parfois chirurgie.","s":21},{"q":"Le MÉSOTHÉLIOME PLEURAL est :","o":["Une tumeur bénigne fréquente","Une tumeur maligne RARE de la plèvre, fortement liée à l'AMIANTE","Une infection","Une atrophie"],"r":1,"e":"Mésothéliome pleural malin : tumeur agressive primitive de la plèvre, fortement liée à l'exposition à l'amiante (avec long délai 20-40 ans). Pronostic très sombre. Maladie professionnelle indemnisable.","s":21},{"q":"Concernant la PRISE EN CHARGE KINÉSITHÉRAPIQUE des troubles restrictifs :","o":["Réentraînement à l'effort","Travail de la ventilation thoraco-abdominale","Maintien des amplitudes thoraciques","Drainage bronchique si encombrement","Aucun bénéfice prouvé"],"r":[0,1,2,3],"e":"Kiné restrictif : réentraînement à l'effort, ventilation dirigée (diaphragmatique), assouplissement thoracique, désencombrement, oxygénothérapie d'effort. Améliore la qualité de vie et la dyspnée.","s":21},{"q":"Les râles crépitants dits 'velcro' sont caractéristiques de :","o":["L'asthme","La fibrose pulmonaire (FPI, MIP)","La BPCO","Le pneumothorax"],"r":1,"e":"Crépitants 'velcro' : crépitants secs, fins, en fin d'inspiration, prédominant aux bases. Caractéristiques de la fibrose pulmonaire idiopathique et autres MIP. Évoquent une atteinte interstitielle.","s":21},{"q":"L'HIPPOCRATISME DIGITAL (clubbing) :","o":["Est un signe de bronchite chronique","Témoigne souvent d'une hypoxie chronique (cardio-pulmonaire) : MIP, BPCO sévère, cancer broncho-pulmonaire","N'a aucune signification","Est une malformation congénitale exclusive"],"r":1,"e":"Hippocratisme digital : déformation des doigts en baguette de tambour avec ongles bombés. Causes : hypoxémie chronique (MIP, mucoviscidose, cardiopathie cyanogène), cancer broncho-pulmonaire, MICI. Mécanisme mal compris.","s":21},{"q":"Le DIAGNOSTIC d'un trouble restrictif repose sur :","o":["La spirométrie seule","La pléthysmographie (mesure des volumes pulmonaires : CPT)","La radiographie seule","L'EFR avec mesure de la diffusion (DLCO) souvent abaissée"],"r":1,"e":"TVR confirmé par pléthysmographie (CPT <80% prédit). EFR complémentaires : DLCO (capacité de diffusion CO) souvent ↓ dans les MIP. Spirométrie seule insuffisante (mesure VEMS/CV).","s":21},{"q":"Causes IATROGÈNES de fibrose pulmonaire :","o":["Amiodarone","Méthotrexate","Bléomycine (chimiothérapie)","Radiothérapie thoracique","Antibiotiques courants"],"r":[0,1,2,3],"e":"Médicaments pneumotoxiques : amiodarone (cordarone), méthotrexate (PR), bléomycine (cancer testiculaire), radiothérapie. Toujours évoquer en cas de toux/dyspnée chez patient sous ces traitements.","s":21},{"q":"Une PLEURÉSIE est :","o":["Une inflammation/épanchement de la plèvre","Une infection bronchique","Un trouble alvéolaire","Un cancer pulmonaire"],"r":0,"e":"Pleurésie = inflammation de la plèvre, souvent associée à un épanchement liquidien. Causes : infectieuses (pneumonie, TB), tumorales, cardiaques (transsudat ICC), inflammatoires (PR, lupus).","s":21},{"q":"Le rôle du KINÉSITHÉRAPEUTE dans la PLEURÉSIE est :","o":["Drainer chirurgicalement la plèvre","Faciliter la réexpansion pulmonaire (incitation à l'inspiration), prévenir la pachypleurite (synéchies)","Prescrire des antibiotiques","Inactiver"],"r":1,"e":"Kiné post-pleurésie : ventilation dirigée pour réexpansion pulmonaire, mobilisation thoracique, prévention des séquelles fibrotiques (pachypleurite). Ne réalise pas le drainage chirurgical.","s":21},{"q":"Une maladie restrictive est caractérisée par :","o":["VEMS/CVF abaissé","↓ Capacité pulmonaire totale (CPT) avec VEMS/CVF normal","Obstruction réversible","Infection chronique"],"r":1,"e":"Restrictif : ↓ CPT (capacité pulmonaire totale), VEMS/CVF normal ou élevé. Causes : fibrose, atteintes pariétales, neuro-musculaires.","s":21},{"q":"La pneumopathie d'hypersensibilité (alvéolite allergique extrinsèque) est due à :","o":["Une infection bactérienne chronique","L'inhalation répétée d'antigènes organiques (moisissures du foin, déjections d'oiseaux)","Une inhalation de fibres d'amiante","Une cause strictement génétique"],"r":1,"e":"Ce sont les « poumons de fermier » et « poumons d'éleveur d'oiseaux » : une réaction immunitaire à des antigènes organiques inhalés, réversible à la phase aiguë si l'exposition cesse, mais qui évolue vers la fibrose en cas d'exposition prolongée. L'éviction de l'antigène est le traitement clé.","s":21},{"q":"L'image radiologique typique de la FPI est :","o":["Pneumonie","Image en rayon de miel (honeycombing) sous-pleural","Cavité","Atélectasie"],"r":1,"e":"FPI : pattern UIP (Usual Interstitial Pneumonia) = rayon de miel sous-pleural, bronchectasies de traction, prédominance basale.","s":21},{"q":"Les causes de pneumopathies interstitielles connues incluent :","o":["Médicaments (amiodarone, MTX)","Connectivites (PR, sclérodermie)","Pneumoconiosis (silicose, asbestose)","Pneumonies d'hypersensibilité","Tabagisme normal"],"r":[0,1,2,3],"e":"PI secondaires : médicaments, connectivites, expositions pro (silice, amiante), hypersensibilité (poumon d'éleveur).","s":21},{"q":"L'asbestose est une maladie due à :","o":["Bactéries","L'inhalation chronique de fibres d'amiante","Un virus","Un parasite"],"r":1,"e":"Asbestose = fibrose pulmonaire par inhalation prolongée de fibres d'amiante (mineurs, BTP). Risque de cancer + mésothéliome.","s":21},{"q":"Le syndrome de Löfgren associe :","o":["Fièvre, érythème noueux, adénopathies hilaires bilatérales et arthralgies","Hémoptysie, amaigrissement et sueurs nocturnes","Dyspnée, hippocratisme digital et râles velcro","Douleur thoracique brutale et abolition du murmure vésiculaire"],"r":0,"e":"C'est la forme aiguë et de bon pronostic de la sarcoïdose : elle régresse spontanément dans la grande majorité des cas. Sa reconnaissance évite des explorations invasives, la biopsie n'étant alors pas indispensable.","s":21},{"q":"L'épanchement pleural restrictif compresse :","o":["Le poumon, ↓ CPT","Le cœur seul","Le rein","Le foie"],"r":0,"e":"Épanchement pleural massif → restriction par compression du poumon, ↓ CPT et capacité ventilatoire.","s":21},{"q":"Les causes neuromusculaires de syndrome restrictif incluent :","o":["Myasthénie","Sclérose latérale amyotrophique (SLA)","Guillain-Barré","Lésion médullaire haute","Asthme"],"r":[0,1,2,3],"e":"Neuromusculaires : SLA, GBS, myasthénie, polio, lésions médullaires (au-dessus de C4) → atteinte respiratoire restrictive.","s":21},{"q":"La cyphoscoliose sévère provoque :","o":["Un syndrome obstructif","Un syndrome restrictif (déformation thoracique)","Une infection","Un cancer"],"r":1,"e":"Cyphoscoliose sévère → restriction par déformation de la cage thoracique, ↓ CPT, peut évoluer vers IRC.","s":21},{"q":"Le traitement de la fibrose pulmonaire idiopathique inclut :","o":["Antibiotiques","Antifibrotiques (pirfénidone, nintédanib)","Antihistaminiques","Aucun"],"r":1,"e":"FPI : antifibrotiques (pirfénidone, nintédanib) ralentissent la progression. Transplantation pulmonaire si éligible.","s":21},{"q":"À quelles altérations tissulaires la réduction d'expansion du parenchyme est-elle liée ?","o":["Aux altérations du tissu conjonctif et du collagène","À une destruction des alvéoles par les protéases","À une bronchoconstriction","À une hypersécrétion de mucus"],"r":0,"e":"Le trouble restrictif est un trouble de compliance, non d'obstruction.","s":21},{"q":"Quelle évolution la compliance pulmonaire suit-elle dans un trouble restrictif ?","o":["Elle diminue","Elle augmente","Elle reste normale","Elle augmente puis diminue"],"r":0,"e":"Elle augmente au contraire dans les troubles obstructifs, comme la capacité pulmonaire totale.","s":21},{"q":"Comment se comporte la CVF dans un trouble obstructif pur ?","o":["Elle est normale ou légèrement diminuée","Elle est nettement diminuée","Elle est augmentée","Elle est nulle"],"r":0,"e":"Dans le trouble restrictif, VEMS et CVF baissent proportionnellement, d'où un rapport conservé.","s":21},{"q":"Quel est le critère distinctif du syndrome restrictif en spirométrie ?","o":["Des réductions proportionnelles du VEMS et de la CPT avec un rapport VEMS/CVF conservé","Un rapport VEMS/CVF inférieur à 0,7","Une augmentation du volume résiduel","Une compliance augmentée"],"r":0,"e":"Le rapport conservé, associé à une CPT abaissée, signe la restriction.","s":21},{"q":"Quel mécanisme explique la restriction dans l'obésité sévère ?","o":["Le tissu adipeux rétrécit les voies aériennes supérieures et limite le diaphragme, altérant le rapport V/Q et provoquant une hypoventilation","Une fibrose interstitielle","Une inflammation des parois alvéolaires","Une destruction des cils bronchiques"],"r":0,"e":"L'obésité est une cause extrinsèque, de même que les maladies pleurales et neuromusculaires.","s":21},{"q":"Quelles causes de restriction sont dites extrinsèques ?","o":["Obésité sévère, maladies pleurales, cyphoscoliose et maladies neuromusculaires","Fibrose pulmonaire idiopathique et sarcoïdose","Pneumoconioses","Connectivites"],"r":0,"e":"Les causes intrinsèques concernent le parenchyme lui-même.","s":21},{"q":"Quels mécanismes étiologiques la fiche retient-elle pour les maladies interstitielles ?","o":["Exposition environnementale ou professionnelle, tabagisme, sénescence, dysrégulation immunitaire et facteurs génétiques","Uniquement le tabagisme","Uniquement l'amiante","Uniquement les infections"],"r":0,"e":"Ces cinq mécanismes recouvrent l'ensemble des MIP.","s":21},{"q":"Combien de catégories de maladies interstitielles la fiche distingue-t-elle ?","o":["5","3","4","6"],"r":0,"e":"Primaires, environnementales, iatrogènes, connectivites et idiopathiques.","s":21},{"q":"À quelle catégorie de MIP la sarcoïdose appartient-elle ?","o":["Aux maladies primaires","Aux expositions environnementales","Aux formes iatrogènes","Aux idiopathiques"],"r":0,"e":"La FPI est la principale forme idiopathique, les pneumoconioses sont environnementales.","s":21},{"q":"Quelle anomalie est présente à tous les stades des maladies interstitielles ?","o":["L'épaississement du septum alvéolaire avec augmentation de la barrière alvéolo-capillaire","La prolifération des fibroblastes","La formation de cavités","L'hyperinflation"],"r":0,"e":"La prolifération du tissu conjonctif et des fibroblastes n'apparaît qu'aux stades avancés.","s":21},{"q":"Quelles cellules interviennent dans la cascade inflammatoire des MIP ?","o":["Macrophages, lymphocytes T et polynucléaires neutrophiles","Uniquement les mastocytes","Uniquement les éosinophiles","Uniquement les plasmocytes"],"r":0,"e":"Elles libèrent des médiateurs pro-fibrotiques qui aboutissent à la fibrose.","s":21},{"q":"Quel type de crépitants caractérise les maladies interstitielles ?","o":["Des crépitements secs, dits « velcro »","Des sibilants expiratoires","Des ronchi","Un souffle tubaire"],"r":0,"e":"Ces crépitants inspiratoires secs sont très évocateurs de fibrose.","s":21},{"q":"Quelle taille ont les nodules radiologiques décrits dans les MIP ?","o":["1 à 5 mm, avec un aspect en nid d'abeille","1 à 5 cm","Moins de 0,5 mm","Plus de 2 cm"],"r":0,"e":"L'aspect en rayon de miel traduit la fibrose évoluée.","s":21},{"q":"Comment évolue la gazométrie dans les maladies interstitielles ?","o":["D'une hypoxémie isolée vers une hypoxémie avec hypercapnie au stade avancé","D'une hypercapnie vers une hypoxémie","Elle reste normale","Elle montre une alcalose métabolique"],"r":0,"e":"L'hypercapnie traduit l'épuisement ventilatoire tardif.","s":21},{"q":"Quel est le mécanisme d'action du nintédanib ?","o":["C'est un anti-fibrotique inhibiteur de tyrosine kinase","C'est un corticoïde inhalé","C'est un bronchodilatateur","C'est un antibiotique"],"r":0,"e":"La pirfénidone est l'autre anti-fibrotique cité, à action anti-inflammatoire.","s":21},{"q":"Une NÉOPLASIE est :","o":["Un retour à un état normal","Une prolifération cellulaire ANORMALE et autonome (échappant aux contrôles physiologiques)","Une simple inflammation","Une atrophie"],"r":1,"e":"Néoplasie = nouvelle formation tissulaire par prolifération cellulaire anormale, autonome (échappe à la régulation du tissu), pouvant être bénigne ou maligne. 'Tumeur' = synonyme.","s":22},{"q":"Quelles sont les CARACTÉRISTIQUES différenciant une tumeur MALIGNE d'une tumeur bénigne ?","o":["Croissance rapide","Anaplasie (perte de différenciation)","Invasion locale (effraction tissulaire)","Métastases possibles","Capsule bien délimitée"],"r":[0,1,2,3],"e":"Tumeur maligne : croissance rapide, anaplasie, invasion locale, métastases, mauvaise délimitation. Bénigne : croissance lente, différenciée, encapsulée, pas d'invasion ni de métastase.","s":22},{"q":"L'ANAPLASIE correspond à :","o":["Une augmentation de la différenciation","Une PERTE de différenciation cellulaire (cellules immatures, atypiques)","Une diminution du nombre de cellules","Une augmentation de la fonction cellulaire"],"r":1,"e":"Anaplasie = perte de différenciation, cellules indifférenciées atypiques (variation taille/forme = pléomorphisme, gros noyaux hyperchromiques, mitoses anormales). Caractéristique des tumeurs malignes.","s":22},{"q":"Les VOIES DE DISSÉMINATION métastatique sont :","o":["Voie sanguine (hématogène)","Voie lymphatique","Voie séreuse / cavités péritonéale, pleurale","Implantation directe (chirurgicale, biopsie)","Voie nerveuse exclusivement"],"r":[0,1,2,3],"e":"4 voies de dissémination : hématogène (carcinomes → poumon, foie, os ; sarcomes), lymphatique (ganglions régionaux puis distance), séreuse (cavités), implantation. La voie nerveuse (périneurale) existe aussi mais minoritaire.","s":22},{"q":"Un CARCINOME est :","o":["Une tumeur maligne d'origine MÉSENCHYMATEUSE","Une tumeur maligne d'origine ÉPITHÉLIALE","Une tumeur bénigne épithéliale","Une tumeur du système nerveux"],"r":1,"e":"Carcinome = tumeur MALIGNE d'origine ÉPITHÉLIALE (carcinome bronchique, mammaire, colorectal...). Sarcome = origine mésenchymateuse (os, muscle, conjonctif). Adénocarcinome = épithélium glandulaire.","s":22},{"q":"Un SARCOME est :","o":["Une tumeur maligne épithéliale","Une tumeur maligne d'origine MÉSENCHYMATEUSE (os, cartilage, muscle, tissu conjonctif)","Une tumeur bénigne","Une métastase"],"r":1,"e":"Sarcome = tumeur maligne MÉSENCHYMATEUSE : ostéosarcome (os), chondrosarcome (cartilage), liposarcome (graisse), rhabdomyosarcome (muscle squelettique), léiomyosarcome (muscle lisse). Plus rares que les carcinomes.","s":22},{"q":"Concernant la NOMENCLATURE des tumeurs, quelles affirmations sont vraies ?","o":["Suffixe -OME = tumeur bénigne","Suffixe -CARCINOME = tumeur épithéliale maligne","Suffixe -SARCOME = tumeur mésenchymateuse maligne","'Lymphome' = tumeur bénigne","'Mélanome' = bénin"],"r":[0,1,2],"e":"-OME : généralement bénin (adénome, lipome, fibrome, ostéome). EXCEPTIONS importantes : lymphome, mélanome, séminome → MALINS malgré la terminaison. Carcinome = épithélial malin, sarcome = mésenchymateux malin.","s":22},{"q":"Le système de stadification TNM repose sur :","o":["T (Tumeur) + N (Ganglions/Nodes) + M (Métastases)","T (Type) + N (Nature) + M (Mécanisme)","Trois grades histologiques","Trois mutations"],"r":0,"e":"TNM (UICC) : T = taille/extension de la Tumeur primitive (T1-T4), N = atteinte ganglionnaire (N0-N3), M = présence de Métastases (M0/M1). Stadification universelle, pronostique, guide le tx.","s":22},{"q":"Concernant les TRAITEMENTS du cancer :","o":["Chirurgie (résection)","Radiothérapie (rayonnements)","Chimiothérapie (cytotoxiques)","Immunothérapie","Antibiothérapie"],"r":[0,1,2,3],"e":"Tx oncologiques : chirurgie, radiothérapie, chimiothérapie, hormonothérapie, thérapies ciblées (anti-HER2, anti-EGFR), immunothérapie (anti-PD1/PD-L1). Choix selon type, stade, état général. Antibiotiques en cas d'infection associée seulement.","s":22},{"q":"L'ANGIOGENÈSE TUMORALE est :","o":["Inutile à la croissance tumorale","Indispensable à la croissance tumorale au-delà de quelques mm (apport nutritif)","Une simple coïncidence","Toujours bénéfique"],"r":1,"e":"Angiogenèse tumorale : la tumeur stimule la formation de nouveaux vaisseaux (VEGF) pour son propre apport en O₂/nutriments. Cible thérapeutique : anti-angiogéniques (bevacizumab).","s":22},{"q":"Concernant les ONCOGÈNES et GÈNES SUPPRESSEURS DE TUMEURS :","o":["Oncogènes : activent la prolifération (RAS, MYC)","Gènes suppresseurs : freinent la prolifération (p53, RB)","Mutations activatrices d'oncogènes → cancer","Mutations inactivatrices de p53 → cancer","Tous les gènes ont la même fonction"],"r":[0,1,2,3],"e":"Oncogènes : activent la croissance. Activation par mutation/amplification = pro-oncogène. Gènes suppresseurs : freinent la croissance et réparent l'ADN. Inactivation par mutation = perte de frein. Cancer = accumulation de ces altérations.","s":22},{"q":"La p53 est :","o":["Un oncogène","Un gène SUPPRESSEUR de tumeur (le 'gardien du génome')","Sans rôle dans le cancer","Un médicament"],"r":1,"e":"p53 (TP53) = gène suppresseur majeur (gardien du génome) : induit l'arrêt du cycle ou apoptose en cas de lésion ADN. Inactivé dans >50% des cancers humains. Mutations germinales = syndrome de Li-Fraumeni.","s":22},{"q":"Quels sont des FACTEURS DE RISQUE généraux du cancer ?","o":["Tabac (poumon, vessie, ORL...)","Alcool (foie, ORL, sein, colorectal)","Obésité","Infections (HPV → col, EBV, H. pylori)","Activité physique régulière"],"r":[0,1,2,3],"e":"FdR : tabac, alcool, obésité, sédentarité, expositions (UV, amiante, radiations), infections (HPV, HBV/HCV, EBV, H. pylori, HIV), antécédents familiaux/génétiques (BRCA), âge. L'activité physique est PROTECTRICE.","s":22},{"q":"Le CANCER DU SEIN est :","o":["Le plus rare des cancers féminins","Le cancer le plus FRÉQUENT chez la femme dans les pays développés","N'existe que chez la femme","Une infection"],"r":1,"e":"Cancer du sein = 1er cancer féminin en incidence (1 femme sur 8 risque vie entière). Possible chez l'homme (rare, ~1%). Dépistage organisé par mammographie 50-74 ans en France.","s":22},{"q":"Concernant le DÉPISTAGE des cancers en France :","o":["Sein : mammographie 50-74 ans tous les 2 ans","Côlon : test immunologique (FIT) 50-74 ans tous les 2 ans","Col utérus : frottis (FCV) puis HPV","Prostate : pas de dépistage organisé (PSA discuté)","Tous les cancers ont un dépistage organisé"],"r":[0,1,2,3],"e":"Dépistages organisés : sein (mammographie 50-74 ans), côlon (FIT 50-74 ans), col utérin (FCV/HPV 25-65 ans). PROSTATE : pas de dépistage organisé (intérêt débattu, individuel). Tous les cancers n'ont pas de dépistage organisé.","s":22},{"q":"Une MÉTASTASE est :","o":["Une tumeur primitive isolée","Une localisation tumorale SECONDAIRE à distance du foyer initial","Une tumeur bénigne","Une cicatrice"],"r":1,"e":"Métastase = colonisation tumorale secondaire à distance (souvent par voie hématogène ou lymphatique). Sites fréquents selon origine : poumons, foie, os, cerveau. Indique une maladie disséminée (M1).","s":22},{"q":"Quels sites sont FRÉQUEMMENT le siège de métastases osseuses ?","o":["Cancer du sein","Cancer de la prostate","Cancer du poumon","Cancer du rein","Cancer thyroïdien","Cancer du côlon"],"r":[0,1,2,3,4],"e":"Cancers ostéophiles (mnémo PSPRT) : Prostate, Sein, Poumon, Rein, Thyroïde. Sites métastatiques : rachis (++), bassin, fémur, côtes. Risque de fractures pathologiques, hypercalcémie, douleurs. Le côlon métastase surtout au foie et au poumon par le drainage porte ; l'os est une localisation rare.","s":22},{"q":"Le syndrome PARANÉOPLASIQUE :","o":["Est lié à une métastase locale","Manifestation à DISTANCE de la tumeur (sans métastase), souvent endocrinienne ou immunologique","Est toujours bénin","N'existe pas"],"r":1,"e":"Syndrome paranéoplasique : manifestations cliniques à distance, indépendantes de l'envahissement local ou métastatique. Mécanismes : sécrétion ectopique d'hormones (ACTH → Cushing, ADH → SIADH), auto-immunité. Peut précéder le diagnostic du cancer.","s":22},{"q":"La CACHEXIE cancéreuse est :","o":["Une bonne nouvelle","Un syndrome de dénutrition + atrophie musculaire malgré apports alimentaires (TNF, IL-6)","Sans gravité","Une réaction allergique"],"r":1,"e":"Cachexie cancéreuse : syndrome multifactoriel = perte de poids, atrophie musculaire, anorexie, asthénie, anémie. Liée aux cytokines (TNF-α 'cachectine', IL-6). Marqueur de mauvais pronostic.","s":22},{"q":"Concernant la KINÉSITHÉRAPIE EN CANCÉROLOGIE :","o":["Réentraînement à l'effort (lutte contre la fatigue, déconditionnement)","Drainage lymphatique manuel (lymphœdème post-curage)","Mobilisations articulaires","Soutien psychologique","Aucun bénéfice prouvé"],"r":[0,1,2,3],"e":"Kiné en oncologie : reconditionnement, lutte contre la fatigue (cancer-related fatigue), DLM pour lymphœdème (mastectomie), mobilisations, prévention des amyotrophies, accompagnement post-chirurgical/radiothérapie. Bénéfices prouvés sur qualité de vie.","s":22},{"q":"Une RADIOTHÉRAPIE peut entraîner comme effet secondaire :","o":["Aucune","Radiodermite, fibrose post-radique, fatigue, troubles selon zone irradiée","Toujours une amélioration sans effet","Une infection systématique"],"r":1,"e":"Effets secondaires radiothérapie : précoces (radiodermite, mucite, fatigue, alopécie locale, troubles digestifs si abdo) et tardifs (fibrose, sténoses, second cancer rare). Importance de la kiné post-RT.","s":22},{"q":"Quels sont des effets secondaires CLASSIQUES des CHIMIOTHÉRAPIES ?","o":["Nausées, vomissements","Alopécie","Pancytopénie (anémie, neutropénie, thrombopénie)","Mucite","Polyarthrose"],"r":[0,1,2,3],"e":"Effets chimio : nausées/vomissements, alopécie, mucite, pancytopénie (risque infection si neutropénie), neuropathie (cisplatine, taxanes), cardiotoxicité (anthracyclines). Ne provoque pas de polyarthrose.","s":22},{"q":"L'IMMUNOTHÉRAPIE moderne du cancer (anti-PD1/PD-L1) :","o":["Tue directement les cellules cancéreuses","Lève l'inhibition des lymphocytes T pour qu'ils détruisent les cellules cancéreuses","Empêche la croissance bactérienne","Stimule les hormones"],"r":1,"e":"Immunothérapie (checkpoint inhibitors : nivolumab, pembrolizumab, atézolizumab) : bloque les freins (PD-1/PD-L1, CTLA-4) du système immunitaire → réactivation des LT contre la tumeur. Révolutionne le pronostic de certains cancers (mélanome, poumon).","s":22},{"q":"Le facteur de risque PRINCIPAL du cancer du POUMON est :","o":["Le tabagisme","La pollution","L'âge","L'amiante"],"r":0,"e":"Tabac = facteur de risque MAJEUR du cancer du poumon (>85% des cas). Amiante (synergie avec tabac), radon, pollution, antécédents familiaux sont aussi des FdR. Sevrage tabagique = meilleure prévention.","s":22},{"q":"Concernant la BIOPSIE en oncologie :","o":["Permet le diagnostic histologique de certitude","Indique le type histologique et le grade","Permet d'orienter la prise en charge thérapeutique","Indispensable avant un traitement curatif","Toujours dangereuse et à éviter"],"r":[0,1,2,3],"e":"Biopsie : geste diagnostique INDISPENSABLE pour confirmer le cancer, identifier le type/grade/marqueurs (récepteurs hormonaux, HER2, EGFR, PD-L1...). Risque ENSEMENCEMENT marginal mais nécessaire pour traitement adapté.","s":22},{"q":"L'effet Warburg des cellules tumorales désigne :","o":["Leur capacité à métastaser par voie lymphatique","Leur recours préférentiel à la glycolyse même en présence d'oxygène","Leur résistance spontanée à la chimiothérapie","Leur perte de la molécule p53"],"r":1,"e":"Les cellules cancéreuses privilégient la glycolyse aérobie, moins rentable en ATP mais rapide et fournissant des précurseurs de biosynthèse. Cette avidité pour le glucose est ce que met en image le TEP-scanner au 18F-FDG.","s":22},{"q":"Une tumeur maligne se distingue d'une tumeur bénigne par :","o":["Croissance rapide / désorganisée","Capacité d'invasion locale","Capacité de métastaser","Différenciation faible","Capsule limitante nette"],"r":[0,1,2,3],"e":"Maligne : croissance rapide, invasive, métastatique, peu différenciée. Bénigne : encapsulée, bien différenciée, lente, locale.","s":22},{"q":"Le préfixe « -ome » indique généralement :","o":["Tumeur maligne","Tumeur bénigne","Infection","Inflammation"],"r":1,"e":"Suffixe -ome = bénin (lipome, fibrome). Carcinome (épithéliale maligne), sarcome (conjonctive maligne).","s":22},{"q":"Un carcinome est un cancer :","o":["Du tissu conjonctif","De l'épithélium","Du sang","Du système nerveux"],"r":1,"e":"Carcinome = cancer d'origine épithéliale (sein, poumon, côlon, prostate, peau).","s":22},{"q":"Un sarcome est un cancer :","o":["De l'épithélium","Du tissu conjonctif (os, muscles, cartilage)","Du sang","Du foie uniquement"],"r":1,"e":"Sarcome = cancer d'origine mésenchymateuse / conjonctive (os = ostéosarcome, muscle = rhabdomyosarcome).","s":22},{"q":"Un lymphome est :","o":["Cancer du tissu lymphoïde","Cancer pulmonaire","Cancer du foie","Cancer cutané"],"r":0,"e":"Lymphome : prolifération maligne de cellules lymphoïdes (Hodgkin, non-Hodgkinien).","s":22},{"q":"Le marqueur tumoral PSA est utilisé dans le dépistage et le suivi du cancer :","o":["Du sein","De la prostate","Du côlon","Du poumon"],"r":1,"e":"Le PSA (antigène spécifique de prostate) est spécifique de l'organe, non du cancer : il s'élève aussi dans l'hypertrophie bénigne et la prostatite. Repères d'usage : CA 15-3 pour le sein, ACE et CA 19-9 pour le tube digestif, AFP pour le foie et le testicule.","s":22},{"q":"Les voies de dissémination tumorale sont :","o":["Lymphatique","Hématogène (sang)","Par contiguïté","Cavités séreuses (pleurale, péritonéale)","Aérienne"],"r":[0,1,2,3],"e":"Voies : lymphatique (carcinomes), hématogène (sarcomes), contiguïté, séreuses. Pas aérienne.","s":22},{"q":"Les facteurs de risque de cancer incluent :","o":["Tabac","Alcool","Rayonnements (UV, ionisants)","Infections (HPV, HBV, EBV)","Génétique","Sport régulier"],"r":[0,1,2,3,4],"e":"Carcinogènes : tabac, alcool, rayonnements, virus oncogènes, prédispositions héréditaires (BRCA, Lynch). Sport = protecteur.","s":22},{"q":"La classification TNM décrit :","o":["Le traitement uniquement","T = taille tumeur, N = ganglions, M = métastases","La couleur","La biologie"],"r":1,"e":"TNM (UICC) : T (Tumor size), N (Nodes ganglions régionaux), M (Metastases) → stadification cancer.","s":22},{"q":"Quelle était la signification initiale du mot « tumeur » ?","o":["Une augmentation de volume causée par l'inflammation","Une masse maligne","Une métastase","Un processus de croissance incontrôlée"],"r":0,"e":"Le terme désigne aujourd'hui toute masse occupant un espace anormal, et s'emploie comme synonyme de néoplasme.","s":22},{"q":"Quelle relation la fiche établit-elle entre cancer et néoplasme ?","o":["Tout cancer est un néoplasme, mais tout néoplasme n'est pas un cancer","Tout néoplasme est un cancer","Les deux termes sont équivalents","Le cancer est un néoplasme bénin"],"r":0,"e":"Le cancer correspond aux seules néoplasies malignes.","s":22},{"q":"Qu'est-ce que la différenciation cellulaire ?","o":["Le mécanisme par lequel les cellules augmentent leur spécialisation à chaque division","La mort cellulaire programmée","La division cellulaire de remplacement","L'entrée en phase G0"],"r":0,"e":"Prolifération, différenciation et apoptose sont les trois processus normaux rappelés par la fiche.","s":22},{"q":"Quelles cellules n'entrent jamais en phase G0 ?","o":["Les cellules labiles, comme les cellules sanguines","Les cellules permanentes","Les cellules stables","Les cellules souches adultes"],"r":0,"e":"Les cellules labiles répètent continuellement le cycle cellulaire.","s":22},{"q":"Que se passe-t-il lors de l'initiation de la carcinogenèse ?","o":["Un agent cancérigène provoque des dommages à l'ADN et une mutation, la cellule étant en G0","Les oncogènes sont activés par un promoteur","Les mutations confèrent des avantages de survie","La tumeur devient invasive"],"r":0,"e":"Initiation, promotion puis progression constituent les trois étapes.","s":22},{"q":"Que se passe-t-il durant la phase de promotion ?","o":["L'hypoxie fait entrer la cellule en G1 et un agent promoteur active les oncogènes","L'ADN est endommagé pour la première fois","Les métastases se forment","La cellule entre en apoptose"],"r":0,"e":"La cellule mutée prolifère alors de manière autonome, sans contrôle de l'apoptose.","s":22},{"q":"Qu'est-ce qui caractérise la phase de progression ?","o":["Des mutations conférant des avantages de survie et de croissance, avec prolifération indépendante des signaux normaux","La première mutation de l'ADN","L'activation initiale des oncogènes","La différenciation cellulaire"],"r":0,"e":"C'est l'aboutissement vers la tumeur maligne.","s":22},{"q":"D'où résulte l'anaplasie ?","o":["D'une prolifération sans maturation, la dédifférenciation étant plus rare","D'une dédifférenciation systématique","D'une hyperplasie prolongée","D'une métaplasie"],"r":0,"e":"L'anaplasie est l'absence de différenciation, caractéristique des cellules malignes.","s":22},{"q":"Quelles mitoses observe-t-on dans une tumeur bénigne ?","o":["Des mitoses rares et normales","Des mitoses nombreuses et anormales","Aucune mitose","Des mitoses anormales mais rares"],"r":0,"e":"Les tumeurs malignes ont une croissance erratique avec des mitoses nombreuses ou atypiques.","s":22},{"q":"Qu'est-ce qui rend une tumeur bénigne mobile et discrètement palpable ?","o":["Sa capsule de tissu conjonctif condensé","Son infiltration des tissus voisins","Sa vascularisation abondante","Son caractère indifférencié"],"r":0,"e":"L'encapsulation empêche la pénétration des tissus environnants.","s":22},{"q":"Quel type de tumeur donne des métastases plus fréquentes ?","o":["Les tumeurs primaires larges et peu différenciées","Les tumeurs petites et bien différenciées","Les tumeurs encapsulées","Les tumeurs bénignes volumineuses"],"r":0,"e":"Taille et indifférenciation augmentent le risque métastatique.","s":22},{"q":"Qu'est-ce qui permet à la cellule cancéreuse d'envahir les tissus ?","o":["L'expression de molécules d'adhésion de surface","La perte totale de toute molécule de surface","Son encapsulation","Sa différenciation accrue"],"r":0,"e":"Ces molécules d'adhésion permettent l'invasion puis la dissémination.","s":22},{"q":"Quels organes la dissémination par voie sanguine atteint-elle fréquemment ?","o":["Le foie, les poumons et les os","Les ganglions lymphatiques régionaux","La plèvre et le péritoine","La peau"],"r":0,"e":"La voie lymphatique gagne les ganglions et la voie cavitaire les séreuses.","s":22},{"q":"Dans quel cas une tumeur bénigne peut-elle être dangereuse ?","o":["Si elle interfère avec des fonctions vitales, par exemple dans le cerveau","Si elle donne des métastases","Si elle est bien différenciée","Si elle est encapsulée"],"r":0,"e":"La localisation, non la nature, fait le danger des tumeurs bénignes.","s":22},{"q":"Sur quelle composante la dénomination d'une tumeur est-elle fondée ?","o":["Sur la composante parenchymateuse","Sur le stroma","Sur la vascularisation","Sur la taille"],"r":0,"e":"C'est le tissu d'origine du parenchyme qui donne son nom à la tumeur.","s":22}]};
